#[cfg(test)]
mod j27_strrx_indexof_from_kind_tests {
    use super::*;

    const KEY: &str = "CRATONVM_JIT_IR_STRING_INDEXOF_FROM_PREFIX";

    fn kind(v: Option<&'static str>, class: &str, desc: &str) -> Option<IrStringSearchKind> {
        cratonvm_types::flags::with_thread_overrides(&[(KEY, v)], || {
            ir_string_search_prefix_kind(class, "indexOf", desc)
        })
    }

    #[test]
    fn indexof_from_is_named_unless_killed() {
        assert_eq!(
            kind(None, "java/lang/String", "(II)I"),
            Some(IrStringSearchKind::IndexOfCharFrom),
            "default ON"
        );
        assert_eq!(kind(Some("0"), "java/lang/String", "(II)I"), None, "=0 kills");
        assert_eq!(
            kind(Some("1"), "java/lang/String", "(II)I"),
            Some(IrStringSearchKind::IndexOfCharFrom)
        );
        // Not a CharSequence member, and the other overloads keep their kinds.
        assert_eq!(kind(Some("1"), "java/lang/CharSequence", "(II)I"), None);
        assert_eq!(
            kind(Some("1"), "java/lang/String", "(I)I"),
            kind(None, "java/lang/String", "(I)I")
        );
        assert_ne!(
            kind(Some("1"), "java/lang/String", "(III)I"),
            Some(IrStringSearchKind::IndexOfCharFrom)
        );
        // The family switch withdraws it too.
        let off = cratonvm_types::flags::with_thread_overrides(
            &[(KEY, Some("1")), ("CRATONVM_JIT_IR_STRING_SEARCH_PREFIX", Some("0"))],
            || ir_string_search_prefix_kind("java/lang/String", "indexOf", "(II)I"),
        );
        assert_eq!(off, None);
    }

    #[test]
    fn indexof_from_shape_is_a_two_argument_virtual_call_kept_a_call() {
        let k = IrStringSearchKind::IndexOfCharFrom;
        assert_eq!(k.num_params(), 2);
        assert!(k.admits_invoke_kind(0) && k.admits_invoke_kind(1));
        assert!(!k.admits_invoke_kind(2) && !k.admits_invoke_kind(3));
        assert!(k.admits_opcode(0xb6) && !k.admits_opcode(0xb8));
        assert!(!k.is_builder() && !k.is_string_accessor_call());
        assert!(ir_string_prefix_site_stays_a_call(k));
        // Handled (so the pin / planning gate see it) only under the switch.
        cratonvm_types::flags::with_thread_overrides(&[(KEY, Some("1"))], || {
            if !crate::x64::narrow_oops_block_inline_fields() {
                assert_eq!(
                    ir_string_search_prefix_handled_kind("java/lang/String", "indexOf", "(II)I"),
                    Some(k)
                );
            }
        });
    }
}

