#[cfg(test)]
mod speculation_feed_tests {
    use super::speculatable_forward_branch;

    /// `ifeq` at pc 0 with a +8 offset: a plain forward `if`, the shape the
    /// whole speculation feature exists for.
    #[test]
    fn a_forward_conditional_branch_is_offered_to_the_builder() {
        // 0x99 = ifeq, offset +8 → target 8.
        let code = [0x99, 0x00, 0x08, 0, 0, 0, 0, 0, 0xb1, 0, 0];
        assert!(speculatable_forward_branch(&code, 9, 0));
    }

    /// The defect this filter exists for: a bottom-tested loop's back edge is
    /// `not_taken == 0` in any profile taken while the loop is still running,
    /// so it passes the counter test and must be rejected on its shape.
    #[test]
    fn a_backward_branch_is_never_offered_however_hot_its_taken_arm_is() {
        // `if_icmplt` at pc 6 with offset -6 → target 0, a back edge.
        let code = [0, 0, 0, 0, 0, 0, 0xa1, 0xff, 0xfa, 0xb1, 0, 0];
        assert!(!speculatable_forward_branch(&code, 10, 6));
    }

    /// A branch to itself is not forward either. `prune_always_taken_branch`
    /// declines `target <= pc`, and the feed says the same thing.
    #[test]
    fn a_self_branch_is_not_a_forward_branch() {
        let code = [0x99, 0x00, 0x00, 0xb1, 0, 0];
        assert!(!speculatable_forward_branch(&code, 4, 0));
    }

    /// A target past the end of the compiling method cannot be walked. A
    /// stale profile keyed to a since-redefined method is how that arrives.
    #[test]
    fn a_target_outside_the_method_is_not_offered() {
        // offset +64, but `code_len` is 4.
        let code = [0x99, 0x00, 0x40, 0xb1, 0, 0];
        assert!(!speculatable_forward_branch(&code, 4, 0));
    }

    /// A profile pc that does not name an offset branch at all — the other
    /// way a stale profile lies — is filtered rather than fed through.
    #[test]
    fn a_pc_that_is_not_a_branch_is_not_offered() {
        // 0x60 = iadd.
        let code = [0x60, 0x60, 0x60, 0xb1, 0, 0];
        assert!(!speculatable_forward_branch(&code, 4, 0));
    }

    /// `goto_w` / `ifnull` are branches too, and the 32-bit form's offset is
    /// decoded by the same helper the CFG builder uses.
    #[test]
    fn the_wide_and_reference_branch_forms_are_decoded_the_same_way() {
        // 0xc6 = ifnull, +5.
        let code = [0xc6, 0x00, 0x05, 0, 0, 0xb1, 0, 0];
        assert!(speculatable_forward_branch(&code, 6, 0));
        // 0xc8 = goto_w, -4 → backward.
        let wide = [0, 0, 0, 0, 0xc8, 0xff, 0xff, 0xff, 0xfc, 0xb1, 0, 0];
        assert!(!speculatable_forward_branch(&wide, 10, 4));
    }

    /// `static int f(int n) { int i = 0; while (i < n) { if (i == 0) i++;
    /// i++; } return i; }`: header 2, exit test at 4 (-> 20), in-loop
    /// `ifne` at 8 (-> 14), back edge `goto` at 17.
    const NIO21W17_LOOP: [u8; 24] = [
        0x03, 0x3c, // 0: iconst_0; 1: istore_1
        0x1b, 0x1a, // 2: iload_1 (header); 3: iload_0
        0xa2, 0x00, 0x10, // 4: if_icmpge +16 -> 20 (the loop EXIT)
        0x1b, // 7: iload_1
        0x9a, 0x00, 0x06, // 8: ifne +6 -> 14 (inside the loop)
        0x84, 0x01, 0x01, // 11: iinc 1 1
        0x84, 0x01, 0x01, // 14: iinc 1 1
        0xa7, 0xff, 0xf1, // 17: goto -15 -> 2
        0x1b, 0xac, // 20: iload_1; 21: ireturn
        0, 0,
    ];

    /// nio21 wave 17 (lane L4): a loop EXIT is never a never-taken candidate
    /// (a profile taken mid-loop has not seen it), an in-loop forward branch
    /// is, and an unconditional `goto` or a non-branch never is.
    #[test]
    fn nio21w17_never_taken_candidates_exclude_loop_exits_and_gotos() {
        use super::never_taken_prune_candidate;
        assert!(
            !never_taken_prune_candidate(&NIO21W17_LOOP, 22, 4),
            "the loop exit"
        );
        assert!(
            never_taken_prune_candidate(&NIO21W17_LOOP, 22, 8),
            "in-loop branch"
        );
        assert!(
            !never_taken_prune_candidate(&NIO21W17_LOOP, 22, 17),
            "a goto"
        );
        assert!(
            !never_taken_prune_candidate(&NIO21W17_LOOP, 22, 0),
            "not a branch"
        );
    }

    /// nio21 wave 17 (lane L4): the feed offers a pc whose taken edge was
    /// never seen over the sample, and not one taken once, one under the
    /// sample floor, or one this VM's de-spec registry withdrew.
    #[test]
    fn nio21w17_the_never_taken_feed_reads_the_profile_and_the_despec_registry() {
        use super::{ir, ir_never_taken_branches, profile};
        let mut prof = profile::MethodProfile::default();
        let floor = ir::MIN_OBSERVATIONS_TO_PRUNE;
        prof.branches.insert(
            8,
            profile::BranchCounts {
                taken: 0,
                not_taken: floor,
            },
        );
        let offered = ir_never_taken_branches(Some(&prof), &NIO21W17_LOOP, 22, None, "K.f:(I)I");
        assert!(offered.contains(&8));
        // The loop exit is never offered, whatever the counts.
        prof.branches.insert(
            4,
            profile::BranchCounts {
                taken: 0,
                not_taken: floor * 4,
            },
        );
        let offered = ir_never_taken_branches(Some(&prof), &NIO21W17_LOOP, 22, None, "K.f:(I)I");
        assert!(!offered.contains(&4));
        // De-specialised at pc 8: withdrawn.
        let reg = super::deopt::DespecRegistry::new();
        reg.insert("K.f:(I)I", 8, super::deopt::SPECULATION_ID_ANY);
        let offered =
            ir_never_taken_branches(Some(&prof), &NIO21W17_LOOP, 22, Some(&reg), "K.f:(I)I");
        assert!(!offered.contains(&8));
        // Taken once, or under the floor: not offered.
        prof.branches.insert(
            8,
            profile::BranchCounts {
                taken: 1,
                not_taken: floor * 4,
            },
        );
        assert!(
            ir_never_taken_branches(Some(&prof), &NIO21W17_LOOP, 22, None, "K.f:(I)I").is_empty()
        );
        prof.branches.insert(
            8,
            profile::BranchCounts {
                taken: 0,
                not_taken: floor - 1,
            },
        );
        assert!(
            ir_never_taken_branches(Some(&prof), &NIO21W17_LOOP, 22, None, "K.f:(I)I").is_empty()
        );
        assert!(ir_never_taken_branches(None, &NIO21W17_LOOP, 22, None, "K.f:(I)I").is_empty());
    }

    /// nio21 wave 17 (lane L4): `int f(int k) { int r; if (k <= 100) r = k;
    /// else { r = 0; while (r < k) r++; } return r; }` -- the never-taken
    /// `if_icmpgt` at 3 is the only way into the loop at 13, so it is not
    /// offered (the OSR door may enter a body at any header), though it is a
    /// candidate by shape.
    #[test]
    fn nio21w17_a_branch_that_is_the_only_way_into_a_loop_is_not_offered() {
        use super::{ir, ir_never_taken_branches, never_taken_prune_candidate, profile};
        const COLD_LOOP: [u8; 28] = [
            0x1a, 0x10, 0x64, // 0: iload_0; 1: bipush 100
            0xa3, 0x00, 0x08, // 3: if_icmpgt +8 -> 11 (never taken)
            0x1a, 0x3c, // 6: iload_0; 7: istore_1
            0xa7, 0x00, 0x10, // 8: goto +16 -> 24
            0x03, 0x3c, // 11: iconst_0; 12: istore_1
            0x1b, 0x1a, // 13: iload_1 (header); 14: iload_0
            0xa2, 0x00, 0x09, // 15: if_icmpge +9 -> 24
            0x84, 0x01, 0x01, // 18: iinc 1 1
            0xa7, 0xff, 0xf8, // 21: goto -8 -> 13
            0x1b, 0xac, // 24: iload_1; 25: ireturn
            0, 0,
        ];
        assert!(never_taken_prune_candidate(&COLD_LOOP, 26, 3));
        let mut prof = profile::MethodProfile::default();
        prof.branches.insert(
            3,
            profile::BranchCounts {
                taken: 0,
                not_taken: ir::MIN_OBSERVATIONS_TO_PRUNE,
            },
        );
        assert!(ir_never_taken_branches(Some(&prof), &COLD_LOOP, 26, None, "K.g:(I)I").is_empty());
    }
}

#[cfg(test)]
mod code_buffer_retry_tests {
    use super::{
        code_buffer_hint, code_buffer_retries_exhausted, note_code_buffer_shortfall,
        ExecutableBuffer, CODE_BUFFER_TOO_SMALL_SITE, MAX_CODE_BUFFER_RETRIES,
    };

    #[test]
    fn osr_capacity_bails_retry_until_the_same_resize_budget_is_exhausted() {
        let registry = super::JitVerdictRegistry::default();
        let cid = cratonvm_types::ClassId::new(91_234);
        let class = "test/OsrCapacityRetry";
        let key = "test/OsrCapacityRetry.loop:()V";
        let mut capacity = 4096;
        for step in 1..=MAX_CODE_BUFFER_RETRIES {
            note_code_buffer_shortfall(key, capacity + 100, capacity);
            super::note_jit_bail_site(CODE_BUFFER_TOO_SMALL_SITE);
            registry.mark_bail_listed_with_site(cid, class, "loop", "()V");
            assert_eq!(
                registry.is_bail_listed(cid, class, "loop", "()V"),
                step == MAX_CODE_BUFFER_RETRIES,
                "OSR and method-entry compilation must agree on a resize retry",
            );
            assert_eq!(
                registry
                    .bail_reason_for(cid, class, "loop", "()V")
                    .as_deref(),
                Some(CODE_BUFFER_TOO_SMALL_SITE),
            );
            capacity = code_buffer_hint(key).unwrap();
        }
        // A real codegen invariant is permanent even with a measured size
        // hint. The capacity exception must not mask a different failure.
        let other = "test/OsrCapacityInvariant";
        let other_cid = cratonvm_types::ClassId::new(91_235);
        assert!(!registry.is_bail_listed(other_cid, other, "loop", "()V"));
        note_code_buffer_shortfall("test/OsrCapacityInvariant.loop:()V", 5000, 4096);
        super::note_jit_bail_site("short-branch-unencodable");
        registry.mark_bail_listed_with_site(other_cid, other, "loop", "()V");
        assert!(registry.is_bail_listed(other_cid, other, "loop", "()V"));
        assert!(super::take_jit_bail_site().is_none());
    }

    /// A method nobody ever measured has no hint, so the heuristic estimate
    /// stands and codegen is byte-identical to before this machinery existed.
    #[test]
    fn an_unmeasured_method_has_no_hint() {
        assert_eq!(code_buffer_hint("com/example/Never.touched:()V"), None);
        // An empty key is what the legacy `compile()` test wrapper passes; it
        // must not collide with a real method under the empty string.
        note_code_buffer_shortfall("", 99_999, 99_999);
        assert_eq!(code_buffer_hint(""), None);
        assert!(!code_buffer_retries_exhausted(""));
    }

    /// The recorded shortfall comes back doubled — `wanted` under-reports,
    /// because an out-of-bounds `try_patch_*` never adds to it.
    #[test]
    fn a_measured_shortfall_comes_back_doubled() {
        let key = "com/example/Big.method:(I)V";
        note_code_buffer_shortfall(key, 6238, 4096);
        assert_eq!(code_buffer_hint(key), Some(12_476));
    }

    /// Two attempts can take different paths through one method, so the
    /// registry keeps the LARGEST measurement. Sizing the next buffer from a
    /// later, smaller observation would overflow again — and that second
    /// overflow would look identical to the first, which is how a "retry" that
    /// never converges hides.
    #[test]
    fn a_smaller_later_measurement_does_not_shrink_the_hint() {
        let key = "com/example/Bimodal.method:()V";
        note_code_buffer_shortfall(key, 15_519, 4096);
        note_code_buffer_shortfall(key, 4_000, 4096);
        assert_eq!(code_buffer_hint(key), Some(31_038));
    }

    /// A zero `wanted` is not a measurement and must not install a hint of 0,
    /// which `max` would silently ignore but which would make the registry
    /// claim the method had been measured.
    #[test]
    fn a_zero_measurement_is_not_recorded() {
        let key = "com/example/Zero.method:()V";
        note_code_buffer_shortfall(key, 0, 0);
        assert_eq!(code_buffer_hint(key), None);
    }

    /// THE NON-CONVERGENCE THIS FIXED. `wanted` can be recorded well BELOW the
    /// capacity that failed (`try_patch_*` overruns add nothing to it), and the
    /// driver sizes the next buffer as `max(heuristic, hint)`. With the hint
    /// derived from `wanted` alone, a `wanted` under half the failing capacity
    /// produced a hint the failing capacity already beat — so the "retry"
    /// allocated the SAME number of bytes and failed in the same place, on every
    /// warmup-gate re-attempt, forever. Folding the failed capacity into the
    /// measurement makes each attempt strictly larger than the last.
    #[test]
    fn the_hint_always_exceeds_the_capacity_that_failed() {
        let key = "com/example/UnderReported.method:()V";
        let failed_capacity = 171_424;
        note_code_buffer_shortfall(key, 12_000, failed_capacity);
        let hint = code_buffer_hint(key).expect("a measured method has a hint");
        assert!(
            hint > failed_capacity,
            "hint {hint} must exceed the capacity {failed_capacity} that just failed, \
             or the retry re-runs the identical compile"
        );
    }

    /// The bail-list exemption is bounded. Each retry is a full re-lowering plus
    /// an mmap/munmap on the calling thread; without a cap a method the estimate
    /// can never satisfy pays that on every re-attempt for the whole run.
    #[test]
    fn concurrent_shortfalls_at_one_capacity_share_a_retry_step() {
        let key = "com/example/Concurrent.method:()V";
        note_code_buffer_shortfall(key, 53_245, 51_392);
        let first_hint = code_buffer_hint(key).expect("first overflow records a hint");
        for _ in 0..12 {
            // Hot workers can cross the threshold together and compile the same
            // method before any failure publishes the larger capacity.
            note_code_buffer_shortfall(key, 53_245, 51_392);
        }
        assert_eq!(code_buffer_hint(key), Some(first_hint));
        assert!(
            !code_buffer_retries_exhausted(key),
            "same-capacity failures must leave the resize retry available"
        );
        note_code_buffer_shortfall(key, 53_245, first_hint);
        assert!(
            !code_buffer_retries_exhausted(key),
            "the larger capacity is a second distinct resize step"
        );
    }

    #[test]
    fn the_retry_exemption_runs_out() {
        let key = "com/example/Hopeless.method:()V";
        let mut capacity = 8192;
        for i in 0..MAX_CODE_BUFFER_RETRIES {
            assert!(
                !code_buffer_retries_exhausted(key),
                "capacity step {i} must still be allowed to retry"
            );
            note_code_buffer_shortfall(key, capacity, capacity);
            capacity *= 2;
        }
        assert!(
            code_buffer_retries_exhausted(key),
            "after {MAX_CODE_BUFFER_RETRIES} distinct failed capacities the refusal must become permanent"
        );
    }

    /// A codegen invariant that has no encoding is NOT a sizing problem, and it
    /// must not be reported or retried as one: `mark_codegen_unencodable` still
    /// discards the method (so every `if buf.overflowed()` bail keeps working)
    /// but names its own reason, which the driver reports instead of the
    /// code-buffer message and which `try_compile` bail-lists permanently.
    #[test]
    fn an_unencodable_codegen_invariant_is_not_reported_as_a_short_buffer() {
        let mut buf = ExecutableBuffer::new(4096).expect("allocate");
        assert!(!buf.overflowed());
        assert_eq!(buf.codegen_failure_reason(), None);
        buf.mark_codegen_unencodable("rel8-displacement-out-of-range");
        assert!(
            buf.overflowed(),
            "the existing overflowed() discards must still fire"
        );
        assert_eq!(
            buf.codegen_failure_reason(),
            Some("rel8-displacement-out-of-range")
        );

        // A genuine capacity overflow reports NO named reason, so the driver
        // keeps taking the measure-and-retry path for it.
        let mut small = ExecutableBuffer::new(4096).expect("allocate");
        small.emit(&[0u8; 8192]);
        assert!(small.overflowed());
        assert_eq!(small.codegen_failure_reason(), None);
        assert!(
            small.wanted() > small.capacity(),
            "a real overflow's `wanted` exceeds its capacity; that is what the retry measures"
        );
    }

    /// The FIRST reason wins. A codegen site that bails mid-instruction can
    /// leave later emitters running against a sticky-overflowed buffer, and
    /// whichever of them marks next must not overwrite the diagnosis.
    #[test]
    fn the_first_named_reason_is_the_one_reported() {
        let mut buf = ExecutableBuffer::new(4096).expect("allocate");
        buf.mark_codegen_unencodable("deopt-stub-without-saved-regs");
        buf.mark_codegen_unencodable("rel8-displacement-out-of-range");
        assert_eq!(
            buf.codegen_failure_reason(),
            Some("deopt-stub-without-saved-regs")
        );
    }

    /// The exemption in `try_compile` matches on this constant, and the
    /// backend records it. If either side were a bare literal, rewording one
    /// would re-arm the permanent bail-list for overflowing methods — silently,
    /// since the only symptom is a method that stops being compiled.
    #[test]
    fn the_retryable_site_name_is_shared_not_duplicated() {
        assert_eq!(CODE_BUFFER_TOO_SMALL_SITE, "code-buffer-estimate-too-small");
        // The predicate `try_compile` actually evaluates, spelled the same way.
        let site: Option<(&'static str, u32, u32)> = Some((CODE_BUFFER_TOO_SMALL_SITE, 0, 0));
        assert!(matches!(site, Some((CODE_BUFFER_TOO_SMALL_SITE, _, _))));
        // …and a neighbouring backend bail is NOT exempted.
        let other: Option<(&'static str, u32, u32)> =
            Some(("branch-target-not-an-instruction-boundary", 0, 0));
        assert!(!matches!(other, Some((CODE_BUFFER_TOO_SMALL_SITE, _, _))));
    }
}

#[cfg(test)]
mod long_box_direct_bind_tests {
    use super::*;

    /// The site counters start at zero and are independent, so a run that
    /// reports `Long.valueOf=0 Long.longValue=N` is reporting two facts and not
    /// one number twice. `the field site cache shipped default-OFF for 13 days`
    /// is what this row is for: "the bind did not help" and "the bind never
    /// happened" have to be distinguishable from the log line alone.
    #[test]
    fn the_two_long_site_counters_are_separate() {
        let (before_v, before_l) = long_box_direct_helper_sites();
        LONG_VALUE_OF_SITES.fetch_add(3, std::sync::atomic::Ordering::Relaxed);
        let (after_v, after_l) = long_box_direct_helper_sites();
        assert_eq!(after_v, before_v + 3);
        assert_eq!(
            after_l, before_l,
            "bumping valueOf moved the longValue tally"
        );
        LONG_LONG_VALUE_SITES.fetch_add(5, std::sync::atomic::Ordering::Relaxed);
        let (final_v, final_l) = long_box_direct_helper_sites();
        assert_eq!(final_v, before_v + 3);
        assert_eq!(final_l, before_l + 5);
    }
}

#[cfg(test)]
mod direct_exc_table_publish_policy {
    use super::*;

    /// The default is ON as of 2026-08-21, and `=0` is what restores the ban.
    ///
    /// Pinned because the flip is NOT justified by a workload win — it is
    /// justified by the static door otherwise being 11x worse than the virtual
    /// door for the same callee — so the next person to read the census could
    /// reasonably conclude it should go back. If they do, it should be a
    /// decision that edits this test, not a silent polarity slip.
    #[test]
    fn the_default_is_on_and_zero_restores_the_ban() {
        assert!(
            direct_call_exc_table_publish_decision(None, SpIcDeoptCheck::On),
            "unset must mean ON since 2026-08-21",
        );
        for off in ["0", "false", "off"] {
            assert!(
                !direct_call_exc_table_publish_decision(Some(off), SpIcDeoptCheck::On),
                "`{off}` must restore the ban",
            );
        }
        for on in ["1", "true", ""] {
            assert!(
                direct_call_exc_table_publish_decision(Some(on), SpIcDeoptCheck::On),
                "`{on}` must not restore the ban",
            );
        }
    }

    /// The interlock outranks the flag, in BOTH directions.
    ///
    /// Publishing a direct `CALL` while the `i64::MIN` sentinel check is
    /// suppressed is the unsound state — the callee's own handler would never
    /// run — and the MIC sibling's page records a throughput reading that was
    /// mistaken for a pass because of exactly this
    /// (`207.04 ns/op` with the interlock holding, `24.12` without it). The
    /// default flipping must not turn the interlock into a knob.
    #[test]
    fn a_suppressed_sentinel_check_forces_the_ban_back_on() {
        for check in [SpIcDeoptCheck::Off, SpIcDeoptCheck::SkipVoid] {
            assert!(
                !direct_call_exc_table_publish_decision(None, check),
                "{check:?} must force the ban on even with the flag unset",
            );
            assert!(
                !direct_call_exc_table_publish_decision(Some("1"), check),
                "{check:?} must force the ban on even when the flag asks for it",
            );
        }
    }
}

#[cfg(test)]
mod varhandle_read_direct_bind_tests {
    use super::*;

    /// The netty shape this bind exists for, at all four read modes.
    ///
    /// `RefCnt.isLiveNonVolatile` is `(int) VH.get(instance)` and `refCnt()` is
    /// `(int) VH.getAcquire(instance) >>> 1`, so a filter that recognised only
    /// `get` would leave the second of the two on the funnel and the class's
    /// `retain`/`release` paths with it.
    #[test]
    fn the_netty_refcnt_shape_is_recognised_in_every_read_mode() {
        let desc = "(Lio/netty/util/internal/RefCnt;)I";
        let int_slot = VARHANDLE_READ_RETURNS
            .iter()
            .position(|r| *r == b'I')
            .unwrap();
        for (mode, name) in VARHANDLE_READ_MODES.iter().enumerate() {
            assert_eq!(
                varhandle_read_helper_slot(name, desc),
                Some(mode * VARHANDLE_READ_KINDS + int_slot),
                "{name} on the netty refCnt descriptor",
            );
        }
    }

    /// Every slot's canonical call-site descriptor, in slot order.
    ///
    /// The primitive kinds are `(Ljava/lang/Object;)X`; the two reference kinds
    /// are the `Object` return and one concrete `REF_STRICT` stand-in
    /// (`java/lang/String` — the class `RJdkHandles`' wrong-type vector uses).
    fn canonical_descriptors() -> Vec<(usize, String, &'static str)> {
        let mut out = Vec::new();
        for (mode, name) in VARHANDLE_READ_MODES.iter().enumerate() {
            for kind in 0..VARHANDLE_READ_KINDS {
                let ret = if kind < VARHANDLE_READ_RETURNS.len() {
                    (VARHANDLE_READ_RETURNS[kind] as char).to_string()
                } else if kind == VARHANDLE_READ_KIND_REF_OBJECT {
                    "Ljava/lang/Object;".to_string()
                } else {
                    "Ljava/lang/String;".to_string()
                };
                out.push((
                    mode * VARHANDLE_READ_KINDS + kind,
                    format!("(Ljava/lang/Object;){ret}"),
                    *name,
                ));
            }
        }
        out
    }

    /// Every slot is reachable and no two shapes share one.
    ///
    /// A collision would be silent: two different return kinds would land on
    /// one helper, and the one whose kind lost would read the field with the
    /// wrong descriptor. The count also pins `VARHANDLE_READ_SLOTS` against the
    /// two tables it is supposed to be the product of.
    #[test]
    fn every_mode_return_pair_has_its_own_slot() {
        let mut seen = std::collections::HashSet::new();
        for (expected, desc, name) in canonical_descriptors() {
            let slot = varhandle_read_helper_slot(name, &desc)
                .unwrap_or_else(|| panic!("{name}{desc} was not recognised"));
            assert_eq!(slot, expected, "{name}{desc} landed on the wrong slot");
            assert!(slot < VARHANDLE_READ_SLOTS);
            assert!(seen.insert(slot), "{name}{desc} collided on slot {slot}");
        }
        assert_eq!(seen.len(), VARHANDLE_READ_SLOTS);
    }

    /// The three-way classification of a REFERENCE return, which is the whole
    /// of how the cold arm keeps W6-1 without the site's descriptor.
    ///
    /// The middle row is the one that is easy to lose: a site returning
    /// `java/lang/Number` must NOT bind, because whether a box satisfies it
    /// depends on which wrapper arrived (`Integer` yes, `Character` no) and
    /// neither reference slot can answer that. Binding it as `REF_STRICT`
    /// would throw where HotSpot does not.
    #[test]
    fn a_reference_return_is_classified_three_ways() {
        assert_eq!(
            varhandle_read_helper_slot("get", "(Ljava/lang/Object;)Ljava/lang/Object;"),
            Some(VARHANDLE_READ_KIND_REF_OBJECT),
        );
        for accepting in VARHANDLE_BOX_ACCEPTING_RETURNS {
            let desc = format!("(Ljava/lang/Object;)L{accepting};");
            assert_eq!(
                varhandle_read_helper_slot("get", &desc),
                None,
                "{accepting} accepts SOME box, so its site cannot be REF_STRICT",
            );
        }
        for strict in [
            "java/lang/String",
            "java/lang/CharSequence",
            "java/util/concurrent/CompletableFuture$Completion",
            "HibfixVarHandleProbe$Node",
        ] {
            let desc = format!("(Ljava/lang/Object;)L{strict};");
            assert_eq!(
                varhandle_read_helper_slot("get", &desc),
                Some(VARHANDLE_READ_KIND_REF_STRICT),
                "{strict} accepts no box and must bind strictly",
            );
        }
    }

    /// The kill switch reaches the recogniser itself, so all three doors refuse
    /// together — and it must leave the PRIMITIVE half alone, which is the
    /// whole reason it is a separate switch from the read bind's own.
    ///
    /// Read through the recogniser rather than the `OnceLock`, because the
    /// process-wide latch cannot be flipped twice in one test binary.
    #[test]
    fn the_reference_half_has_its_own_switch() {
        // The switch is a `OnceLock` on an env var, so this test asserts the
        // SHAPE of the decision the recogniser makes, not the latch: a slot
        // >= VARHANDLE_READ_RETURNS.len() is a reference kind, and every one of
        // them is reached through the `varhandle_ref_read_direct_enabled()`
        // arm, while no primitive kind is.
        let primitive = varhandle_read_helper_slot("get", "(Ljava/lang/Object;)I").unwrap();
        assert!(!varhandle_read_slot_is_reference(primitive));
        for desc in [
            "(Ljava/lang/Object;)Ljava/lang/Object;",
            "(Ljava/lang/Object;)Ljava/lang/String;",
        ] {
            let slot = varhandle_read_helper_slot("get", desc)
                .expect("the reference kinds bind by default");
            assert!(varhandle_read_slot_is_reference(slot), "{desc}");
        }
    }

    /// `varhandle_read_slot_return` is what three emit sites now use in place
    /// of the old `slot % RETURNS.len()`, and it has to agree with the
    /// descriptor the slot's synthetic call site carries.
    #[test]
    fn a_slots_return_byte_matches_its_descriptor() {
        for (slot, desc, _) in canonical_descriptors() {
            let want = desc.as_bytes()[desc.find(')').unwrap() + 1];
            assert_eq!(
                varhandle_read_slot_return(slot),
                want,
                "slot {slot} ({desc})",
            );
        }
        assert_eq!(varhandle_read_slot_mode(VARHANDLE_READ_SLOTS - 1), 3);
        assert_eq!(
            varhandle_read_slot_kind(VARHANDLE_READ_SLOTS - 1),
            VARHANDLE_READ_KIND_REF_STRICT
        );
    }

    /// The shapes that must NOT bind, each for its own reason.
    ///
    /// This is the whole correctness argument for using the descriptor as the
    /// instance-field test, so every family that reads through a `VarHandle`
    /// with a different coordinate list is listed explicitly rather than
    /// summarised. A regression here does not fail loudly — it hands a helper
    /// that assumes `[handle, receiver]` an argument list of a different
    /// shape.
    #[test]
    fn only_a_single_reference_coordinate_with_a_servable_return_binds() {
        // A static-field handle: no coordinates at all.
        assert_eq!(varhandle_read_helper_slot("get", "()I"), None);
        // An array-element handle: (array, index).
        assert_eq!(varhandle_read_helper_slot("get", "([II)I"), None);
        // A byte-array / ByteBuffer view handle: (container, byte offset).
        assert_eq!(varhandle_read_helper_slot("get", "([BI)J"), None);
        assert_eq!(
            varhandle_read_helper_slot("get", "(Ljava/nio/ByteBuffer;I)J"),
            None
        );
        // A MemorySegment handle: (segment, long offset).
        assert_eq!(
            varhandle_read_helper_slot("get", "(Ljava/lang/foreign/MemorySegment;J)I"),
            None
        );
        // Two reference coordinates.
        assert_eq!(
            varhandle_read_helper_slot("get", "(Ljava/lang/Object;Ljava/lang/Object;)I"),
            None
        );
        // A primitive coordinate is not an instance-field receiver.
        assert_eq!(varhandle_read_helper_slot("get", "(I)I"), None);
        // An ARRAY return is still out of scope: it is outside
        // `varhandle_reference_return_mismatch`'s fire set today, so neither
        // reference kind describes it and a stand-in would have to reproduce
        // that exclusion for no measured caller.
        assert_eq!(
            varhandle_read_helper_slot("get", "(Ljava/lang/Object;)[I"),
            None
        );
        assert_eq!(
            varhandle_read_helper_slot("get", "(Ljava/lang/Object;)[Ljava/lang/String;"),
            None
        );
        // Two object descriptors run together is not one return type.
        assert_eq!(
            varhandle_read_helper_slot("get", "(Ljava/lang/Object;)Lfoo;Lbar;"),
            None
        );
        // `void` is not a read.
        assert_eq!(
            varhandle_read_helper_slot("get", "(Ljava/lang/Object;)V"),
            None
        );
        // Write and read-modify-write modes are not read modes.
        for name in [
            "set",
            "setVolatile",
            "setRelease",
            "getAndAdd",
            "compareAndSet",
        ] {
            assert_eq!(
                varhandle_read_helper_slot(name, "(Ljava/lang/Object;)I"),
                None,
                "{name} bound as a read mode",
            );
        }
    }

    /// An array-TYPED instance field still binds: `[I` as a *coordinate* means
    /// the receiver is an array-valued object reference, which is an ordinary
    /// instance-field read, not the array-ELEMENT handle the row above rejects.
    /// The two are told apart by the coordinate COUNT, and this is the row that
    /// says a stricter "no `[` anywhere" filter would be over-broad.
    #[test]
    fn an_array_typed_receiver_is_still_one_reference_coordinate() {
        assert!(varhandle_read_helper_slot("get", "([Ljava/lang/String;)I").is_some());
        assert!(varhandle_read_helper_slot("get", "([[B)J").is_some());
        assert_eq!(
            varhandle_read_helper_slot("get", "([Ljava/lang/String;I)I"),
            None
        );
    }

    /// The cells default to "not wired", and `set_varhandle_read_direct_fns`
    /// lands each address on the slot the recognition will look it up under.
    ///
    /// The failure this catches is an off-by-one or reversed registration
    /// order, which would not fail to compile and would not fail loudly: a
    /// `get`-returning-`I` site would call the helper whose baked slot says
    /// `getAcquire` returning `Z`, and read the right field with the wrong
    /// return kind.
    #[test]
    fn the_slots_are_registered_in_recognition_order() {
        let addrs: [usize; VARHANDLE_READ_SLOTS] = std::array::from_fn(|i| 0x1000 + i * 0x10);
        let table = DirectHelperTable {
            varhandle_read: addrs,
            ..DirectHelperTable::EMPTY
        };
        for (_, desc, name) in canonical_descriptors() {
            let slot = varhandle_read_helper_slot(name, &desc).unwrap();
            assert_eq!(
                table.varhandle_read[slot], addrs[slot],
                "{name}{desc} -> slot {slot}"
            );
        }
        assert!(DirectHelperTable::EMPTY
            .varhandle_read
            .iter()
            .all(|&a| a == 0));
    }

    /// The two door counters are separate, so `VarHandle.read=N/0` reports two
    /// facts. The OSR column is the load-bearing one — netty reads `refCnt`
    /// inside loop bodies — and a single-pass-only bind reporting a non-zero
    /// total would otherwise read as success.
    #[test]
    fn the_two_varhandle_door_counters_are_separate() {
        let (before_sp, before_osr) = varhandle_read_direct_helper_sites();
        VARHANDLE_READ_SITES_SINGLEPASS.fetch_add(2, std::sync::atomic::Ordering::Relaxed);
        let (mid_sp, mid_osr) = varhandle_read_direct_helper_sites();
        assert_eq!(mid_sp, before_sp + 2);
        assert_eq!(
            mid_osr, before_osr,
            "bumping single-pass moved the OSR tally"
        );
        VARHANDLE_READ_SITES_OSR.fetch_add(7, std::sync::atomic::Ordering::Relaxed);
        let (end_sp, end_osr) = varhandle_read_direct_helper_sites();
        assert_eq!(end_sp, before_sp + 2);
        assert_eq!(end_osr, before_osr + 7);
    }
}

// ---------------------------------------------------------------------------
// Retirement-queue quiescence — RT-3
// ---------------------------------------------------------------------------

/// The retirement queue's release predicate, tested as a predicate.
///
/// `ThreadQuiescenceEvidence`, `BlockedStackSummary` and
/// `classify_thread_quiescence` are private to this file, so none of this can
/// be an integration test; that is why it lives here rather than in
/// `jit/tests/`.
///
/// # The plan this replaces, and why it was wrong
///
/// `NOTES-runtime.md` RT-3 asked for boundary cases "`entry` itself,
/// `entry + len - 1`, `entry + len` (must permit), `entry - 1` (must permit)".
/// There is no `len` in this decision. `BlockedStackSummary::buffers` holds
/// the sorted, deduplicated STARTS of the buffers a stack word points into —
/// the range containment happened in `collect_code_buffers_in_band`, which
/// mapped each word to its owning buffer's start. `permits_stamp` does an
/// exact-match `binary_search` on those starts and never sees a length. A test
/// built on `entry + len - 1` would have asserted a property of a different
/// design, and would have passed for the wrong reason.
///
/// The boundaries below are the ones `binary_search` actually has: the first
/// element, an interior element, the last element, a value below the first,
/// between two, and above the last, and an empty list. One of them —
/// `0x1001`, one byte past a present start — is deliberately the shape the old
/// plan would have written, and it must PERMIT.
#[cfg(test)]
mod retirement_quiescence_tests {
    use super::{
        classify_thread_quiescence, BlockedStackSummary, JitThreadQuiescence,
        ThreadQuiescenceEvidence,
    };
    use std::sync::atomic::{AtomicU32, AtomicU64, AtomicUsize};
    use std::sync::Arc;

    fn evidence(min_running_gen: u64, blocked: Vec<(u64, Vec<usize>)>) -> ThreadQuiescenceEvidence {
        ThreadQuiescenceEvidence {
            min_running_gen,
            min_running_ic_gen: min_running_gen,
            blocked,
        }
    }

    /// A thread record in a chosen state. `blocked` is `Some(buffers)` for a
    /// thread parked inside compiled code whose stack scan COMPLETED.
    fn thread_record(
        depth: usize,
        quiescent_gen: u64,
        blocked: Option<Vec<usize>>,
    ) -> Arc<JitThreadQuiescence> {
        let valid = blocked.is_some();
        Arc::new(JitThreadQuiescence {
            depth: AtomicUsize::new(depth),
            quiescent_gen: AtomicU64::new(quiescent_gen),
            ic_quiescent_gen: AtomicU64::new(0),
            blocked_nesting: AtomicU32::new(u32::from(valid)),
            blocked: parking_lot::Mutex::new(BlockedStackSummary {
                valid,
                buffers: blocked.unwrap_or_default(),
                pending: None,
            }),
        })
    }

    /// A thread inside a blocked window whose scan did NOT complete — the band
    /// was larger than `collect_code_buffers_in_band` will walk — so the
    /// partial buffer list is not a statement about its stack.
    fn thread_record_with_unusable_scan(
        depth: usize,
        quiescent_gen: u64,
        partial: Vec<usize>,
    ) -> Arc<JitThreadQuiescence> {
        Arc::new(JitThreadQuiescence {
            depth: AtomicUsize::new(depth),
            quiescent_gen: AtomicU64::new(quiescent_gen),
            ic_quiescent_gen: AtomicU64::new(0),
            blocked_nesting: AtomicU32::new(1),
            blocked: parking_lot::Mutex::new(BlockedStackSummary {
                valid: false,
                buffers: partial,
                pending: None,
            }),
        })
    }

    /// nio21 wave 17 L3: a lazy summary's band is scanned by the drain, under
    /// the summary lock, against the region snapshot captured at the
    /// transition -- and answers what the eager scan answers for the same
    /// band (sorted, deduplicated buffer starts; the last-region memo agrees
    /// with the binary search).
    #[test]
    fn w17_l3_lazy_blocked_summary_is_resolved_by_the_drain() {
        let regions = Arc::new(vec![(0x1000usize, 0x2000usize), (0x5000, 0x6000)]);
        let band: [usize; 7] = [0x1004, 7, 0x5008, 0x1ff0, 0x3000, 0x5000, 0x1004];
        let lo = band.as_ptr() as usize;
        let hi = lo + std::mem::size_of_val(&band);
        let lazy = Arc::new(JitThreadQuiescence {
            depth: AtomicUsize::new(1),
            quiescent_gen: AtomicU64::new(3),
            ic_quiescent_gen: AtomicU64::new(0),
            blocked_nesting: AtomicU32::new(1),
            blocked: parking_lot::Mutex::new(BlockedStackSummary {
                valid: true,
                buffers: vec![0xdead],
                pending: Some(super::PendingBlockedBand {
                    lo,
                    hi,
                    regions: Arc::clone(&regions),
                }),
            }),
        });
        let e = classify_thread_quiescence(0, std::slice::from_ref(&lazy)).expect("evidence");
        assert_eq!(e.blocked, vec![(3, vec![0x1000, 0x5000])]);
        assert_eq!(
            e.min_running_gen,
            u64::MAX,
            "a resolved band is blocked evidence"
        );
        // Resolved once: the band is gone and the answer stays.
        assert!(lazy.blocked.lock().pending.is_none());
        let again = classify_thread_quiescence(0, std::slice::from_ref(&lazy)).expect("evidence");
        assert_eq!(again.blocked, vec![(3, vec![0x1000, 0x5000])]);
        // The eager scan over the same band and snapshot agrees.
        let mut eager = Vec::new();
        // SAFETY: `band` is a live local array.
        assert!(unsafe { super::scan_code_buffers_in_band(lo, hi, &regions, &mut eager) });
        assert_eq!(eager, vec![0x1000, 0x5000]);
        std::hint::black_box(&band);

        // A band too large to scan leaves the thread counted as running.
        let too_large = Arc::new(JitThreadQuiescence {
            depth: AtomicUsize::new(1),
            quiescent_gen: AtomicU64::new(4),
            ic_quiescent_gen: AtomicU64::new(0),
            blocked_nesting: AtomicU32::new(1),
            blocked: parking_lot::Mutex::new(BlockedStackSummary {
                valid: true,
                buffers: Vec::new(),
                pending: Some(super::PendingBlockedBand {
                    lo: 0x10_0000,
                    hi: 0x10_0000 + super::MAX_BLOCKED_BAND_BYTES + 8,
                    regions,
                }),
            }),
        });
        let e = classify_thread_quiescence(0, std::slice::from_ref(&too_large)).expect("evidence");
        assert!(e.blocked.is_empty());
        assert_eq!(e.min_running_gen, 4);
    }

    // -- 1. `permits_stamp` as a pure predicate --------------------------

    /// Arm (a): the running bound is a veto, not a vote. A body queued after
    /// some running thread's last return to depth 0 is held whatever the
    /// blocked evidence says — including blocked evidence that would permit it
    /// on its own. Catches a rewrite of the `&&` into an `||`.
    #[test]
    fn a_body_retired_after_a_running_threads_last_return_is_never_released() {
        assert!(!evidence(4, Vec::new()).permits_stamp(5, 0x1000));
        assert!(!evidence(4, vec![(9, vec![0x2000])]).permits_stamp(5, 0x1000));
        // Equality releases: the thread stood at depth 0 AT the stamp, which
        // is after the caller unpublished the body.
        assert!(evidence(5, Vec::new()).permits_stamp(5, 0x1000));
    }

    /// Arm (b), the "it has been out since" arm: a blocked thread whose
    /// `quiescent_gen` is at or past the body's stamp permits it without the
    /// buffer list being consulted at all — here the list names the body and
    /// it is released anyway. Without this arm a parked thread would pin every
    /// body whose address a scan older than the retirement still mentions.
    #[test]
    fn a_blocked_thread_out_since_the_stamp_permits_whatever_its_stack_holds() {
        assert!(evidence(u64::MAX, vec![(7, vec![0x1000])]).permits_stamp(7, 0x1000));
        // One generation earlier and the list decides instead.
        assert!(!evidence(u64::MAX, vec![(6, vec![0x1000])]).permits_stamp(7, 0x1000));
    }

    /// Arm (c), and the boundaries `binary_search` really has.
    ///
    /// `0x1001` is the important one: one byte past a start that IS on the
    /// list. It must PERMIT, because the list holds identities and not ranges.
    /// A future rewrite that reintroduced `[entry, entry + len)` containment
    /// here — the design `NOTES-runtime.md` RT-3 assumed — would answer "held"
    /// and fail this line.
    #[test]
    fn a_blocked_threads_buffer_list_is_searched_by_exact_start() {
        let e = evidence(
            u64::MAX,
            vec![(1, vec![0x1000usize, 0x3000, 0x5000, 0x9000])],
        );
        for present in [0x1000usize, 0x5000, 0x9000] {
            assert!(
                !e.permits_stamp(9, present),
                "{present:#x} is on the blocked thread's list and must pin the body"
            );
        }
        for absent in [0x0fffusize, 0x1001, 0x4000, 0x9001, usize::MAX] {
            assert!(
                e.permits_stamp(9, absent),
                "{absent:#x} is not a recorded buffer START, so nothing on that \
                 stack can return into it"
            );
        }
    }

    /// An empty buffer list permits. A thread can be inside compiled code by
    /// depth and have no word of its scanned band point into any executable
    /// buffer — parked in a helper, say. `binary_search` on an empty slice is
    /// `Err(0)`, which is the answer this relies on, and a rewrite to
    /// `!buffers.is_empty() && ..` would invert it and pin the whole queue.
    #[test]
    fn a_blocked_thread_whose_scan_found_no_code_permits() {
        assert!(evidence(u64::MAX, vec![(1, Vec::new())]).permits_stamp(9, 0x1000));
    }

    /// With no blocked threads the decision is `min_running_gen` alone —
    /// `all` over an empty iterator is `true`. Pinned because it is what makes
    /// the first conjunct load-bearing.
    #[test]
    fn no_blocked_threads_leaves_the_running_bound_in_charge() {
        assert!(evidence(9, Vec::new()).permits_stamp(9, 0x1000));
        assert!(!evidence(8, Vec::new()).permits_stamp(9, 0x1000));
    }

    /// `all`, not `any`. Two blocked threads, the first permitting on every
    /// ground and the second holding the buffer: the body stays. An `any`
    /// would pass every single-thread case above and free bodies under the
    /// second thread here, which is the shape this test exists to catch.
    #[test]
    fn one_blocked_thread_that_holds_the_body_is_enough_to_keep_it() {
        let e = evidence(u64::MAX, vec![(99, vec![0x1000]), (1, vec![0x1000])]);
        assert!(!e.permits_stamp(9, 0x1000));
    }

    /// Staleness (the note's item 2, restated against this predicate): a
    /// summary five generations older than the body may not release it on the
    /// strength of its generation. Only genuine absence from the list may.
    #[test]
    fn a_summary_older_than_the_body_releases_only_on_absence() {
        let e = evidence(u64::MAX, vec![(2, vec![0x1000])]);
        assert!(!e.permits_stamp(7, 0x1000), "present on a stale list: held");
        assert!(
            e.permits_stamp(7, 0x2000),
            "absent from that same list: free"
        );
    }

    // -- 2. the fail-closed arm, one function up -------------------------

    /// The fail-closed edge, and the one a test can get wrong in the
    /// safe-looking direction. `None` and "evidence with nothing in it" are
    /// OPPOSITES: the latter has `min_running_gen == u64::MAX` and no blocked
    /// threads, so it permits every body in the queue. This asserts both — the
    /// untracked arm answers `None`, and the value it would otherwise have
    /// returned releases everything.
    #[test]
    fn an_untracked_jit_execution_yields_no_evidence_at_all() {
        assert!(classify_thread_quiescence(1, &[]).is_none());
        let running = thread_record(1, 3, None);
        assert!(classify_thread_quiescence(1, std::slice::from_ref(&running)).is_none());

        let empty = classify_thread_quiescence(0, &[])
            .expect("zero untracked executions must yield evidence");
        assert!(
            empty.permits_stamp(u64::MAX, 0x1000),
            "a process with no thread inside compiled code releases everything — \
             which is exactly why the untracked arm must answer `None` and not \
             this value"
        );
    }

    /// A thread at depth 0 vouches for itself and contributes nothing. Its
    /// `quiescent_gen` must NOT be folded into `min_running_gen`: one
    /// long-idle thread would otherwise hold the entire queue for the life of
    /// the process, which is the bug the per-thread records were added for.
    #[test]
    fn a_thread_at_depth_zero_contributes_nothing() {
        let idle = thread_record(0, 0, None);
        let e = classify_thread_quiescence(0, std::slice::from_ref(&idle)).unwrap();
        assert_eq!(e.min_running_gen, u64::MAX);
        assert!(e.blocked.is_empty());
        assert!(e.permits_stamp(9, 0x1000));
    }

    /// The second inversion. `valid == false` means the scan did not complete,
    /// so the partial buffer list says nothing about this thread's stack. It
    /// must be routed into `min_running_gen`, where it BOUNDS releases, and
    /// never onto `blocked`, where the same thread would instead permit every
    /// body its partial list happens to miss. `0x2000` below is exactly such a
    /// body: the blocked arm would have released it.
    #[test]
    fn a_blocked_window_with_an_unusable_scan_counts_as_running() {
        let torn = thread_record_with_unusable_scan(1, 4, vec![0x1000]);
        let e = classify_thread_quiescence(0, std::slice::from_ref(&torn)).unwrap();
        assert!(
            e.blocked.is_empty(),
            "an incomplete scan is not evidence of quiescence"
        );
        assert_eq!(e.min_running_gen, 4);
        assert!(!e.permits_stamp(5, 0x2000));
        assert!(e.permits_stamp(4, 0x2000));
    }

    /// A valid blocked summary is carried through with its own generation, and
    /// does not bound the running side. Both halves matter: folding a blocked
    /// thread into `min_running_gen` would be safe but would give back the
    /// whole benefit, and dropping its generation would lose arm (b).
    #[test]
    fn a_valid_blocked_summary_is_carried_through_with_its_generation() {
        let parked = thread_record(1, 4, Some(vec![0x1000, 0x3000]));
        let e = classify_thread_quiescence(0, std::slice::from_ref(&parked)).unwrap();
        assert_eq!(
            e.min_running_gen,
            u64::MAX,
            "a blocked thread must not bound the running side"
        );
        assert_eq!(e.blocked, vec![(4u64, vec![0x1000usize, 0x3000])]);
    }

    /// A running thread with a miss-handler stamp (round 14 wave 2, lane mic,
    /// M8-1). `blocked` as in [`thread_record`].
    fn thread_record_with_ic_stamp(
        depth: usize,
        quiescent_gen: u64,
        ic_quiescent_gen: u64,
        blocked: Option<Vec<usize>>,
    ) -> Arc<JitThreadQuiescence> {
        let record = thread_record(depth, quiescent_gen, blocked);
        record
            .ic_quiescent_gen
            .store(ic_quiescent_gen, std::sync::atomic::Ordering::Relaxed);
        record
    }

    /// M8-1's two minima must never be confused. A thread spinning in compiled
    /// code that last returned to depth 0 at 3 and entered a miss handler at 9
    /// bounds the inline-cache grace at 9 and code release at 3: a body retired
    /// at 5 may still be on its stack, so `permits_stamp` (the release
    /// decision, which reads `min_running_gen` only) must hold it.
    #[test]
    fn a_miss_handler_stamp_bounds_the_ic_grace_but_never_code_release() {
        let spinner = thread_record_with_ic_stamp(1, 3, 9, None);
        let e = classify_thread_quiescence(0, std::slice::from_ref(&spinner)).unwrap();
        assert_eq!(e.min_running_gen, 3);
        assert_eq!(e.min_running_ic_gen, 9);
        assert!(
            !e.permits_stamp(5, 0x1000),
            "a miss-handler stamp is not evidence the thread left the body"
        );
    }

    /// The later stamp wins in either order, and the minimum is over threads:
    /// one thread with no miss-handler stamp at all bounds the grace at its
    /// depth-0 stamp, which is the pre-M8-1 value (what the kill switch
    /// `CRATONVM_JIT_IC_QUIESCENT_STAMP=0` leaves: every stamp `0`).
    #[test]
    fn the_ic_bound_is_the_minimum_over_threads_of_the_later_stamp() {
        let stale_ic = thread_record_with_ic_stamp(1, 7, 2, None);
        let e = classify_thread_quiescence(0, std::slice::from_ref(&stale_ic)).unwrap();
        assert_eq!(e.min_running_ic_gen, 7);

        let fresh = thread_record_with_ic_stamp(1, 1, 12, None);
        let unstamped = thread_record(2, 4, None);
        let e = classify_thread_quiescence(0, &[fresh, unstamped]).unwrap();
        assert_eq!(e.min_running_gen, 1);
        assert_eq!(e.min_running_ic_gen, 4);

        let never = thread_record(1, 6, None);
        let e = classify_thread_quiescence(0, std::slice::from_ref(&never)).unwrap();
        assert_eq!(e.min_running_ic_gen, e.min_running_gen);
    }

    /// Blocked and idle threads bound neither minimum, whatever their
    /// miss-handler stamp says.
    #[test]
    fn blocked_and_idle_threads_leave_the_ic_bound_alone() {
        let parked = thread_record_with_ic_stamp(1, 2, 3, Some(vec![0x1000]));
        let idle = thread_record_with_ic_stamp(0, 0, 0, None);
        let e = classify_thread_quiescence(0, &[parked, idle]).unwrap();
        assert_eq!(e.min_running_gen, u64::MAX);
        assert_eq!(e.min_running_ic_gen, u64::MAX);
    }

    /// The whole reason the per-thread proof exists, end to end over the two
    /// functions: a pool worker parked forever inside compiled code releases
    /// every body it is not parked inside. Before these records,
    /// `ACTIVE_JIT_EXECUTIONS` stayed non-zero and the queue never drained
    /// until the code-cache cap refused every compile.
    #[test]
    fn a_worker_parked_inside_compiled_code_does_not_pin_unrelated_bodies() {
        let parked = thread_record(1, 2, Some(vec![0xAAAA_0000]));
        let e = classify_thread_quiescence(0, std::slice::from_ref(&parked)).unwrap();
        assert!(
            e.permits_stamp(7, 0xBBBB_0000),
            "an unrelated body must be releasable while the worker stays parked"
        );
        assert!(
            !e.permits_stamp(7, 0xAAAA_0000),
            "the body it is parked inside must not be"
        );
    }
}

/// Round 14 wave 7 (lane mega): [`jit_ic_grace_catch_up`] re-stamps the
/// refusing thread before it collects the evidence
/// (`CRATONVM_JIT_IC_CATCH_UP_SELF_STAMP`). Each test runs on its own fresh
/// thread, so its record starts unstamped (`ic_quiescent_gen == 0`) and its
/// catch-up countdown at zero (the first call proves). Only this thread's own
/// record is read; the generations are process-wide and only compared with
/// `>=` against a value read before the call (they never go down).
#[cfg(test)]
mod r14w7_mega_catch_up_self_stamp_tests {
    use super::{jit_ic_grace_catch_up, JIT_RETIRE_GENERATION, THREAD_QUIESCENCE};
    use std::sync::atomic::Ordering;

    fn own_ic_stamp() -> u64 {
        THREAD_QUIESCENCE.with(|h| h.record.ic_quiescent_gen.load(Ordering::Acquire))
    }

    #[test]
    fn a_catch_up_vouches_for_the_refusing_thread_first() {
        THREAD_QUIESCENCE.with(|h| {
            h.ic_stamp_flag.set(2);
            h.ic_catch_up_self_stamp_flag.set(2);
        });
        assert_eq!(
            own_ic_stamp(),
            0,
            "a fresh thread has no miss-handler stamp"
        );
        let before = JIT_RETIRE_GENERATION.load(Ordering::Acquire);
        let _ = jit_ic_grace_catch_up();
        assert!(
            own_ic_stamp() >= before,
            "the refusing thread must not bound its own catch-up with a stale stamp"
        );
    }

    #[test]
    fn the_kill_switch_leaves_the_stamp_to_the_miss_handlers() {
        THREAD_QUIESCENCE.with(|h| {
            h.ic_stamp_flag.set(2);
            h.ic_catch_up_self_stamp_flag.set(1);
        });
        let _ = jit_ic_grace_catch_up();
        assert_eq!(own_ic_stamp(), 0);
    }
}

// ---------------------------------------------------------------------------
// Code-cache cold-body sweep — RT-8
// ---------------------------------------------------------------------------

/// The sweep POLICY, over synthetic censuses.
///
/// Everything around the policy needs real compiled artifacts: a
/// `CompiledMethod` cannot be built without running a compile, and an
/// end-to-end test of an evictor is the worst kind of vacuous, because "it
/// retired nothing" is both the healthy outcome and what a permanently-refusing
/// sweeper looks like. `CodeCacheSweepState::plan` is the decision with the
/// artifacts replaced by the three numbers it reads from each of them, so each
/// arm below fails for a stated reason when the arm is removed.
#[cfg(test)]
mod code_cache_sweep_tests {
    use super::{
        code_cache_sweep_enabled, CodeCacheSweepState, CompiledMethod, ExecutableBuffer, JitCache,
        JitCodeCacheSweepRefusal,
    };

    /// `(artifact_id, entry count, entry address)`, as `sweep_cold_bodies`
    /// builds it from the live set, with the total the caller also computes.
    fn census(rows: &[(u64, u64, usize)]) -> (Vec<(u64, u64, usize)>, u64) {
        (rows.to_vec(), rows.iter().map(|&(_, count, _)| count).sum())
    }

    /// The first sweep of a cache retires nothing, however cold everything
    /// looks. There is only one reading, so "has not moved" is not yet a
    /// statement about anything — and a body compiled between the cap being
    /// hit and this call has by construction not been entered. Without this
    /// arm the very first sweep would withdraw the entire cache.
    #[test]
    fn the_first_sweep_only_takes_a_census() {
        let mut state = CodeCacheSweepState::default();
        let (live, total) = census(&[(1, 0, 0x1000), (2, 0, 0x2000)]);
        let (doomed, refusal) = state.plan(&live, total, 0);
        assert!(doomed.is_empty());
        assert_eq!(refusal, Some(JitCodeCacheSweepRefusal::FirstSweepIsACensus));
        assert_eq!(state.sweeps, 1, "the census still counts as a sweep");
        assert_eq!(state.seen.len(), 2, "and it still records both readings");
    }

    /// The rate limit. Two sweeps with NOTHING between them -- no body entered,
    /// no progress on the caller's clock -- see identical readings, and the
    /// ENTIRE cache would qualify as "has not moved". Removing this arm turns
    /// a back-to-back second call into a full flush.
    #[test]
    fn a_sweep_with_nothing_run_since_the_last_is_refused() {
        let mut state = CodeCacheSweepState::default();
        let (live, total) = census(&[(1, 4, 0x1000), (2, 6, 0x2000)]);
        state.plan(&live, total, 0);
        let (doomed, refusal) = state.plan(&live, total, 0);
        assert!(doomed.is_empty());
        assert_eq!(
            refusal,
            Some(JitCodeCacheSweepRefusal::NothingRanSinceTheLastSweep)
        );
        assert_eq!(state.sweeps, 1, "a refused sweep must not count as one");
    }

    /// **The RT-8 soak's finding.** The program moved on: the interpreter ran
    /// (the clock advanced) and not one compiled body was entered. That is the
    /// phase change at the cap -- new code is refused compilation and runs
    /// interpreted, old code is dead -- and every body in the cache is cold.
    ///
    /// Before 2026-09-18 the rate limit read "no body entered" as "nothing
    /// ran" and refused here, on every sweep, for the life of the process:
    /// `tools/probes/SweepPhases` at a 1 MiB cap swept once in 30 s and then
    /// never again. Make the refusal ignore the clock and this fails.
    #[test]
    fn an_idle_cache_is_swept_when_the_process_moved_on_without_it() {
        let mut state = CodeCacheSweepState::default();
        let (live, total) = census(&[(1, 4, 0x1000), (2, 6, 0x2000)]);
        state.plan(&live, total, 100);
        let (doomed, refusal) = state.plan(&live, total, 356);
        assert_eq!(refusal, None, "the process ran; this is not the idle case");
        assert_eq!(
            doomed.len(),
            2,
            "no body was entered, so every body is cold"
        );
    }

    /// The policy itself: of two bodies, the one whose counter stood still
    /// while the other ran is the cold one. This is the whole difference
    /// between this policy and "least-invoked" — `0x1000` has been entered
    /// FOUR times and `0x2000` only twice, and it is `0x1000` that goes,
    /// because a count is a history and a delta is a recency.
    #[test]
    fn only_bodies_whose_count_did_not_move_are_swept() {
        let mut state = CodeCacheSweepState::default();
        let (first, first_total) = census(&[(1, 4, 0x1000), (2, 2, 0x2000)]);
        state.plan(&first, first_total, 0);
        let (second, second_total) = census(&[(1, 4, 0x1000), (2, 9, 0x2000)]);
        let (doomed, refusal) = state.plan(&second, second_total, 0);
        assert_eq!(refusal, None);
        assert_eq!(doomed.len(), 1);
        assert!(doomed.contains(&0x1000));
        assert!(!doomed.contains(&0x2000));
    }

    /// A body published since the last sweep has no previous reading, and "no
    /// previous reading" must not read as "has not moved". It is the method
    /// that just went hot enough to be compiled, so sweeping it is both the
    /// most expensive possible mistake and an invisible one — it would simply
    /// be recompiled and swept again, forever.
    #[test]
    fn a_body_first_seen_on_this_sweep_is_never_a_candidate() {
        let mut state = CodeCacheSweepState::default();
        let (first, first_total) = census(&[(1, 5, 0x1000), (3, 1, 0x3000)]);
        state.plan(&first, first_total, 0);
        let (second, second_total) = census(&[(1, 5, 0x1000), (2, 0, 0x2000), (3, 4, 0x3000)]);
        let (doomed, _) = state.plan(&second, second_total, 0);
        assert!(
            !doomed.contains(&0x2000),
            "artifact 2 is new; its count of 0 is not evidence of coldness"
        );
        assert!(doomed.contains(&0x1000), "artifact 1 genuinely stood still");
    }

    /// The snapshot is keyed on `artifact_id`, not on the entry ADDRESS, and
    /// this is the test that says why. An executable buffer is recycled to the
    /// next compile of a similar size, so an address-keyed snapshot is an ABA:
    /// here a brand-new artifact 9 lands on the address artifact 1 vacated,
    /// with the same count artifact 1 had. Keyed on the address it would match
    /// and be swept on its first sweep; keyed on the id it is simply unknown.
    #[test]
    fn the_snapshot_is_keyed_on_artifact_id_not_the_recycled_entry_address() {
        let mut state = CodeCacheSweepState::default();
        let (first, first_total) = census(&[(1, 5, 0x1000), (7, 2, 0x7000)]);
        state.plan(&first, first_total, 0);
        let (second, second_total) = census(&[(9, 5, 0x1000), (7, 3, 0x7000)]);
        let (doomed, _) = state.plan(&second, second_total, 0);
        assert!(
            doomed.is_empty(),
            "the artifact at 0x1000 is a different one from the artifact the \
             previous reading of 0x1000 described"
        );
    }

    /// The snapshot is rebuilt from the live set, so it cannot grow without
    /// bound as artifacts come and go. `artifact_id` is monotonic and never
    /// repeats, so an update-in-place map would only ever accumulate.
    #[test]
    fn the_snapshot_holds_only_bodies_that_are_still_live() {
        let mut state = CodeCacheSweepState::default();
        let (first, first_total) = census(&[(1, 1, 0x1000), (2, 1, 0x2000), (3, 1, 0x3000)]);
        state.plan(&first, first_total, 0);
        assert_eq!(state.seen.len(), 3);
        let (second, second_total) = census(&[(4, 9, 0x4000)]);
        state.plan(&second, second_total, 0);
        assert_eq!(state.seen.len(), 1);
        assert_eq!(state.seen.get(&4), Some(&9));
    }

    /// Default OFF, and it declines before taking the census — a sweeper that
    /// walked every published body to then do nothing would be paying the
    /// whole cost of the feature in a configuration that does not have it.
    #[test]
    fn the_sweeper_is_off_by_default_and_declines_before_looking() {
        if code_cache_sweep_enabled() {
            eprintln!(
                "CRATONVM_JIT_CODE_CACHE_SWEEP is set in this process; this test \
                 is about the DEFAULT and has nothing to assert here"
            );
            return;
        }
        let cache = JitCache::new();
        let report = cache.sweep_cold_bodies(1);
        assert_eq!(
            report.refused,
            Some(JitCodeCacheSweepRefusal::Disabled),
            "the sweeper must refuse explicitly, not return an empty report — \
             'disabled' and 'nothing was cold' are different facts"
        );
        assert_eq!(report.observed, 0);
        assert_eq!(
            cache.code_cache_sweeps(),
            0,
            "a disabled sweeper must not even advance the sweep state"
        );
    }

    /// **RT-8's stuck-at-C1 residual, closed.**
    ///
    /// `invalidate_matching` withdraws the transitive reverse closure over
    /// baked direct calls: evict a cold callee and every caller that baked a
    /// direct call into it goes too. Those closure members used to be computed
    /// inside that function and thrown away, so the sweeper -- which pre-scanned
    /// the shard maps for its own cold CANDIDATES -- reported only the
    /// candidates. A caller withdrawn this way lost its body and was never
    /// handed to `note_body_withdrawn`, and since `current_tier` only advances
    /// it could never be offered for compilation again.
    ///
    /// Here `caller` is not cold and does not match the predicate. It is
    /// withdrawn anyway, because it baked a direct call into `callee`. The
    /// assertion is that it comes BACK -- `withdrawn` must account for `swept`,
    /// not for the predicate.
    #[test]
    fn the_reverse_closure_is_reported_and_not_just_withdrawn() {
        use std::sync::Arc;

        let cache = JitCache::new();
        let cid = cratonvm_types::ClassId::new(1);
        let desc: Arc<str> = Arc::from("()V");
        let class: Arc<str> = Arc::from("ClosureReportTest");

        let mut callee_buf = ExecutableBuffer::new(64).expect("executable buffer");
        callee_buf.emit(&[0xC3]);
        let callee_name: Arc<str> = Arc::from("callee");
        cache.put(
            class.clone(),
            callee_name.clone(),
            desc.clone(),
            cid,
            CompiledMethod::new(callee_buf),
        );
        let callee_entry = cache
            .get(&class, &callee_name, &desc, cid)
            .expect("the callee is published")
            .entry_ptr() as usize;

        // The caller bakes a direct call into the callee -- the edge the
        // closure walks.
        let mut caller_buf = ExecutableBuffer::new(64).expect("executable buffer");
        caller_buf.emit(&[0xC3]);
        let mut caller = CompiledMethod::new(caller_buf);
        caller._direct_callee_entries = vec![callee_entry];
        let caller_name: Arc<str> = Arc::from("caller");
        cache.put(
            class.clone(),
            caller_name.clone(),
            desc.clone(),
            cid,
            caller,
        );

        // A third body with no edge to either, so "everything was withdrawn"
        // cannot pass for "the closure was followed".
        let mut other_buf = ExecutableBuffer::new(64).expect("executable buffer");
        other_buf.emit(&[0xC3]);
        let other_name: Arc<str> = Arc::from("unrelated");
        cache.put(
            class.clone(),
            other_name.clone(),
            desc.clone(),
            cid,
            CompiledMethod::new(other_buf),
        );

        // The predicate names ONLY the callee -- exactly what a cold-candidate
        // set looks like to `invalidate_matching`.
        // Read BEFORE the withdrawal: a buffer's capacity is its mapping,
        // rounded up by the allocator, so it is not simply the 64 asked for.
        let capacity_of = |name: &Arc<str>| {
            cache
                .get(&class, name, &desc, cid)
                .expect("published")
                ._buffer
                .capacity() as u64
        };
        let expected_bytes = capacity_of(&callee_name) + capacity_of(&caller_name);

        let (swept, withdrawn, withdrawn_bytes) = cache
            .invalidate_matching_collecting(crate::retire_reason::INVALIDATED, |key, _| {
                &*key.method_name == "callee"
            });
        // Exactly the callee's and the closure member's mappings: a total that
        // omitted the closure would under-count, and one that included
        // `unrelated` would count a body that is still live.
        assert_eq!(
            withdrawn_bytes, expected_bytes,
            "the byte total must be the callee's plus the caller's capacity"
        );

        assert_eq!(
            swept, 2,
            "the callee and the caller that baked a direct call into it",
        );

        let names: Vec<&str> = withdrawn.iter().map(|(_, m, _, _)| &**m).collect();
        assert!(
            names.contains(&"callee"),
            "the candidate itself must be reported; got {names:?}",
        );
        assert!(
            names.contains(&"caller"),
            "THE POINT: the closure member must be reported too, or it loses \
             its body without being demoted and is stuck at its old tier \
             forever. Got {names:?}",
        );
        assert!(
            !names.contains(&"unrelated"),
            "a body with no edge to the candidate must survive; got {names:?}",
        );
        assert_eq!(
            withdrawn.len(),
            swept,
            "`withdrawn` must account for `swept`, which is the property the \
             sweeper's demotion loop depends on",
        );
    }

    /// The empty case allocates nothing and reports nothing.
    ///
    /// This runs on every class define, and the fast path returning
    /// `(0, Vec::new())` is what keeps it free.
    #[test]
    fn a_withdrawal_that_matches_nothing_reports_nothing() {
        use std::sync::Arc;

        let cache = JitCache::new();
        let cid = cratonvm_types::ClassId::new(1);
        let desc: Arc<str> = Arc::from("()V");
        let class: Arc<str> = Arc::from("NoMatchTest");
        let name: Arc<str> = Arc::from("m");
        let mut buf = ExecutableBuffer::new(64).expect("executable buffer");
        buf.emit(&[0xC3]);
        cache.put(
            class.clone(),
            name.clone(),
            desc.clone(),
            cid,
            CompiledMethod::new(buf),
        );

        let (swept, withdrawn, withdrawn_bytes) = cache
            .invalidate_matching_collecting(crate::retire_reason::INVALIDATED, |key, _| {
                &*key.method_name == "absent"
            });
        assert_eq!(swept, 0);
        assert_eq!(withdrawn_bytes, 0, "nothing withdrawn, nothing counted");
        assert!(withdrawn.is_empty());
        assert_eq!(
            withdrawn.capacity(),
            0,
            "the empty path must not allocate -- it is on every class define",
        );
    }
}

