/// Round 9 wave 3, lane `runtime3`: tests for the pages this lane resolved.
#[cfg(test)]
mod r9w3_runtime3_tests {
    use super::*;
    use std::sync::Arc;

    fn push_compile_stack(keys: &[(&str, &str, &str)]) {
        JIT_COMPILE_STACK.with(|stack| {
            let mut stack = stack.borrow_mut();
            for (c, m, d) in keys {
                stack.push(JitCompileMethodKey::new(c, m, d));
            }
        });
    }

    // ── object-hashcode-on-a-string-receiver-pays-the-mic-native-helper ──

    fn receivers_at(pc: usize, counts: &[(u32, u32)]) -> profile::MethodProfile {
        let mut prof = profile::MethodProfile::default();
        let site = prof.receivers.entry(pc).or_default();
        for &(class_id, n) in counts {
            site.insert(class_id, n);
        }
        prof
    }

    const HASH_STRING_ID: u32 = 0x4_0001;

    fn hash_layout() -> StringFieldLayout {
        StringFieldLayout {
            string_class_id: HASH_STRING_ID,
            ..STRING_INTRINSIC_NAME_PROBE
        }
    }

    fn hash_guard(
        class: &str,
        name: &str,
        desc: &str,
        prof: Option<&profile::MethodProfile>,
        pc: usize,
    ) -> Option<u32> {
        object_hashcode_string_guard(class, name, desc, Some(hash_layout()), prof, pc)
    }

    /// Positive evidence only: a String-dominant profile admits the guarded
    /// intrinsic for an `Object`- or `CharSequence`-typed `hashCode()`; a
    /// mixed, thin or missing profile, any other member, and a `String`-typed
    /// site (the ordinary resolver's business) do not.
    #[test]
    fn object_hashcode_takes_the_string_intrinsic_only_on_a_string_dominant_profile() {
        let dominant = receivers_at(7, &[(HASH_STRING_ID, 950), (0x4_0002, 50)]);
        let mixed = receivers_at(7, &[(HASH_STRING_ID, 800), (0x4_0002, 200)]);
        let thin = receivers_at(7, &[(HASH_STRING_ID, MIN_GUARDED_RECEIVER_EVIDENCE - 1)]);
        let obj = "java/lang/Object";
        assert_eq!(
            hash_guard(obj, "hashCode", "()I", Some(&dominant), 7),
            Some(HASH_STRING_ID)
        );
        assert_eq!(
            hash_guard(
                "java/lang/CharSequence",
                "hashCode",
                "()I",
                Some(&dominant),
                7
            ),
            Some(HASH_STRING_ID)
        );
        assert_eq!(hash_guard(obj, "hashCode", "()I", Some(&mixed), 7), None);
        assert_eq!(hash_guard(obj, "hashCode", "()I", Some(&thin), 7), None);
        assert_eq!(hash_guard(obj, "hashCode", "()I", None, 7), None);
        assert_eq!(
            hash_guard(obj, "hashCode", "()I", Some(&dominant), 8),
            None,
            "the evidence is per bci"
        );
        assert_eq!(
            hash_guard(obj, "toString", "()Ljava/lang/String;", Some(&dominant), 7),
            None
        );
        assert_eq!(
            hash_guard("java/lang/String", "hashCode", "()I", Some(&dominant), 7),
            None
        );
        assert_eq!(
            object_hashcode_string_guard(obj, "hashCode", "()I", None, Some(&dominant), 7),
            None,
            "no resolved String layout, nothing to decode with"
        );
        let no_coder = StringFieldLayout {
            has_coder: false,
            ..hash_layout()
        };
        assert_eq!(
            object_hashcode_string_guard(
                obj,
                "hashCode",
                "()I",
                Some(no_coder),
                Some(&dominant),
                7
            ),
            None,
            "the inline decode needs the compact `coder` layout"
        );
    }

    // ── perf-mutual-recursion-forces-every-call-through-invoke-dispatch ──

    /// A cycle closed by a STATICALLY bound edge is recorded, but no longer
    /// forces every edge into its participants onto `jit_invoke_dispatch`: the
    /// closing edge itself is refused by `note_recursive_compile_cycle`'s
    /// `true`, and that is the one dispatch the cycle needs. The legacy rule
    /// is one flag away.
    #[test]
    fn a_statically_closed_cycle_is_recorded_but_does_not_force_dispatch() {
        // A registry of this test's own: no other test can clear or fill it.
        let verdicts = JitVerdictRegistry::default();
        clear_jit_compile_stack_for_test();
        let _on = cratonvm_types::flags::override_thread(
            cratonvm_types::flags::VmFlags::from_env_with_edits(&[(
                "CRATONVM_JIT_CYCLE_DIRECT_BIND",
                Some("1"),
            )]),
        );
        push_compile_stack(&[("r3/A", "a", "()V"), ("r3/B", "b", "()V")]);
        assert!(
            verdicts.note_recursive_compile_cycle("r3/A", "a", "()V", false, || None),
            "B -> A closes the open A -> B compile"
        );
        for (c, m) in [("r3/A", "a"), ("r3/B", "b")] {
            assert!(verdicts.is_recursive_cycle_participant(c, m, "()V"));
            assert!(
                !verdicts.direct_call_requires_dispatch(c, m, "()V"),
                "{c}.{m} is a cycle participant but must stay bindable"
            );
        }
        {
            let _legacy = cratonvm_types::flags::override_thread(
                cratonvm_types::flags::VmFlags::from_env_with_edits(&[(
                    "CRATONVM_JIT_CYCLE_DIRECT_BIND",
                    Some("0"),
                )]),
            );
            assert!(verdicts.direct_call_requires_dispatch("r3/A", "a", "()V"));
            assert!(verdicts.direct_call_requires_dispatch("r3/B", "b", "()V"));
        }
        clear_jit_compile_stack_for_test();
    }

    /// A cycle closed by an INLINE-CACHE edge stays sticky: a MIC/PIC slot is
    /// filled at run time with the newest entry, so the "baked edges only
    /// point at older artifacts" argument does not cover it.
    #[test]
    fn an_inline_cache_closed_cycle_keeps_its_participants_on_dispatch() {
        let verdicts = JitVerdictRegistry::default();
        clear_jit_compile_stack_for_test();
        let _on = cratonvm_types::flags::override_thread(
            cratonvm_types::flags::VmFlags::from_env_with_edits(&[(
                "CRATONVM_JIT_CYCLE_DIRECT_BIND",
                Some("1"),
            )]),
        );
        push_compile_stack(&[("r3/V", "v", "()V"), ("r3/W", "w", "()V")]);
        assert!(verdicts.note_recursive_compile_cycle("r3/V", "v", "()V", true, || None));
        assert!(verdicts.direct_call_requires_dispatch("r3/V", "v", "()V"));
        assert!(verdicts.direct_call_requires_dispatch("r3/W", "w", "()V"));
        clear_jit_compile_stack_for_test();
    }

    /// A target that is not open BELOW the current compile closes nothing and
    /// records nothing; the propagation mark stays sticky.
    #[test]
    fn a_non_cycle_edge_records_nothing_and_the_propagation_mark_is_sticky() {
        let verdicts = JitVerdictRegistry::default();
        clear_jit_compile_stack_for_test();
        let _on = cratonvm_types::flags::override_thread(
            cratonvm_types::flags::VmFlags::from_env_with_edits(&[(
                "CRATONVM_JIT_CYCLE_DIRECT_BIND",
                Some("1"),
            )]),
        );
        push_compile_stack(&[("r3/P", "p", "()V"), ("r3/Q", "q", "()V")]);
        // `q` is the current compile: a call to itself is self-recursion, not
        // a cycle, and `r3/Z` is not open at all.
        assert!(!verdicts.note_recursive_compile_cycle("r3/Q", "q", "()V", false, || None));
        assert!(!verdicts.note_recursive_compile_cycle("r3/Z", "z", "()V", true, || None));
        assert!(!verdicts.is_recursive_cycle_participant("r3/Q", "q", "()V"));
        assert!(!verdicts.is_recursive_cycle_participant("r3/Z", "z", "()V"));
        verdicts.mark_current_compile_method_recursive_cycle();
        assert!(
            verdicts.direct_call_requires_dispatch("r3/Q", "q", "()V"),
            "a caller marked because its callee still demanded dispatch stays on dispatch"
        );
        assert!(!verdicts.direct_call_requires_dispatch("r3/P", "p", "()V"));
        clear_jit_compile_stack_for_test();
    }

    /// End to end through `try_compile`: A calls B, B calls A (both
    /// `invokestatic`). B's call back to A closes the open compile and keeps
    /// dispatch; A's call to B -- a cycle participant, but published by the
    /// time A asks -- now binds B's entry DIRECTLY. Before wave 3 it fell back
    /// to dispatch too (`recursive_compile_cycle_routes_parent_direct_call_through_dispatch`
    /// in `tests.rs` pins that legacy rule under `CRATONVM_JIT_CYCLE_DIRECT_BIND=0`).
    #[test]
    #[cfg(target_arch = "x86_64")]
    fn a_published_cycle_participant_is_bound_directly() {
        // Both compiles record into this test's own registry.
        let verdicts = JitVerdictRegistry::default();
        let realm = CompileRealm {
            verdicts: &verdicts,
            ..CompileRealm::process()
        };
        crate::x64::set_moving_young_override(Some(false));
        clear_jit_compile_stack_for_test();
        let _flags = cratonvm_types::flags::override_thread(
            cratonvm_types::flags::VmFlags::from_env_with_edits(&[
                ("CRATONVM_JIT_DIRECT_CALLEE_CALLS", Some("1")),
                ("CRATONVM_JIT_CYCLE_DIRECT_BIND", Some("1")),
            ]),
        );
        let mk = |class: &str, name: &str, id: u32, code: &[u8]| CachedBytecodeMethod {
            declaring_class_id: cratonvm_types::ClassId::new(id),
            class_name: Arc::from(class),
            method_name: Arc::from(name),
            method_descriptor: Arc::from("()V"),
            source_file: None,
            code: Arc::from(code),
            exception_table: Arc::from(Vec::new().as_slice()),
            max_stack: 0,
            max_locals: 0,
            num_params: 0,
            is_synchronized: false,
            is_static: true,
            force_native_cache: std::sync::OnceLock::new(),
            hidden_frame: std::sync::OnceLock::new(),
            descriptor_facts_cache: std::sync::OnceLock::new(),
            intercept_shape_cache: std::sync::OnceLock::new(),
            interp_invocations: std::sync::atomic::AtomicU32::new(0),
            tiering_settled: std::sync::atomic::AtomicU32::new(0),
            branch_profile_armed: std::sync::atomic::AtomicBool::new(false),
            native_callback_cache: std::sync::OnceLock::new(),
            invoc_key: std::sync::OnceLock::new(),
            jit_probe_generation: std::sync::atomic::AtomicU64::new(0),
            quickened: std::sync::OnceLock::new(),
            array_inc_declined: std::sync::OnceLock::new(),
            ctor_verdict_memo: std::sync::OnceLock::new(),
            pool_generation: u64::MAX,
        };
        // invokestatic #1; return
        let a_cached = mk("r3e2e/A", "a", 31, &[0xb8, 0x00, 0x01, 0xb1, 0x00, 0x00]);
        let b_cached = mk("r3e2e/B", "b", 32, &[0xb8, 0x00, 0x01, 0xb1, 0x00, 0x00]);
        // SAFETY: every helper address is an integer slot. This test only
        // inspects emitted metadata and never executes the generated code.
        let helpers: JitRuntimeHelpers = unsafe { std::mem::zeroed() };
        let a_resolver = |cp_idx: u16| -> Option<(String, String, String)> {
            (cp_idx == 1).then(|| ("r3e2e/B".to_string(), "b".to_string(), "()V".to_string()))
        };
        let b_resolver = |cp_idx: u16| -> Option<(String, String, String)> {
            (cp_idx == 1).then(|| ("r3e2e/A".to_string(), "a".to_string(), "()V".to_string()))
        };
        let callee_compiler =
            |class_name: &str, method_name: &str, descriptor: &str| -> Option<(usize, bool)> {
                assert_eq!(
                    (class_name, method_name, descriptor),
                    ("r3e2e/B", "b", "()V")
                );
                let compiled_b = try_compile_request(&CompileRequest {
                    cp_invoke_resolver: Some(&b_resolver),
                    ..CompileRequest::new(&b_cached, &helpers, realm)
                })?;
                assert!(
                    compiled_b._direct_callee_entries.is_empty(),
                    "B -> A closes the open compile of A and must keep dispatch"
                );
                let compiled_b = Box::leak(Box::new(compiled_b));
                Some((compiled_b.entry_ptr() as usize, compiled_b.needs_context()))
            };
        let compiled_a = try_compile_request(&CompileRequest {
            cp_invoke_resolver: Some(&a_resolver),
            callee_compiler: Some(&callee_compiler),
            ..CompileRequest::new(&a_cached, &helpers, realm)
        })
        .expect("A should compile");

        assert!(verdicts.is_recursive_cycle_participant("r3e2e/A", "a", "()V"));
        assert!(verdicts.is_recursive_cycle_participant("r3e2e/B", "b", "()V"));
        assert!(!verdicts.direct_call_requires_dispatch("r3e2e/B", "b", "()V"));
        assert!(
            !process_jit_verdicts().is_recursive_cycle_participant("r3e2e/A", "a", "()V"),
            "a request's cycle is recorded in the registry it names, never the process's"
        );
        assert_eq!(
            compiled_a._direct_callee_entries.len(),
            1,
            "A -> B must bind B's published entry directly"
        );
        assert_eq!(
            compiled_a._jit_invoke_infos.len(),
            1,
            "the direct bind still registers its callee-deopt JitInvokeInfo"
        );
        clear_jit_compile_stack_for_test();
    }
}

/// Round 9 wave 5, lane `volatile5`:
/// `volatile-instance-fields-are-plain-accesses-in-compiled-code`.
#[cfg(test)]
mod r9w5_volatile5_tests {
    use super::*;
    use std::sync::Arc;

    /// `static int get(r9w5/Vol o) { return o.v; }` —
    /// `aload_0; getfield #2; ireturn`, padded like a VM method.
    fn getter() -> CachedBytecodeMethod {
        CachedBytecodeMethod {
            declaring_class_id: cratonvm_types::ClassId::new(1),
            class_name: Arc::from("r9w5/Vol"),
            method_name: Arc::from("get"),
            method_descriptor: Arc::from("(Lr9w5/Vol;)I"),
            source_file: None,
            code: Arc::from([0x2a, 0xb4, 0x00, 0x02, 0xac, 0x00, 0x00].as_slice()),
            exception_table: Arc::from(Vec::new().as_slice()),
            max_stack: 2,
            max_locals: 1,
            num_params: 1,
            is_synchronized: false,
            is_static: true,
            force_native_cache: std::sync::OnceLock::new(),
            hidden_frame: std::sync::OnceLock::new(),
            descriptor_facts_cache: std::sync::OnceLock::new(),
            intercept_shape_cache: std::sync::OnceLock::new(),
            interp_invocations: std::sync::atomic::AtomicU32::new(0),
            tiering_settled: std::sync::atomic::AtomicU32::new(0),
            branch_profile_armed: std::sync::atomic::AtomicBool::new(false),
            native_callback_cache: std::sync::OnceLock::new(),
            invoc_key: std::sync::OnceLock::new(),
            jit_probe_generation: std::sync::atomic::AtomicU64::new(0),
            quickened: std::sync::OnceLock::new(),
            array_inc_declined: std::sync::OnceLock::new(),
            ctor_verdict_memo: std::sync::OnceLock::new(),
            pool_generation: u64::MAX,
        }
    }

    /// An optimizing (C2) compile of a volatile-field reader comes out of the
    /// IR pipeline by default (round 9 wave 7 flip of
    /// `CRATONVM_JIT_IR_VOLATILE_FIELDS`): the builder emits an ordered
    /// `Op::Load` (`ir::Node::volatile_access`) that GVN / LICM /
    /// redundant-load elimination refuse to merge or hoist. The identical
    /// non-volatile reader is the control. `CRATONVM_JIT_IR_VOLATILE_FIELDS=0`
    /// restores the old route: the volatile reader is refused by the IR builder
    /// and compiles single-pass, which hoists no field read.
    #[test]
    // Routing assertion: on aarch64 `try_compile_inner` returns before the
    // x86-64 tier choice, like the other routing tests.
    #[cfg(target_arch = "x86_64")]
    fn a_volatile_getfield_takes_the_ir_tier_by_default() {
        // Routing, not the acceptance policy: publish every body that lowers,
        // so the control's trivial getter is not refused for want of evidence.
        let _accept = crate::ir_evidence::AcceptAlways::on();
        // The optimizing tier is gated off while the young generation can
        // relocate; pin it off on this thread so the control can reach it.
        crate::x64::set_moving_young_override(Some(false));
        let cached = getter();
        // SAFETY: an all-zero `JitRuntimeHelpers` is valid (every entry is an
        // address or a flag); the two entries the field lowering needs are
        // non-zero so the IR lowerer does not refuse for want of a helper.
        // The generated code is never executed.
        let mut helpers: JitRuntimeHelpers = unsafe { std::mem::zeroed() };
        helpers.getfield = 1;
        helpers.putfield_int = 1;
        let field = |cp: u16| -> Option<(usize, u8, Option<(u32, bool)>)> {
            (cp == 2).then_some((0, b'I', None))
        };
        let compile = |volatile: bool| -> (bool, u64) {
            let is_volatile = move |cp: u16| volatile && cp == 2;
            IR_LOWER_COMPILES.with(|c| c.set(0));
            let compiled = try_compile_request(&CompileRequest {
                cp_field_resolver: Some(&field),
                cp_field_volatile_resolver: Some(&is_volatile),
                optimize: true,
                ..CompileRequest::new(&cached, &helpers, CompileRealm::process())
            });
            (compiled.is_some(), IR_LOWER_COMPILES.with(|c| c.get()))
        };
        assert_eq!(
            compile(false),
            (true, 1),
            "control: a plain int field reader must compile through the IR pipeline"
        );
        assert_eq!(
            compile(true),
            (true, 1),
            "a volatile field reader now compiles through the IR pipeline (ordered Op::Load)"
        );
        crate::x64::set_moving_young_override(None);
    }
}

/// Round 9 wave 7, lane `mutrec7`: the guarded cycle-edge cell
/// (`perf-mutual-recursion-forces-every-call-through-invoke-dispatch-20260918.md`).
#[cfg(test)]
mod r9w7_mutrec7_tests {
    use super::*;
    use std::sync::Arc;

    fn body(with_context: bool) -> CompiledMethod {
        let mut buf = ExecutableBuffer::new(64).expect("executable buffer");
        buf.emit(&[0xC3]); // RET
        if with_context {
            CompiledMethod::new_with_context(buf)
        } else {
            CompiledMethod::new(buf)
        }
    }

    fn put(cache: &JitCache, class: &str, name: &str, id: u32, cm: CompiledMethod) {
        cache.put(
            Arc::from(class),
            Arc::from(name),
            Arc::from("()V"),
            cratonvm_types::ClassId::new(id),
            cm,
        );
    }

    fn entry_of(cache: &JitCache, class: &str, name: &str, id: u32) -> u64 {
        cache
            .get(class, name, "()V", cratonvm_types::ClassId::new(id))
            .expect("published")
            .entry_ptr() as u64
    }

    fn cell_for(class: &str, id: u32) -> Arc<JitCycleEdgeCell> {
        JitCycleEdgeCell::new(class, "a", "()V", cratonvm_types::ClassId::new(id), true)
    }

    /// Generated code loads `[cell + JIT_CYCLE_EDGE_CELL_ENTRY_OFFSET]`.
    #[test]
    fn the_entry_word_sits_at_the_offset_the_codegen_loads() {
        let cell = cell_for("t/A", 1);
        let base = Arc::as_ptr(&cell) as usize;
        let word = &cell.entry_word as *const std::sync::atomic::AtomicU64 as usize;
        assert_eq!(word - base, JIT_CYCLE_EDGE_CELL_ENTRY_OFFSET as usize);
        assert_eq!(cell.current_entry(), 0, "a fresh cell dispatches");
    }

    /// The closing caller publishes first (it was compiled inside its
    /// ancestor's compile); the ancestor's publication fills the cell, a
    /// tier-up re-fills it with the newer body, and an invalidation of the
    /// target sends the site back to dispatch.
    #[test]
    fn put_fills_a_waiting_cell_and_an_invalidation_clears_it() {
        let cache = JitCache::new();
        let mut b = body(true);
        let cell = cell_for("r9w7/A", 41);
        b._jit_cycle_cells.push(Arc::clone(&cell));
        put(&cache, "r9w7/B", "b", 42, b);
        assert_eq!(
            cell.current_entry(),
            0,
            "the ancestor has not published yet"
        );

        put(&cache, "r9w7/A", "a", 41, body(true));
        let a1 = entry_of(&cache, "r9w7/A", "a", 41);
        assert_eq!(
            cell.current_entry(),
            a1,
            "the ancestor's publication fills the cell"
        );

        put(&cache, "r9w7/A", "a", 41, body(true));
        let a2 = entry_of(&cache, "r9w7/A", "a", 41);
        assert_eq!(cell.current_entry(), a2, "the newest body wins");

        cache.remove("r9w7/A", "a", "()V", cratonvm_types::ClassId::new(41));
        assert_eq!(
            cell.current_entry(),
            0,
            "a withdrawn target must not stay callable"
        );
        assert!(
            cache
                .get("r9w7/B", "b", "()V", cratonvm_types::ClassId::new(42))
                .is_some(),
            "the closing caller itself stays published: its site dispatches again"
        );

        put(&cache, "r9w7/A", "a", 41, body(true));
        assert_eq!(cell.current_entry(), entry_of(&cache, "r9w7/A", "a", 41));
        cache.clear_all();
        assert_eq!(cell.current_entry(), 0, "a flush clears every cell");
    }

    /// A target that is already published when the closing caller publishes
    /// fills the cell at registration.
    #[test]
    fn a_cell_whose_target_is_already_published_is_filled_at_registration() {
        let cache = JitCache::new();
        put(&cache, "r9w7r/A", "a", 51, body(true));
        let a = entry_of(&cache, "r9w7r/A", "a", 51);
        let mut b = body(true);
        let cell = cell_for("r9w7r/A", 51);
        b._jit_cycle_cells.push(Arc::clone(&cell));
        put(&cache, "r9w7r/B", "b", 52, b);
        assert_eq!(cell.current_entry(), a);
        cache.clear_all();
    }

    /// Only a body the site can call raw is ever installed: another loader's
    /// same-named class, a body with the other entry ABI, and a body that
    /// needs the synchronized wrapper all leave the cell alone.
    #[test]
    fn a_cell_admits_only_its_own_class_and_entry_abi() {
        let cache = JitCache::new();
        let mut b = body(true);
        let cell = cell_for("r9w7x/A", 61);
        b._jit_cycle_cells.push(Arc::clone(&cell));
        put(&cache, "r9w7x/B", "b", 62, b);

        put(&cache, "r9w7x/A", "a", 63, body(true));
        assert_eq!(cell.current_entry(), 0, "same name, another class id");

        put(&cache, "r9w7x/A", "a", 61, body(false));
        assert_eq!(
            cell.current_entry(),
            0,
            "a context-free body has the other ABI"
        );

        let mut wrapped = body(true);
        wrapped.requires_wrapped_entry = true;
        put(&cache, "r9w7x/A", "a", 61, wrapped);
        assert_eq!(
            cell.current_entry(),
            0,
            "a synchronized body needs its wrapper"
        );

        put(&cache, "r9w7x/A", "a", 61, body(true));
        assert_eq!(cell.current_entry(), entry_of(&cache, "r9w7x/A", "a", 61));
        cache.clear_all();
    }

    /// End to end through `try_compile_request`, with
    /// `CRATONVM_JIT_CYCLE_EDGE_CELL=1`: `A -> B -> A` compiled eagerly. B's
    /// closing edge gets a cell (baked into B's code as an imm64, with its
    /// `JitInvokeInfo` still registered for the dispatch fallback), A binds B
    /// directly, and publishing both fills B's cell with A's entry.
    #[test]
    // x86-64 only: this asserts how `try_compile_inner` ROUTES a compile, and
    // on aarch64 it never gets that far -- the `#[cfg(target_arch =
    // "aarch64")]` block returns before any routing happens (with
    // `CRATONVM_JIT_ARM64` unset, immediately), so `try_compile_request`
    // answers `None` and the test reads it as "A should compile". Thirteen
    // sibling routing tests were gated for this in 2026-09-04; these two
    // landed after. Found 2026-09-21 by running the suite as a real aarch64
    // binary under `qemu-user`.
    #[cfg(target_arch = "x86_64")]
    fn the_closing_edge_is_planned_as_a_cell_and_publication_fills_it() {
        let verdicts = JitVerdictRegistry::default();
        let realm = CompileRealm {
            verdicts: &verdicts,
            ..CompileRealm::process()
        };
        crate::x64::set_moving_young_override(Some(false));
        clear_jit_compile_stack_for_test();
        let flags = cratonvm_types::flags::override_thread(
            cratonvm_types::flags::VmFlags::from_env_with_edits(&[
                ("CRATONVM_JIT_DIRECT_CALLEE_CALLS", Some("1")),
                ("CRATONVM_JIT_CYCLE_DIRECT_BIND", Some("1")),
                ("CRATONVM_JIT_CYCLE_EDGE_CELL", Some("1")),
            ]),
        );
        let mk = |class: &str, name: &str, id: u32, code: &[u8]| CachedBytecodeMethod {
            declaring_class_id: cratonvm_types::ClassId::new(id),
            class_name: Arc::from(class),
            method_name: Arc::from(name),
            method_descriptor: Arc::from("()V"),
            source_file: None,
            code: Arc::from(code),
            exception_table: Arc::from(Vec::new().as_slice()),
            max_stack: 0,
            max_locals: 0,
            num_params: 0,
            is_synchronized: false,
            is_static: true,
            force_native_cache: std::sync::OnceLock::new(),
            hidden_frame: std::sync::OnceLock::new(),
            descriptor_facts_cache: std::sync::OnceLock::new(),
            intercept_shape_cache: std::sync::OnceLock::new(),
            interp_invocations: std::sync::atomic::AtomicU32::new(0),
            tiering_settled: std::sync::atomic::AtomicU32::new(0),
            branch_profile_armed: std::sync::atomic::AtomicBool::new(false),
            native_callback_cache: std::sync::OnceLock::new(),
            invoc_key: std::sync::OnceLock::new(),
            jit_probe_generation: std::sync::atomic::AtomicU64::new(0),
            quickened: std::sync::OnceLock::new(),
            array_inc_declined: std::sync::OnceLock::new(),
            ctor_verdict_memo: std::sync::OnceLock::new(),
            pool_generation: u64::MAX,
        };
        // invokestatic #1; return
        let a_cached = mk("r9w7e/A", "a", 71, &[0xb8, 0x00, 0x01, 0xb1, 0x00, 0x00]);
        let b_cached = mk("r9w7e/B", "b", 72, &[0xb8, 0x00, 0x01, 0xb1, 0x00, 0x00]);
        // SAFETY: every helper address is an integer slot. The two the cell
        // site needs get distinct fake values; nothing here executes the
        // generated code.
        let mut helpers: JitRuntimeHelpers = unsafe { std::mem::zeroed() };
        helpers.self_call_stack_guard = 0x7100_0000_1000;
        helpers.invoke_dispatch = 0x7100_0000_2000;
        let a_resolver = |cp_idx: u16| -> Option<(String, String, String)> {
            (cp_idx == 1).then(|| ("r9w7e/B".to_string(), "b".to_string(), "()V".to_string()))
        };
        let b_resolver = |cp_idx: u16| -> Option<(String, String, String)> {
            (cp_idx == 1).then(|| ("r9w7e/A".to_string(), "a".to_string(), "()V".to_string()))
        };
        let a_cid = |cp_idx: u16| -> Option<u32> { (cp_idx == 1).then_some(72) };
        let b_cid = |cp_idx: u16| -> Option<u32> { (cp_idx == 1).then_some(71) };
        // The VM's direct-bind gates, as `jit_bridge` answers them for an
        // initialized, unsynchronized, handler-free static callee.
        let admit = |_: &str, _: &str, _: &str| -> bool { true };
        let compiled_b_slot: std::cell::RefCell<Option<CompiledMethod>> =
            std::cell::RefCell::new(None);
        let callee_compiler =
            |class_name: &str, method_name: &str, descriptor: &str| -> Option<(usize, bool)> {
                assert_eq!(
                    (class_name, method_name, descriptor),
                    ("r9w7e/B", "b", "()V")
                );
                let mut req = CompileRequest::new(&b_cached, &helpers, realm);
                req.cp_invoke_resolver = Some(&b_resolver);
                req.cp_invoke_class_id_resolver = Some(&b_cid);
                req.cycle_edge_admission = Some(&admit);
                let compiled_b = try_compile_request(&req)?;
                let out = (compiled_b.entry_ptr() as usize, compiled_b.needs_context());
                *compiled_b_slot.borrow_mut() = Some(compiled_b);
                Some(out)
            };
        let mut req = CompileRequest::new(&a_cached, &helpers, realm);
        req.cp_invoke_resolver = Some(&a_resolver);
        req.cp_invoke_class_id_resolver = Some(&a_cid);
        req.callee_compiler = Some(&callee_compiler);
        let compiled_a = try_compile_request(&req).expect("A should compile");
        let compiled_b = compiled_b_slot
            .borrow_mut()
            .take()
            .expect("B was compiled inside A's compile");

        assert_eq!(
            compiled_b._jit_cycle_cells.len(),
            1,
            "B -> A closes the cycle"
        );
        assert!(compiled_b._direct_callee_entries.is_empty());
        assert_eq!(
            compiled_b._jit_invoke_infos.len(),
            1,
            "the cell site keeps its JitInvokeInfo for the dispatch fallback"
        );
        assert!(
            compiled_b.needs_context(),
            "the cell site needs the VM context"
        );
        let cell = Arc::clone(&compiled_b._jit_cycle_cells[0]);
        let cell_bytes = (Arc::as_ptr(&cell) as u64).to_le_bytes();
        assert!(
            compiled_b
                ._buffer_slice_for_debug()
                .windows(8)
                .any(|w| w == cell_bytes),
            "B's code must bake the cell's address"
        );
        assert_eq!(
            compiled_a._direct_callee_entries.len(),
            1,
            "A -> B binds directly"
        );
        assert!(compiled_a.needs_context(), "A calls a context-ABI body");

        let cache = JitCache::new();
        let a_entry = compiled_a.entry_ptr() as u64;
        put(&cache, "r9w7e/B", "b", 72, compiled_b);
        assert_eq!(cell.current_entry(), 0);
        put(&cache, "r9w7e/A", "a", 71, compiled_a);
        assert_eq!(
            cell.current_entry(),
            a_entry,
            "A's publication fills B's cell"
        );
        cache.clear_all();
        assert_eq!(cell.current_entry(), 0);

        drop(flags);
        crate::x64::set_moving_young_override(None);
        clear_jit_compile_stack_for_test();
    }

    /// JIT round 20 wave 11 (lane pLate, W15L1-P1): an `invokestatic` whose
    /// callee `callee_compiler` cannot give yet (it compiles AFTER the
    /// caller) gets a late-bind cell under `CRATONVM_JIT_LATE_STATIC_CELL`
    /// (default ON) and none under `=0`; the callee's publication fills it.
    #[test]
    #[cfg(target_arch = "x86_64")]
    fn an_unbound_static_site_gets_a_late_cell_that_publication_fills() {
        for (switch, expect_cell) in [(None, true), (Some("0"), false)] {
            let verdicts = JitVerdictRegistry::default();
            let realm = CompileRealm {
                verdicts: &verdicts,
                ..CompileRealm::process()
            };
            crate::x64::set_moving_young_override(Some(false));
            clear_jit_compile_stack_for_test();
            let flags = cratonvm_types::flags::override_thread(
                cratonvm_types::flags::VmFlags::from_env_with_edits(&[
                    ("CRATONVM_JIT_DIRECT_CALLEE_CALLS", Some("1")),
                    ("CRATONVM_JIT_CYCLE_DIRECT_BIND", Some("1")),
                    ("CRATONVM_JIT_CYCLE_EDGE_CELL", Some("1")),
                    ("CRATONVM_JIT_LATE_STATIC_CELL", switch),
                ]),
            );
            let a_cached = CachedBytecodeMethod {
                declaring_class_id: cratonvm_types::ClassId::new(81),
                class_name: Arc::from("r20pl/A"),
                method_name: Arc::from("a"),
                method_descriptor: Arc::from("()V"),
                source_file: None,
                // invokestatic #1; return
                code: Arc::from(&[0xb8u8, 0x00, 0x01, 0xb1, 0x00, 0x00][..]),
                exception_table: Arc::from(Vec::new().as_slice()),
                max_stack: 0,
                max_locals: 0,
                num_params: 0,
                is_synchronized: false,
                is_static: true,
                force_native_cache: std::sync::OnceLock::new(),
                hidden_frame: std::sync::OnceLock::new(),
                descriptor_facts_cache: std::sync::OnceLock::new(),
                intercept_shape_cache: std::sync::OnceLock::new(),
                interp_invocations: std::sync::atomic::AtomicU32::new(0),
                tiering_settled: std::sync::atomic::AtomicU32::new(0),
                branch_profile_armed: std::sync::atomic::AtomicBool::new(false),
                native_callback_cache: std::sync::OnceLock::new(),
                invoc_key: std::sync::OnceLock::new(),
                jit_probe_generation: std::sync::atomic::AtomicU64::new(0),
                quickened: std::sync::OnceLock::new(),
                array_inc_declined: std::sync::OnceLock::new(),
                ctor_verdict_memo: std::sync::OnceLock::new(),
                pool_generation: u64::MAX,
            };
            // SAFETY: every helper address is an integer slot; nothing here
            // executes the generated code.
            let mut helpers: JitRuntimeHelpers = unsafe { std::mem::zeroed() };
            helpers.self_call_stack_guard = 0x7100_0000_1000;
            helpers.invoke_dispatch = 0x7100_0000_2000;
            let a_resolver = |cp_idx: u16| -> Option<(String, String, String)> {
                (cp_idx == 1).then(|| ("r20pl/B".to_string(), "b".to_string(), "()V".to_string()))
            };
            let a_cid = |cp_idx: u16| -> Option<u32> { (cp_idx == 1).then_some(82) };
            let admit = |_: &str, _: &str, _: &str| -> bool { true };
            // B is not compiled yet: the compiler has nothing to give.
            let callee_compiler = |_: &str, _: &str, _: &str| -> Option<(usize, bool)> { None };
            let mut req = CompileRequest::new(&a_cached, &helpers, realm);
            req.cp_invoke_resolver = Some(&a_resolver);
            req.cp_invoke_class_id_resolver = Some(&a_cid);
            req.callee_compiler = Some(&callee_compiler);
            req.cycle_edge_admission = Some(&admit);
            let compiled_a = try_compile_request(&req).expect("A should compile");
            if !expect_cell {
                assert!(
                    compiled_a._jit_cycle_cells.is_empty(),
                    "=0 keeps the blind dispatch"
                );
            } else {
                assert_eq!(compiled_a._jit_cycle_cells.len(), 1, "the late cell");
                assert_eq!(
                    compiled_a._jit_invoke_infos.len(),
                    1,
                    "the cell site keeps its JitInvokeInfo for the dispatch fallback"
                );
                let cell = Arc::clone(&compiled_a._jit_cycle_cells[0]);
                let cache = JitCache::new();
                put(&cache, "r20pl/A", "a", 81, compiled_a);
                assert_eq!(cell.current_entry(), 0, "B has not published yet");
                put(&cache, "r20pl/B", "b", 82, body(true));
                assert_eq!(
                    cell.current_entry(),
                    entry_of(&cache, "r20pl/B", "b", 82),
                    "B's publication binds A's site"
                );
                cache.clear_all();
                assert_eq!(cell.current_entry(), 0);
            }
            drop(flags);
            crate::x64::set_moving_young_override(None);
            clear_jit_compile_stack_for_test();
        }
    }
}

/// Round 9 wave 9, lane `evict9`: retire cells
/// (`evicted-callee-stays-reachable-through-a-compiled-callers-binding-FIXED-20260918.md`).
#[cfg(test)]
mod r9w9_evict9_tests {
    use super::*;
    use std::sync::Arc;

    fn body(with_context: bool) -> CompiledMethod {
        let mut buf = ExecutableBuffer::new(64).expect("executable buffer");
        buf.emit(&[0xC3]); // RET
        if with_context {
            CompiledMethod::new_with_context(buf)
        } else {
            CompiledMethod::new(buf)
        }
    }

    fn put(cache: &JitCache, class: &str, name: &str, id: u32, cm: CompiledMethod) {
        cache.put(
            Arc::from(class),
            Arc::from(name),
            Arc::from("()V"),
            cratonvm_types::ClassId::new(id),
            cm,
        );
    }

    fn entry_of(cache: &JitCache, class: &str, name: &str, id: u32) -> usize {
        cache
            .get(class, name, "()V", cratonvm_types::ClassId::new(id))
            .expect("published")
            .entry_ptr() as usize
    }

    /// A caller body that bakes `callee_entry` through a retire cell, as the
    /// compile doors build it: the entry itself is a baked callee (so it is
    /// rooted), and the artifact owns the cell.
    fn caller_of(callee_entry: usize, class: &str) -> (CompiledMethod, Arc<JitCycleEdgeCell>) {
        let mut a = body(true);
        let cell = JitCycleEdgeCell::new_retire(callee_entry, class, "b", "()V", true);
        a._jit_cycle_cells.push(Arc::clone(&cell));
        a._direct_callee_entries = vec![callee_entry];
        (a, cell)
    }

    /// `for (i = 0; i < 10; i++) b();` -- the invoke at pc 8 is inside the
    /// loop, the `return` at 17 is not.
    ///
    /// ```text
    ///  0 iconst_0   1 istore_0   2 iload_0   3 bipush 10   5 if_icmpge +12 (17)
    ///  8 invokestatic #1   11 iinc 0,1   14 goto -12 (2)   17 return
    /// ```
    const LOOP_CALLER: [u8; 20] = [
        0x03, 0x3b, 0x1a, 0x10, 0x0a, 0xa2, 0x00, 0x0c, 0xb8, 0x00, 0x01, 0x84, 0x00, 0x01, 0xa7,
        0xff, 0xf4, 0xb1, 0x00, 0x00,
    ];

    #[test]
    fn pc_in_loop_sees_the_backward_branch_range_only() {
        assert!(bytecode_pc_in_loop(&LOOP_CALLER, 18, 8));
        assert!(bytecode_pc_in_loop(&LOOP_CALLER, 18, 2), "the header");
        assert!(bytecode_pc_in_loop(&LOOP_CALLER, 18, 14), "the back edge");
        assert!(!bytecode_pc_in_loop(&LOOP_CALLER, 18, 0));
        assert!(!bytecode_pc_in_loop(&LOOP_CALLER, 18, 17));
        // invokestatic #1; return -- no loop at all.
        assert!(!bytecode_pc_in_loop(&[0xb8, 0x00, 0x01, 0xb1], 4, 0));
    }

    /// The planner answers the plain row unless the flag is on AND the site is
    /// an in-loop `invokestatic` (to a body of either ABI since wave 10).
    #[test]
    fn a_retire_cell_is_planned_only_for_an_in_loop_static_context_call() {
        let plan = |pc: usize, kind: u8, ctx: bool, cells: &mut Vec<Arc<JitCycleEdgeCell>>| {
            retirable_direct_call(
                &LOOP_CALLER,
                18,
                pc,
                kind,
                0x7100_0000_0000,
                ctx,
                0,
                b'V',
                "r9w9p/B",
                "b",
                "()V",
                cells,
            )
        };
        let mut cells = Vec::new();
        {
            let _off = cratonvm_types::flags::override_thread(
                cratonvm_types::flags::VmFlags::from_env_with_edits(&[(
                    "CRATONVM_JIT_RETIRE_CELL",
                    Some("0"),
                )]),
            );
            let row = plan(8, 3, true, &mut cells);
            assert_eq!(row.guard_class_id, 0, "switched off: the plain row");
            assert_eq!(row.entry, 0x7100_0000_0000);
            assert!(cells.is_empty());
        }
        let _on = cratonvm_types::flags::override_thread(
            cratonvm_types::flags::VmFlags::from_env_with_edits(&[(
                "CRATONVM_JIT_RETIRE_CELL",
                Some("1"),
            )]),
        );
        assert_eq!(
            plan(8, 1, true, &mut cells).guard_class_id,
            0,
            "not invokestatic"
        );
        assert_eq!(
            plan(2, 3, true, &mut cells).guard_class_id,
            0,
            "no invokestatic at pc"
        );
        assert!(cells.is_empty());
        let row = plan(8, 3, true, &mut cells);
        assert_eq!(row.guard_class_id, JIT_RETIRE_CELL_GUARD);
        assert_eq!(cells.len(), 1);
        assert_eq!(row.entry, Arc::as_ptr(&cells[0]) as usize);
        assert_eq!(cells[0].pinned_entry(), 0x7100_0000_0000);
        // SAFETY: `cells[0]` is alive for the call.
        let pinned = unsafe { JitCycleEdgeCell::pinned_entry_at(row.entry) };
        assert_eq!(pinned, 0x7100_0000_0000);
        assert_eq!(cells[0].current_entry(), 0, "filled only at publication");
    }

    /// Round 9 wave 10 (`call10`): a CONTEXT-FREE callee (a leaf loop like
    /// `TryLoop.sumThrow`) is retirable too. The cell carries the pinned
    /// body's ABI, so publication fills it with that body, and the callee's
    /// eviction clears it -- the OSR'd `main` of `TryLoop throw` got no cell
    /// at all before, and re-entered the trapping body 2 000 times.
    #[test]
    fn a_context_free_in_loop_callee_gets_a_retire_cell_that_eviction_clears() {
        let _on = cratonvm_types::flags::override_thread(
            cratonvm_types::flags::VmFlags::from_env_with_edits(&[(
                "CRATONVM_JIT_RETIRE_CELL",
                Some("1"),
            )]),
        );
        let cache = JitCache::new();
        put(&cache, "r9w10a/B", "b", 191, body(false));
        let b1 = entry_of(&cache, "r9w10a/B", "b", 191);
        let mut cells = Vec::new();
        let row = retirable_direct_call(
            &LOOP_CALLER,
            18,
            8,
            3,
            b1,
            false,
            0,
            b'V',
            "r9w10a/B",
            "b",
            "()V",
            &mut cells,
        );
        assert_eq!(row.guard_class_id, JIT_RETIRE_CELL_GUARD);
        assert!(!row.needs_context, "the row keeps the callee's own ABI");
        assert_eq!(cells.len(), 1);
        let cell = Arc::clone(&cells[0]);
        assert_eq!(cell.pinned_entry(), b1);

        let mut a = body(true);
        a._jit_cycle_cells.extend(cells);
        a._direct_callee_entries = vec![b1];
        put(&cache, "r9w10a/A", "a", 190, a);
        assert_eq!(
            cell.current_entry() as usize,
            b1,
            "a context-free pinned body is admitted"
        );
        cache.remove("r9w10a/B", "b", "()V", cratonvm_types::ClassId::new(191));
        assert_eq!(
            cell.current_entry(),
            0,
            "the eviction sends the site to dispatch"
        );
        cache.clear_all();
    }

    /// Publication fills the cell with the body the caller baked; a tier-up
    /// of the callee leaves it alone; the callee's eviction clears it even
    /// though the evicted CURRENT body is not the one the caller baked; and
    /// nothing ever refills it.
    #[test]
    fn publication_fills_a_retire_cell_and_the_callee_eviction_clears_it() {
        let cache = JitCache::new();
        put(&cache, "r9w9a/B", "b", 91, body(true));
        let b1 = entry_of(&cache, "r9w9a/B", "b", 91);
        let (a, cell) = caller_of(b1, "r9w9a/B");
        put(&cache, "r9w9a/A", "a", 90, a);
        assert_eq!(cell.current_entry() as usize, b1, "filled at publication");

        put(&cache, "r9w9a/B", "b", 91, body(true));
        let b2 = entry_of(&cache, "r9w9a/B", "b", 91);
        assert_ne!(b1, b2);
        assert_eq!(
            cell.current_entry() as usize,
            b1,
            "a retire cell never takes a newer body"
        );

        cache.remove("r9w9a/B", "b", "()V", cratonvm_types::ClassId::new(91));
        assert_eq!(
            cell.current_entry(),
            0,
            "an evicted method is not reachable through an older baked body"
        );

        put(&cache, "r9w9a/B", "b", 91, body(true));
        assert_eq!(
            cell.current_entry(),
            0,
            "a republication does not refill it"
        );
        cache.clear_all();
    }

    /// Withdrawing the pinned body itself: the cell is cleared and the caller
    /// is withdrawn with it (the transitive closure); a frame still running
    /// the caller reaches the callee through dispatch from then on.
    #[test]
    fn withdrawing_the_pinned_body_clears_the_cell_and_retires_the_caller() {
        let cache = JitCache::new();
        put(&cache, "r9w9b/B", "b", 93, body(true));
        let b1 = entry_of(&cache, "r9w9b/B", "b", 93);
        let (a, cell) = caller_of(b1, "r9w9b/B");
        put(&cache, "r9w9b/A", "a", 92, a);
        let a_arc = cache
            .get("r9w9b/A", "a", "()V", cratonvm_types::ClassId::new(92))
            .expect("published");
        assert_eq!(cell.current_entry() as usize, b1);
        cache.remove("r9w9b/B", "b", "()V", cratonvm_types::ClassId::new(93));
        assert_eq!(cell.current_entry(), 0);
        assert!(a_arc.retired.load(std::sync::atomic::Ordering::SeqCst));
        drop(a_arc);
        cache.clear_all();
    }

    /// A retire cell is never a key's waiting cell: publishing a body of the
    /// method its names give does not fill an unfilled one.
    #[test]
    fn a_retire_cell_is_not_filled_by_key() {
        let cache = JitCache::new();
        let (mut a, cell) = caller_of(0x7100_0000_0000, "r9w9c/B");
        // Nothing to root: the cell stays at `0` (the site dispatches).
        a._direct_callee_entries.clear();
        put(&cache, "r9w9c/A", "a", 94, a);
        assert_eq!(cell.current_entry(), 0);
        put(&cache, "r9w9c/B", "b", 95, body(true));
        assert_eq!(cell.current_entry(), 0, "a retire cell waits for no key");
        cache.clear_all();
    }

    /// The ArrayList pin asks what the single-pass prefix asks: a resolved
    /// layout, an `invokevirtual`/`invokeinterface` site on one of the two
    /// members, and it can be switched off.
    #[test]
    fn the_arraylist_pin_fires_only_on_a_prefix_site_with_a_layout() {
        let Some(al) = ArrayListFieldLayout::new(1, 2, 11) else {
            return; // this configuration refuses the prefix itself
        };
        if crate::x64::zgc_read_barrier_blocks_inline_fields() {
            return;
        }
        let layout = StringFieldLayout::new(0, Some(1), 2, 0x0055_0001).with_array_list(Some(al));
        let resolver = |cp_idx: u16| -> Option<(String, String, String)> {
            match cp_idx {
                1 => Some((
                    "java/util/List".to_string(),
                    "get".to_string(),
                    "(I)Ljava/lang/Object;".to_string(),
                )),
                2 => Some((
                    "java/util/LinkedList".to_string(),
                    "get".to_string(),
                    "(I)Ljava/lang/Object;".to_string(),
                )),
                _ => None,
            }
        };
        let list_get = [(3usize, 1u16, 0xb9u8)];
        // nio20 wave 3 (L2, NIO20-L3-3): by default the optimizing tier lowers
        // the prefix itself, so nothing is pinned.
        {
            let _default = cratonvm_types::flags::override_thread(
                cratonvm_types::flags::VmFlags::from_env_with_edits(&[
                    ("CRATONVM_JIT_NO_ARRAYLIST_PIN", None),
                    ("CRATONVM_JIT_IR_ARRAYLIST_PREFIX", None),
                ]),
            );
            assert!(!arraylist_prefix_pins_single_pass(
                &list_get,
                Some(&resolver),
                Some(layout)
            ));
        }
        // `CRATONVM_JIT_IR_ARRAYLIST_PREFIX=0`: the pre-nio20 pin.
        let _flags = cratonvm_types::flags::override_thread(
            cratonvm_types::flags::VmFlags::from_env_with_edits(&[
                ("CRATONVM_JIT_NO_ARRAYLIST_PIN", None),
                ("CRATONVM_JIT_IR_ARRAYLIST_PREFIX", Some("0")),
            ]),
        );
        assert!(arraylist_prefix_pins_single_pass(
            &list_get,
            Some(&resolver),
            Some(layout)
        ));
        assert!(
            !arraylist_prefix_pins_single_pass(&[(3, 2, 0xb6)], Some(&resolver), Some(layout)),
            "not a prefix site"
        );
        assert!(
            !arraylist_prefix_pins_single_pass(&[(3, 1, 0xb8)], Some(&resolver), Some(layout)),
            "not a virtual/interface opcode"
        );
        let no_al = StringFieldLayout::new(0, Some(1), 2, 0x0055_0001);
        assert!(
            !arraylist_prefix_pins_single_pass(&list_get, Some(&resolver), Some(no_al)),
            "no ArrayList layout: the emitter would not answer inline either"
        );
        assert!(!arraylist_prefix_pins_single_pass(
            &list_get,
            None,
            Some(layout)
        ));
        let _off = cratonvm_types::flags::override_thread(
            cratonvm_types::flags::VmFlags::from_env_with_edits(&[(
                "CRATONVM_JIT_NO_ARRAYLIST_PIN",
                Some("1"),
            )]),
        );
        assert!(!arraylist_prefix_pins_single_pass(
            &list_get,
            Some(&resolver),
            Some(layout)
        ));
    }

    /// End to end through `try_compile_request`, with
    /// `CRATONVM_JIT_RETIRE_CELL=1`: A calls B inside a loop; B is compiled
    /// inside A's compile. A's site becomes a retire cell pinned to B's entry,
    /// baked into A's code, with B still recorded as a baked callee and the
    /// site's `JitInvokeInfo` registered; publishing fills it, evicting B
    /// clears it.
    #[test]
    // x86-64 only: this asserts how `try_compile_inner` ROUTES a compile, and
    // on aarch64 it never gets that far -- the `#[cfg(target_arch =
    // "aarch64")]` block returns before any routing happens (with
    // `CRATONVM_JIT_ARM64` unset, immediately), so `try_compile_request`
    // answers `None` and the test reads it as "A should compile". Thirteen
    // sibling routing tests were gated for this in 2026-09-04; these two
    // landed after. Found 2026-09-21 by running the suite as a real aarch64
    // binary under `qemu-user`.
    #[cfg(target_arch = "x86_64")]
    fn an_in_loop_static_bind_is_planned_as_a_retire_cell() {
        let verdicts = JitVerdictRegistry::default();
        let realm = CompileRealm {
            verdicts: &verdicts,
            ..CompileRealm::process()
        };
        crate::x64::set_moving_young_override(Some(false));
        clear_jit_compile_stack_for_test();
        let flags = cratonvm_types::flags::override_thread(
            cratonvm_types::flags::VmFlags::from_env_with_edits(&[
                ("CRATONVM_JIT_DIRECT_CALLEE_CALLS", Some("1")),
                ("CRATONVM_JIT_RETIRE_CELL", Some("1")),
            ]),
        );
        let mk =
            |class: &str, name: &str, id: u32, code: &[u8], max_locals: u16| CachedBytecodeMethod {
                declaring_class_id: cratonvm_types::ClassId::new(id),
                class_name: Arc::from(class),
                method_name: Arc::from(name),
                method_descriptor: Arc::from("()V"),
                source_file: None,
                code: Arc::from(code),
                exception_table: Arc::from(Vec::new().as_slice()),
                max_stack: 2,
                max_locals,
                num_params: 0,
                is_synchronized: false,
                is_static: true,
                force_native_cache: std::sync::OnceLock::new(),
                hidden_frame: std::sync::OnceLock::new(),
                descriptor_facts_cache: std::sync::OnceLock::new(),
                intercept_shape_cache: std::sync::OnceLock::new(),
                interp_invocations: std::sync::atomic::AtomicU32::new(0),
                tiering_settled: std::sync::atomic::AtomicU32::new(0),
                branch_profile_armed: std::sync::atomic::AtomicBool::new(false),
                native_callback_cache: std::sync::OnceLock::new(),
                invoc_key: std::sync::OnceLock::new(),
                jit_probe_generation: std::sync::atomic::AtomicU64::new(0),
                quickened: std::sync::OnceLock::new(),
                array_inc_declined: std::sync::OnceLock::new(),
                ctor_verdict_memo: std::sync::OnceLock::new(),
                pool_generation: u64::MAX,
            };
        let a_cached = mk("r9w9e/A", "a", 96, &LOOP_CALLER, 1);
        // B: `invokestatic #1 (C.c, never compiled: a dispatch site, so B
        // takes the VM context); return`.
        let b_cached = mk("r9w9e/B", "b", 97, &[0xb8, 0x00, 0x01, 0xb1, 0x00, 0x00], 0);
        // SAFETY: every helper address is an integer slot; nothing here
        // executes the generated code.
        let mut helpers: JitRuntimeHelpers = unsafe { std::mem::zeroed() };
        helpers.invoke_dispatch = 0x7100_0000_2000;
        let a_resolver = |cp_idx: u16| -> Option<(String, String, String)> {
            (cp_idx == 1).then(|| ("r9w9e/B".to_string(), "b".to_string(), "()V".to_string()))
        };
        let b_resolver = |cp_idx: u16| -> Option<(String, String, String)> {
            (cp_idx == 1).then(|| ("r9w9e/C".to_string(), "c".to_string(), "()V".to_string()))
        };
        let compiled_b_slot: std::cell::RefCell<Option<CompiledMethod>> =
            std::cell::RefCell::new(None);
        let callee_compiler =
            |class_name: &str, method_name: &str, descriptor: &str| -> Option<(usize, bool)> {
                if (class_name, method_name, descriptor) != ("r9w9e/B", "b", "()V") {
                    return None;
                }
                let mut req = CompileRequest::new(&b_cached, &helpers, realm);
                req.cp_invoke_resolver = Some(&b_resolver);
                let compiled_b = try_compile_request(&req)?;
                let out = (compiled_b.entry_ptr() as usize, compiled_b.needs_context());
                *compiled_b_slot.borrow_mut() = Some(compiled_b);
                Some(out)
            };
        let mut req = CompileRequest::new(&a_cached, &helpers, realm);
        req.cp_invoke_resolver = Some(&a_resolver);
        req.callee_compiler = Some(&callee_compiler);
        let compiled_a = try_compile_request(&req).expect("A should compile");
        let compiled_b = compiled_b_slot
            .borrow_mut()
            .take()
            .expect("B was compiled inside A's compile");
        let b_entry = compiled_b.entry_ptr() as usize;
        assert!(
            compiled_b.needs_context(),
            "B dispatches, so it takes the context"
        );

        assert_eq!(
            compiled_a._jit_cycle_cells.len(),
            1,
            "A's in-loop bind is a retire cell"
        );
        let cell = Arc::clone(&compiled_a._jit_cycle_cells[0]);
        assert_eq!(cell.pinned_entry(), b_entry);
        assert_eq!(
            compiled_a._direct_callee_entries,
            vec![b_entry],
            "the pinned body is still a rooted baked callee"
        );
        assert!(
            !compiled_a._jit_invoke_infos.is_empty(),
            "the site keeps its JitInvokeInfo for the dispatch fallback"
        );
        let cell_bytes = (Arc::as_ptr(&cell) as u64).to_le_bytes();
        assert!(
            compiled_a
                ._buffer_slice_for_debug()
                .windows(8)
                .any(|w| w == cell_bytes),
            "A's code must bake the cell's address"
        );

        let cache = JitCache::new();
        put(&cache, "r9w9e/B", "b", 97, compiled_b);
        put(&cache, "r9w9e/A", "a", 96, compiled_a);
        assert_eq!(
            cell.current_entry() as usize,
            b_entry,
            "A's publication fills it"
        );
        cache.remove("r9w9e/B", "b", "()V", cratonvm_types::ClassId::new(97));
        assert_eq!(cell.current_entry(), 0, "B's eviction clears it");
        cache.clear_all();

        drop(flags);
        crate::x64::set_moving_young_override(None);
        clear_jit_compile_stack_for_test();
    }
}

/// t1 wave 2, lane jit2 (B5 of `jit-proposals/jit-r24-alloc-and-ffm-loop-residuals-proposals-RETIRED-20261026.md`,
/// [`jit_osr_late_static_cell_enabled`]): an OSR body's late-bind cell waits
/// for its callee's publication ([`JitCache::publish_osr_body_late_cells`]).
#[cfg(test)]
mod t1_jit2_osr_late_cell_tests {
    use super::*;
    use std::sync::Arc;

    const CALLER: u32 = 0x7a10;
    const CALLEE: u32 = 0x7a11;

    fn body(with_context: bool) -> CompiledMethod {
        let mut buf = ExecutableBuffer::new(64).expect("executable buffer");
        buf.emit(&[0xC3]); // RET
        if with_context {
            CompiledMethod::new_with_context(buf)
        } else {
            CompiledMethod::new(buf)
        }
    }

    /// An OSR body owning one late-bind cell for `t1j2/B.b()V`, published.
    /// `None` when this configuration refuses the publication.
    fn publish_osr_caller(cache: &JitCache) -> Option<Arc<JitCycleEdgeCell>> {
        let mut osr = body(true);
        osr.compiled_via_osr = true;
        let cell = JitCycleEdgeCell::new(
            "t1j2/B",
            "b",
            "()V",
            cratonvm_types::ClassId::new(CALLEE),
            true,
        );
        osr._jit_cycle_cells.push(Arc::clone(&cell));
        cache.put_osr(
            "t1j2/A".into(),
            "a".into(),
            "()V".into(),
            cratonvm_types::ClassId::new(CALLER),
            osr,
        );
        cache
            .get_osr("t1j2/A", "a", "()V", cratonvm_types::ClassId::new(CALLER))
            .map(|_| cell)
    }

    fn publish_callee(cache: &JitCache, with_context: bool) {
        cache.put(
            "t1j2/B".into(),
            "b".into(),
            "()V".into(),
            cratonvm_types::ClassId::new(CALLEE),
            body(with_context),
        );
    }

    fn callee_entry(cache: &JitCache) -> Option<u64> {
        cache
            .get("t1j2/B", "b", "()V", cratonvm_types::ClassId::new(CALLEE))
            .map(|b| b.entry_ptr() as u64)
    }

    /// The callee publishes AFTER the OSR body: the publication binds the
    /// site, and the callee's eviction sends it back to dispatch.
    #[test]
    fn put_osr_registers_a_late_cell_that_the_callee_publication_fills() {
        let cache = JitCache::new();
        let Some(cell) = publish_osr_caller(&cache) else {
            return;
        };
        assert_eq!(cell.current_entry(), 0, "no callee body yet: the site dispatches");
        publish_callee(&cache, true);
        let Some(b) = callee_entry(&cache) else {
            return;
        };
        assert_eq!(cell.current_entry(), b, "the callee's publication binds the OSR site");
        cache.remove("t1j2/B", "b", "()V", cratonvm_types::ClassId::new(CALLEE));
        assert_eq!(cell.current_entry(), 0, "the eviction sends the site back to dispatch");
        cache.clear_all();
    }

    /// The callee was published before the OSR body: `put_osr` fills at once.
    #[test]
    fn put_osr_fills_a_late_cell_whose_callee_is_already_published() {
        let cache = JitCache::new();
        publish_callee(&cache, true);
        let Some(b) = callee_entry(&cache) else {
            return;
        };
        let Some(cell) = publish_osr_caller(&cache) else {
            return;
        };
        assert_eq!(cell.current_entry(), b);
        cache.clear_all();
        assert_eq!(cell.current_entry(), 0, "clear_all clears the OSR body's cell too");
    }

    /// An unpublished body's cells (the VM's optimizing OSR bodies): the
    /// explicit registration fills them, a later callee publication refills
    /// them, and `clear_all` clears them.
    #[test]
    fn an_unpublished_body_late_cell_binds_after_registration() {
        let cache = JitCache::new();
        let mut osr = body(true);
        osr.compiled_via_osr = true;
        let cell = JitCycleEdgeCell::new(
            "t1j2/B",
            "b",
            "()V",
            cratonvm_types::ClassId::new(CALLEE),
            true,
        );
        osr._jit_cycle_cells.push(Arc::clone(&cell));
        let osr = Arc::new(osr);
        publish_callee(&cache, true);
        assert_eq!(cell.current_entry(), 0, "not registered: nothing fills it");
        cache.register_unpublished_body_late_cells(&osr);
        let Some(b1) = callee_entry(&cache) else {
            return;
        };
        assert_eq!(cell.current_entry(), b1);
        publish_callee(&cache, true);
        let Some(b2) = callee_entry(&cache) else {
            return;
        };
        assert_eq!(cell.current_entry(), b2, "a key-waiting cell follows the newest body");
        cache.clear_all();
        assert_eq!(cell.current_entry(), 0);
        drop(osr);
    }

    /// A callee body of the other entry ABI is never installed (the cell
    /// stages the VM context): the site keeps dispatching.
    #[test]
    fn a_late_osr_cell_refuses_a_callee_of_another_abi() {
        let cache = JitCache::new();
        let Some(cell) = publish_osr_caller(&cache) else {
            return;
        };
        publish_callee(&cache, false);
        assert_eq!(cell.current_entry(), 0);
        cache.clear_all();
    }

    /// The switch is default ON since j27 2026-10-28 (`=0` kills) and implies
    /// the late cell's own switches.
    #[test]
    fn the_osr_late_static_cell_switch_is_default_on_under_its_implications() {
        {
            let _flags = cratonvm_types::flags::override_thread(
                cratonvm_types::flags::VmFlags::from_env_with_edits(&[(
                    "CRATONVM_JIT_OSR_LATE_STATIC_CELL",
                    None,
                )]),
            );
            assert_eq!(
                jit_osr_late_static_cell_enabled(),
                jit_late_static_cell_enabled()
                    && jit_cycle_edge_cell_enabled()
                    && jit_cycle_direct_bind_enabled()
                    && direct_jit_callee_calls_enabled(),
                "unset is ON wherever the implied switches are"
            );
        }
        {
            let _flags = cratonvm_types::flags::override_thread(
                cratonvm_types::flags::VmFlags::from_env_with_edits(&[(
                    "CRATONVM_JIT_OSR_LATE_STATIC_CELL",
                    Some("0"),
                )]),
            );
            assert!(!jit_osr_late_static_cell_enabled());
        }
        {
            let _flags = cratonvm_types::flags::override_thread(
                cratonvm_types::flags::VmFlags::from_env_with_edits(&[
                    ("CRATONVM_JIT_OSR_LATE_STATIC_CELL", Some("1")),
                    ("CRATONVM_JIT_LATE_STATIC_CELL", Some("0")),
                ]),
            );
            assert!(!jit_osr_late_static_cell_enabled());
        }
    }

    /// t1 wave 3, lane X: the IR-OSR registration is default ON, killed by
    /// `CRATONVM_JIT_IR_OSR_CELL_REGISTER=0`, and implied by the opt-in switch.
    #[test]
    fn t1x_the_ir_osr_cell_registration_is_default_on() {
        {
            let _flags = cratonvm_types::flags::override_thread(
                cratonvm_types::flags::VmFlags::from_env_with_edits(&[
                    ("CRATONVM_JIT_IR_OSR_CELL_REGISTER", None),
                    ("CRATONVM_JIT_OSR_LATE_STATIC_CELL", None),
                ]),
            );
            assert!(jit_ir_osr_cell_registration_enabled());
        }
        {
            // `CRATONVM_JIT_OSR_LATE_STATIC_CELL` is default ON since j27
            // 2026-10-28 and implies the registration, so the kill needs both.
            let _flags = cratonvm_types::flags::override_thread(
                cratonvm_types::flags::VmFlags::from_env_with_edits(&[
                    ("CRATONVM_JIT_IR_OSR_CELL_REGISTER", Some("0")),
                    ("CRATONVM_JIT_OSR_LATE_STATIC_CELL", Some("0")),
                ]),
            );
            assert!(!jit_ir_osr_cell_registration_enabled());
        }
        {
            let _flags = cratonvm_types::flags::override_thread(
                cratonvm_types::flags::VmFlags::from_env_with_edits(&[
                    ("CRATONVM_JIT_IR_OSR_CELL_REGISTER", Some("0")),
                    ("CRATONVM_JIT_OSR_LATE_STATIC_CELL", Some("1")),
                ]),
            );
            assert_eq!(
                jit_ir_osr_cell_registration_enabled(),
                jit_osr_late_static_cell_enabled()
            );
        }
    }

    /// t1 wave 3, lane X: an IR-OSR body's cell (unpublished body) never reads
    /// a stale target. Unregistered, nothing fills it, so a callee published
    /// and then evicted is never seen; registered, it binds the live callee,
    /// returns to dispatch on the callee's eviction, rebinds on a republication,
    /// and is cleared by `clear_all`.
    #[test]
    fn t1x_an_ir_osr_cell_follows_its_callee_only_while_registered() {
        let cache = JitCache::new();
        let mut osr = body(true);
        osr.compiled_via_osr = true;
        let cell = JitCycleEdgeCell::new(
            "t1j2/B",
            "b",
            "()V",
            cratonvm_types::ClassId::new(CALLEE),
            true,
        );
        osr._jit_cycle_cells.push(Arc::clone(&cell));
        let osr = Arc::new(osr);
        publish_callee(&cache, true);
        cache.remove("t1j2/B", "b", "()V", cratonvm_types::ClassId::new(CALLEE));
        assert_eq!(cell.current_entry(), 0, "unregistered: never filled");
        publish_callee(&cache, true);
        cache.register_unpublished_body_late_cells(&osr);
        let Some(b1) = callee_entry(&cache) else {
            return;
        };
        assert_eq!(cell.current_entry(), b1, "registration binds the live callee");
        cache.remove("t1j2/B", "b", "()V", cratonvm_types::ClassId::new(CALLEE));
        assert_eq!(cell.current_entry(), 0, "the eviction sends the site back to dispatch");
        publish_callee(&cache, true);
        let Some(b2) = callee_entry(&cache) else {
            return;
        };
        assert_eq!(cell.current_entry(), b2, "the republication rebinds it");
        cache.clear_all();
        assert_eq!(cell.current_entry(), 0);
        drop(osr);
    }
}

#[cfg(test)]
mod r9w10_call10_tests {
    use super::*;

    fn method(is_static: bool, is_synchronized: bool, name: &str) -> CachedBytecodeMethod {
        CachedBytecodeMethod {
            declaring_class_id: cratonvm_types::ClassId::new(0x0010_2001),
            class_name: Arc::from("r9w10/P"),
            method_name: Arc::from(name),
            method_descriptor: Arc::from("(I)I"),
            source_file: None,
            code: Arc::from(&[0xac_u8, 0x00, 0x00][..]),
            exception_table: Arc::from(Vec::new().as_slice()),
            max_stack: 2,
            max_locals: 2,
            num_params: 1,
            is_synchronized,
            is_static,
            force_native_cache: std::sync::OnceLock::new(),
            hidden_frame: std::sync::OnceLock::new(),
            descriptor_facts_cache: std::sync::OnceLock::new(),
            intercept_shape_cache: std::sync::OnceLock::new(),
            interp_invocations: std::sync::atomic::AtomicU32::new(0),
            tiering_settled: std::sync::atomic::AtomicU32::new(0),
            branch_profile_armed: std::sync::atomic::AtomicBool::new(false),
            native_callback_cache: std::sync::OnceLock::new(),
            invoc_key: std::sync::OnceLock::new(),
            jit_probe_generation: std::sync::atomic::AtomicU64::new(0),
            quickened: std::sync::OnceLock::new(),
            array_inc_declined: std::sync::OnceLock::new(),
            ctor_verdict_memo: std::sync::OnceLock::new(),
            pool_generation: u64::MAX,
        }
    }

    /// The one predicate both tiers ask: a statically bound
    /// `invokevirtual`/`invokespecial` of this very instance method, and
    /// nothing else.
    #[test]
    fn only_a_statically_bound_instance_self_call_goes_direct() {
        let _on = cratonvm_types::flags::override_thread(
            cratonvm_types::flags::VmFlags::from_env_with_edits(&[(
                "CRATONVM_JIT_INSTANCE_SELF_CALL",
                None,
            )]),
        );
        let m = method(false, false, "s");
        let ask = |m: &CachedBytecodeMethod, op: u8, bound: bool, owner: &str, name: &str| {
            instance_self_call_goes_direct(m, op, bound, owner, name, "(I)I", true, 0x1140)
        };
        assert!(
            ask(&m, 0xb6, true, "r9w10/P", "s"),
            "private invokevirtual, pinned"
        );
        assert!(ask(&m, 0xb7, true, "r9w10/P", "s"), "invokespecial");
        assert!(
            !ask(&m, 0xb6, false, "r9w10/P", "s"),
            "a virtual site dispatches"
        );
        assert!(
            !ask(&m, 0xb9, true, "r9w10/P", "s"),
            "invokeinterface keeps its bind"
        );
        assert!(
            !ask(&m, 0xb8, true, "r9w10/P", "s"),
            "static sites have their own route"
        );
        assert!(
            !ask(&m, 0xb7, true, "r9w10/Q", "s"),
            "a super call is another method"
        );
        assert!(!ask(&m, 0xb7, true, "r9w10/P", "t"), "another method");
        assert!(!instance_self_call_goes_direct(
            &m, 0xb7, true, "r9w10/P", "s", "(J)I", true, 0x1140
        ));
        assert!(
            !instance_self_call_goes_direct(&m, 0xb7, true, "r9w10/P", "s", "(I)I", false, 0x1140),
            "unstable loader identity"
        );
        assert!(
            !instance_self_call_goes_direct(&m, 0xb7, true, "r9w10/P", "s", "(I)I", true, 0),
            "no stack guard"
        );
        assert!(!ask(&method(true, false, "s"), 0xb7, true, "r9w10/P", "s"));
        assert!(
            !ask(&method(false, true, "s"), 0xb7, true, "r9w10/P", "s"),
            "synchronized: the entry takes no monitor"
        );
        assert!(!ask(
            &method(false, false, "<init>"),
            0xb7,
            true,
            "r9w10/P",
            "<init>"
        ));
        let _off = cratonvm_types::flags::override_thread(
            cratonvm_types::flags::VmFlags::from_env_with_edits(&[(
                "CRATONVM_JIT_INSTANCE_SELF_CALL",
                Some("0"),
            )]),
        );
        assert!(!ask(&m, 0xb7, true, "r9w10/P", "s"), "switched off");
    }
}

/// Interpreter round i1 wave 10, lane L5: the adapter fold is armed by the
/// constant pool (`lambda_int_to_double_runs_proven`), not by a class name.
#[cfg(test)]
mod lambda_int_to_double_proof_tests {
    use super::lambda_int_to_double_runs_proven;

    type Names = Option<(String, String, String)>;

    fn names(c: &str, m: &str, d: &str) -> Names {
        Some((c.to_string(), m.to_string(), d.to_string()))
    }

    /// `f.apply(i)` unboxed to `double`: `aload_1; iload_2; invokestatic #10;
    /// invokeinterface #11 1 0; checkcast #12; invokevirtual #13; dreturn`.
    const RUN: [u8; 17] = [
        0x2b, 0x1c, 0xb8, 0x00, 0x0a, 0xb9, 0x00, 0x0b, 0x01, 0x00, 0xc0, 0x00, 0x0c, 0xb6, 0x00,
        0x0d, 0xaf,
    ];

    fn invoke(idx: u16) -> Names {
        match idx {
            10 => names("java/lang/Integer", "valueOf", "(I)Ljava/lang/Integer;"),
            11 => names(
                "java/util/function/Function",
                "apply",
                "(Ljava/lang/Object;)Ljava/lang/Object;",
            ),
            13 => names("java/lang/Double", "doubleValue", "()D"),
            _ => None,
        }
    }

    fn class(idx: u16) -> Option<String> {
        (idx == 12).then(|| "java/lang/Double".to_string())
    }

    #[test]
    fn a_run_whose_four_members_the_pool_proves_arms_the_fold() {
        assert!(lambda_int_to_double_runs_proven(
            &RUN,
            RUN.len(),
            &invoke,
            &class
        ));
    }

    #[test]
    fn a_run_naming_another_member_does_not() {
        // Another boxing overload at the first site.
        let other_box = |idx: u16| match idx {
            10 => names(
                "java/lang/Integer",
                "valueOf",
                "(Ljava/lang/String;)Ljava/lang/Integer;",
            ),
            _ => invoke(idx),
        };
        assert!(!lambda_int_to_double_runs_proven(
            &RUN,
            RUN.len(),
            &other_box,
            &class
        ));
        // Another functional interface.
        let other_sam = |idx: u16| match idx {
            11 => names(
                "java/util/function/IntFunction",
                "apply",
                "(I)Ljava/lang/Object;",
            ),
            _ => invoke(idx),
        };
        assert!(!lambda_int_to_double_runs_proven(
            &RUN,
            RUN.len(),
            &other_sam,
            &class
        ));
        // Another cast.
        let other_cast = |idx: u16| (idx == 12).then(|| "java/lang/Number".to_string());
        assert!(!lambda_int_to_double_runs_proven(
            &RUN,
            RUN.len(),
            &invoke,
            &other_cast
        ));
        // A pool that cannot answer.
        assert!(!lambda_int_to_double_runs_proven(
            &RUN,
            RUN.len(),
            &|_| None,
            &class
        ));
    }

    #[test]
    fn one_unproven_run_disarms_the_whole_method() {
        // The run twice (the first without its `dreturn`, its double popped
        // with `pop2`), the second naming `apply` through pool entry 14.
        let mut code = RUN[..16].to_vec();
        code.push(0x58);
        let second = [
            0x2b, 0x1c, 0xb8, 0x00, 0x0a, 0xb9, 0x00, 0x0e, 0x01, 0x00, 0xc0, 0x00, 0x0c, 0xb6,
            0x00, 0x0d, 0xaf,
        ];
        code.extend_from_slice(&second);
        assert!(!lambda_int_to_double_runs_proven(
            &code,
            code.len(),
            &invoke,
            &class
        ));
        let with_14 = |idx: u16| if idx == 14 { invoke(11) } else { invoke(idx) };
        assert!(lambda_int_to_double_runs_proven(
            &code,
            code.len(),
            &with_14,
            &class
        ));
    }

    #[test]
    fn a_method_with_no_run_is_not_armed_and_operand_bytes_are_not_opcodes() {
        assert!(!lambda_int_to_double_runs_proven(
            &[0xb1],
            1,
            &invoke,
            &class
        ));
        // `bipush 0xb8; pop; nop; invokeinterface #11; checkcast #12;
        // invokevirtual #13; return`: read byte by byte, pc 1 would be an
        // `invokestatic #0x5700` heading the shape. It is `bipush`'s operand.
        let code = [
            0x10, 0xb8, 0x57, 0x00, 0xb9, 0x00, 0x0b, 0x01, 0x00, 0xc0, 0x00, 0x0c, 0xb6, 0x00,
            0x0d, 0xb1,
        ];
        let lenient = |idx: u16| {
            if idx == 0x5700 {
                invoke(10)
            } else {
                invoke(idx)
            }
        };
        assert!(!lambda_int_to_double_runs_proven(
            &code,
            code.len(),
            &lenient,
            &class
        ));
    }

    /// No jit-crate source names the TDigest class in a string literal any
    /// more: the fold, the splice stand-down and the allocation-sink screen
    /// all ask `lambda_int_to_double_proven`.
    #[test]
    fn the_jit_crate_names_no_application_class_for_the_fold() {
        let needle = concat!("\"org/elasticsearch/", "tdigest/");
        for src in [
            include_str!("lib.rs"),
            include_str!("ir.rs"),
            include_str!("x64/op_invoke.rs"),
            include_str!("x64/op_object.rs"),
            include_str!("x64/inlining.rs"),
        ] {
            assert!(!src.contains(needle));
        }
    }
}

/// Interpreter round i1 wave 17, lane L3: a spliced body's substituted owner
/// travels with its id (`i14-L2-proposal-substitutions-keyed-by-call-site`,
/// stage 1).
#[cfg(test)]
mod i17_l3_inline_owner_id_tests {
    use super::*;

    fn target(class: &str, kind: u8, owner_class_id: u32) -> InlineInvokeTarget {
        InlineInvokeTarget {
            class_name: class.to_string(),
            method_name: "m".to_string(),
            descriptor: "()I".to_string(),
            num_jit_args: 1,
            return_type: b'I',
            invoke_kind: kind,
            declaring_class_id: 21,
            resolved_class_id: 0,
            owner_class_id,
            direct_entry: None,
        }
    }

    /// The interned `JitInvokeInfo` of a spliced call carries the owner id
    /// the resolver recorded (a private target pinned to its declaring class)
    /// and `0` for a site the resolver did not substitute, at every nesting
    /// level. Before wave 17 every spliced info carried `0`, so the dispatch
    /// helper resolved the declaring class's name through the body's loader.
    #[test]
    fn interning_copies_the_substituted_owner_id() {
        let inner = InlineSite {
            invoke_targets: vec![(2, target("i17/Nest$Peer", 1, 0x0003_0007))],
            ..Default::default()
        };
        let mut outer = InlineSite {
            invoke_targets: vec![
                (1, target("i17/Nest$Host", 1, 0x0003_0005)),
                (4, target("i17/Plain", 0, 0)),
            ],
            nested_sites: vec![NestedInlineSite {
                callee_pc: 9,
                guard_class_id: 0,
                site: inner,
                bimorphic_second: None,
            }],
            ..Default::default()
        };
        let mut strings: Vec<Box<str>> = Vec::new();
        let mut infos: Vec<Box<JitInvokeInfo>> = Vec::new();
        let mut direct: Vec<(usize, u64)> = Vec::new();
        intern_inline_invoke_targets(&mut outer, &mut strings, &mut infos, &mut direct);

        let owner_at = |site: &InlineSite, pc: usize| -> (&'static str, u32, u8) {
            let resolved = site
                .resolved_invoke_infos
                .iter()
                .find(|r| r.callee_pc == pc)
                .expect("every target is interned");
            // SAFETY: the pointee is one of `infos`, alive for this test.
            let info = unsafe { &*(resolved.info_addr as *const JitInvokeInfo) };
            (info.class_name, info.owner_class_id, info.invoke_kind)
        };
        assert_eq!(owner_at(&outer, 1), ("i17/Nest$Host", 0x0003_0005, 1));
        assert_eq!(owner_at(&outer, 4), ("i17/Plain", 0, 0));
        assert_eq!(
            owner_at(&outer.nested_sites[0].site, 2),
            ("i17/Nest$Peer", 0x0003_0007, 1),
            "a nested body's substituted owner keeps its id too"
        );
        assert_eq!(infos.len(), 3);
    }
}

/// Interpreter round i1 wave 17, lane L3: an inherited-name call's declaring
/// class is named by identity in the recursion-cycle checks
/// (`i13-L3-proposal-callee-resolvers-answer-the-bound-method-identity`,
/// stage 1).
#[cfg(test)]
mod i17_l3_declaring_identity_tests {
    use super::*;

    const DESC: &str = "(I)I";

    fn with_stack<R>(keys: &[JitCompileMethodKey], body: impl FnOnce() -> R) -> R {
        JIT_COMPILE_STACK.with(|stack| stack.borrow_mut().extend(keys.iter().cloned()));
        let out = body();
        JIT_COMPILE_STACK.with(|stack| {
            let mut stack = stack.borrow_mut();
            let keep = stack.len() - keys.len();
            stack.truncate(keep);
        });
        out
    }

    /// `invokestatic i17/Sub.f` (cp #7) resolves to `i17/A.f`. With the VM's
    /// declaring-class id, a cycle through loader one's `A.f` (id 21) keeps
    /// the call on dispatch only when the site's own loader resolves `A` to
    /// that class: another loader's same-named `A` (id 22) is neither closed
    /// nor kept. Without an id (no resolver, a `None` or `0` answer) the ask
    /// matches by names, the pre-wave-17 answer.
    #[test]
    fn an_inherited_name_call_is_matched_by_its_declaring_class_identity() {
        let one = cratonvm_types::ClassId::new(21);
        let vm = JitVerdictRegistry::default();
        let declaring_name = |cp_idx: u16| (cp_idx == 7).then(|| "i17/A".to_string());
        let names: &dyn Fn(u16) -> Option<String> = &declaring_name;
        let this_loader = |cp_idx: u16| (cp_idx == 7).then_some(21u32);
        let other_loader = |cp_idx: u16| (cp_idx == 7).then_some(22u32);
        let sentinel = |_: u16| Some(0u32);
        let this_loader: &dyn Fn(u16) -> Option<u32> = &this_loader;
        let other_loader: &dyn Fn(u16) -> Option<u32> = &other_loader;
        let sentinel: &dyn Fn(u16) -> Option<u32> = &sentinel;

        let stack = [
            JitCompileMethodKey::of_class(one, "i17/A", "f", DESC),
            JitCompileMethodKey::of_class(one, "i17/A", "g", DESC),
        ];
        let (other_closed, closed) = with_stack(&stack, || {
            let cycle =
                cycle_site_declaring_class(&vm, Some(names), 7, "i17/Sub", "f", DESC, || true);
            assert_eq!(cycle.as_deref(), Some("i17/A"));
            // Another loader's `A.f` is not the open compile: nothing closes.
            let other = vm.note_recursive_compile_cycle("i17/A", "f", DESC, true, || {
                cycle_site_declaring_class_id(Some(other_loader), 7)
            });
            let same = vm.note_recursive_compile_cycle("i17/A", "f", DESC, true, || {
                cycle_site_declaring_class_id(Some(this_loader), 7)
            });
            (other, same)
        });
        assert!(
            !other_closed,
            "another loader's same-named A.f closes no cycle"
        );
        assert!(closed, "the site's own A.f closes the cycle");

        let keeps = |resolver: Option<&dyn Fn(u16) -> Option<u32>>| {
            vm.direct_call_requires_dispatch_of("i17/A", "f", DESC, || {
                cycle_site_declaring_class_id(resolver, 7)
            })
        };
        assert!(keeps(Some(this_loader)));
        assert!(
            !keeps(Some(other_loader)),
            "another loader's same-named A.f is not kept on dispatch"
        );
        // No identity: the conservative, name-matched answer.
        assert!(keeps(None));
        assert!(keeps(Some(sentinel)));
        assert_eq!(cycle_site_declaring_class_id(Some(this_loader), 8), None);
    }
}

/// gc-common w36-c: the class-unload batch forms (`UnloadedClassSet`) are
/// equivalent to a loop of their per-class forms
/// (`docs/feature-designs/jit-ir-optimizations.md`).
#[cfg(test)]
mod w36c_unload_batch_tests {
    use super::*;
    use cratonvm_types::ClassId;

    const A: ClassId = ClassId::new(0x7A36_C101);
    const A2: ClassId = ClassId::new(0x7A36_C102);
    const B: ClassId = ClassId::new(0x7A36_C103);
    const C: ClassId = ClassId::new(0x7A36_C104);
    const NONE: ClassId = ClassId::new(0);

    /// Two loaders' `w36c/A`, an identified and an id-less `w36c/B` and
    /// `w36c/C`.
    const ROWS: [(ClassId, &str); 6] = [
        (A, "w36c/A"),
        (A2, "w36c/A"),
        (B, "w36c/B"),
        (NONE, "w36c/B"),
        (C, "w36c/C"),
        (NONE, "w36c/C"),
    ];

    /// The empty set, an absent class, one class, and a mixed set with an
    /// id-less member.
    const SETS: [&[(ClassId, &str)]; 4] = [
        &[],
        &[(ClassId::new(0x7A36_C1F8), "w36c/Absent")],
        &[(A, "w36c/A")],
        &[(A, "w36c/A"), (B, "w36c/B"), (NONE, "w36c/C")],
    ];

    /// `owns` is `tiered::MethodKey::belongs_to` asked of every member, for
    /// every subset of the rows as members and every row as the key.
    #[test]
    fn owns_is_belongs_to_asked_of_every_member() {
        for mask in 0u32..(1 << ROWS.len()) {
            let members: Vec<(ClassId, &str)> = ROWS
                .iter()
                .enumerate()
                .filter(|(i, _)| mask & (1 << i) != 0)
                .map(|(_, row)| *row)
                .collect();
            let set = UnloadedClassSet::new(members.iter().copied());
            assert_eq!(set.is_empty(), members.is_empty());
            for &(id, name) in &ROWS {
                let key = crate::tiered::MethodKey::with_class_id(id, name, "m", "()V");
                let expected = members
                    .iter()
                    .any(|&(mid, mname)| key.belongs_to(mid, mname));
                assert_eq!(
                    set.owns(id, name),
                    expected,
                    "key {id:?} {name} in {members:?}"
                );
                assert_eq!(
                    set.contains_nonzero_id(id),
                    id.as_u32() != 0 && members.iter().any(|&(mid, _)| mid == id)
                );
            }
        }
    }

    #[test]
    fn forget_for_classes_matches_a_loop_of_forget_for_class() {
        let fill = || {
            let vm = JitVerdictRegistry::default();
            for &(id, name) in &ROWS {
                vm.mark_bail_listed(id, name, "m", "()V");
            }
            vm
        };
        let state = |vm: &JitVerdictRegistry| -> Vec<bool> {
            ROWS.iter()
                .map(|&(id, name)| vm.is_bail_listed(id, name, "m", "()V"))
                .collect()
        };
        for set in SETS {
            let looped = fill();
            let looped_count: usize = set
                .iter()
                .map(|&(id, name)| looped.forget_for_class(id, name))
                .sum();
            let batched = fill();
            let batched_count =
                batched.forget_for_classes(&UnloadedClassSet::new(set.iter().copied()));
            assert_eq!(state(&looped), state(&batched), "set {set:?}");
            assert_eq!(looped_count, batched_count, "set {set:?}");
            assert_eq!(looped.bail_list_size(), batched.bail_list_size());
        }
        let batched = fill();
        assert_eq!(
            batched.forget_for_classes(&UnloadedClassSet::new(SETS[3].iter().copied())),
            5
        );
        assert_eq!(state(&batched), [false, true, false, false, false, false]);
    }

    #[test]
    fn forget_class_ids_matches_a_loop_of_forget_class_id() {
        let fill = || {
            let mut cycles = CycleSet::default();
            for &(id, name) in &ROWS {
                cycles.insert(JitCompileMethodKey::of_class(id, name, "m", "()V"));
            }
            cycles
        };
        let members = |cycles: &CycleSet| {
            let mut rows: Vec<(u32, String)> = cycles
                .by_names
                .values()
                .flatten()
                .map(|key| (key.class_id.as_u32(), key.class_name.clone()))
                .collect();
            rows.sort();
            rows
        };
        for set in SETS {
            let mut looped = fill();
            let looped_count: usize = set.iter().map(|&(id, _)| looped.forget_class_id(id)).sum();
            let mut batched = fill();
            let batched_count =
                batched.forget_class_ids(&UnloadedClassSet::new(set.iter().copied()));
            assert_eq!(members(&looped), members(&batched), "set {set:?}");
            assert_eq!(looped_count, batched_count, "set {set:?}");
        }
        // Exact non-zero identity only: the mixed set drops `A` and `B`, and
        // keeps the other loader's `A` and every id-less member.
        let mut batched = fill();
        assert_eq!(
            batched.forget_class_ids(&UnloadedClassSet::new(SETS[3].iter().copied())),
            2
        );
        assert_eq!(batched.len(), 4);
        let registry = JitVerdictRegistry::default();
        assert_eq!(
            registry.forget_cycle_members_of_unloaded_classes(&UnloadedClassSet::new(
                SETS[3].iter().copied()
            )),
            0
        );
    }

    fn body(inlined: &[(&str, &str, &str)]) -> CompiledMethod {
        let mut cm = CompiledMethod::new(ExecutableBuffer::new(64).unwrap());
        cm.inlined_methods = inlined
            .iter()
            .map(|(c, m, d)| (c.to_string(), m.to_string(), d.to_string()))
            .collect();
        cm
    }

    /// `(class, method, declaring id)` of every body `fill_cache` publishes.
    const BODIES: [(&str, &str, ClassId); 6] = [
        ("w36c/A", "m", A),
        ("w36c/A", "m", A2),
        ("w36c/Caller", "inl", ClassId::new(0x7A36_C105)),
        ("w36c/Direct", "call", ClassId::new(0x7A36_C106)),
        ("w36c/Other", "o", ClassId::new(0x7A36_C107)),
        ("w36c/Z", "z", NONE),
    ];

    /// Body 2 inlined from `w36c/B`; body 3 bakes a direct call into body 0,
    /// so it goes with body 0 through the reverse closure.
    fn fill_cache() -> JitCache {
        let cache = JitCache::new();
        let mut direct_callee = 0usize;
        for (i, &(class, method, id)) in BODIES.iter().enumerate() {
            let mut cm = match i {
                2 => body(&[("w36c/B", "x", "()V")]),
                _ => body(&[]),
            };
            if i == 0 {
                direct_callee = cm.entry_ptr() as usize;
            }
            if i == 3 {
                cm._direct_callee_entries.push(direct_callee);
            }
            cache.put(class.into(), method.into(), "()V".into(), id, cm);
        }
        cache
    }

    fn live_bodies(cache: &JitCache) -> Vec<bool> {
        BODIES
            .iter()
            .map(|&(class, method, id)| cache.get(class, method, "()V", id).is_some())
            .collect()
    }

    #[test]
    fn invalidate_unloaded_classes_matches_a_loop_of_invalidate_unloaded_class() {
        for set in SETS {
            let looped = fill_cache();
            assert_eq!(live_bodies(&looped), [true; 6], "every body published");
            let looped_count: usize = set
                .iter()
                .map(|&(id, name)| looped.invalidate_unloaded_class(id, name))
                .sum();
            let batched = fill_cache();
            let batched_count =
                batched.invalidate_unloaded_classes(&UnloadedClassSet::new(set.iter().copied()));
            assert_eq!(live_bodies(&looped), live_bodies(&batched), "set {set:?}");
            assert_eq!(looped_count, batched_count, "set {set:?}");
        }
        // The mixed set: `A`'s body and its direct caller, the body that
        // inlined from `B`, and (by plain equality with the id-less member,
        // as the per-class form does) the id-less body.
        let batched = fill_cache();
        assert_eq!(
            batched.invalidate_unloaded_classes(&UnloadedClassSet::new(SETS[3].iter().copied())),
            4
        );
        assert_eq!(
            live_bodies(&batched),
            [false, true, false, false, true, false]
        );
    }

    /// Round 13 wave 12 (lane guardsplice): a body that spliced an unloaded
    /// class's bytecode -- recorded only in `copied_classes`, as the IR tier
    /// records it -- goes with the class, in both forms; with
    /// `CRATONVM_JIT_UNLOAD_WITHDRAWS_COPIED=0` it stays.
    #[test]
    fn an_unload_withdraws_a_body_that_copied_the_class() {
        const DOOMED: ClassId = ClassId::new(0x7A36_C1F0);
        let fill = || {
            let cache = JitCache::new();
            let mut cm = body(&[]);
            cm.copied_classes = vec![DOOMED.as_u32()].into_boxed_slice();
            cache.put(
                "w12g/Caller".into(),
                "run".into(),
                "()V".into(),
                ClassId::new(0x7A36_C1F1),
                cm,
            );
            cache
        };
        let live = |cache: &JitCache| {
            cache
                .get("w12g/Caller", "run", "()V", ClassId::new(0x7A36_C1F1))
                .is_some()
        };
        let set = [(DOOMED, "w12g/Plugin")];
        let batched = fill();
        assert!(live(&batched));
        assert_eq!(
            batched.invalidate_unloaded_classes(&UnloadedClassSet::new(set.iter().copied())),
            1
        );
        assert!(!live(&batched));
        let looped = fill();
        assert_eq!(looped.invalidate_unloaded_class(DOOMED, "w12g/Plugin"), 1);
        assert!(!live(&looped));
        cratonvm_types::flags::with_thread_overrides(
            &[("CRATONVM_JIT_UNLOAD_WITHDRAWS_COPIED", Some("0"))],
            || {
                let kept = fill();
                assert_eq!(
                    kept.invalidate_unloaded_classes(&UnloadedClassSet::new(set.iter().copied())),
                    0
                );
                assert!(live(&kept));
            },
        );
    }
}

/// Interpreter round i1 wave 40, lane L2 follow-up: nothing is published
/// while a multi-class redefinition call holds the cache
/// (`JitCache::hold_publications`), and publication resumes once it is
/// released.
#[cfg(test)]
mod i40_l2_publication_hold_tests {
    use super::*;
    use std::sync::Arc;

    fn body() -> CompiledMethod {
        let mut buf = ExecutableBuffer::new(64).expect("executable buffer");
        buf.emit(&[0xC3]); // RET
        CompiledMethod::new(buf)
    }

    fn put(cache: &JitCache) {
        cache.put(
            Arc::from("i40l2/P"),
            Arc::from("v"),
            Arc::from("()I"),
            cratonvm_types::ClassId::new(0x0040_1201),
            body(),
        );
    }

    fn published(cache: &JitCache) -> bool {
        cache
            .get(
                "i40l2/P",
                "v",
                "()I",
                cratonvm_types::ClassId::new(0x0040_1201),
            )
            .is_some()
    }

    #[test]
    fn a_held_cache_publishes_nothing_until_released() {
        let cache = JitCache::new();
        assert!(!cache.publications_held());
        cache.hold_publications();
        assert!(cache.publications_held());
        put(&cache);
        assert!(!published(&cache), "refused while a call installs");
        cache.release_publications();
        assert!(!cache.publications_held());
        put(&cache);
        assert!(published(&cache), "published once the call is done");
        // An unmatched release does not wrap the count.
        cache.release_publications();
        assert!(!cache.publications_held());
    }
}

#[cfg(test)]
mod r16w15_throwfill_walk_lookup_tests {
    use super::{
        jit_code_range_view, lookup_jit_code_range, register_jit_code_range,
        unregister_jit_code_range, CompiledMethod, ExecutableBuffer, OopMapEntry,
    };

    fn artifact() -> CompiledMethod {
        CompiledMethod::new(
            ExecutableBuffer::new(64).expect("executable buffer alloc must succeed in tests"),
        )
    }

    fn map(id: u32) -> OopMapEntry {
        let mut m = OopMapEntry::new(0);
        m.bytecode_pc = id;
        m
    }

    /// The index answers exactly what the scan answers, for ids present (in
    /// any order, repeated), absent, and at the edges of `u32`.
    #[test]
    fn the_index_answers_the_scan() {
        let mut cm = artifact();
        for id in [40, 7, 7, 0, 0xFFFF_FFFE, 19, 40] {
            cm.push_oop_map(map(id));
        }
        for id in [0, 1, 6, 7, 8, 19, 20, 39, 40, 41, 0xFFFF_FFFE, 0xFFFF_FFFF] {
            assert_eq!(
                cm.has_oop_map_for_safepoint_id(id),
                cm.find_oop_map_for_safepoint_id(id).is_some(),
                "{id}"
            );
        }
        let empty = artifact();
        assert!(!empty.has_oop_map_for_safepoint_id(0));
    }

    /// A map added after the index was built is seen: by `push_oop_map`
    /// (which drops the index) and by a direct push onto the public vector
    /// (whose count no longer matches the index's).
    #[test]
    fn a_map_added_after_the_index_is_seen() {
        let mut cm = artifact();
        cm.push_oop_map(map(3));
        assert!(!cm.has_oop_map_for_safepoint_id(9));
        cm.push_oop_map(map(9));
        assert!(cm.has_oop_map_for_safepoint_id(9));
        assert!(!cm.has_oop_map_for_safepoint_id(12));
        cm.oop_maps.push(map(12));
        assert!(cm.has_oop_map_for_safepoint_id(12));
        assert!(cm.has_oop_map_for_safepoint_id(3));
    }

    /// A view answers what `lookup_jit_code_range` answers for every address
    /// in, at the edges of, and around a registered range.
    #[test]
    fn a_view_answers_the_lookup() {
        // Far from any address a real body or another test registers.
        let entry = 0x7E15_0F00_0000usize;
        let cm_ptr = 0x7E15_0F10_0000usize;
        register_jit_code_range(entry, 0x40, cm_ptr);
        let view = jit_code_range_view();
        for addr in [
            entry - 1,
            entry,
            entry + 1,
            entry + 0x3F,
            entry + 0x40,
            entry + 0x1000,
        ] {
            assert_eq!(view.lookup(addr), lookup_jit_code_range(addr), "{addr:#x}");
        }
        assert_eq!(view.lookup(entry + 8), Some(cm_ptr));
        drop(view);
        unregister_jit_code_range(entry);
        assert_eq!(jit_code_range_view().lookup(entry + 8), None);
    }

    /// A walk's batched verdicts land in the same columns as one note each.
    /// The census is process-wide and other tests add to it concurrently, so
    /// only a lower bound on each column's growth is asserted.
    #[test]
    fn batched_verdicts_land_in_their_columns() {
        let before = super::compiled_frame_line_counts();
        let mut batch = [0u64; super::FRAME_LINE_SLOTS];
        batch[super::FRAME_LINE_ANSWERED_SINGLE_PASS] = 5;
        batch[super::FRAME_LINE_REFUSED_ID_UNRECORDED] = 2;
        batch[super::FRAME_LINE_INNERMOST_UNRECORDED] = 1;
        super::note_compiled_frame_lines(&batch);
        let after = super::compiled_frame_line_counts();
        assert_eq!(super::FRAME_LINE_SLOT_NAMES[8], "innermost-unrecorded");
        for slot in 0..super::FRAME_LINE_SLOTS {
            assert!(after[slot] - before[slot] >= batch[slot], "{slot}");
        }
    }
}

#[cfg(test)]
mod gcj_crash_owner_label_tests {
    use super::*;

    #[test]
    fn gcj_crash_label_uses_the_published_owner_without_the_name_census() {
        let mut artifact = CompiledMethod::new(ExecutableBuffer::new(64).unwrap());
        artifact.method_label = "gcj/Owner.field:(Ljava/lang/Object;)I".to_owned();
        let owner = Arc::new(artifact);
        let entry = owner.entry_ptr() as usize;
        register_jit_code_range_owned(entry, 64, &owner);
        cratonvm_types::flags::with_thread_overrides(
            &[("CRATONVM_DBG_JIT_NAMES", Some("0"))],
            || {
                assert_eq!(
                    lookup_jit_code_owner_label(entry + 7).as_deref(),
                    Some("gcj/Owner.field:(Ljava/lang/Object;)I")
                );
            },
        );
        // Keep the buffer mapped while checking withdrawal, so a parallel
        // test cannot reuse this address and supply a different live owner.
        unregister_jit_code_range(entry);
        assert!(lookup_jit_code_owner_label(entry + 7).is_none());
    }

    #[test]
    fn gcj_crash_label_does_not_dereference_a_bare_range_owner() {
        let mut artifact = CompiledMethod::new(ExecutableBuffer::new(64).unwrap());
        artifact.method_label = "gcj/Unpublished.field:()V".to_owned();
        let entry = artifact.entry_ptr() as usize;
        register_jit_code_range(entry, 64, &artifact as *const CompiledMethod as usize);
        assert!(lookup_jit_code_owner_label(entry + 7).is_none());
        unregister_jit_code_range(entry);
    }
}

