/// Round 16 wave 17 (lane mega5, NIO2-1): the `ScopedMemoryAccess` bind
/// admission.
#[cfg(test)]
mod r16w17_mega5_scoped_memory_bind_tests {
    use super::*;

    const SWITCH: &str = "CRATONVM_JIT_SCOPED_MEMORY_BIND_ADMISSION";
    const CLASS: &str = "jdk/internal/misc/ScopedMemoryAccess";
    const NAME: &str = "getIntUnaligned";
    const DESC: &str = "(Ljdk/internal/foreign/MemorySessionImpl;Ljava/lang/Object;JZ)I";

    /// Off (`=0`; default ON since wave 17): the old unconditional bind,
    /// whatever the policy says, and the policy is not even asked.
    #[test]
    fn off_binds_without_asking() {
        let asked = std::cell::Cell::new(0u32);
        let refuse = |_: &str, _: &str, _: &str| {
            asked.set(asked.get() + 1);
            false
        };
        let got = cratonvm_types::flags::with_thread_overrides(&[(SWITCH, Some("0"))], || {
            scoped_memory_bind_admitted(Some(&refuse), CLASS, NAME, DESC)
        });
        assert!(got);
        assert_eq!(asked.get(), 0);
    }

    /// On: the VM's answer decides, for the site's own triple; a request with
    /// no predicate keeps the bind.
    #[test]
    fn on_asks_the_policy_for_the_sites_triple() {
        let seen = std::cell::RefCell::new(Vec::new());
        let refuse = |c: &str, m: &str, d: &str| {
            seen.borrow_mut().push(format!("{c}.{m}{d}"));
            false
        };
        let admit = |_: &str, _: &str, _: &str| true;
        cratonvm_types::flags::with_thread_overrides(&[(SWITCH, Some("1"))], || {
            assert!(!scoped_memory_bind_admitted(
                Some(&refuse),
                CLASS,
                NAME,
                DESC
            ));
            assert!(scoped_memory_bind_admitted(Some(&admit), CLASS, NAME, DESC));
            assert!(scoped_memory_bind_admitted(None, CLASS, NAME, DESC));
        });
        assert_eq!(seen.borrow().as_slice(), &[format!("{CLASS}.{NAME}{DESC}")]);
    }
}

#[cfg(test)]
mod unloaded_static_splice_admission_tests {
    use super::*;

    #[test]
    fn an_unloaded_static_call_requires_a_precise_chain_and_its_own_proof() {
        if !ir_splice_refuse_unbindable_call_enabled() {
            return;
        }
        let mut nested = NestedInlineSite {
            callee_pc: 0,
            guard_class_id: 0,
            site: InlineSite {
                callee_code: vec![0x1a, 0xb8, 0, 1, 0xac],
                callee_code_len: 5,
                callee_max_locals: 1,
                callee_num_args: 1,
                callee_is_static: true,
                return_type: b'I',
                unloaded_static_call_pcs: vec![1],
                invoke_targets: vec![(
                    1,
                    InlineInvokeTarget {
                        class_name: "Unloaded".into(),
                        method_name: "cold".into(),
                        descriptor: "(I)I".into(),
                        invoke_kind: 3,
                        num_jit_args: 1,
                        return_type: b'I',
                        ..Default::default()
                    },
                )],
                ..Default::default()
            },
            bimorphic_second: None,
        };
        assert!(!ir_splice_nested_entry_refused(&nested, None, true));
        assert!(ir_splice_nested_entry_refused(&nested, None, false));
        nested.site.unloaded_static_call_pcs = vec![0];
        assert!(ir_splice_nested_entry_refused(&nested, None, true));
        nested.site.unloaded_static_call_pcs.clear();
        assert!(ir_splice_nested_entry_refused(&nested, None, true));
    }
}

