#[cfg(test)]
mod r18w9_osrpoly_prefer_spliced_single_pass_tests {
    use super::*;

    const IR_POLY: &str = "CRATONVM_JIT_IR_POLYMORPHIC_GUARDED_SPLICE";
    const OSR_POLY: &str = "CRATONVM_JIT_OSR_SPLICE_POLYMORPHIC";

    // 0 iload_0; 1 invokestatic #2; 4 invokespecial #3; 7 invokevirtual #4;
    // 10 goto 1; 13 invokestatic #5 (after the loop); 16 ireturn; padding.
    const CODE: [u8; 19] = [
        0x1a, 0xb8, 0, 2, 0xb7, 0, 3, 0xb6, 0, 4, 0xa7, 0xff, 0xf7, 0xb8, 0, 5, 0xac, 0, 0,
    ];
    const CODE_LEN: usize = 17;
    const OPS: [(usize, u16, u8); 4] = [(1, 2, 0xb8), (4, 3, 0xb7), (7, 4, 0xb6), (13, 5, 0xb8)];

    fn profile_at_7(counts: &[(u32, u32)]) -> profile::MethodProfile {
        let mut receivers = profile::ReceiverCounts::default();
        for &(class_id, n) in counts {
            receivers.insert(class_id, n);
        }
        let mut prof = profile::MethodProfile::default();
        prof.receivers.insert(7, receivers);
        prof
    }

    fn names(_: u16) -> Option<(String, String, String)> {
        Some(("p/Shape".to_string(), "area".to_string(), "()I".to_string()))
    }

    fn body() -> InlineSite {
        InlineSite {
            callee_code: vec![0x03, 0xac, 0, 0],
            callee_code_len: 2,
            callee_is_static: false,
            ..InlineSite::default()
        }
    }

    fn ask(
        prof: Option<&profile::MethodProfile>,
        precise: bool,
        resolve: Option<&dyn Fn(u32, &str, &str, &str) -> Option<InlineSite>>,
    ) -> Option<usize> {
        osr_door_lost_polymorphic_splice_pc(
            &CODE,
            CODE_LEN,
            &OPS,
            precise,
            prof,
            Some(&names),
            resolve,
        )
    }

    /// `R16Bench poly`'s shape: three classes at 50/25/25 % at an in-loop
    /// virtual site. The single-pass OSR door splices it and the optimizing
    /// tier (its polymorphic splice off by default) would not, so the site is
    /// named; every gate the single-pass door asks withdraws the answer.
    #[test]
    fn a_three_class_in_loop_site_is_named_until_a_gate_withdraws_it() {
        let poly = profile_at_7(&[(9, 500), (4, 250), (6, 250)]);
        let all = |_: u32, _: &str, _: &str, _: &str| Some(body());
        let none = |_: u32, _: &str, _: &str, _: &str| -> Option<InlineSite> { None };
        let only_nine = |cid: u32, _: &str, _: &str, _: &str| (cid == 9).then(body);
        cratonvm_types::flags::with_thread_overrides(&[(IR_POLY, None), (OSR_POLY, None)], || {
            assert_eq!(ask(Some(&poly), false, None), Some(7), "profile alone");
            assert_eq!(ask(Some(&poly), false, Some(&all)), Some(7));
            assert_eq!(
                ask(Some(&poly), false, Some(&none)),
                None,
                "no body resolves"
            );
            assert_eq!(
                ask(Some(&poly), false, Some(&only_nine)),
                None,
                "one body is no splice"
            );
            assert_eq!(
                ask(Some(&poly), true, Some(&all)),
                None,
                "precise frames: no splice"
            );
            assert_eq!(ask(None, false, Some(&all)), None, "no profile");
            let mono = profile_at_7(&[(9, 1000)]);
            assert_eq!(ask(Some(&mono), false, Some(&all)), None, "monomorphic");
            let bi = profile_at_7(&[(9, 500), (4, 480), (6, 20)]);
            assert_eq!(
                ask(Some(&bi), false, Some(&all)),
                None,
                "bimorphic: the IR splices it"
            );
        });
        cratonvm_types::flags::with_thread_overrides(&[(IR_POLY, Some("1"))], || {
            assert_eq!(
                ask(Some(&poly), false, Some(&all)),
                None,
                "the IR body splices it too"
            );
        });
        cratonvm_types::flags::with_thread_overrides(
            &[(IR_POLY, None), (OSR_POLY, Some("0"))],
            || {
                assert_eq!(
                    ask(Some(&poly), false, Some(&all)),
                    None,
                    "single-pass arm off"
                );
            },
        );
    }

    /// A site outside every loop is never the reason: the single-pass door
    /// plans guarded splices only inside loops.
    #[test]
    fn a_site_outside_the_loop_is_not_named() {
        let mut prof = profile_at_7(&[]);
        prof.receivers.clear();
        let mut counts = profile::ReceiverCounts::default();
        counts.insert(9, 500);
        counts.insert(4, 250);
        counts.insert(6, 250);
        prof.receivers.insert(13, counts);
        // pc 13 as a virtual site after the loop.
        let mut code = CODE;
        code[13] = 0xb6;
        let ops = [(13usize, 5u16, 0xb6u8)];
        cratonvm_types::flags::with_thread_overrides(&[(IR_POLY, None), (OSR_POLY, None)], || {
            assert_eq!(
                osr_door_lost_polymorphic_splice_pc(
                    &code,
                    CODE_LEN,
                    &ops,
                    false,
                    Some(&prof),
                    Some(&names),
                    None
                ),
                None
            );
        });
    }

    /// Both new switches are default-ON regression fixes with a `=0` kill.
    #[test]
    fn both_switches_default_on_with_a_kill_word() {
        for (key, reader) in [
            (
                "CRATONVM_JIT_OSR_PREFER_SPLICED_SINGLE_PASS",
                osr_door_prefer_spliced_single_pass_enabled as fn() -> bool,
            ),
            (
                "CRATONVM_JIT_OSR_DOOR_OWN_REFUSAL_MEMO",
                osr_door_own_refusal_memo_enabled as fn() -> bool,
            ),
        ] {
            cratonvm_types::flags::with_thread_overrides(&[(key, None)], || {
                assert!(reader(), "{key}")
            });
            cratonvm_types::flags::with_thread_overrides(&[(key, Some("0"))], || {
                assert!(!reader(), "{key}=0")
            });
        }
    }
}

#[cfg(test)]
mod r18w11_osrfollow_tests {
    use super::*;

    const IR_POLY: &str = "CRATONVM_JIT_IR_POLYMORPHIC_GUARDED_SPLICE";
    const GUARDED: &str = "CRATONVM_JIT_OSR_SPLICE_GUARDED";
    const OSR_POLY: &str = "CRATONVM_JIT_OSR_SPLICE_POLYMORPHIC";
    const PREFER: &str = "CRATONVM_JIT_OSR_PREFER_SPLICED_SINGLE_PASS";

    // 0 aload_0; 1 invokeinterface #4, 1, 0; 6 goto 1; 9 return; padding.
    const CODE: [u8; 12] = [0x2a, 0xb9, 0, 4, 1, 0, 0xa7, 0xff, 0xfb, 0xb1, 0, 0];
    const CODE_LEN: usize = 10;

    fn body(class: &str, code_len: usize) -> InlineSite {
        // `aload_0; getfield #1; ireturn`, padded with `nop`s to `code_len`
        // bytecodes when a bigger body is wanted.
        let mut code = vec![0x2a, 0xb4, 0, 1];
        code.resize(code_len.saturating_sub(1).max(4), 0x00);
        code.push(0xac);
        code.extend([0, 0]);
        InlineSite {
            callee_code_len: code.len() - 2,
            callee_code: code,
            callee_max_locals: 1,
            callee_num_args: 1,
            callee_is_static: false,
            return_type: b'I',
            class_name: class.to_string(),
            method_name: "area".to_string(),
            descriptor: "()I".to_string(),
            ..InlineSite::default()
        }
    }

    fn poly_profile() -> profile::MethodProfile {
        let mut p = profile::MethodProfile::default();
        p.receivers.insert(
            1,
            [(9u32, 490u32), (4, 255), (6, 255)].into_iter().collect(),
        );
        p
    }

    fn candidate() -> OsrSpliceCandidate<'static> {
        OsrSpliceCandidate {
            pc: 1,
            invoke_kind: 2,
            class_name: "p/Shape",
            method_name: "area",
            descriptor: "()I",
        }
    }

    fn namer(cid: u32) -> Option<String> {
        Some(format!("p/C{cid}"))
    }

    fn no_static(_: &str, _: &str, _: &str) -> Option<InlineSite> {
        None
    }

    /// `(refused class, body size)` -> the shared predicate's answer.
    fn ask(
        refuse: Option<u32>,
        size: usize,
        profile: Option<&profile::MethodProfile>,
    ) -> Option<usize> {
        let resolve = |cid: u32, _: &str, _: &str, _: &str| {
            (Some(cid) != refuse).then(|| body(&format!("p/C{cid}"), size))
        };
        osr_door_single_pass_polymorphic_splice_pc(
            &CODE,
            CODE_LEN,
            ("p/Main", "poly", "(I)J"),
            &[],
            profile,
            Some(1),
            &[],
            &[candidate()],
            &no_static,
            &namer,
            &resolve,
        )
    }

    /// Every invoke opcode, by instruction, with its constant-pool index;
    /// operand bytes are never opcodes.
    #[test]
    fn osr_door_own_invoke_ops_lists_every_invoke() {
        assert_eq!(osr_door_own_invoke_ops(&CODE), vec![(1, 4, 0xb9)]);
        // `sipush 0xb6b6` hides two 0xb6 operand bytes.
        let code = [0x11, 0xb6, 0xb6, 0xb8, 0, 9, 0xb7, 0, 3, 0xb6, 0, 2, 0xb1];
        assert_eq!(
            osr_door_own_invoke_ops(&code),
            vec![(3, 9, 0xb8), (6, 3, 0xb7), (9, 2, 0xb6)]
        );
        assert!(osr_door_own_invoke_ops(&[0xb6, 0]).is_empty(), "truncated");
    }

    /// OSRFOLLOW18-4: the decline is the single-pass planner's own answer. It
    /// names `R16Bench poly`'s shape; it does NOT when the planner would not
    /// splice the site -- a body that fails to resolve, a body above every
    /// size tier -- which the profile-only predicate it replaced still named.
    #[test]
    fn the_decline_is_the_single_pass_planners_answer() {
        let poly = poly_profile();
        let on = [
            (IR_POLY, None),
            (GUARDED, None),
            (OSR_POLY, None),
            (PREFER, None),
        ];
        cratonvm_types::flags::with_thread_overrides(&on, || {
            assert_eq!(ask(None, 5, Some(&poly)), Some(1), "three small bodies");
            assert_eq!(
                ask(Some(4), 5, Some(&poly)),
                None,
                "one body left: no splice"
            );
            assert_eq!(ask(None, 400, Some(&poly)), None, "above FreqInlineSize");
            assert_eq!(ask(None, 5, None), None, "no profile");
            // The profile-only predicate names the same two refused shapes:
            // that is the defect this closes.
            let ops = [(1usize, 4u16, 0xb9u8)];
            assert_eq!(
                osr_door_lost_polymorphic_splice_pc(
                    &CODE,
                    CODE_LEN,
                    &ops,
                    false,
                    Some(&poly),
                    None,
                    None
                ),
                Some(1)
            );
        });
        cratonvm_types::flags::with_thread_overrides(&[(PREFER, Some("0"))], || {
            assert_eq!(ask(None, 5, Some(&poly)), None, "the switch's kill word");
        });
        cratonvm_types::flags::with_thread_overrides(
            &[(IR_POLY, Some("1")), (PREFER, None)],
            || {
                assert_eq!(
                    ask(None, 5, Some(&poly)),
                    None,
                    "the optimizing body splices it"
                );
            },
        );
        cratonvm_types::flags::with_thread_overrides(
            &[(OSR_POLY, Some("0")), (PREFER, None)],
            || {
                assert_eq!(
                    ask(None, 5, Some(&poly)),
                    None,
                    "single-pass polymorphic arm off"
                );
            },
        );
    }

    const PER_HEADER: &str = "CRATONVM_JIT_OSR_POLY_DECLINE_PER_HEADER";

    /// JIT round 19 wave 2 (lane osr2, OSR19-1): a polymorphic site is in the
    /// loop an entry names only when that loop's `[header, back edge]` range
    /// holds it; the other loop of the method is not declined by it.
    ///
    /// ```text
    ///  0: iconst_0  1: nop  2: goto 1        (loop A: [1, 2])
    ///  5: nop  6: nop  7: goto 6             (loop B: [6, 7])
    /// 10: return
    /// ```
    #[test]
    fn r19_osr2_a_polymorphic_pc_declines_only_the_loop_it_is_in() {
        let code = [
            0x03, 0x00, 0xa7, 0xff, 0xff, 0x00, 0x00, 0xa7, 0xff, 0xff, 0xb1, 0, 0,
        ];
        let len = 11;
        assert_eq!(osr_door_first_pc_in_entry_loop(&code, len, 1, &[6]), None);
        assert_eq!(
            osr_door_first_pc_in_entry_loop(&code, len, 6, &[6]),
            Some(6)
        );
        assert_eq!(
            osr_door_first_pc_in_entry_loop(&code, len, 1, &[1, 6]),
            Some(1)
        );
        assert_eq!(
            osr_door_first_pc_in_entry_loop(&code, len, 10, &[1, 6]),
            None,
            "no loop"
        );
        // Nested: an outer loop [0, 8] around an inner one [1, 2] holds the
        // inner loop's site.
        //  0: nop  1: nop  2: goto 1  5: nop  6: nop  7: nop  8: goto 0  11: return
        let nested = [
            0x00, 0x00, 0xa7, 0xff, 0xff, 0x00, 0x00, 0x00, 0xa7, 0xff, 0xf8, 0xb1, 0, 0,
        ];
        assert_eq!(
            osr_door_first_pc_in_entry_loop(&nested, 12, 0, &[1]),
            Some(1)
        );
        assert_eq!(osr_door_first_pc_in_entry_loop(&nested, 12, 1, &[6]), None);
    }

    /// Under the switch the shared predicate still names `R16Bench poly`'s
    /// site for an entry in its own loop, and nothing for an entry pc in no
    /// loop that holds it; off, the entry pc does not matter (the method-wide
    /// answer). The switch is opt-in.
    #[test]
    fn r19_osr2_the_per_header_decline_asks_the_entry_loop() {
        let poly = poly_profile();
        let ask_at = |entry: usize| {
            let resolve = |cid: u32, _: &str, _: &str, _: &str| Some(body(&format!("p/C{cid}"), 5));
            osr_door_single_pass_polymorphic_splice_pc(
                &CODE,
                CODE_LEN,
                ("p/Main", "poly", "(I)J"),
                &[],
                Some(&poly),
                Some(entry),
                &[],
                &[candidate()],
                &no_static,
                &namer,
                &resolve,
            )
        };
        let base = [
            (IR_POLY, None),
            (GUARDED, None),
            (OSR_POLY, None),
            (PREFER, None),
        ];
        let mut on = base.to_vec();
        on.push((PER_HEADER, Some("1")));
        cratonvm_types::flags::with_thread_overrides(&on, || {
            assert_eq!(ask_at(1), Some(1), "the site's own loop");
            assert_eq!(ask_at(9), None, "an entry in no loop holding the site");
        });
        let mut off = base.to_vec();
        off.push((PER_HEADER, None));
        cratonvm_types::flags::with_thread_overrides(&off, || {
            assert_eq!(ask_at(9), Some(1), "method-wide without the switch");
            assert!(!osr_poly_decline_per_header_enabled());
        });
    }

    /// The in-compile conjunct is gone: the door's question is the only one.
    #[test]
    fn the_compile_no_longer_asks_its_own_question() {
        let src = include_str!("lib.rs");
        let production = src.split("mod r18w11_osrfollow_tests").next().unwrap_or("");
        let inner = production
            .split("\nfn try_compile_inner(")
            .nth(1)
            .and_then(|s| s.split("\n}\n").next())
            .expect("try_compile_inner is in this file");
        assert!(!inner.contains("osr_door_lost_polymorphic_splice_pc("));
    }

    /// OSRPOLY18-2 is a perf switch: default OFF, `=1` opts in.
    #[test]
    fn the_narrowed_opaque_door_is_opt_in() {
        let key = "CRATONVM_JIT_OSR_NARROW_OPAQUE_DOOR";
        cratonvm_types::flags::with_thread_overrides(&[(key, None)], || {
            assert!(!osr_narrow_opaque_door_enabled())
        });
        cratonvm_types::flags::with_thread_overrides(&[(key, Some("1"))], || {
            assert!(osr_narrow_opaque_door_enabled())
        });
    }

    /// The narrowed build withholds only the door's own clause of
    /// `osr_opaque_all`; the process switch and the unloaded static splices
    /// keep theirs, and the soundness argument stays written on the reader.
    #[test]
    fn the_narrowed_build_withholds_only_the_door_clause() {
        let src = include_str!("lib.rs");
        let attempt = src
            .split("\nfn ir_tier_attempt(")
            .nth(1)
            .expect("ir_tier_attempt is in this file")
            .split("\n}\n")
            .next()
            .expect("the function ends");
        let flat: String = attempt.chars().filter(|c| !c.is_whitespace()).collect();
        assert!(flat.contains(
            "letosr_opaque_all=osr_exit::osr_opaque_entry_enabled()||(req.osr_mode_exit_polls&&!osr_narrow_opaque)||builder.has_unloaded_static_splice_calls();"
        ));
        let reader = src
            .split("pub(crate) fn osr_narrow_opaque_door_enabled()")
            .next()
            .expect("the reader is in this file");
        assert!(reader.contains("Why this keeps 44df838b5f's soundness argument"));
        let tier = src
            .split("\nfn ir_tier(")
            .nth(1)
            .expect("ir_tier is in this file");
        let tier: String = tier
            .split("\nfn ")
            .next()
            .unwrap_or("")
            .chars()
            .filter(|c| !c.is_whitespace())
            .collect();
        assert!(tier.contains("ifosr_narrow_opaque&&cm.ir_osr_guard_fact_needs_opaque_entries{"));
        assert!(tier.contains("osr_narrow_opaque=false;continue;"));
    }
}

/// JIT round 19 proposal wave 3 (lane megaosr, MEGAOSR19-1): the blind
/// megamorphic splice decline of the optimizing OSR door.
#[cfg(test)]
mod r19_megaosr_blind_mega_splice_tests {
    use super::*;

    const SWITCH: &str = "CRATONVM_JIT_OSR_DECLINE_BLIND_MEGA_SPLICE";

    /// `R16MegaBlindSites.run`'s shape:
    ///
    /// ```text
    /// 0: nop  1: invokestatic #5 (site)  4: pop  5: goto 0  8: return
    /// ```
    ///
    /// one loop `[0, 5]`, the call at pc 1; two padding bytes.
    const CODE: [u8; 11] = [0x00, 0xb8, 0, 5, 0x57, 0xa7, 0xff, 0xfb, 0xb1, 0, 0];
    const CODE_LEN: usize = 9;

    /// `site(V, int)`: `aload_0; iload_1; invokeinterface #7, 2, 0; ireturn`,
    /// the interface call at callee pc 2.
    fn site_body(class_id: u32) -> InlineSite {
        let code = vec![0x2a, 0x1b, 0xb9, 0, 7, 2, 0, 0xac, 0, 0];
        InlineSite {
            callee_code_len: code.len() - 2,
            callee_code: code,
            callee_max_locals: 2,
            callee_num_args: 2,
            callee_is_static: true,
            return_type: b'I',
            class_name: "p/Main".to_string(),
            class_id,
            method_name: "site".to_string(),
            descriptor: "(Lp/V;I)I".to_string(),
            ..InlineSite::default()
        }
    }

    fn candidate(kind: u8) -> OsrSpliceCandidate<'static> {
        OsrSpliceCandidate {
            pc: 1,
            invoke_kind: kind,
            class_name: "p/Main",
            method_name: "site",
            descriptor: "(Lp/V;I)I",
        }
    }

    /// `classes` receiver classes seen `each` times at callee pc `at`.
    fn profile(at: usize, classes: u32, each: u32) -> profile::MethodProfile {
        let mut p = profile::MethodProfile::default();
        p.receivers
            .insert(at, (0..classes).map(|c| (100 + c, each)).collect());
        p
    }

    fn ask(
        entry_pc: usize,
        kind: u8,
        class_id: u32,
        callee: Option<(usize, u32, u32)>,
    ) -> Option<(usize, usize)> {
        let resolve = |cn: &str, mn: &str, desc: &str| {
            (cn == "p/Main" && mn == "site" && desc == "(Lp/V;I)I").then(|| site_body(class_id))
        };
        let lookup = |cid: u32, mn: &str, desc: &str| {
            assert_eq!(
                (cid, mn, desc),
                (class_id, "site", "(Lp/V;I)I"),
                "the body's own key"
            );
            callee.map(|(at, classes, each)| profile(at, classes, each))
        };
        osr_door_blind_megamorphic_splice_site(
            &CODE,
            CODE_LEN,
            entry_pc,
            &[candidate(kind)],
            &resolve,
            &lookup,
        )
    }

    /// The switch is default ON (round-19 proposal round), read live; the kill
    /// word `0` turns it off.
    #[test]
    fn the_decline_is_default_on_with_kill_word() {
        let mega = (2, 24, 20);
        cratonvm_types::flags::with_thread_overrides(&[(SWITCH, None)], || {
            assert!(osr_decline_blind_mega_splice_enabled());
        });
        cratonvm_types::flags::with_thread_overrides(&[(SWITCH, Some("0"))], || {
            assert!(!osr_decline_blind_mega_splice_enabled());
            assert_eq!(ask(0, 3, 42, Some(mega)), None, "off: never declines");
        });
        cratonvm_types::flags::with_thread_overrides(&[(SWITCH, Some("1"))], || {
            assert!(osr_decline_blind_mega_splice_enabled());
        });
    }

    /// `R16MegaBlindSites`: 24 classes at the callee's interface site name the
    /// loop's call and the callee pc; three classes (the polymorphic shape a
    /// splice's PIC holds) and an unprofiled pc do not.
    #[test]
    fn a_megamorphic_callee_site_in_the_entry_loop_declines() {
        cratonvm_types::flags::with_thread_overrides(&[(SWITCH, Some("1"))], || {
            assert_eq!(ask(0, 3, 42, Some((2, 24, 20))), Some((1, 2)));
            assert_eq!(
                ask(5, 3, 42, Some((2, 24, 20))),
                Some((1, 2)),
                "back-edge pc"
            );
            assert_eq!(ask(0, 3, 42, Some((2, 3, 300))), None, "three classes");
            assert_eq!(ask(0, 3, 42, Some((4, 24, 20))), None, "another pc");
            assert_eq!(ask(0, 3, 42, Some((2, 24, 0))), None, "no observation");
            assert_eq!(ask(0, 3, 42, None), None, "no callee profile");
        });
    }

    /// Every other gate: an entry in no loop, a kind that does not match its
    /// opcode, the resolver's unknown-class sentinel, an unresolved body.
    #[test]
    fn the_other_gates_refuse() {
        cratonvm_types::flags::with_thread_overrides(&[(SWITCH, Some("1"))], || {
            let mega = (2, 24, 20);
            assert_eq!(ask(8, 3, 42, Some(mega)), None, "the return is in no loop");
            assert_eq!(ask(0, 1, 42, Some(mega)), None, "kind 1 at an invokestatic");
            assert_eq!(
                ask(0, 3, 0, Some(mega)),
                None,
                "class id 0 has no profile key"
            );
            let unresolved = |_: &str, _: &str, _: &str| None;
            let lookup = |_: u32, _: &str, _: &str| Some(profile(2, 24, 20));
            assert_eq!(
                osr_door_blind_megamorphic_splice_site(
                    &CODE,
                    CODE_LEN,
                    0,
                    &[candidate(3)],
                    &unresolved,
                    &lookup,
                ),
                None
            );
        });
    }

    /// MEGA5-3 (lane osrentry6, `CRATONVM_JIT_OSR_DECLINE_BLIND_MEGA_NESTED`):
    /// `run` -> static `a` (no virtual site of its own) -> nested static `site`
    /// whose interface site is megamorphic in `site`'s OWN profile. Declined
    /// only with the walk on; the nested body is asked under its own key.
    #[test]
    fn a_megamorphic_site_one_nesting_level_down_declines_only_with_the_walk() {
        const NESTED: &str = "CRATONVM_JIT_OSR_DECLINE_BLIND_MEGA_NESTED";
        // `a(V, int)`: `aload_0; iload_1; invokestatic #9; ireturn`.
        let a_code = vec![0x2a, 0x1b, 0xb8, 0, 9, 0xac, 0, 0];
        let a_body = InlineSite {
            callee_code_len: a_code.len() - 2,
            callee_code: a_code,
            callee_max_locals: 2,
            callee_num_args: 2,
            callee_is_static: true,
            return_type: b'I',
            class_name: "p/Main".to_string(),
            class_id: 42,
            method_name: "a".to_string(),
            descriptor: "(Lp/V;I)I".to_string(),
            nested_sites: vec![NestedInlineSite {
                callee_pc: 2,
                guard_class_id: 0,
                site: site_body(43),
                bimorphic_second: None,
            }],
            ..InlineSite::default()
        };
        let resolve =
            |cn: &str, mn: &str, _: &str| (cn == "p/Main" && mn == "site").then(|| a_body.clone());
        let lookup = |cid: u32, mn: &str, _: &str| {
            // `a` has no receiver row; `site` (class 43) has the megamorphic one.
            (cid == 43 && mn == "site").then(|| profile(2, 24, 20))
        };
        let run = || {
            osr_door_blind_megamorphic_splice_site(
                &CODE,
                CODE_LEN,
                0,
                &[candidate(3)],
                &resolve,
                &lookup,
            )
        };
        cratonvm_types::flags::with_thread_overrides(
            &[(SWITCH, Some("1")), (NESTED, None)],
            || assert_eq!(run(), None, "walk off: one level only"),
        );
        cratonvm_types::flags::with_thread_overrides(
            &[(SWITCH, Some("1")), (NESTED, Some("1"))],
            || assert_eq!(run(), Some((1, 2)), "walk on: the nested site's pc"),
        );
        cratonvm_types::flags::with_thread_overrides(
            &[(SWITCH, Some("0")), (NESTED, Some("1"))],
            || assert_eq!(run(), None, "the decline itself off"),
        );
    }

    /// A call outside the entry's loop is not the loop's: two loops, the call
    /// in the second, an entry at the first.
    ///
    /// ```text
    /// 0: nop  1: goto 0                       (loop A: [0, 1])
    /// 4: invokestatic #5  7: pop  8: goto 4   (loop B: [4, 8])
    /// 11: return
    /// ```
    #[test]
    fn a_call_in_another_loop_does_not_decline_this_one() {
        let code = [
            0x00, 0xa7, 0xff, 0xff, 0xb8, 0, 5, 0x57, 0xa7, 0xff, 0xfc, 0xb1, 0, 0,
        ];
        let len = 12;
        let resolve = |_: &str, _: &str, _: &str| Some(site_body(42));
        let lookup = |_: u32, _: &str, _: &str| Some(profile(2, 24, 20));
        let at = OsrSpliceCandidate {
            pc: 4,
            ..candidate(3)
        };
        cratonvm_types::flags::with_thread_overrides(&[(SWITCH, Some("1"))], || {
            assert_eq!(
                osr_door_blind_megamorphic_splice_site(&code, len, 0, &[at], &resolve, &lookup),
                None
            );
            assert_eq!(
                osr_door_blind_megamorphic_splice_site(&code, len, 4, &[at], &resolve, &lookup),
                Some((4, 2))
            );
        });
    }
}

/// JIT round 19 wave 1 (lane osrpoly19, OSRFOLLOW18-3): the optimizing tier's
/// polymorphic guarded splice scoped to OSR-door compiles.
#[cfg(test)]
mod r19_osrpoly19_door_polymorphic_tests {
    use super::*;

    const DOOR: &str = "CRATONVM_JIT_OSR_DOOR_IR_POLYMORPHIC_SPLICE";
    const IR_POLY: &str = "CRATONVM_JIT_IR_POLYMORPHIC_GUARDED_SPLICE";

    // The r18w9 shape: an in-loop `invokevirtual` at pc 7.
    const CODE: [u8; 19] = [
        0x1a, 0xb8, 0, 2, 0xb7, 0, 3, 0xb6, 0, 4, 0xa7, 0xff, 0xf7, 0xb8, 0, 5, 0xac, 0, 0,
    ];
    const CODE_LEN: usize = 17;
    const OPS: [(usize, u16, u8); 4] = [(1, 2, 0xb8), (4, 3, 0xb7), (7, 4, 0xb6), (13, 5, 0xb8)];

    fn poly() -> profile::MethodProfile {
        let mut receivers = profile::ReceiverCounts::default();
        for &(class_id, n) in &[(9u32, 500u32), (4, 250), (6, 250)] {
            receivers.insert(class_id, n);
        }
        let mut prof = profile::MethodProfile::default();
        prof.receivers.insert(7, receivers);
        prof
    }

    #[test]
    fn the_door_switch_is_opt_in() {
        cratonvm_types::flags::with_thread_overrides(&[(DOOR, None)], || {
            assert!(!ir::osr_door_ir_polymorphic_splice_enabled());
        });
        cratonvm_types::flags::with_thread_overrides(&[(DOOR, Some("1"))], || {
            assert!(ir::osr_door_ir_polymorphic_splice_enabled());
        });
    }

    /// With the door switch on, the spliced-single-pass preference stands
    /// aside exactly as it does for the process-wide switch.
    #[test]
    fn the_preference_stands_aside_under_the_door_switch() {
        let prof = poly();
        let ask = || {
            osr_door_lost_polymorphic_splice_pc(
                &CODE,
                CODE_LEN,
                &OPS,
                false,
                Some(&prof),
                None,
                None,
            )
        };
        cratonvm_types::flags::with_thread_overrides(&[(DOOR, None), (IR_POLY, None)], || {
            assert_eq!(ask(), Some(7), "named by default");
        });
        cratonvm_types::flags::with_thread_overrides(&[(DOOR, Some("1")), (IR_POLY, None)], || {
            assert_eq!(ask(), None, "the door's optimizing body splices it");
        });
    }

    /// The planner's polymorphic answer takes the switch it is handed: the
    /// process-wide form still reads only the process switch.
    #[test]
    fn the_planner_answers_with_the_switch_it_is_handed() {
        let all = |_: u32, _: &str, _: &str, _: &str| -> Option<InlineSite> {
            Some(InlineSite {
                callee_code: vec![0xb1; 3],
                callee_code_len: 3,
                callee_is_static: false,
                ..InlineSite::default()
            })
        };
        let classes = || Some(vec![9u32, 4, 6]);
        cratonvm_types::flags::with_thread_overrides(&[(DOOR, Some("1")), (IR_POLY, None)], || {
            assert_eq!(
                ir_profile_polymorphic_sites(0xb6, true, classes(), Some(&all), "A", "m", "()I")
                    .err(),
                Some("switched-off"),
                "the method-entry form ignores the door switch"
            );
            let got = ir_profile_polymorphic_sites_when(
                true,
                0xb6,
                true,
                classes(),
                Some(&all),
                "A",
                "m",
                "()I",
            )
            .map(|b| b.iter().map(|(_, c)| *c).collect::<Vec<u32>>());
            assert_eq!(got, Ok(vec![9, 4, 6]));
        });
    }
}

#[cfg(test)]
mod r19_megaosr4_callee_seed_tests {
    //! JIT round 19 proposal wave 4 (lane megaosr4, MEGAOSR19-2): a spliced
    //! body's surviving virtual site is seeded from the CALLEE's own receiver
    //! profile (`CRATONVM_JIT_IR_SPLICE_CALLEE_PROFILE_SEED`).
    use super::*;
    use std::sync::atomic::Ordering;

    const SWITCH: &str = "CRATONVM_JIT_IR_SPLICE_CALLEE_PROFILE_SEED";

    fn counts(pairs: &[(u32, u32)]) -> profile::ReceiverCounts {
        pairs.iter().copied().collect()
    }

    fn uniform(classes: u32, each: u32) -> profile::ReceiverCounts {
        (0..classes).map(|c| (100 + c, each)).collect()
    }

    /// The switch is opt-in, read live.
    #[test]
    fn the_seed_is_opt_in() {
        cratonvm_types::flags::with_thread_overrides(&[(SWITCH, None)], || {
            assert!(!ir_splice_callee_profile_seed_enabled());
        });
        cratonvm_types::flags::with_thread_overrides(&[(SWITCH, Some("1"))], || {
            assert!(ir_splice_callee_profile_seed_enabled());
        });
    }

    /// `R16MegaBlindSites`' `visit` site: 24 classes seed the slot
    /// megamorphic and put no class in the MIC; a dominant receiver goes in
    /// the MIC only; no row seeds nothing (the unseeded cache of before).
    #[test]
    fn a_callee_row_seeds_the_cache_like_an_own_site_row() {
        cratonvm_types::flags::with_thread_overrides(
            &[
                ("CRATONVM_JIT_IC_PROFILE_MEGA_SEED", None),
                ("CRATONVM_JIT_IR_SPLICE_CALLEE_PROFILE_SEED_MEGA", Some("1")),
            ],
            || {
                let mic = JitMICSlot::new_at(12);
                let pic = JitPICSlot::new_at(12);
                let mega = uniform(24, 100);
                let got = ir_seed_spliced_inline_cache(&mic, &pic, Some(&mega));
                assert_eq!(
                    got,
                    SplicedSeedOutcome {
                        dominant: None,
                        megamorphic: true,
                        classes: 24
                    }
                );
                assert!(pic.is_megamorphic());
                assert!(JitMICSlot::is_empty_class_id(
                    mic.cached_class_id.load(Ordering::Relaxed)
                ));

                let mic = JitMICSlot::new_at(12);
                let pic = JitPICSlot::new_at(12);
                let mono = counts(&[(42, 990), (43, 10)]);
                let got = ir_seed_spliced_inline_cache(&mic, &pic, Some(&mono));
                assert_eq!(got.dominant, Some(42));
                assert!(!got.megamorphic);
                assert!(!pic.is_megamorphic());
                assert_eq!(mic.cached_class_id.load(Ordering::Relaxed), 42);

                let mic = JitMICSlot::new_at(12);
                let pic = JitPICSlot::new_at(12);
                let got = ir_seed_spliced_inline_cache(&mic, &pic, None);
                assert_eq!(
                    got,
                    SplicedSeedOutcome {
                        dominant: None,
                        megamorphic: false,
                        classes: 0
                    }
                );
                assert!(!pic.is_megamorphic());
                assert!(JitMICSlot::is_empty_class_id(
                    mic.cached_class_id.load(Ordering::Relaxed)
                ));
            },
        );
    }

    /// The M13-9 kill switch still governs the megamorphic half.
    #[test]
    fn the_profile_mega_seed_kill_switch_still_applies() {
        cratonvm_types::flags::with_thread_overrides(
            &[
                ("CRATONVM_JIT_IC_PROFILE_MEGA_SEED", Some("0")),
                ("CRATONVM_JIT_IR_SPLICE_CALLEE_PROFILE_SEED_MEGA", Some("1")),
            ],
            || {
                let mic = JitMICSlot::new_at(12);
                let pic = JitPICSlot::new_at(12);
                let got = ir_seed_spliced_inline_cache(&mic, &pic, Some(&uniform(24, 100)));
                assert!(!got.megamorphic);
                assert!(!pic.is_megamorphic());
            },
        );
    }

    /// JIT round 19 proposal wave 5 (lane mega5): without
    /// `CRATONVM_JIT_IR_SPLICE_CALLEE_PROFILE_SEED_MEGA` a megamorphic callee
    /// row seeds nothing megamorphic (the own-site-wide-call regression's
    /// suspected path), and a dominant row still seeds the MIC.
    #[test]
    fn the_megamorphic_half_is_its_own_opt_in() {
        cratonvm_types::flags::with_thread_overrides(
            &[
                ("CRATONVM_JIT_IC_PROFILE_MEGA_SEED", None),
                ("CRATONVM_JIT_IR_SPLICE_CALLEE_PROFILE_SEED_MEGA", None),
            ],
            || {
                let mic = JitMICSlot::new_at(12);
                let pic = JitPICSlot::new_at(12);
                let got = ir_seed_spliced_inline_cache(&mic, &pic, Some(&uniform(24, 100)));
                assert!(!got.megamorphic);
                assert!(!pic.is_megamorphic());
                assert_eq!(got.classes, 24);

                let mic = JitMICSlot::new_at(12);
                let pic = JitPICSlot::new_at(12);
                let got =
                    ir_seed_spliced_inline_cache(&mic, &pic, Some(&counts(&[(42, 990), (43, 10)])));
                assert_eq!(got.dominant, Some(42));
                assert_eq!(mic.cached_class_id.load(Ordering::Relaxed), 42);
            },
        );
    }

    /// `site(V v, int x) { return v.visit(x); }` as a static body:
    /// `aload_0; iload_1; invokeinterface visit; ireturn`, the call at callee
    /// pc 2, with the callee's own receiver rows `rows`.
    fn site_body(rows: Vec<(usize, profile::ReceiverCounts)>) -> InlineSite {
        InlineSite {
            callee_code: vec![0x2a, 0x1b, 0xb9, 0x00, 0x07, 0x02, 0x00, 0xac, 0, 0],
            callee_code_len: 8,
            callee_max_locals: 2,
            callee_num_args: 2,
            callee_is_static: true,
            return_type: b'I',
            class_name: "p/Main".to_string(),
            class_id: 9,
            method_name: "site".to_string(),
            descriptor: "(Lp/V;I)I".to_string(),
            invoke_targets: vec![(
                2,
                InlineInvokeTarget {
                    class_name: "p/V".to_string(),
                    method_name: "visit".to_string(),
                    descriptor: "(I)I".to_string(),
                    num_jit_args: 2,
                    return_type: b'I',
                    invoke_kind: 2,
                    declaring_class_id: 8,
                    ..Default::default()
                },
            )],
            callee_receiver_profile: rows,
            callee_never_taken_pcs: Vec::new(),
            callee_cold_arm_ranges: Vec::new(),
            callee_hot_path_pcs: Vec::new(),
            callee_invocations: 0,
            ..Default::default()
        }
    }

    type Appended = (
        Result<(), &'static str>,
        ir::IrInlineTables,
        Vec<(usize, usize)>,
    );

    /// Append `site` at caller pc 3 of a 10-byte caller: the body lands at
    /// combined pc 10, so its call at callee pc 2 is combined pc 12.
    fn append(site: InlineSite) -> Appended {
        let mut combined = vec![0u8; 10];
        let mut tables = ir::IrInlineTables::default();
        let mut owned_strings: Vec<Box<str>> = Vec::new();
        let mut owned_invoke_infos: Vec<Box<JitInvokeInfo>> = Vec::new();
        let mut direct_callee_entries: Vec<(usize, u64)> = Vec::new();
        let mut budget = IR_INLINE_MAX_TOTAL_BYTES;
        let mut vcalls: Vec<(usize, usize)> = Vec::new();
        let mut compact: HashMap<(usize, bool), (u32, bool, u8)> = HashMap::new();
        let mut static_init: Vec<u32> = Vec::new();
        let mut direct_calls: Vec<(usize, (usize, bool))> = Vec::new();
        let mut checkcast_seen = false;
        let mut volatile: Vec<usize> = Vec::new();
        let mut exact: Vec<(usize, u32)> = Vec::new();
        let result = append_ir_inline_site(
            site,
            3,
            &mut combined,
            &mut tables,
            &mut owned_strings,
            &mut owned_invoke_infos,
            &mut direct_callee_entries,
            &mut budget,
            &mut vcalls,
            &mut compact,
            false,
            false,
            &mut static_init,
            &mut direct_calls,
            &mut checkcast_seen,
            &mut volatile,
            &mut exact,
            None,
            &|_, _, _| None,
            ir::SpliceFenceRelax::NONE,
            false,
        );
        (result, tables, vcalls)
    }

    /// The callee's row for the surviving call's bci is re-keyed at the
    /// call's combined pc, beside its inline-cache row; a row for another
    /// bci and an empty profile leave no seed.
    #[test]
    fn the_callee_row_rides_to_the_combined_pc() {
        let mega = uniform(24, 100);
        let (result, tables, vcalls) = append(site_body(vec![(2, mega.clone())]));
        assert_eq!(result, Ok(()));
        assert!(vcalls.iter().any(|&(pc, _)| pc == 12), "{vcalls:?}");
        assert_eq!(tables.spliced_receiver_seeds.get(&12), Some(&mega));
        assert_eq!(tables.spliced_receiver_seeds.len(), 1);

        let (_, tables, vcalls) = append(site_body(vec![(5, mega.clone())]));
        assert!(vcalls.iter().any(|&(pc, _)| pc == 12));
        assert!(
            tables.spliced_receiver_seeds.is_empty(),
            "another bci's row"
        );

        let (_, tables, _) = append(site_body(Vec::new()));
        assert!(tables.spliced_receiver_seeds.is_empty(), "no profile");
    }

    /// The rows survive the planner's per-site merge.
    #[test]
    fn the_merge_carries_the_seed_rows() {
        let mega = uniform(24, 100);
        let (_, sub, _) = append(site_body(vec![(2, mega.clone())]));
        let mut into = ir::IrInlineTables::default();
        merge_ir_inline_tables(&mut into, sub);
        assert_eq!(into.spliced_receiver_seeds.get(&12), Some(&mega));
    }
}

#[cfg(test)]
mod nio20w6_l1_buffer_trap_and_plain_static_tests {
    //! Round nio20 wave 6 (lane L1): the byte-buffer trap-miss site rule and
    //! the plain-static-read feed.
    use super::*;

    #[test]
    fn only_a_byte_buffer_call_into_a_java_nio_byte_buffer_body_is_a_buffer_site() {
        assert!(ir_buffer_trap_site(
            "java/nio/ByteBuffer",
            "java/nio/HeapByteBuffer"
        ));
        assert!(ir_buffer_trap_site(
            "java/nio/ByteBuffer",
            "java/nio/DirectByteBuffer"
        ));
        assert!(ir_buffer_trap_site(
            "java/nio/MappedByteBuffer",
            "java/nio/DirectByteBufferR"
        ));
        assert!(ir_buffer_trap_site(
            "java/nio/ByteBuffer",
            "java/nio/HeapByteBufferR"
        ));
        // Another static type, another body, a user subclass: no.
        assert!(!ir_buffer_trap_site(
            "java/nio/CharBuffer",
            "java/nio/HeapCharBuffer"
        ));
        assert!(!ir_buffer_trap_site(
            "java/nio/Buffer",
            "java/nio/HeapByteBuffer"
        ));
        assert!(!ir_buffer_trap_site(
            "java/nio/ByteBuffer",
            "java/nio/ByteBufferAsIntBufferB"
        ));
        assert!(!ir_buffer_trap_site(
            "java/nio/ByteBuffer",
            "com/example/MyBuffer"
        ));
    }

    #[test]
    fn the_buffer_trap_switch_defaults_on() {
        let read = |v: Option<&str>| {
            cratonvm_types::flags::with_thread_overrides(
                &[("CRATONVM_JIT_IR_BUFFER_TRAP_MISS", v)],
                ir_buffer_trap_miss_enabled,
            )
        };
        assert_eq!(read(None), ir::ir_guarded_receiver_splice_enabled());
        assert!(!read(Some("0")));
    }

    /// nio21 wave 3 (lane L3): a lone `put*` keeps the call edge; a lone get,
    /// a put beside another buffer site and every site with the switch off
    /// keep the trap; a pc that is not a buffer site never takes it.
    #[test]
    fn nio21w3_a_lone_buffer_put_keeps_the_call_edge() {
        use std::collections::HashSet;
        let set = |pcs: &[usize]| pcs.iter().copied().collect::<HashSet<usize>>();
        let lone_put = (set(&[7]), set(&[7]));
        let lone_get = (set(&[7]), set(&[]));
        let pair = (set(&[7, 12]), set(&[7]));
        assert!(!ir_buffer_trap_admits_site(
            &lone_put.0,
            &lone_put.1,
            7,
            true
        ));
        assert!(ir_buffer_trap_admits_site(
            &lone_put.0,
            &lone_put.1,
            7,
            false
        ));
        assert!(ir_buffer_trap_admits_site(
            &lone_get.0,
            &lone_get.1,
            7,
            true
        ));
        assert!(ir_buffer_trap_admits_site(&pair.0, &pair.1, 7, true));
        assert!(ir_buffer_trap_admits_site(&pair.0, &pair.1, 12, true));
        assert!(!ir_buffer_trap_admits_site(&pair.0, &pair.1, 3, true));
        let read = |v: Option<&str>| {
            cratonvm_types::flags::with_thread_overrides(
                &[("CRATONVM_JIT_IR_BUFFER_TRAP_LONE_PUT_CALL", v)],
                ir_buffer_trap_lone_put_call_enabled,
            )
        };
        assert!(read(None));
        assert!(!read(Some("0")));
    }

    #[test]
    fn the_plain_static_feed_needs_a_resolved_base_and_a_plain_read() {
        // A table with no static-base resolver answers nothing.
        let table = DirectHelperTable::EMPTY;
        let rows = [
            (5u32, 0usize, b'L', false),
            (5, 1, b'I', true),
            (6, 0, b'I', false),
            (5, 0, b'L', false),
        ];
        assert!(ir_plain_static_read_rows(&table, rows.iter()).is_empty());
        // A resolver that answers for class 5 only.
        extern "C" fn class_five(_ctx: i64, class_id: i64, _field: i64) -> i64 {
            if class_id == 5 {
                0x1000
            } else {
                0
            }
        }
        let mut table = DirectHelperTable::EMPTY;
        table.static_base_resolver = class_five as *const () as usize;
        table.static_base_resolver_ctx = 1;
        let on = ir::ir_plain_static_read_enabled() && x64::inline_getstatic_enabled();
        let got = ir_plain_static_read_rows(&table, rows.iter());
        if on {
            // The volatile read and the unresolved class are left out; the
            // duplicate collapses.
            assert_eq!(got, vec![(5, 0)]);
        } else {
            assert!(got.is_empty());
        }
    }
}

#[cfg(test)]
mod nio21w11_l3_spliced_indy_rows_tests {
    //! nio21 wave 11, lane L3 (W10L3-1, `CRATONVM_JIT_IR_SPLICE_INDY`): a
    //! callee's constant-word lambda rows are rebased into the builder's indy
    //! tables, and the replay fence counts such a site as neither a trap nor a
    //! call.

    use super::*;

    const SITE: usize = 0x5A5A_1357_9BDF_2468;
    const FLAG: &str = "CRATONVM_JIT_IR_SPLICE_INDY";

    /// `static Runnable g() { return () -> {}; }`:
    /// `0: invokedynamic #2 ()Ljava/lang/Runnable;  5: areturn`.
    fn lambda_body(rows: Vec<(usize, usize, u8, usize)>) -> InlineSite {
        InlineSite {
            callee_code: vec![0xba, 0x00, 0x02, 0x00, 0x00, 0xb0, 0, 0],
            callee_code_len: 6,
            callee_max_locals: 1,
            callee_num_args: 0,
            callee_is_static: true,
            return_type: b'L',
            class_name: "p/Host".to_string(),
            class_id: 7,
            method_name: "g".to_string(),
            descriptor: "()Ljava/lang/Runnable;".to_string(),
            ir_indy_rows: rows,
            ..Default::default()
        }
    }

    /// Append `site` at caller pc 3 of a 10-byte caller.
    fn append(site: InlineSite) -> (Result<(), &'static str>, ir::IrInlineTables) {
        let mut combined = vec![0u8; 10];
        let mut tables = ir::IrInlineTables::default();
        let mut owned_strings: Vec<Box<str>> = Vec::new();
        let mut owned_invoke_infos: Vec<Box<JitInvokeInfo>> = Vec::new();
        let mut direct_callee_entries: Vec<(usize, u64)> = Vec::new();
        let mut budget = IR_INLINE_MAX_TOTAL_BYTES;
        let mut vcalls: Vec<(usize, usize)> = Vec::new();
        let mut compact: HashMap<(usize, bool), (u32, bool, u8)> = HashMap::new();
        let mut static_init: Vec<u32> = Vec::new();
        let mut direct_calls: Vec<(usize, (usize, bool))> = Vec::new();
        let mut checkcast_seen = false;
        let mut volatile: Vec<usize> = Vec::new();
        let mut exact_nested: Vec<(usize, u32)> = Vec::new();
        let result = append_ir_inline_site(
            site,
            3,
            &mut combined,
            &mut tables,
            &mut owned_strings,
            &mut owned_invoke_infos,
            &mut direct_callee_entries,
            &mut budget,
            &mut vcalls,
            &mut compact,
            false,
            false,
            &mut static_init,
            &mut direct_calls,
            &mut checkcast_seen,
            &mut volatile,
            &mut exact_nested,
            None,
            &|_, _, _| None,
            ir::SpliceFenceRelax::NONE,
            false,
        );
        (result, tables)
    }

    #[test]
    fn nio21w11_l3_constant_lambda_rows_are_rebased() {
        cratonvm_types::flags::with_thread_overrides(&[(FLAG, None)], || {
            let (result, tables) = append(lambda_body(vec![(0, 0, b'L', SITE)]));
            assert_eq!(result, Ok(()));
            assert_eq!(
                tables.indy_trap_sites,
                HashMap::from([(10usize, (0usize, b'L'))])
            );
            assert_eq!(tables.indy_bridge_sites, HashMap::from([(10usize, SITE)]));

            let (result, _) = append(lambda_body(vec![(5, 0, b'L', SITE)]));
            assert_eq!(
                result,
                Err("ir-splice-indy-row-mismatch"),
                "a row on the areturn"
            );
            let (result, _) = append(lambda_body(vec![(0, 1, b'L', SITE)]));
            assert_eq!(
                result,
                Err("ir-splice-indy-row-mismatch"),
                "a capturing shape"
            );
            let (result, _) = append(lambda_body(vec![(0, 0, b'L', 0)]));
            assert_eq!(result, Err("ir-splice-indy-row-mismatch"), "no site");

            let mut handlers = lambda_body(vec![(0, 0, b'L', SITE)]);
            handlers.ir_handler_rows = vec![(0, 5, 5, "java/lang/RuntimeException".to_string(), 7)];
            assert_eq!(append(handlers).0, Err("ir-splice-indy-with-handlers"));
        });
        cratonvm_types::flags::with_thread_overrides(&[(FLAG, Some("0"))], || {
            let (result, tables) = append(lambda_body(vec![(0, 0, b'L', SITE)]));
            assert_eq!(result, Err("ir-splice-indy-off"));
            assert!(tables.indy_bridge_sites.is_empty());
        });
    }

    /// `h(); return () -> {};`: the indy after the surviving call is not a
    /// trap the replay fence must refuse -- with its row. Without one it is.
    #[test]
    fn nio21w11_l3_the_fence_admits_a_constant_lambda_after_a_call() {
        let code = vec![0xb8, 0x00, 0x01, 0xba, 0x00, 0x02, 0x00, 0x00, 0xb0, 0, 0];
        let mut site = InlineSite {
            callee_code: code,
            callee_code_len: 9,
            callee_max_locals: 1,
            callee_is_static: true,
            return_type: b'L',
            descriptor: "()Ljava/lang/Runnable;".to_string(),
            ..Default::default()
        };
        assert!(ir_splice_body_may_trap_after_a_call(&site, None));
        site.ir_indy_rows = vec![(3, 0, b'L', SITE)];
        assert!(!ir_splice_body_may_trap_after_a_call(&site, None));
    }
}

#[cfg(test)]
mod r20w19_ysplice_rebase_tests {
    //! JIT round 20 wave 19, lane ySplice: a spliced body's linked CAPTURING
    //! lambda rows (SPLICE20-1, `CRATONVM_JIT_IR_SPLICE_INDY_CAPTURE`) and its
    //! unloaded-`new` exit rows (SPLICE20-2,
    //! `CRATONVM_JIT_IR_SPLICE_UNRESOLVED_NEW_EXIT`) are rebased into the
    //! builder's tables, or the body keeps its call.

    use super::*;

    const PROXY: u32 = 0x7000_0042;
    const CAPTURE: &str = "CRATONVM_JIT_IR_SPLICE_INDY_CAPTURE";
    const NEW_EXIT: &str = "CRATONVM_JIT_IR_SPLICE_UNRESOLVED_NEW_EXIT";

    /// Append `site` at caller pc 3 of a 10-byte caller (base 10).
    fn append(
        site: InlineSite,
        chain_fences: bool,
    ) -> (Result<(), &'static str>, ir::IrInlineTables) {
        let mut combined = vec![0u8; 10];
        let mut tables = ir::IrInlineTables::default();
        let mut owned_strings: Vec<Box<str>> = Vec::new();
        let mut owned_invoke_infos: Vec<Box<JitInvokeInfo>> = Vec::new();
        let mut direct_callee_entries: Vec<(usize, u64)> = Vec::new();
        let mut budget = IR_INLINE_MAX_TOTAL_BYTES;
        let mut vcalls: Vec<(usize, usize)> = Vec::new();
        let mut compact: HashMap<(usize, bool), (u32, bool, u8)> = HashMap::new();
        let mut static_init: Vec<u32> = Vec::new();
        let mut direct_calls: Vec<(usize, (usize, bool))> = Vec::new();
        let mut checkcast_seen = false;
        let mut volatile: Vec<usize> = Vec::new();
        let mut exact_nested: Vec<(usize, u32)> = Vec::new();
        let result = append_ir_inline_site(
            site,
            3,
            &mut combined,
            &mut tables,
            &mut owned_strings,
            &mut owned_invoke_infos,
            &mut direct_callee_entries,
            &mut budget,
            &mut vcalls,
            &mut compact,
            false,
            false,
            &mut static_init,
            &mut direct_calls,
            &mut checkcast_seen,
            &mut volatile,
            &mut exact_nested,
            None,
            &|_, _, _| None,
            ir::SpliceFenceRelax::NONE,
            chain_fences,
        );
        (result, tables)
    }

    /// `static IntSupplier c(int x) { return () -> x; }`:
    /// `0: iload_0  1: invokedynamic #2 (I)Ljava/util/function/IntSupplier;
    /// 6: areturn`.
    fn capturing_body(rows: Vec<(usize, u32, Vec<u8>)>) -> InlineSite {
        InlineSite {
            callee_code: vec![0x1a, 0xba, 0x00, 0x02, 0x00, 0x00, 0xb0, 0, 0],
            callee_code_len: 7,
            callee_max_locals: 1,
            callee_num_args: 1,
            callee_is_static: true,
            return_type: b'L',
            class_name: "p/Host".to_string(),
            class_id: 7,
            method_name: "c".to_string(),
            descriptor: "(I)Ljava/util/function/IntSupplier;".to_string(),
            ir_indy_capture_rows: rows,
            ..Default::default()
        }
    }

    #[test]
    fn r20w19_capturing_lambda_rows_are_rebased() {
        cratonvm_types::flags::with_thread_overrides(&[(CAPTURE, None)], || {
            let (result, tables) = append(capturing_body(vec![(1, PROXY, vec![b'I'])]), false);
            assert_eq!(result, Ok(()));
            assert_eq!(
                tables.indy_trap_sites,
                HashMap::from([(11usize, (1usize, b'L'))])
            );
            assert_eq!(
                tables.indy_capture_news,
                HashMap::from([(
                    11usize,
                    ir::IndyCaptureNew {
                        proxy_class_id: PROXY,
                        capture_tags: vec![b'I'],
                    },
                )])
            );
            // Never a constant-word row: no bridge site is rebased for it.
            assert!(tables.indy_bridge_sites.is_empty());

            let (result, _) = append(capturing_body(vec![(0, PROXY, vec![b'I'])]), false);
            assert_eq!(
                result,
                Err("ir-splice-indy-row-mismatch"),
                "a row on the iload"
            );
            let (result, _) = append(capturing_body(vec![(1, 0, vec![b'I'])]), false);
            assert_eq!(result, Err("ir-splice-indy-row-mismatch"), "no proxy");
            let (result, _) = append(capturing_body(vec![(1, PROXY, Vec::new())]), false);
            assert_eq!(result, Err("ir-splice-indy-row-mismatch"), "no capture");

            let mut handlers = capturing_body(vec![(1, PROXY, vec![b'I'])]);
            handlers.ir_handler_rows = vec![(0, 6, 6, "java/lang/RuntimeException".to_string(), 7)];
            assert_eq!(
                append(handlers, false).0,
                Err("ir-splice-indy-with-handlers")
            );
        });
        cratonvm_types::flags::with_thread_overrides(&[(CAPTURE, Some("0"))], || {
            let (result, tables) = append(capturing_body(vec![(1, PROXY, vec![b'I'])]), false);
            assert_eq!(result, Err("ir-splice-indy-capture-off"));
            assert!(tables.indy_capture_news.is_empty());
        });
    }

    /// `h(); return () -> x;`: unlike a constant-word site, a capturing site
    /// ALLOCATES, so after a call that stays a call it is a trap the replay
    /// fence must count (the design's "the planner's trap-after-call rule
    /// must count it").
    #[test]
    fn r20w19_the_fence_counts_a_capturing_lambda_after_a_call() {
        let code = vec![
            0xb8, 0x00, 0x01, 0x1a, 0xba, 0x00, 0x02, 0x00, 0x00, 0xb0, 0, 0,
        ];
        let site = InlineSite {
            callee_code: code,
            callee_code_len: 10,
            callee_max_locals: 1,
            callee_num_args: 1,
            callee_is_static: true,
            return_type: b'L',
            descriptor: "(I)Ljava/util/function/IntSupplier;".to_string(),
            ir_indy_capture_rows: vec![(4, PROXY, vec![b'I'])],
            ..Default::default()
        };
        assert!(ir_splice_body_may_trap_after_a_call(&site, None));
    }

    /// `static void m() { new Lazy(); }` reduced to the row's own bytes:
    /// `0: new #5  3: pop  4: return`, the `new`'s class not loaded (row
    /// class id 0).
    fn unloaded_new_body(npc: usize) -> InlineSite {
        InlineSite {
            callee_code: vec![0xbb, 0x00, 0x05, 0x57, 0xb1, 0, 0],
            callee_code_len: 5,
            callee_max_locals: 1,
            callee_num_args: 0,
            callee_is_static: true,
            return_type: b'V',
            class_name: "p/Host".to_string(),
            class_id: 7,
            method_name: "m".to_string(),
            descriptor: "()V".to_string(),
            ir_new_info: vec![(npc, 0, 0, false)],
            ..Default::default()
        }
    }

    #[test]
    fn r20w19_unloaded_new_rows_become_precise_exit_pcs() {
        cratonvm_types::flags::with_thread_overrides(
            &[(NEW_EXIT, None), ("CRATONVM_JIT_IR_SITE_TRAP", None)],
            || {
                let (result, tables) = append(unloaded_new_body(0), true);
                assert_eq!(result, Ok(()));
                assert!(tables.unloaded_static_call_pcs.contains(&10));
                assert!(
                    tables.new_info.is_empty(),
                    "a class-id-0 row is an exit, never an allocation row"
                );
                // The exit resumes through a chain snapshot: none without the
                // chain fences, so the body keeps its call.
                let (result, tables) = append(unloaded_new_body(0), false);
                assert_eq!(result, Err("ir-splice-new-site-unresolved"));
                assert!(tables.unloaded_static_call_pcs.is_empty());
                let (result, _) = append(unloaded_new_body(3), true);
                assert_eq!(
                    result,
                    Err("ir-splice-unresolved-new-row-mismatch"),
                    "a row on the pop"
                );
            },
        );
        cratonvm_types::flags::with_thread_overrides(&[(NEW_EXIT, Some("0"))], || {
            let (result, _) = append(unloaded_new_body(0), true);
            assert_eq!(result, Err("ir-splice-new-site-unresolved"));
        });
        cratonvm_types::flags::with_thread_overrides(
            &[(NEW_EXIT, None), ("CRATONVM_JIT_IR_SITE_TRAP", Some("0"))],
            || {
                let (result, _) = append(unloaded_new_body(0), true);
                assert_eq!(result, Err("ir-splice-new-site-unresolved"));
            },
        );
    }

    #[test]
    fn r20w19_the_switches_default_on() {
        cratonvm_types::flags::with_thread_overrides(
            &[
                (CAPTURE, None),
                (NEW_EXIT, None),
                ("CRATONVM_JIT_SP_SPLICE_INDY_CONSTANT", None),
                ("CRATONVM_JIT_IR_SPLICE_INDY", None),
                ("CRATONVM_JIT_IR_INDY_CAPTURE_NEW", None),
                ("CRATONVM_JIT_INDY_CONSTANT_LAMBDA", None),
            ],
            || {
                assert!(ir::ir_splice_indy_capture_enabled());
                assert!(ir::ir_splice_unresolved_new_exit_enabled());
                assert!(ir::sp_splice_indy_constant_enabled());
            },
        );
        cratonvm_types::flags::with_thread_overrides(
            &[
                (CAPTURE, Some("0")),
                (NEW_EXIT, Some("0")),
                ("CRATONVM_JIT_SP_SPLICE_INDY_CONSTANT", Some("0")),
            ],
            || {
                assert!(!ir::ir_splice_indy_capture_enabled());
                assert!(!ir::ir_splice_unresolved_new_exit_enabled());
                assert!(!ir::sp_splice_indy_constant_enabled());
            },
        );
    }
}

/// Interpreter round i6 wave 121, lane L2 (stage 3a of
/// `i43-L1-proposal-deoptimize-a-compiled-frame-for-the-frame-commands`):
/// [`CompiledMethod::debugger_exit_after_call`] answers only a recorded call
/// bci, and nothing for a body compiled without a debugger.
#[cfg(test)]
mod i121_l2_debugger_exit_after_call_tests {
    use super::*;

    #[test]
    fn only_a_recorded_call_has_an_exit_door() {
        let mut cm = CompiledMethod::new(ExecutableBuffer::new(64).unwrap());
        assert!(!cm.debugger_exit_after_call(0));
        assert!(!cm.debugger_exit_after_call(7));
        cm.debugger_exit_call_bcis = vec![(3, 6), (7, 10), (12, 15)];
        assert!(cm.debugger_exit_after_call(7));
        assert!(cm.debugger_exit_after_call(12));
        assert!(!cm.debugger_exit_after_call(8));
        assert!(!cm.debugger_exit_after_call(u32::MAX));
        assert_eq!(cm.debugger_exit_bci_after_call(7), Some(10));
        assert_eq!(cm.debugger_exit_bci_after_call(6), None);
    }

    fn state(bci: u32, locals: usize) -> deopt::FrameState {
        deopt::FrameState {
            method_key: String::new(),
            bci,
            locals: vec![deopt::FrameValue::Undefined; locals],
            stack: Vec::new(),
            monitors: Vec::new(),
            caller: None,
        }
    }

    fn exit_point(bci: u32, locals: usize, chained: bool) -> deopt::DeoptimizationPoint {
        let reason = deopt::DeoptReason::OsrExit;
        let mut frame_state = state(bci, locals);
        if chained {
            frame_state.caller = Some(Box::new(state(3, 1)));
        }
        deopt::DeoptimizationPoint {
            native_offset: 0,
            bci,
            reason,
            action: deopt::DeoptAction::Reinterpret,
            speculation_id: 0,
            frame_state,
            semantics: deopt::ResumeSemantics::for_reason(reason),
        }
    }

    /// Interpreter round i6 wave 122, lane L2 (stage 3b, first slice): the
    /// write door opens only on a kept single-frame exit whose map describes
    /// every local, and names each refusal.
    #[test]
    fn the_write_door_opens_only_on_a_describing_single_frame_exit() {
        let mut cm = CompiledMethod::new(ExecutableBuffer::new(64).unwrap());
        assert_eq!(cm.debugger_write_door(7, 2), DebuggerWriteDoor::NoExit);
        cm.debugger_exit_call_bcis = vec![(7, 10)];
        assert_eq!(cm.debugger_write_door(7, 2), DebuggerWriteDoor::NoMap { exit_bci: 10 });
        cm.deopt_points = vec![exit_point(10, 1, false)];
        assert_eq!(
            cm.debugger_write_door(7, 2),
            DebuggerWriteDoor::ShortMap {
                exit_bci: 10,
                described: 1
            }
        );
        cm.deopt_points = vec![exit_point(10, 3, false)];
        assert_eq!(cm.debugger_write_door(7, 2), DebuggerWriteDoor::Open { exit_bci: 10 });
        cm._deopt_point_boxes = vec![Box::new(exit_point(10, 3, true))];
        assert_eq!(
            cm.debugger_write_door(7, 2),
            DebuggerWriteDoor::ChainExit { exit_bci: 10 }
        );
        cm._deopt_point_boxes.clear();
        cm.exits_spared_as_obsolete
            .store(true, std::sync::atomic::Ordering::Release);
        assert_eq!(cm.debugger_write_door(7, 2), DebuggerWriteDoor::SparedAsObsolete);
    }

    /// Interpreter round i6 wave 123, lane L2 (stage 3b, force slice): the
    /// verdict says `Leaves` only for an open door on a withdrawn,
    /// non-obsolete body whose post-call sites were all written.
    #[test]
    fn the_force_verdict_leaves_only_for_a_withdrawn_forced_body() {
        let mut cm = CompiledMethod::new(ExecutableBuffer::new(64).unwrap());
        assert_eq!(
            cm.debugger_force_verdict(7, 2, true, false),
            DebuggerForceVerdict::Door(DebuggerWriteDoor::NoExit)
        );
        cm.debugger_exit_call_bcis = vec![(7, 10)];
        cm.deopt_points = vec![exit_point(10, 3, false)];
        assert_eq!(
            cm.debugger_force_verdict(7, 2, false, false),
            DebuggerForceVerdict::NotWithdrawn { exit_bci: 10 }
        );
        assert_eq!(
            cm.debugger_force_verdict(7, 2, true, true),
            DebuggerForceVerdict::Obsolete { exit_bci: 10 }
        );
        assert_eq!(
            cm.debugger_force_verdict(7, 2, true, false),
            DebuggerForceVerdict::SitesNotForced { exit_bci: 10 }
        );
        assert!(!cm.post_call_exits_forced());
        cm.post_call_exits_forced
            .store(true, std::sync::atomic::Ordering::Release);
        assert_eq!(
            cm.debugger_force_verdict(7, 2, true, false),
            DebuggerForceVerdict::Leaves { exit_bci: 10 }
        );
        assert_eq!(cm.debugger_force_verdict(7, 2, true, false).name(), "leaves");
        assert_eq!(
            cm.debugger_force_verdict(8, 2, true, false).name(),
            "refused:no-exit"
        );
    }
}

/// Interpreter round i6 wave 117, lane L2 (`CRATONVM_JIT_REENTRY_ONLY_PUBLICATION`,
/// page `i115-L4-proposal-shadowed-jdk-bodies-compile-for-their-bytecode-only-reentries`):
/// the re-entry-only publication contract of [`JitCache`].
#[cfg(test)]
mod i117_l2_reentry_only_publication_tests {
    use super::*;
    use cratonvm_types::ClassId;

    const ID: ClassId = ClassId::new(0x117_0001);

    fn body() -> CompiledMethod {
        CompiledMethod::new(ExecutableBuffer::new(64).unwrap())
    }

    fn cache(on: bool) -> JitCache {
        cratonvm_types::flags::with_thread_overrides(
            &[(
                "CRATONVM_JIT_REENTRY_ONLY_PUBLICATION",
                if on { Some("1") } else { None },
            )],
            JitCache::new,
        )
    }

    #[test]
    fn a_marked_body_is_answered_only_to_a_reentry() {
        let cache = cache(true);
        assert!(cache.mark_reentry_only("i117/H", "asType", "(LT;)LH;"));
        assert!(cache.is_reentry_only_key("i117/H", "asType", "(LT;)LH;"));
        cache.put("i117/H".into(), "asType".into(), "(LT;)LH;".into(), ID, body());
        assert!(cache.get("i117/H", "asType", "(LT;)LH;", ID).is_none());
        let reentry = cache.get_for_reentry("i117/H", "asType", "(LT;)LH;", ID);
        assert!(reentry.is_some_and(|b| b.reentry_only));
        // An unmarked method of the same class publishes as before.
        cache.put("i117/H".into(), "other".into(), "()V".into(), ID, body());
        assert!(cache
            .get("i117/H", "other", "()V", ID)
            .is_some_and(|b| !b.reentry_only));
    }

    #[test]
    fn a_reentry_only_body_never_displaces_a_live_binding_body() {
        let cache = cache(true);
        cache.put("i117/H".into(), "bindTo".into(), "(LO;)LH;".into(), ID, body());
        let live = cache.get("i117/H", "bindTo", "(LO;)LH;", ID).expect("published");
        assert!(cache.mark_reentry_only("i117/H", "bindTo", "(LO;)LH;"));
        cache.put("i117/H".into(), "bindTo".into(), "(LO;)LH;".into(), ID, body());
        let still = cache.get("i117/H", "bindTo", "(LO;)LH;", ID).expect("kept");
        assert_eq!(still.artifact_id, live.artifact_id);
    }

    /// JIT round 23 wave 8h: a row marked by its own switch
    /// (`mark_reentry_only_row`) publishes re-entry-only with the cache-wide
    /// switch OFF, and only that row.
    #[test]
    fn a_row_marked_by_its_own_switch_is_reentry_only_with_the_cache_switch_off() {
        let cache = cache(false);
        let (c, m, d) = ("i117/L", "loadClassOrNull", "(Ljava/lang/String;Z)Ljava/lang/Class;");
        cache.mark_reentry_only_row(c, m, d);
        assert!(cache.is_reentry_only_key(c, m, d));
        cache.put(c.into(), m.into(), d.into(), ID, body());
        assert!(cache.get(c, m, d, ID).is_none(), "no caller binds it");
        assert!(cache
            .get_for_reentry(c, m, d, ID)
            .is_some_and(|b| b.reentry_only));
        assert!(!cache.is_reentry_only_key(c, "other", "()V"));
        assert!(!cache.mark_reentry_only("i117/H", "asType", "(LT;)LH;"), "cache switch still off");
    }

    #[test]
    fn switch_off_marks_nothing() {
        let cache = cache(false);
        assert!(!cache.mark_reentry_only("i117/H", "asType", "(LT;)LH;"));
        assert!(!cache.is_reentry_only_key("i117/H", "asType", "(LT;)LH;"));
        cache.put("i117/H".into(), "asType".into(), "(LT;)LH;".into(), ID, body());
        assert!(cache
            .get("i117/H", "asType", "(LT;)LH;", ID)
            .is_some_and(|b| !b.reentry_only));
    }
}

#[cfg(test)]
mod r21w2_splice_nest_frame_clamp_tests {
    use super::*;

    const KNOB: &str = "CRATONVM_JIT_IR_INLINE_MAX_NEST";
    const CLAMP: &str = "CRATONVM_JIT_IR_INLINE_MAX_NEST_FRAME_CLAMP";
    const LEAF: &str = "CRATONVM_JIT_IR_SPLICE_LEAF_PAST_DEPTH";
    /// rx27: `CRATONVM_JIT_IR_CHAIN_DEEP_SPINE` (default ON since 2026-10-29)
    /// moves the builder's frame cap; every case here pins it off.
    const DEEP: &str = "CRATONVM_JIT_IR_CHAIN_DEEP_SPINE";

    /// A chain planned at nesting depth `depth` opens `depth` frames, plus one
    /// with the leaf tier; the builder opens at most `MAX_IR_SPLICE_DEPTH`.
    fn frames(depth: usize, leaf: bool) -> usize {
        depth + usize::from(leaf)
    }

    #[test]
    fn r21w2_the_default_depth_fits_the_builder() {
        assert!(frames(MAX_IR_INLINE_NEST_DEPTH, true) <= ir::MAX_IR_SPLICE_DEPTH);
        // rx27 (2026-10-29): the deep spine (default ON) raises the builder
        // cap to 12; this test measures the 8-frame cap, so it is pinned off.
        cratonvm_types::flags::with_thread_overrides(&[(DEEP, Some("0"))], || {
            assert!(MAX_IR_INLINE_NEST_DEPTH <= ir_inline_max_nest_frame_cap(true));
            assert_eq!(frames(ir_inline_max_nest_frame_cap(true), true), ir::MAX_IR_SPLICE_DEPTH);
            assert_eq!(
                frames(ir_inline_max_nest_frame_cap(false), false),
                ir::MAX_IR_SPLICE_DEPTH
            );
        });
        // JIT r25 wave 10 (W10-3): the chain switch, which deepens the unset
        // knob, pinned off.
        cratonvm_types::flags::with_thread_overrides(&[(KNOB, None), (CLAMP, None), (LEAF, None), (DEEP, Some("0")), ("CRATONVM_JIT_IR_NESTED_CHAIN_SPLICE", Some("0")), ("CRATONVM_JIT_IR_NESTED_LAMBDA_IFACE", Some("0"))], || {
            assert!(ir_inline_max_nest_frame_clamp_enabled());
            assert_eq!(ir_inline_max_nest_depth(), MAX_IR_INLINE_NEST_DEPTH);
        });
    }

    #[test]
    fn r21w2_a_deep_knob_is_clamped_to_the_builder_frames() {
        cratonvm_types::flags::with_thread_overrides(
            &[(KNOB, Some("12")), (CLAMP, None), (LEAF, None), (DEEP, Some("0"))],
            || {
                let d = ir_inline_max_nest_depth();
                assert_eq!(d, ir::MAX_IR_SPLICE_DEPTH - 1);
                assert!(frames(d, true) <= ir::MAX_IR_SPLICE_DEPTH);
            },
        );
        cratonvm_types::flags::with_thread_overrides(
            &[(KNOB, Some("12")), (CLAMP, None), (LEAF, Some("0")), (DEEP, Some("0"))],
            || {
                let d = ir_inline_max_nest_depth();
                assert_eq!(d, ir::MAX_IR_SPLICE_DEPTH);
                assert!(frames(d, false) <= ir::MAX_IR_SPLICE_DEPTH);
            },
        );
        // A knob inside the cap is unchanged.
        cratonvm_types::flags::with_thread_overrides(
            &[(KNOB, Some("4")), (CLAMP, None), (LEAF, None), (DEEP, Some("0"))],
            || assert_eq!(ir_inline_max_nest_depth(), 4),
        );
    }

    #[test]
    fn r21w2_the_kill_word_restores_the_unclamped_knob() {
        cratonvm_types::flags::with_thread_overrides(
            &[(KNOB, Some("12")), (CLAMP, Some("0")), (LEAF, None), (DEEP, Some("0"))],
            || {
                assert!(!ir_inline_max_nest_frame_clamp_enabled());
                assert_eq!(ir_inline_max_nest_depth(), 12);
            },
        );
    }
}

#[cfg(test)]
mod r21w3_splice_cha_guard_tests {
    use super::*;

    #[test]
    fn r21w3_the_cha_guard_is_opt_in() {
        cratonvm_types::flags::with_thread_overrides(
            &[("CRATONVM_JIT_IR_CHA_GUARDED_SPLICE", None)],
            || assert!(!ir_cha_guarded_splice_enabled()),
        );
        cratonvm_types::flags::with_thread_overrides(
            &[("CRATONVM_JIT_IR_CHA_GUARDED_SPLICE", Some("1"))],
            || assert!(ir_cha_guarded_splice_enabled()),
        );
    }

    #[test]
    fn r21w3_only_an_unprofiled_site_takes_the_hierarchy_answer() {
        // No profile at all, and a profile with no row at the pc.
        assert!(ir_cha_guard_site_unprofiled(None, 4));
        let empty = profile::MethodProfile::default();
        assert!(ir_cha_guard_site_unprofiled(Some(&empty), 4));
    }

    /// The planner asks the profile first and the hierarchy last.
    #[test]
    fn r21w3_the_planner_asks_the_hierarchy_after_the_profile() {
        let src = include_str!("lib.rs").replace("\r\n", "\n");
        let profile = src
            // JIT round 21 wave 19 (lane mhbind2): a bound constant handle's
            // exact class is asked ahead of the profile.
            .find(".or_else(|| ir::profile_guarded_receiver_class(profile, pc))\n                                .or_else(|| ir_mh_interface_cha_class(")
            .expect("the profile first");
        let cha = src
            .find(".or_else(|| ir_cha_guard_class(pc, opcode, &cn, &mn, &desc))")
            .expect("the hierarchy last");
        assert!(profile < cha);
    }
}

/// JIT round 21 wave 4 (lane codecache): a body whose mapping is rescued into
/// the retirement queue keeps the side tables its code addresses
/// (`RescuedSideTables`, `CRATONVM_JIT_RESCUE_KEEPS_SIDE_TABLES`).
#[cfg(test)]
mod r21w4_codecache_rescued_side_tables_tests {
    use super::*;
    use std::sync::atomic::AtomicU8;

    /// A published body whose one class-init cell is `cell` (a side table its
    /// code would read by address), and its buffer start.
    fn published_body_with_cell(cell: &Arc<AtomicU8>) -> (CompiledMethod, usize) {
        let mut buf = ExecutableBuffer::new(64).expect("executable buffer");
        buf.emit(&[0xC3]); // RET
        let mut cm = CompiledMethod::new(buf);
        let _ = cm._buffer.mark_published();
        cm._jit_class_init_cells.push(Arc::clone(cell));
        let base = cm.entry_ptr() as usize;
        (cm, base)
    }

    /// Drop `cm` the way the round-14 cascade does (inside another buffer's
    /// reclamation scope) while this thread is inside compiled code, and
    /// answer how many owners `cell` has right after.
    fn owners_after_a_cascaded_drop(cell: &Arc<AtomicU8>) -> usize {
        let token = jit_execution_enter();
        let (cm, base) = published_body_with_cell(cell);
        {
            let _other = AuthorisedReclaim::enter_for(base.wrapping_add(0x10_0000));
            drop(cm);
        }
        let owners = Arc::strong_count(cell);
        jit_execution_leave(token);
        owners
    }

    /// The `gcd-d10v` cascade kept the MAPPING of a body a thread may still be
    /// inside, and freed every box its code reads by address. Now they wait in
    /// the queue with it: the cell is still owned after the drop. Before the
    /// fix its count fell to 1 at once.
    #[test]
    fn a_cascaded_body_keeps_its_side_tables_until_its_own_proof() {
        let cell = Arc::new(AtomicU8::new(0));
        assert_eq!(
            owners_after_a_cascaded_drop(&cell),
            2,
            "a rescued body's side tables must stay alive with its mapping"
        );
    }

    /// `=0` restores the old drop: the tables go with the artifact.
    #[test]
    fn the_kill_switch_frees_the_side_tables_with_the_artifact() {
        cratonvm_types::flags::with_thread_overrides(
            &[("CRATONVM_JIT_RESCUE_KEEPS_SIDE_TABLES", Some("0"))],
            || {
                let cell = Arc::new(AtomicU8::new(0));
                assert_eq!(owners_after_a_cascaded_drop(&cell), 1);
            },
        );
    }

    /// An ordinary authorised release (the queue's own proof covering this
    /// buffer) is not a rescue: nothing is kept.
    #[test]
    fn an_authorised_release_keeps_nothing() {
        let cell = Arc::new(AtomicU8::new(0));
        let (cm, _base) = published_body_with_cell(&cell);
        {
            let _proof = AuthorisedReclaim::enter();
            assert!(!cm._buffer.release_would_be_rescued());
            drop(cm);
        }
        assert_eq!(Arc::strong_count(&cell), 1);
    }
}

/// JIT round 21 wave 4 follow-up (lane codecache): CODECACHE21-1 (inline-cache
/// owners leave a dying body through the queue) and CODECACHE21-2 (the
/// `RetainedCode` holder count).
#[cfg(test)]
mod r21w4_codecache_owner_routing_tests {
    use super::*;
    use std::sync::atomic::Ordering;

    fn published_body() -> Arc<CompiledMethod> {
        let mut buf = ExecutableBuffer::new(64).expect("executable buffer");
        buf.emit(&[0xC3]); // RET
        let mut cm = CompiledMethod::new(buf);
        let _ = cm._buffer.mark_published();
        Arc::new(cm)
    }

    /// Caller `B` whose one MIC slot is the ONLY owner of callee `D`; `B` is
    /// released on a proof about its own buffer while this thread is inside
    /// compiled code. Answers whether `D` is still a live artifact afterwards.
    fn callee_survives_its_callers_release() -> bool {
        let token = jit_execution_enter();
        let callee = published_body();
        let weak = Arc::downgrade(&callee);
        let mut caller = {
            let mut buf = ExecutableBuffer::new(64).expect("executable buffer");
            buf.emit(&[0xC3]);
            CompiledMethod::new(buf)
        };
        let _ = caller._buffer.mark_published();
        let slot = JitMICSlot::new();
        slot.cached_entry_word
            .store(callee.entry_ptr() as u64, Ordering::SeqCst);
        *slot.compiled_owner.lock() = Some(callee);
        caller._jit_mic_slots.push(Box::new(slot));
        let base = caller.entry_ptr() as usize;
        {
            // The queue's per-thread proof covering the CALLER only.
            let _proof = AuthorisedReclaim::enter_for(base);
            drop(caller);
        }
        let alive = weak.upgrade().is_some();
        jit_execution_leave(token);
        alive
    }

    /// Before CODECACHE21-1 the slot's bare `Arc` was dropped with the
    /// caller's fields: `D`'s artifact died at once, as a cascade of a proof
    /// about another buffer (its mapping was re-queued, its registrations
    /// went). Now it waits in the queue, whole.
    #[test]
    fn a_callee_held_only_by_a_dying_callers_slot_waits_in_the_queue_whole() {
        assert!(callee_survives_its_callers_release());
    }

    #[test]
    fn the_ic_owner_kill_switch_drops_the_callee_with_the_caller() {
        cratonvm_types::flags::with_thread_overrides(
            &[("CRATONVM_JIT_IC_OWNERS_THROUGH_QUEUE", Some("0"))],
            || assert!(!callee_survives_its_callers_release()),
        );
    }

    /// The dying caller's slot word is zeroed before its owner leaves, so a
    /// thread still inside the caller misses instead of calling the callee.
    #[test]
    fn a_withdrawn_slot_word_is_zeroed() {
        let mut caller = {
            let mut buf = ExecutableBuffer::new(64).expect("executable buffer");
            buf.emit(&[0xC3]);
            CompiledMethod::new(buf)
        };
        let callee = published_body();
        let slot = JitMICSlot::new();
        slot.cached_entry_word
            .store(callee.entry_ptr() as u64, Ordering::SeqCst);
        *slot.compiled_owner.lock() = Some(Arc::clone(&callee));
        caller._jit_mic_slots.push(Box::new(slot));
        caller.withdraw_inline_cache_owners();
        assert_eq!(caller._jit_mic_slots[0].cached_entry_word.load(Ordering::SeqCst), 0);
        assert!(caller._jit_mic_slots[0].compiled_owner.lock().is_none());
        drop(RetainedCode::new(callee));
    }

    /// Answers how many strong references a bare holder sees after the LAST
    /// `RetainedCode` handle drops while a thread is inside compiled code.
    fn strong_after_the_last_handle_drops() -> usize {
        let token = jit_execution_enter();
        let bare = published_body();
        let handle = RetainedCode::new(Arc::clone(&bare));
        let twin = handle.clone();
        drop(handle);
        drop(twin);
        let strong = Arc::strong_count(&bare);
        jit_execution_leave(token);
        drop(RetainedCode::new(bare));
        strong
    }

    /// CODECACHE21-2: the handle that takes the holder count to zero routes
    /// its reference through the queue even though `strong_count` reads 2 (a
    /// bare holder remains), so the queue holds one. The old shortcut dropped
    /// it plainly -- the shape of the last-two race, where the other "holder"
    /// is a concurrent drop.
    #[test]
    fn the_last_holder_routes_whatever_strong_count_reads() {
        assert_eq!(strong_after_the_last_handle_drops(), 2);
    }

    #[test]
    fn the_holder_count_kill_switch_restores_the_shortcut() {
        cratonvm_types::flags::with_thread_overrides(
            &[("CRATONVM_JIT_RETAINED_HOLDER_COUNT", Some("0"))],
            || assert_eq!(strong_after_the_last_handle_drops(), 1),
        );
    }

    #[test]
    fn handles_are_counted() {
        let body = published_body();
        let a = RetainedCode::new(Arc::clone(&body));
        let b = a.clone();
        assert_eq!(body.retained_holders.load(Ordering::SeqCst), 2);
        drop(a);
        assert_eq!(body.retained_holders.load(Ordering::SeqCst), 1);
        drop(b);
        drop(RetainedCode::new(body));
    }
}

/// Review rev-w45-jit item 1 (JIT round 21 wave 7, lane codecache): the
/// holder count does NOT send a reader's handle on a still-published body
/// through the retirement queue. The cache's own shard-map entry is a counted
/// `RetainedCode`, so a per-thread invoke-cache handle on a published body is
/// never the last holder and drops as a plain decrement. Only a body the cache
/// no longer holds (superseded here; withdrawn, unpublished or memo-only bodies
/// alike) has its last handle routed, which is the case CODECACHE21-2 closes.
#[cfg(test)]
mod r21w7_codecache_published_handle_tests {
    use super::*;
    use std::sync::atomic::Ordering;

    fn ret_body() -> CompiledMethod {
        let mut buf = ExecutableBuffer::new(64).expect("executable buffer");
        buf.emit(&[0xC3]); // RET
        CompiledMethod::new(buf)
    }

    /// `(strong before the handle drops, strong after, holders after,
    /// superseded)` for a reader handle on the cache's body, dropped while this
    /// thread is inside compiled code (so a queued reference stays queued).
    /// `supersede` republishes the key first, so the handle is the last holder.
    fn drop_a_reader_handle(supersede: bool) -> (usize, usize, usize, bool) {
        let cache = JitCache::new();
        let class: Arc<str> = Arc::from("r21w7/PublishedHandle");
        let method: Arc<str> = Arc::from("m");
        let desc: Arc<str> = Arc::from("()V");
        let cid = cratonvm_types::ClassId::new(1);
        cache.put(class.clone(), method.clone(), desc.clone(), cid, ret_body());
        let bare = cache.get(&class, &method, &desc, cid).expect("published");
        let handle = RetainedCode::new(Arc::clone(&bare));
        // Entered BEFORE the supersede, so the reference the supersede itself
        // queues cannot be released by the drain the handle's drop runs (which
        // would read as a plain decrement).
        let token = jit_execution_enter();
        if supersede {
            cache.put(class.clone(), method.clone(), desc.clone(), cid, ret_body());
        }
        let before = Arc::strong_count(&bare);
        drop(handle);
        let after = Arc::strong_count(&bare);
        jit_execution_leave(token);
        let holders = bare.retained_holders.load(Ordering::SeqCst);
        let superseded = bare.superseded.load(Ordering::SeqCst);
        cache.clear_all();
        drop(RetainedCode::new(bare));
        (before, after, holders, superseded)
    }

    /// The common invoke-cache eviction: the body is still published, the
    /// map's handle keeps the count above zero, and the reader's reference is
    /// released on the spot -- nothing waits in the queue for it.
    #[test]
    fn a_handle_on_a_published_body_drops_plainly() {
        let (before, after, holders, superseded) = drop_a_reader_handle(false);
        assert!(!superseded);
        assert_eq!(holders, 1, "the shard map's own handle is counted");
        assert_eq!(after, before - 1, "a plain decrement, not a queue entry");
    }

    /// The race CODECACHE21-2 closes is still closed: once the cache has let
    /// go, the reader's handle is the last holder and its reference moves into
    /// the queue instead of being released.
    #[test]
    fn the_last_handle_on_a_superseded_body_still_routes() {
        let (before, after, holders, superseded) = drop_a_reader_handle(true);
        assert!(superseded);
        assert_eq!(holders, 0);
        assert_eq!(after, before, "the reference moved into the queue");
    }
}

/// Review rev-x64 item 8 (JIT round 21 wave 5, lane codecache): only a
/// decompilation charges the recompile cutoff.
#[cfg(test)]
mod r21w5_codecache_charged_withdrawal_tests {
    use super::*;

    #[derive(Default)]
    struct CountingSink {
        charged: parking_lot::Mutex<usize>,
    }

    impl JitBodyWithdrawalSink for CountingSink {
        fn bodies_withdrawn(&self, _keys: &[WithdrawnMethodKey]) {}
        fn optimizing_bodies_invalidated(&self, keys: &[WithdrawnMethodKey]) {
            *self.charged.lock() += keys.len();
        }
    }

    fn key(name: &str) -> WithdrawnMethodKey {
        (
            Arc::from("r21w5/Charged"),
            Arc::from(name),
            Arc::from("()V"),
            cratonvm_types::ClassId::new(0),
        )
    }

    #[test]
    fn only_invalidations_and_trap_evictions_charge() {
        let cache = JitCache::new();
        let sink = Arc::new(CountingSink::default());
        let dyn_sink: Arc<dyn JitBodyWithdrawalSink> = sink.clone();
        assert!(cache.install_withdrawal_sink(Arc::downgrade(&dyn_sink)));
        let (a, b) = (key("a"), key("b"));
        for reason in [
            retire_reason::SUPERSEDED,
            retire_reason::CACHE_PRESSURE,
            retire_reason::CLASS_UNLOADED,
            retire_reason::SHUTDOWN,
        ] {
            cache.report_charged_withdrawals(reason, &[a.clone()], &[b.clone()]);
        }
        assert_eq!(*sink.charged.lock(), 0, "no decompilation, no charge");
        cache.report_charged_withdrawals(retire_reason::INVALIDATED, &[a.clone()], &[a.clone()]);
        assert_eq!(*sink.charged.lock(), 1, "one key, deduplicated across entry and OSR");
        cache.report_charged_withdrawals(retire_reason::DEOPTIMIZED, &[a.clone()], &[b.clone()]);
        assert_eq!(*sink.charged.lock(), 3);
        cratonvm_types::flags::with_thread_overrides(
            &[("CRATONVM_JIT_OSR_WITHDRAWAL_CHARGED", Some("0"))],
            || cache.report_charged_withdrawals(retire_reason::INVALIDATED, &[], &[b.clone()]),
        );
        assert_eq!(*sink.charged.lock(), 3, "OSR keys are left out with the switch off");
    }
}

/// JIT round 22, lane sync (SYNC22-1): an inline-cache owner published into a
/// rescued body's slot AFTER the body's drop withdrew its owners leaves through
/// the queue when the rescued side tables are released, not as a field drop.
#[cfg(test)]
mod r22_sync_rescued_tables_rewithdraw_tests {
    use super::*;
    use std::sync::atomic::Ordering;

    fn published_body() -> Arc<CompiledMethod> {
        let mut buf = ExecutableBuffer::new(64).expect("executable buffer");
        buf.emit(&[0xC3]); // RET
        let mut cm = CompiledMethod::new(buf);
        let _ = cm._buffer.mark_published();
        Arc::new(cm)
    }

    /// A caller whose side tables were moved out (as a rescue does) and whose
    /// MIC slot is then re-published with callee `D` as its only owner; the
    /// tables are dropped while this thread is inside compiled code. Answers
    /// whether `D` is still a live artifact afterwards (queued, not freed).
    fn republished_callee_survives_the_tables_release() -> bool {
        let token = jit_execution_enter();
        let mut caller = {
            let mut buf = ExecutableBuffer::new(64).expect("executable buffer");
            buf.emit(&[0xC3]);
            CompiledMethod::new(buf)
        };
        caller._jit_mic_slots.push(Box::new(JitMICSlot::new()));
        let tables = RescuedSideTables::take_from(&mut caller);
        drop(caller);
        let callee = published_body();
        let weak = Arc::downgrade(&callee);
        {
            // The late publication by a thread still inside the rescued code.
            let slot = &tables.mic_slots[0];
            let mut owner = slot.compiled_owner.lock();
            slot.cached_entry_word
                .store(callee.entry_ptr() as u64, Ordering::SeqCst);
            *owner = Some(callee);
        }
        drop(tables);
        let alive = weak.upgrade().is_some();
        jit_execution_leave(token);
        alive
    }

    #[test]
    fn a_late_published_owner_leaves_a_rescued_table_through_the_queue() {
        assert!(republished_callee_survives_the_tables_release());
    }

    /// `=0` restores the field drop: the callee dies with the tables.
    #[test]
    fn the_rewithdraw_kill_switch_drops_the_owner_with_the_tables() {
        cratonvm_types::flags::with_thread_overrides(
            &[("CRATONVM_JIT_RESCUED_TABLES_REWITHDRAW", Some("0"))],
            || assert!(!republished_callee_survives_the_tables_release()),
        );
    }
}

#[cfg(test)]
mod r22_throws_indy_loop_sites_tests {
    use super::indy_sites_all_outside_loops;

    /// JIT round 22 wave 2 (lane throws, THROWS22-2): an `invokedynamic` after
    /// the loop qualifies; one inside it, or a method with no loop, does not.
    #[test]
    fn an_indy_after_the_loop_is_outside_every_loop() {
        //  0: iconst_0  1: istore_0  2: iload_0  3: bipush 10  5: if_icmpge 14
        //  8: iinc 0 1  11: goto 2   14: invokedynamic #1  19: areturn
        let code = [
            0x03, 0x3b, 0x1a, 0x10, 0x0a, 0xa2, 0x00, 0x09, 0x84, 0x00, 0x01, 0xa7, 0xff, 0xf7,
            0xba, 0x00, 0x01, 0x00, 0x00, 0xb0, 0, 0,
        ];
        assert!(indy_sites_all_outside_loops(&code, 20, &[(14, 1)], &[]));
        // A site inside [2, 11] (the loop's textual range) is on the cycle.
        assert!(!indy_sites_all_outside_loops(&code, 20, &[(14, 1), (8, 1)], &[]));
        // No back edge: no loop, so the plan is not taken.
        let straight = [0xba, 0x00, 0x01, 0x00, 0x00, 0xb0, 0, 0];
        assert!(!indy_sites_all_outside_loops(&straight, 6, &[(0, 1)], &[]));
        // JIT r22 wave 3: a handler at pc 14 protecting [14, 20) re-enters
        // itself through its exception edge (no backward branch): the indy at
        // 14 is on that cycle. A handler past its range adds nothing.
        let row = |start_pc: u16, end_pc: u16, handler_pc: u16| {
            cratonvm_reader::attribute::ExceptionTableEntry {
                start_pc,
                end_pc,
                handler_pc,
                catch_type: 0,
            }
        };
        assert!(!indy_sites_all_outside_loops(&code, 20, &[(14, 1)], &[row(14, 20, 14)]));
        assert!(indy_sites_all_outside_loops(&code, 20, &[(14, 1)], &[row(0, 2, 14)]));
    }
}

/// JIT round 23 wave 1, lane L6 (SYNC22-3): `direct_native_helper` asks the
/// VM's bind admission in `--compatible` too, and the `_for_impl` variant asks
/// the implementing row there.
#[cfg(test)]
mod r23_w1_l6_compat_direct_bind_tests {
    use super::{direct_native_helper, direct_native_helper_for_impl};

    const ENTRY: usize = 0x1234;

    #[test]
    fn compat_binds_only_what_the_vm_admits() {
        let refuse_all = |_: &str, _: &str, _: &str| false;
        let admit_all = |_: &str, _: &str, _: &str| true;
        assert_eq!(direct_native_helper(ENTRY, false, Some(&refuse_all), "a/B", "m", "()V"), 0);
        assert_eq!(
            direct_native_helper(ENTRY, false, Some(&admit_all), "a/B", "m", "()V"),
            ENTRY
        );
        // No admission closure (hand-built request): the old unconditional bind.
        assert_eq!(direct_native_helper(ENTRY, false, None, "a/B", "m", "()V"), ENTRY);
        // An unwired cell stays unwired without asking.
        let panics = |_: &str, _: &str, _: &str| -> bool { panic!("not asked for a zero cell") };
        assert_eq!(direct_native_helper(0, false, Some(&panics), "a/B", "m", "()V"), 0);
    }

    #[test]
    fn compat_for_impl_asks_the_implementing_row() {
        let asked = std::cell::RefCell::new(Vec::<String>::new());
        let only_impl = |c: &str, _: &str, _: &str| {
            asked.borrow_mut().push(c.to_string());
            c == "java/util/concurrent/ConcurrentHashMap"
        };
        let entry = direct_native_helper_for_impl(
            ENTRY,
            false,
            Some(&only_impl),
            "java/util/concurrent/ConcurrentMap",
            "java/util/concurrent/ConcurrentHashMap",
            "get",
            "(Ljava/lang/Object;)Ljava/lang/Object;",
        );
        assert_eq!(entry, ENTRY);
        assert_eq!(*asked.borrow(), vec!["java/util/concurrent/ConcurrentHashMap".to_string()]);
    }
}

/// JIT round 23 wave 8 (lane W8-L2, CF-W8-3;
/// `CRATONVM_JIT_IR_EVIDENCE_COLD_ARM_WEIGHT`): the callee's rarely taken arms.
#[cfg(test)]
mod r23_w8_splice_cold_arm_tests {
    use super::*;

    const KEY: &str = "CRATONVM_JIT_IR_EVIDENCE_COLD_ARM_WEIGHT";

    /// `0 iload_0; 1 ifeq -> 6; 4 iconst_1; 5 ireturn; 6 iconst_2; 7 ireturn`
    /// (padded): the taken arm is pcs 6..8.
    const BODY: [u8; 10] = [0x1a, 0x99, 0x00, 0x05, 0x04, 0xac, 0x05, 0xac, 0, 0];

    fn profile(taken: u32, not_taken: u32) -> profile::MethodProfile {
        let mut p = profile::MethodProfile::default();
        p.branches
            .insert(1, profile::BranchCounts { taken, not_taken });
        p
    }

    #[test]
    fn a_rare_arm_is_one_weighted_range_and_a_common_one_none() {
        let floor = ir::MIN_OBSERVATIONS_TO_PRUNE;
        cratonvm_types::flags::with_thread_overrides(&[(KEY, None)], || {
            // Taken a handful of times: floored weight over the arm only.
            assert_eq!(
                splice_cold_arm_ranges(&profile(3, floor), &BODY, 8),
                vec![(6, 8, ir_evidence::COLD_ARM_WEIGHT_FLOOR_PERMILLE)]
            );
            // One in ten: its share.
            assert_eq!(
                splice_cold_arm_ranges(&profile(floor / 10, floor), &BODY, 8),
                vec![(6, 8, u16::try_from(u64::from(floor / 10) * 1000 / u64::from(floor / 10 + floor)).unwrap())]
            );
            // Taken one time in four: not rare.
            assert!(splice_cold_arm_ranges(&profile(floor, 3 * floor), &BODY, 8).is_empty());
            // Under-observed: nothing.
            assert!(splice_cold_arm_ranges(&profile(0, floor - 1), &BODY, 8).is_empty());
        });
        cratonvm_types::flags::with_thread_overrides(&[(KEY, Some("0"))], || {
            assert!(splice_cold_arm_ranges(&profile(3, floor), &BODY, 8).is_empty());
        });
    }

    #[test]
    fn the_cold_arm_weight_rule() {
        let floor = ir::MIN_OBSERVATIONS_TO_PRUNE;
        assert_eq!(cold_arm_weight(0, floor), Some(ir_evidence::COLD_ARM_WEIGHT_FLOOR_PERMILLE));
        assert_eq!(cold_arm_weight(floor, 7 * floor), Some(125));
        assert_eq!(cold_arm_weight(floor + 1, 7 * floor), None);
        assert_eq!(cold_arm_weight(0, floor - 1), None);
    }
}

/// JIT round 23 wave 9 (lane W9-L2, CF-W9-2; `CRATONVM_JIT_IR_PRUNE_RARE_ARM`):
/// a rarely taken arm is pruned like a never-taken one, in a splice and in the
/// compiling method's own code.
#[cfg(test)]
mod r23_w9_rare_arm_prune_tests {
    use super::*;

    const RARE: &str = "CRATONVM_JIT_IR_PRUNE_RARE_ARM";
    const NEVER: &str = "CRATONVM_JIT_IR_SPLICE_NEVER_TAKEN";

    /// `uniApplyStage`'s shape (as in `r23_l1_splice_never_taken_tests`).
    const BODY: [u8; 10] = [0x1a, 0x99, 0x00, 0x05, 0x04, 0xac, 0x05, 0xac, 0, 0];

    fn profile(taken: u32, not_taken: u32) -> profile::MethodProfile {
        let mut p = profile::MethodProfile::default();
        p.branches
            .insert(1, profile::BranchCounts { taken, not_taken });
        p
    }

    #[test]
    fn the_rare_edge_rule() {
        let floor = ir::MIN_OBSERVATIONS_TO_PRUNE;
        let ratio = u32::try_from(RARE_ARM_RATIO).unwrap();
        cratonvm_types::flags::with_thread_overrides(&[(RARE, None)], || {
            assert!(ir_prune_rare_arm_enabled());
            assert!(branch_edge_prunable(0, floor), "never taken: the old rule");
            assert!(!branch_edge_prunable(0, floor - 1), "under the sample floor");
            assert!(branch_edge_prunable(2, 2 * ratio - 2), "two in RATIO");
            assert!(!branch_edge_prunable(2, 2 * ratio - 3), "just over one in RATIO");
            assert!(!branch_edge_prunable(1, floor), "once in ~2000 is not rare");
        });
        cratonvm_types::flags::with_thread_overrides(&[(RARE, Some("0"))], || {
            assert!(branch_edge_prunable(0, floor), "the old rule stays");
            assert!(!branch_edge_prunable(2, 4 * ratio));
        });
    }

    /// The facts-prologue shape: the pending arm taken 3 times in 400 000.
    /// Both switches at their defaults: the row is fed. The rare switch at `0`
    /// keeps the spliced feed with the "never taken" rule only. JIT round 25
    /// review: CF23-2's own switch at `0` kills the spliced feed whatever the
    /// rare switch says (it used to gate nothing while the rare switch was on).
    #[test]
    fn a_rarely_taken_spliced_branch_is_a_prune_row() {
        let rare = profile(3, 400_000);
        cratonvm_types::flags::with_thread_overrides(&[(RARE, None), (NEVER, None)], || {
            assert!(ir_splice_prune_feed_enabled());
            assert_eq!(splice_never_taken_pcs(&rare, &BODY, 8), vec![1]);
            assert!(splice_never_taken_pcs(&profile(3, 10_000), &BODY, 8).is_empty());
        });
        cratonvm_types::flags::with_thread_overrides(&[(RARE, Some("0")), (NEVER, None)], || {
            assert!(ir_splice_prune_feed_enabled(), "the spliced feed is its own switch's");
            assert!(splice_never_taken_pcs(&rare, &BODY, 8).is_empty(), "taken 0 only");
            assert_eq!(splice_never_taken_pcs(&profile(0, 400_000), &BODY, 8), vec![1]);
        });
        for off in ["0", "false"] {
            cratonvm_types::flags::with_thread_overrides(&[(RARE, None), (NEVER, Some(off))], || {
                assert!(!ir_splice_prune_feed_enabled(), "NEVER={off} kills the spliced feed");
                assert!(splice_never_taken_pcs(&rare, &BODY, 8).is_empty());
                assert!(splice_never_taken_pcs(&profile(0, 400_000), &BODY, 8).is_empty());
            });
        }
    }

    /// The compiling method's own never-taken feed takes the rare arm too.
    #[test]
    fn the_own_never_taken_feed_takes_a_rare_arm() {
        let rare = profile(3, 400_000);
        cratonvm_types::flags::with_thread_overrides(&[(RARE, None)], || {
            assert!(ir_never_taken_branches(Some(&rare), &BODY, 8, None, "K.f:(I)I").contains(&1));
        });
        cratonvm_types::flags::with_thread_overrides(&[(RARE, Some("0"))], || {
            assert!(!ir_never_taken_branches(Some(&rare), &BODY, 8, None, "K.f:(I)I").contains(&1));
        });
    }
}

/// JIT round 23 wave 4 (lane L1, CF23-2; `CRATONVM_JIT_IR_SPLICE_NEVER_TAKEN`):
/// the planner half of the in-splice never-taken prune.
#[cfg(test)]
mod r23_l1_splice_never_taken_tests {
    use super::*;

    const KEY: &str = "CRATONVM_JIT_IR_SPLICE_NEVER_TAKEN";

    /// `uniApplyStage`'s shape: `if (x == 0) { pending } else return now;`
    /// as `0 iload_0; 1 ifeq -> 6; 4 iconst_1; 5 ireturn; 6 iconst_2;
    /// 7 ireturn` (padded).
    const BODY: [u8; 10] = [0x1a, 0x99, 0x00, 0x05, 0x04, 0xac, 0x05, 0xac, 0, 0];

    fn profile(taken: u32, not_taken: u32) -> profile::MethodProfile {
        let mut p = profile::MethodProfile::default();
        p.branches
            .insert(1, profile::BranchCounts { taken, not_taken });
        p
    }

    /// Off: nothing. On: a branch never taken over the observation floor is a
    /// row; one taken once, or under-observed, is not.
    #[test]
    fn r23_l1_the_callee_profile_names_its_never_taken_branches_under_the_switch() {
        let floor = ir::MIN_OBSERVATIONS_TO_PRUNE;
        // JIT round 25 review: "off" is this switch at `0` (default ON since
        // then; the rare-arm switch only widens the rule).
        cratonvm_types::flags::with_thread_overrides(
            &[(KEY, Some("0")), ("CRATONVM_JIT_IR_PRUNE_RARE_ARM", None)],
            || {
                assert!(splice_never_taken_pcs(&profile(0, floor), &BODY, 8).is_empty());
            },
        );
        // JIT r23 wave 10 (CF-W10-1): the 2000 floor is pinned here; the low
        // spliced floor has its own test (`r23_w10_splice_low_floor_tests`).
        cratonvm_types::flags::with_thread_overrides(
            &[(KEY, Some("1")), ("CRATONVM_JIT_IR_SPLICE_PRUNE_LOW_FLOOR", Some("0"))],
            || {
                assert_eq!(splice_never_taken_pcs(&profile(0, floor), &BODY, 8), vec![1]);
                assert!(splice_never_taken_pcs(&profile(1, floor), &BODY, 8).is_empty());
                assert!(splice_never_taken_pcs(&profile(0, floor - 1), &BODY, 8).is_empty());
            },
        );
    }

    /// JIT r24 (`CRATONVM_JIT_IR_SPLICE_PRUNE_FROZEN_FLOOR`): a frozen
    /// profile (the callee has a published body) prunes a taken-0 arm at
    /// [`SPLICE_PRUNE_FROZEN_FLOOR`]; a live one keeps the low floor, a taken
    /// arm is never pruned that way, and `=0` restores the low floor.
    #[test]
    fn r24_a_frozen_callee_profile_prunes_at_the_frozen_floor() {
        let frozen = SPLICE_PRUNE_FROZEN_FLOOR;
        assert!(frozen < SPLICE_PRUNE_LOW_FLOOR);
        cratonvm_types::flags::with_thread_overrides(
            &[("CRATONVM_JIT_IR_SPLICE_PRUNE_FROZEN_FLOOR", None)],
            || {
                // The slow run's census: (taken 0, not taken 217).
                assert_eq!(splice_never_taken_pcs_frozen(&profile(0, 217), &BODY, 8, true), vec![1]);
                assert!(splice_never_taken_pcs_frozen(&profile(0, 217), &BODY, 8, false).is_empty());
                assert_eq!(
                    splice_never_taken_pcs_frozen(&profile(0, frozen), &BODY, 8, true),
                    vec![1]
                );
                assert!(
                    splice_never_taken_pcs_frozen(&profile(0, frozen - 1), &BODY, 8, true)
                        .is_empty()
                );
                assert!(splice_never_taken_pcs_frozen(&profile(1, 217), &BODY, 8, true).is_empty());
            },
        );
        cratonvm_types::flags::with_thread_overrides(
            &[("CRATONVM_JIT_IR_SPLICE_PRUNE_FROZEN_FLOOR", Some("0"))],
            || {
                assert!(splice_never_taken_pcs_frozen(&profile(0, 217), &BODY, 8, true).is_empty());
            },
        );
    }

    /// The code only the taken edge reached is the pending arm (6, 7); the
    /// fall-through is live.
    #[test]
    fn r23_l1_the_pruned_edge_leaves_exactly_its_own_arm_dead() {
        assert_eq!(splice_never_taken_dead_pcs(&BODY, 8, &[1]), vec![6, 7]);
        assert!(splice_never_taken_dead_pcs(&BODY, 8, &[]).is_empty());
        // `0 iload_0; 1 ifeq -> 5; 4 nop; 5 iconst_1; 6 ireturn`: the target is
        // the fall-through's own successor, so nothing is dead.
        let join = [0x1a, 0x99, 0x00, 0x04, 0x00, 0x04, 0xac, 0, 0];
        assert!(splice_never_taken_dead_pcs(&join, 7, &[1]).is_empty());
    }

    /// A row is admitted inside its site's range unless its chain id (or the
    /// wildcard) is recorded at the OUTERMOST call site; another id there,
    /// another call site, or the flat `UnstableIf` id leave it standing. A
    /// row in no planned range is dropped.
    #[test]
    fn r23_l1_a_spliced_never_taken_row_is_withdrawn_at_its_call_site() {
        let m = "p/Main.run:()V";
        let callee = "java/util/concurrent/CompletableFuture.uniApplyStage:(Ljava/util/concurrent/Executor;Ljava/util/function/Function;)Ljava/util/concurrent/CompletableFuture;";
        let rows = vec![(110usize, callee.to_string(), 10u32), (400, callee.to_string(), 10)];
        let ranges = [(100usize, 200usize, 24usize)];
        let own = deopt::chain_predicate_speculation_id(callee, 10, deopt::PredicateKind::UnstableIf);
        let admitted = |reg: Option<&deopt::DespecRegistry>| {
            let mut v: Vec<usize> = splice_never_taken_admitted(&rows, &ranges, reg, m)
                .into_iter()
                .collect();
            v.sort_unstable();
            v
        };
        assert_eq!(admitted(None), vec![110], "pc 400 lies in no planned site");
        for (bci, id, kept) in [
            (24u32, own, false),
            (24, deopt::SPECULATION_ID_ANY, false),
            (24, deopt::chain_predicate_speculation_id(callee, 10, deopt::PredicateKind::NullBase), true),
            (25, own, true),
        ] {
            let reg = deopt::DespecRegistry::new();
            reg.insert(m, bci, id);
            assert_eq!(admitted(Some(&reg)).contains(&110), kept, "bci {bci} id {id:#x}");
        }
    }
}

#[cfg(test)]
mod r23w4b_l2_mh_constant_condy_receiver_tests {
    use super::*;

    /// cp 9: `MethodHandle.invokeExact(I)I`.
    fn shape(cp: u16) -> Option<(usize, bool)> {
        (cp == 9).then_some((1, true))
    }

    /// JIT r23 wave 4b, lane L2 (L2W4B-1): the receiver walk names an `ldc` /
    /// `ldc_w` as the receiver's instruction only when asked to, and never a
    /// constant that is not the receiver.
    #[test]
    fn the_receiver_walk_accepts_an_ldc_only_when_asked() {
        // ldc #5 ; iload_1 ; invokevirtual #9
        let ldc = [0x12, 0x05, 0x1b, 0xb6, 0x00, 0x09];
        let none = vec![false; ldc.len()];
        assert_eq!(
            mh_constant_receiver_push(&ldc, ldc.len(), 3, 1, &none, &shape, true),
            Some((0, 5))
        );
        assert_eq!(
            mh_constant_receiver_push(&ldc, ldc.len(), 3, 1, &none, &shape, false),
            None
        );
        assert_eq!(mh_constant_receiver_getstatic(&ldc, ldc.len(), 3, 1, &none, &shape), None);
        // ldc_w #0x0105 ; iload_1 ; invokevirtual #9
        let ldc_w = [0x13, 0x01, 0x05, 0x1b, 0xb6, 0x00, 0x09];
        let none = vec![false; ldc_w.len()];
        assert_eq!(
            mh_constant_receiver_push(&ldc_w, ldc_w.len(), 4, 1, &none, &shape, true),
            Some((0, 0x0105))
        );
        // aload_0 ; ldc #5 ; invokevirtual #9: the ldc is the ARGUMENT.
        let arg = [0x2a, 0x12, 0x05, 0xb6, 0x00, 0x09];
        let none = vec![false; arg.len()];
        assert_eq!(
            mh_constant_receiver_push(&arg, arg.len(), 3, 1, &none, &shape, true),
            None
        );
    }
}

/// JIT round 25 wave 7, lane W7-B (`CRATONVM_JIT_IR_NESTED_CHAIN_SPLICE`,
/// default ON since the wave-10 flip, `=0` kills it; `docs/known-issues/jit/r23-w2-regex-rows-gap-is-per-call-cost-20261021.md`,
/// "Wave 7 (W7-B)"): nested profile-guarded splices of a DISPATCH CHAIN.
///
/// A chain site is a virtual or interface call inside a spliced body whose
/// selector (name and descriptor) is the body's own: `next.match(matcher, i,
/// seq)` inside `Pattern$X.match(matcher, i, seq)`, the shape of every
/// `Pattern$Node` subclass, of filter / interceptor chains and of visitor
/// walks. HotSpot inlines those links from the receiver profile at each site
/// (`FreqInlineSize` once the site has run `InlineFrequencyCount` times, under
/// its inlining depth and size bounds). The IR tier held every link one level
/// down as a call:
///
/// * the nest-exact row of the constant-pool class (`Pattern$Node`, whose own
///   27-byte body never arrives) pre-empted the profiled route;
/// * the profiled body (`GroupHead` 47, `BmpCharPropertyGreedy` 89,
///   `GroupTail` 110 bytes) is over the cold cap and is not a leaf, so the
///   nested hot rule (`ir_nested_hot_body_admitted`) refused it;
/// * the body's own interface calls (`predicate.is`, `seq.charAt`) had no
///   nested route unless `CRATONVM_JIT_IR_NESTED_GUARDED_INTERFACE` was on,
///   so a link spliced without them would trade one call per position for
///   one call per character.
///
/// Under the switch a chain link is admitted by its own rule,
/// [`chain_link_verdict`]: the site is hot (in a loop of the enclosing body,
/// on its entry prefix, or [`CHAIN_HOT_MIN_CALLS`] receiver samples), the
/// body fits the multi-body hot cap, and every call the body makes is either
/// spliced in turn (it has a nested row) or is itself the chain's next link.
/// A spliced link therefore removes one call and keeps only the next-link
/// call it made anyway. The VM's nested resolver
/// (`jit_bridge::resolve_inline_site_from`) and the planner
/// ([`ir_splice_nested_exact_admitted_in`]) ask the same function of the same
/// body and row. The guard, its miss edge (the site's call) and the deopt
/// chain snapshots are the existing nested guarded row's, unchanged.
pub mod r25_w7b_chain_splice {
    use super::*;

    /// The switch's token.
    pub const SWITCH: &str = "CRATONVM_JIT_IR_NESTED_CHAIN_SPLICE";

    /// HotSpot's `InlineFrequencyCount` (100 on x86-64): receiver samples at
    /// which a chain site outside every loop and past the entry prefix of its
    /// enclosing body counts as hot.
    pub const CHAIN_HOT_MIN_CALLS: u32 = 100;

    /// Nested hot-cap slots a compile may register beyond the top-level
    /// guarded hot sites' [`GUARDED_SPLICE_HOT_MAX_SITES`] under the switch:
    /// a regex chain is three to six links over the cold cap, and the
    /// per-compile byte budget (`ir_inline_total_budget`) still bounds them.
    pub const CHAIN_NESTED_HOT_EXTRA_SITES: usize = 8;

    /// `CRATONVM_JIT_IR_NESTED_CHAIN_SPLICE` (default ON since the r25 wave-10 flip, `=0` kills it). Read per call, no
    /// `static`.
    pub fn ir_nested_chain_splice_enabled() -> bool {
        cratonvm_types::flags::runtime_flag_default_on("CRATONVM_JIT_IR_NESTED_CHAIN_SPLICE")
    }

    /// Round rx27 wave 3 (lane chain, W7B-3): `CRATONVM_JIT_IR_CHAIN_BIMORPHIC_LINKS`
    /// (**default ON** since the 2026-10-29 bundle flip, `=0` kills it,
    /// `rx27_chain_entry::bundle_flip_evidence`; inert without the chain switch, the nested guarded row and
    /// the bimorphic guarded splice). Read per call, no `static`.
    ///
    /// `GroupTail.match` pc 70 in `regex-groups` is a 50 / 49 % `next.match`
    /// pair (`LastNode` / `BmpCharProperty`). The nested two-class row that
    /// splices it exists since round 19 (SPLICE19-4), but only under the
    /// global `CRATONVM_JIT_IR_NESTED_BIMORPHIC_SPLICE`, which opens a pair
    /// at every nested virtual site of every compile. Under this switch a
    /// pair is admitted at a chain site only ([`row_is_chain`]): the
    /// resolver's `pair` arm, the planner's strip and append, and the
    /// builder ask [`nested_pair_admitted`] instead of the global switch. The
    /// rows, guards and miss edges are SPLICE19-4's, unchanged.
    pub fn chain_bimorphic_links_enabled() -> bool {
        ir_nested_chain_splice_enabled()
            && ir::ir_nested_guarded_splice_enabled()
            && ir::ir_bimorphic_guarded_splice_enabled()
            // rx27: default ON since the 2026-10-29 bundle flip (`=0` kills).
            && cratonvm_types::flags::runtime_flag_default_on("CRATONVM_JIT_IR_CHAIN_BIMORPHIC_LINKS")
    }

    /// May a nested site hold a two-class row? Everywhere under the global
    /// nested bimorphic switch; at a chain site (`chain_site`) also under
    /// [`chain_bimorphic_links_enabled`].
    pub fn nested_pair_admitted(chain_site: bool) -> bool {
        ir::ir_nested_bimorphic_splice_enabled()
            || (chain_site && chain_bimorphic_links_enabled())
    }

    /// The builder's form: the planner already dropped every pair that
    /// [`nested_pair_admitted`] refuses, so a registered nested pair is
    /// admitted under either switch.
    pub fn nested_pair_switch_on() -> bool {
        ir::ir_nested_bimorphic_splice_enabled()
            || chain_bimorphic_links_enabled()
            || chain_bimorphic_predicates_enabled()
    }

    /// Round rx27 wave 4 (lane chain): `CRATONVM_JIT_IR_CHAIN_BIMORPHIC_PREDICATES`
    /// (**default ON** since the 2026-10-29 bundle flip, `=0` kills it,
    /// `rx27_chain_entry::bundle_flip_evidence`; inert without the chain switch, the nested guarded row and the
    /// bimorphic guarded splice). Read per call, no `static`.
    ///
    /// A greedy node's `predicate.is` is one bytecode site shared by every
    /// instance of the class, so `[a-z]+\d*` (`regex-matches`) or
    /// `[\w.+-]+@[\w-]+\.[a-z]{2,}` (`regex-find-email`) read two predicate
    /// lambda classes there. One class takes the profiled interface row
    /// (W7-B); the other stays an inline-cache call into the lambda's own
    /// compiled body, paid per character with its argument moves and frame.
    /// Under this switch an INTERFACE site of a chain body may hold the
    /// SPLICE19-4 two-class row too, as [`chain_bimorphic_links_enabled`]
    /// lets a chain site hold one.
    pub fn chain_bimorphic_predicates_enabled() -> bool {
        ir_nested_chain_splice_enabled()
            && ir::ir_nested_guarded_splice_enabled()
            && ir::ir_bimorphic_guarded_splice_enabled()
            // rx27: default ON since the 2026-10-29 bundle flip (`=0` kills).
            && cratonvm_types::flags::runtime_flag_default_on(
                "CRATONVM_JIT_IR_CHAIN_BIMORPHIC_PREDICATES",
            )
    }

    /// The VM resolver's form: an interface call (`invoke_kind` 2) inside a
    /// chain body (`chain_body`) under [`chain_bimorphic_predicates_enabled`].
    pub fn chain_predicate_pair_site(chain_body: bool, invoke_kind: u8) -> bool {
        chain_body && invoke_kind == 2 && chain_bimorphic_predicates_enabled()
    }

    /// The planner's form of the pair admission for nested row `n` of
    /// `parent`: [`nested_pair_admitted`] at a chain site, or an interface
    /// site of a chain body ([`chain_predicate_pair_site`]).
    pub fn nested_pair_admitted_row(parent: &InlineSite, n: &NestedInlineSite) -> bool {
        nested_pair_admitted(row_is_chain(parent, n))
            || chain_predicate_pair_site(
                body_is_chain_shaped(parent),
                parent
                    .invoke_targets
                    .iter()
                    .find(|(pc, _)| *pc == n.callee_pc)
                    .map_or(0, |(_, t)| t.invoke_kind),
            )
    }

    /// Is a call of kind `invoke_kind` (`jit_invoke_dispatch`'s encoding) to
    /// `call_name` `call_desc` inside a body `body_name` `body_desc` a chain
    /// site: a virtual or interface call of the body's own selector?
    pub fn is_chain_call(
        invoke_kind: u8,
        call_name: &str,
        call_desc: &str,
        body_name: &str,
        body_desc: &str,
    ) -> bool {
        matches!(invoke_kind, 0 | 2) && call_name == body_name && call_desc == body_desc
    }

    /// W7-B fix (round 2): [`is_chain_call`] for a call row, and never a call
    /// whose constant-pool class is `java/lang/Object`. `AbstractSet.hashCode`
    /// -> `e.hashCode()`, `AbstractList.equals` -> `o1.equals(o2)` and every
    /// `toString` delegation have the body's own selector but are no dispatch
    /// chain: the receiver is an element, not the next link of the body's own
    /// class family. The VM resolver also asks that the enclosing body's class
    /// is a subclass of the call's constant-pool class
    /// (`jit_bridge::resolve_inline_site_from`, `Pattern$GroupHead` of
    /// `Pattern$Node`), which only it can answer.
    pub fn is_chain_target(t: &InlineInvokeTarget, body_name: &str, body_desc: &str) -> bool {
        t.class_name != "java/lang/Object"
            && is_chain_call(
                t.invoke_kind,
                &t.method_name,
                &t.descriptor,
                body_name,
                body_desc,
            )
    }

    /// Does `site` hold a chain site (it calls its own selector virtually)?
    pub fn body_is_chain_shaped(site: &InlineSite) -> bool {
        site.invoke_targets
            .iter()
            .any(|(_, t)| is_chain_target(t, &site.method_name, &site.descriptor))
    }

    /// Why [`chain_link_verdict`] refused a body.
    #[derive(Clone, Copy, Debug, PartialEq, Eq)]
    pub enum ChainRefusal {
        /// The switch, or a switch the nested guarded row needs, is off.
        SwitchedOff,
        /// A static body (a chain link is always an instance method).
        Static,
        /// Over the multi-body hot cap; the cap is carried.
        OverCap(usize),
        /// Not in a loop, not on the entry prefix, under the sample floor.
        ColdSite,
        /// The body keeps a call at this pc that is neither spliced nor the
        /// chain's next link.
        KeptCall(usize),
        /// W7-B fix 2: the site runs on fewer than
        /// [`CHAIN_MIN_FREQUENCY_PERMILLE`] of the enclosing body's entries
        /// (the per-mille share is carried).
        RareSite(u32),
        /// Round rx27 wave 4 (`CRATONVM_JIT_IR_CHAIN_DEEP_SPINE`): the body's
        /// row at this pc, in a loop of the body, is spliced but keeps a call
        /// in its own tree ([`crate::rx27_deep_spine::first_half_spliced_row`]).
        HalfSpliced(usize),
    }

    impl std::fmt::Display for ChainRefusal {
        fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
            match self {
                Self::SwitchedOff => write!(f, "switched off"),
                Self::Static => write!(f, "static body"),
                Self::OverCap(cap) => write!(f, "over the chain cap {cap}"),
                Self::ColdSite => write!(
                    f,
                    "cold site (not in a loop, not on the entry prefix, under {CHAIN_HOT_MIN_CALLS} samples)"
                ),
                Self::KeptCall(pc) => write!(
                    f,
                    "keeps a call at body pc {pc} that is neither spliced nor the next link"
                ),
                Self::RareSite(permille) => write!(
                    f,
                    "rare site ({permille} per mille of the body's entries, under \
                     {CHAIN_MIN_FREQUENCY_PERMILLE})"
                ),
                Self::HalfSpliced(pc) => write!(
                    f,
                    "half-spliced row at body pc {pc} (in a loop of the body, it keeps a call \
                     in its own tree; deep spine)"
                ),
            }
        }
    }

    /// Is the chain site at `callee_pc` of the enclosing body
    /// `code[..code_len]` (its receiver row `row`) hot: in a loop there (the
    /// top-level rule's `InLoop`), on the body's entry prefix (it runs on every
    /// execution of the link that holds it), or [`CHAIN_HOT_MIN_CALLS`]
    /// receiver samples?
    pub fn chain_site_is_hot(
        row: Option<&profile::ReceiverCounts>,
        code: &[u8],
        code_len: usize,
        callee_pc: usize,
    ) -> bool {
        ir_nested_row_samples(row) >= CHAIN_HOT_MIN_CALLS
            || ir_splice_pc_in_entry_prefix(code, code_len, callee_pc)
            || bytecode_pc_in_loop(code, code_len, callee_pc)
    }

    /// The first call of `site` that would stay a call and is not the
    /// chain's next link, if any. A pc with a nested row counts as spliced.
    pub fn first_kept_non_link_call(site: &InlineSite) -> Option<usize> {
        site.invoke_targets
            .iter()
            .find(|(pc, t)| {
                !site.nested_sites.iter().any(|n| n.callee_pc == *pc)
                    && !is_chain_target(t, &site.method_name, &site.descriptor)
                    // W10-3b: a call the inline String prefix answers
                    // (`CharSequence.charAt` on a String) is no real call.
                    && !(crate::r25_w10_3b::prefix_kept_enabled()
                        && crate::r25_w10_3b::site_answered_by_string_prefix(
                            &t.class_name,
                            &t.method_name,
                            &t.descriptor,
                            t.invoke_kind,
                        ))
            })
            .map(|(pc, _)| *pc)
    }

    /// The chain admission of the body `site`, resolved for one of `bodies`
    /// classes at the chain site `callee_pc` of the enclosing body
    /// `code[..code_len]` whose receiver row there is `row`. The caller has
    /// established that the site is a chain site ([`is_chain_call`]).
    pub fn chain_link_verdict(
        row: Option<&profile::ReceiverCounts>,
        code: &[u8],
        code_len: usize,
        callee_pc: usize,
        site: &InlineSite,
        bodies: usize,
    ) -> Result<(), ChainRefusal> {
        if !ir_nested_chain_splice_enabled()
            || !ir::ir_nested_guarded_splice_enabled()
            || !ir::ir_guarded_splice_hot_cap_enabled()
        {
            return Err(ChainRefusal::SwitchedOff);
        }
        if site.callee_is_static {
            return Err(ChainRefusal::Static);
        }
        let cap = ir_guarded_multi_body_cap(ir::GUARDED_SPLICE_HOT_MAX_BODY_BYTES, bodies.max(1));
        if site.callee_code_len > cap {
            return Err(ChainRefusal::OverCap(cap));
        }
        if !chain_site_is_hot(row, code, code_len, callee_pc) {
            return Err(ChainRefusal::ColdSite);
        }
        if let Some(pc) = first_kept_non_link_call(site) {
            return Err(ChainRefusal::KeptCall(pc));
        }
        // Round rx27 wave 4: the transitive half of the cost rule.
        if crate::rx27_deep_spine::enabled() {
            if let Some(pc) = crate::rx27_deep_spine::first_half_spliced_row(site) {
                return Err(ChainRefusal::HalfSpliced(pc));
            }
        }
        Ok(())
    }

    /// W7-B fix 2: C2's `InlineFrequencyRatio` (0.25), as per mille. A chain
    /// link whose site runs on fewer of its enclosing body's entries than this
    /// is not frequent, and HotSpot inlines such a site only up to
    /// `MaxInlineSize` (the cold cap here), which every chain body is over.
    pub const CHAIN_MIN_FREQUENCY_PERMILLE: u32 = 250;

    /// W7-B fix 2: the frequency half of the chain rule, asked by the VM
    /// resolver, which holds both counts. `samples` are the receiver samples
    /// at the chain site in the enclosing body's own profile and
    /// `invocations` that body's invocation count, the same interpreted
    /// window. `invocations == 0` is no evidence: the structural rule
    /// ([`chain_link_verdict`]) decides alone.
    ///
    /// The structural rule took any site in a loop or on a loop-rooted chain.
    /// That kept links that run on a few per cent of their parent's entries --
    /// the `\s*` after `,` in `,\s*` (one position in twenty), a group's
    /// tail after `=` -- whose bodies then sit in the frame of a body entered
    /// on every text position: its fresh-frame clear grows with every spliced
    /// level, and the link almost never runs.
    pub fn chain_frequency_verdict(samples: u32, invocations: u32) -> Result<(), ChainRefusal> {
        if invocations == 0 {
            return Ok(());
        }
        let permille = chain_frequency_permille(samples, invocations);
        if permille < CHAIN_MIN_FREQUENCY_PERMILLE {
            return Err(ChainRefusal::RareSite(permille));
        }
        Ok(())
    }

    /// `samples` per thousand `invocations`, saturating (0 with no
    /// invocations).
    pub fn chain_frequency_permille(samples: u32, invocations: u32) -> u32 {
        if invocations == 0 {
            return 0;
        }
        u32::try_from(u64::from(samples) * 1000 / u64::from(invocations)).unwrap_or(u32::MAX)
    }

    /// [`chain_link_verdict`] as a yes / no.
    pub fn ir_nested_chain_link_admitted(
        row: Option<&profile::ReceiverCounts>,
        code: &[u8],
        code_len: usize,
        callee_pc: usize,
        site: &InlineSite,
        bodies: usize,
    ) -> bool {
        chain_link_verdict(row, code, code_len, callee_pc, site, bodies).is_ok()
    }

    /// The planner's form: is nested row `n` of `parent` a chain link the
    /// chain rule admits? Asks that the call at `n.callee_pc` in `parent` is
    /// a chain site, and reads the receiver row the VM carried there.
    pub(crate) fn chain_row_admitted_in(
        parent: &InlineSite,
        n: &NestedInlineSite,
        bodies: usize,
    ) -> bool {
        if !ir_nested_chain_splice_enabled()
            || !(row_is_chain(parent, n) || super::rx27_chain_entry::entry_row(parent, n))
        {
            return false;
        }
        let row = parent
            .callee_receiver_profile
            .iter()
            .find(|(pc, _)| *pc == n.callee_pc)
            .map(|(_, counts)| counts);
        ir_nested_chain_link_admitted(
            row,
            &parent.callee_code,
            parent.callee_code_len,
            n.callee_pc,
            &n.site,
            bodies,
        )
    }

    /// The strip's re-check ([`ir_splice_strip_unadmitted_exact_nested`]):
    /// after the rows under `n` were stripped, does `n` -- admitted before --
    /// still pass? Only the chain rule depends on a body's own rows (a
    /// stripped row can only turn a body INTO a leaf), so this asks nothing
    /// with the switch off.
    pub(crate) fn withdrawn_after_strip(
        parent: &InlineSite,
        n: &NestedInlineSite,
        chain_fences: bool,
    ) -> bool {
        ir_nested_chain_splice_enabled()
            && n.guard_class_id != 0
            && !ir_splice_nested_exact_admitted_in(Some(parent), n, chain_fences)
    }

    /// The nested hot-cap pcs of one compile ([`ir_nested_hot_cap_pcs`]):
    /// `body(key)` is the row's body length and whether it is a chain link the
    /// cost rule kept. W7-B fix (round 2): only those links take the
    /// [`CHAIN_NESTED_HOT_EXTRA_SITES`] slots; every other nested row keeps the
    /// `base_slots` (what the top-level hot sites left of
    /// [`GUARDED_SPLICE_HOT_MAX_SITES`]) it had before the switch. Round 1
    /// added the slots to every row, so non-chain bodies of 36-325 bytes the
    /// slots had held to the cold cap (`Pattern.compile`'s helpers on the rows
    /// that compile a pattern per op) were spliced too. Switch off: exactly
    /// [`ir_nested_hot_cap_pcs`].
    pub(crate) fn nested_hot_cap_pcs(
        rows: &[(usize, u32)],
        body: impl Fn(usize) -> Option<(usize, bool)>,
        base_slots: usize,
    ) -> Vec<usize> {
        let len = |key: usize| body(key).map(|(len, _)| len);
        if !ir_nested_chain_splice_enabled() {
            return ir_nested_hot_cap_pcs(rows, len, base_slots);
        }
        let (links, plain): (Vec<(usize, u32)>, Vec<(usize, u32)>) = rows
            .iter()
            .copied()
            .partition(|&(key, _)| body(key).is_some_and(|(_, link)| link));
        let mut out = ir_nested_hot_cap_pcs(&plain, len, base_slots);
        for pc in ir_nested_hot_cap_pcs(&links, len, CHAIN_NESTED_HOT_EXTRA_SITES) {
            if !out.contains(&pc) {
                out.push(pc);
            }
        }
        out
    }

    /// Is nested row `n` of `parent` at a chain site of `parent` (the call
    /// at `n.callee_pc` is [`is_chain_target`] of `parent`'s selector)?
    pub fn row_is_chain(parent: &InlineSite, n: &NestedInlineSite) -> bool {
        parent.invoke_targets.iter().any(|(pc, t)| {
            *pc == n.callee_pc && is_chain_target(t, &parent.method_name, &parent.descriptor)
        })
    }

    /// W7-B fix (round 2): the link bytecode one top-level splice tree may
    /// add, HotSpot's `FreqInlineSize` (a quarter of the compile's default
    /// splice budget, [`IR_INLINE_MAX_TOTAL_BYTES`]). Counted per link as its
    /// body plus every non-link body under it (`predicate.is`, `charAt`),
    /// in tree order, so the links nearest the loop that roots the chain are
    /// the ones kept.
    pub const CHAIN_TREE_MAX_BYTES: usize = MAX_INLINE_BYTECODE_SIZE;

    /// Round rx27 (lane chain, W7B-2): the tree cap this compile uses,
    /// `CRATONVM_JIT_IR_CHAIN_TREE_MAX_BYTES` (a byte count, clamped to
    /// `0..=`[`IR_INLINE_MAX_TOTAL_BYTES`]), else [`CHAIN_TREE_MAX_BYTES`].
    /// Read per call, no `static`. `FreqInlineSize` is HotSpot's bound for ONE
    /// callee, not for a tree (C2 bounds a tree by `MaxInlineLevel` 15 and
    /// `DesiredMethodLimit`), so the default cap is stricter than HotSpot
    /// where a chain is long: `regex-groups`' `(\w+)=(\w+)` keeps the first
    /// group's links (about 320 bytes) and the second group's stay calls.
    /// A knob for the A/B only; the W8-5 frame rule still prices every link.
    pub fn chain_tree_max_bytes() -> usize {
        cratonvm_types::flags::runtime_var("CRATONVM_JIT_IR_CHAIN_TREE_MAX_BYTES")
            .ok()
            .and_then(|v| v.trim().parse::<usize>().ok())
            .map_or(CHAIN_TREE_MAX_BYTES, |n| n.min(IR_INLINE_MAX_TOTAL_BYTES))
    }

    /// What [`strip_chain_tree`] did to one top-level splice tree: the census
    /// fields of the planner's `ir-chain-tree` line.
    #[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
    pub struct ChainTreeReport {
        /// Chain rows kept (a bimorphic pair counts two).
        pub kept: usize,
        /// Dropped: no loop roots the chain above the row.
        pub unrooted: usize,
        /// Dropped: over [`CHAIN_TREE_MAX_BYTES`].
        pub capped: usize,
        /// Link bytes kept (see [`CHAIN_TREE_MAX_BYTES`]).
        pub bytes: usize,
        /// The `max_locals` those kept bodies add to the compile's frame.
        pub added_locals: usize,
        /// The deepest kept link, in splice levels below the top-level body.
        pub max_depth: usize,
        /// W8-5: dropped by the frame-growth cost rule ([`link_pays_for_its_frame`]).
        pub costly: usize,
        /// W8-5: the estimated frame bytes of the top-level body and its
        /// non-link rows ([`est_frame_bytes`]), before the chain links.
        pub est_frame_before: usize,
        /// W8-5: the same with the kept links' estimated frame bytes added.
        pub est_frame_after: usize,
        /// W8-5: the least entries per thousand top-level-body entries of
        /// any kept link (`None`: no link kept).
        pub min_entry_permille: Option<u64>,
    }

    /// W8-5: what one compiled-to-compiled call costs beyond its callee's
    /// fresh-frame clear, in executed instructions: the frame record, the
    /// shadow watermark save and restore, the entry poll, the inline-cache
    /// cascade and the argument stores (wave 8b: 4.3-4.6 ns a call against
    /// HotSpot's 2.07 on `NodeCall poly`, about 40 instructions).
    pub const CHAIN_CALL_INSTRS: u64 = 40;

    /// W8-5: frame bytes one fresh-frame clear instruction zeroes (one
    /// 32-byte vector store).
    pub const CLEAR_BYTES_PER_INSTR: u64 = 32;

    /// W8-5: the estimated IR frame bytes of a spliced body of `bytecode`
    /// bytes and `locals` locals: 8 bytes a local and 8 a bytecode byte (the
    /// homes of its values). Calibrated on `BmpCharPropertyGreedy.match`, 89
    /// bytes, whose own optimizing frame is 912 bytes (wave 12).
    pub fn est_frame_bytes(bytecode: usize, locals: usize) -> usize {
        (bytecode + locals) * 8
    }

    /// W8-5: how often the call at `callee_pc` of `parent` runs per thousand
    /// entries of `parent`: its receiver samples over `parent`'s invocation
    /// count, from the same interpreted window. `None` without an
    /// invocation count (no evidence).
    pub fn site_entry_permille(parent: &InlineSite, callee_pc: usize) -> Option<u64> {
        if parent.callee_invocations == 0 {
            return None;
        }
        let samples = ir_nested_row_samples(
            parent
                .callee_receiver_profile
                .iter()
                .find(|(pc, _)| *pc == callee_pc)
                .map(|(_, counts)| counts),
        );
        Some(u64::from(samples) * 1000 / u64::from(parent.callee_invocations))
    }

    /// W8-5, the frame-growth cost rule. A link that runs `entry_permille`
    /// times per thousand entries of the top-level body saves that many calls
    /// into its own artifact, each a call ([`CHAIN_CALL_INSTRS`]) plus that
    /// artifact's fresh-frame clear. Spliced, its frame (`frame_bytes`,
    /// [`est_frame_bytes`]) joins the compile root's, whose clear runs on
    /// every entry whether the link runs or not. The link pays when
    /// `entry x (call + clear(frame)) >= 1000 x clear(frame)`, in instructions
    /// per thousand entries; for a 760-byte link that is an entry share of
    /// about 0.37.
    pub fn link_pays_for_its_frame(entry_permille: u64, frame_bytes: usize) -> bool {
        let clear = (frame_bytes as u64).div_ceil(CLEAR_BYTES_PER_INSTR);
        entry_permille.saturating_mul(CHAIN_CALL_INSTRS + clear) >= 1000 * clear
    }

    /// A link's own cost: its body plus every body under it that is not
    /// itself a chain row (those are judged as links of their own), as
    /// (bytecode bytes, `max_locals`).
    fn link_cost(site: &InlineSite) -> (usize, usize) {
        let mut bytes = site.callee_code_len;
        let mut locals = site.callee_max_locals;
        for n in &site.nested_sites {
            if n.guard_class_id != 0 && row_is_chain(site, n) {
                continue;
            }
            let (b, l) = link_cost(&n.site);
            bytes += b;
            locals += l;
            if let Some(second) = &n.bimorphic_second {
                let (b, l) = link_cost(&second.site);
                bytes += b;
                locals += l;
            }
        }
        (bytes, locals)
    }

    /// W7-B fix (round 2): the planner's cost rule over one top-level splice
    /// tree, run after the admission strips. A chain row is kept only when
    ///
    /// * a loop ROOTS its chain: the row's site is in a loop of its enclosing
    ///   body, or the enclosing body is itself a kept chain row (or the
    ///   top-level body, when `top_rooted`: its top-level site is in a loop of
    ///   the compiling method). That is the chain running per iteration of a
    ///   loop, which is where splicing a link removes calls per root entry
    ///   (`Start.match`'s position loop, `Branch.match`'s alternatives, the
    ///   back-off loop of a greedy node). A chain entered once per root entry
    ///   (`Node.study` under `Pattern.compile`, every `split` row compiles its
    ///   pattern per op) only grew the root's frame and took splice budget;
    /// * the tree's kept link bytes stay within [`CHAIN_TREE_MAX_BYTES`].
    ///
    /// Dropping a row keeps the call at its pc, as every strip does, and never
    /// withdraws an admitted parent: the link rule lets a link keep its
    /// next-link call. A no-op with the switch off.
    ///
    /// `keys` receives the method key (`Class.name:desc`, the site table's
    /// `method_key`) of every kept link body, for [`nested_hot_cap_pcs`].
    pub(crate) fn strip_chain_tree(
        site: &mut InlineSite,
        top_rooted: bool,
        keys: &mut Vec<String>,
    ) -> ChainTreeReport {
        let mut report = ChainTreeReport::default();
        if ir_nested_chain_splice_enabled() {
            let (bytes, locals) = link_cost(site);
            report.est_frame_before = est_frame_bytes(bytes, locals);
            strip_chain_rows(site, top_rooted, top_rooted, 1, 1000, &mut report, keys);
            report.est_frame_after =
                report.est_frame_before + est_frame_bytes(report.bytes, report.added_locals);
        }
        report
    }

    /// Would `n` (and its second body) be admitted under `parent` by the
    /// plain nested rules of [`ir_splice_nested_exact_admitted_in`], without
    /// the chain rule? Its size admissions only: the switches and chain fences
    /// that rule also asks are the same for both.
    fn plain_row_admitted(parent: &InlineSite, n: &NestedInlineSite) -> bool {
        let fits = |site: &InlineSite, bodies: usize| {
            site.callee_code_len
                <= ir_splice_nested_exact_size_cap(
                    &parent.callee_code,
                    parent.callee_code_len,
                    n.callee_pc,
                    site.callee_num_args,
                )
                || ir_nested_hot_body_admitted(
                    site,
                    ir_nested_row_hot_cap(parent, n.callee_pc, bodies),
                )
                || ir_psplice_nested_exact_row_admitted(
                    site,
                    parent
                        .callee_receiver_profile
                        .iter()
                        .find(|(pc, _)| *pc == n.callee_pc)
                        .map(|(_, counts)| counts),
                    &parent.callee_code,
                    parent.callee_code_len,
                    n.callee_pc,
                    site.callee_num_args,
                )
        };
        let bodies = 1 + usize::from(n.bimorphic_second.is_some());
        fits(&n.site, bodies) && n.bimorphic_second.as_ref().is_none_or(|s| fits(&s.site, 2))
    }

    fn method_key(site: &InlineSite) -> String {
        format!(
            "{}.{}:{}",
            site.class_name, site.method_name, site.descriptor
        )
    }

    fn strip_chain_rows(
        parent: &mut InlineSite,
        parent_rooted: bool,
        // Round rx27 wave 4: some site above `parent` (or the top-level site)
        // is in a loop of its enclosing body; roots a chain ENTRY row
        // (`rx27_chain_entry`). Chain rows keep `parent_rooted`.
        ancestor_loop: bool,
        depth: usize,
        parent_entries: u64,
        report: &mut ChainTreeReport,
        keys: &mut Vec<String>,
    ) {
        let nested = std::mem::take(&mut parent.nested_sites);
        let mut kept = Vec::with_capacity(nested.len());
        for mut n in nested {
            let pair = 1 + usize::from(n.bimorphic_second.is_some());
            // W7-B fix 2: only a row the chain rule alone admits is judged; a
            // same-selector row the plain nested rules admit (a leaf, a cold
            // body) is the row it was with the switch off.
            let site_in_loop =
                bytecode_pc_in_loop(&parent.callee_code, parent.callee_code_len, n.callee_pc);
            // Round rx27 wave 4 (`CRATONVM_JIT_IR_CHAIN_ENTRY_SPLICE`): a chain
            // body entered from a non-chain body (`matchRoot.match` inside
            // `Matcher.match`) is judged as a link, rooted by any loop above.
            let entry = super::rx27_chain_entry::entry_row(parent, &n);
            if n.guard_class_id == 0
                || !(row_is_chain(parent, &n) || entry)
                || plain_row_admitted(parent, &n)
            {
                // Its entries, for the links under it.
                let entries = site_entry_permille(parent, n.callee_pc)
                    .map_or(parent_entries, |f| parent_entries.saturating_mul(f) / 1000);
                let below = ancestor_loop || site_in_loop;
                strip_chain_rows(&mut n.site, false, below, depth + 1, entries, report, keys);
                if let Some(second) = n.bimorphic_second.as_mut() {
                    let s2 = &mut second.site;
                    strip_chain_rows(s2, false, below, depth + 1, entries, report, keys);
                }
                kept.push(n);
                continue;
            }
            let rooted = parent_rooted || site_in_loop || (entry && ancestor_loop);
            if !rooted {
                report.unrooted += pair;
                continue;
            }
            let (mut bytes, mut locals) = link_cost(&n.site);
            if let Some(second) = &n.bimorphic_second {
                let (b, l) = link_cost(&second.site);
                bytes += b;
                locals += l;
            }
            if report.bytes + bytes > chain_tree_max_bytes() {
                report.capped += pair;
                continue;
            }
            // W8-5: the link's entries per thousand top-level-body entries,
            // and whether they pay for the frame it adds to the root.
            let entries = site_entry_permille(parent, n.callee_pc)
                .map_or(parent_entries, |f| parent_entries.saturating_mul(f) / 1000);
            if !link_pays_for_its_frame(entries, est_frame_bytes(bytes, locals)) {
                report.costly += pair;
                continue;
            }
            report.min_entry_permille = Some(
                report
                    .min_entry_permille
                    .map_or(entries, |m| m.min(entries)),
            );
            report.bytes += bytes;
            report.added_locals += locals;
            report.kept += pair;
            report.max_depth = report.max_depth.max(depth);
            keys.push(method_key(&n.site));
            if let Some(second) = &n.bimorphic_second {
                keys.push(method_key(&second.site));
            }
            strip_chain_rows(&mut n.site, true, true, depth + 1, entries, report, keys);
            if let Some(second) = n.bimorphic_second.as_mut() {
                strip_chain_rows(&mut second.site, true, true, depth + 1, entries, report, keys);
            }
            kept.push(n);
        }
        parent.nested_sites = kept;
    }

    /// JIT r25 wave 9 (W9-3): the chain links one compile kept, summed over
    /// its top-level trees, for the `chain-compile` line printed with the
    /// compile's outcome. It answers, in one host run, the three suspects
    /// left after W8-5 for the rows the switch still loses (`split-ws`,
    /// `cached`, `matchonly`, `regex-split`):
    ///
    /// 1. **The acceptance gate.** A compile whose spliced chain left calls
    ///    the lowerer had to route through the blind dispatch helper is
    ///    priced as a regression (`CompileRecord::added_ns_per_execution`:
    ///    171 ns a blind dispatch against 4 ns a spliced frame) and its
    ///    optimizing body is DISCARDED: the root then runs its single-pass
    ///    body, and every splice of the round with it. `verdict=` and
    ///    `blind_in_splice=` / `added_ns=` name it.
    /// 2. **The real frame.** `real_frame=` is the lowered body's frame
    ///    (`CompiledMethod::osr_frame_size`, the `SUB RSP` size) beside
    ///    `est_frame_added=`, the cost rule's estimate of the links' share. A
    ///    real frame far above the estimate means W8-5 priced the wrong
    ///    frame.
    /// 3. **Field proofs.** Not on this line: the same compile's
    ///    `[cratonvm-jitc] ir proven-receiver-fields: loads full= ...
    ///    method=` line (`CRATONVM_JIT_IR_PROVEN_RECEIVER_FIELDS`), whose
    ///    `full=` count for the root against the link's own artifact says
    ///    whether the spliced link lost the proofs its own body made.
    #[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
    pub struct ChainCompileCensus {
        /// Top-level trees that kept at least one link.
        pub trees: usize,
        /// Links kept, over every tree.
        pub links: usize,
        /// Links the frame-growth rule dropped.
        pub costly: usize,
        /// The kept links' estimated frame bytes ([`est_frame_bytes`]).
        pub est_frame_added: usize,
        /// The least entries per thousand top-level entries of a kept link.
        pub min_entry_permille: Option<u64>,
    }

    impl ChainCompileCensus {
        /// Fold one tree's report in.
        pub fn note(&mut self, r: &ChainTreeReport) {
            if r.kept > 0 {
                self.trees += 1;
            }
            self.links += r.kept;
            self.costly += r.costly;
            self.est_frame_added += r.est_frame_after.saturating_sub(r.est_frame_before);
            if let Some(m) = r.min_entry_permille {
                self.min_entry_permille = Some(self.min_entry_permille.map_or(m, |o| o.min(m)));
            }
        }

        /// The `chain-compile` line for compile `method`: whether it lowered
        /// and whether the acceptance gate kept it, its real frame bytes and
        /// the gate's inputs.
        pub fn line(
            &self,
            method: &str,
            lowered: bool,
            accepted: bool,
            real_frame: Option<i32>,
            rec: Option<ir_evidence::CompileRecord>,
        ) -> String {
            let verdict = if !lowered {
                "NOT-LOWERED (single-pass body runs)"
            } else if accepted {
                "accepted"
            } else {
                "REFUSED by the acceptance gate (single-pass body runs)"
            };
            let gate = match rec {
                Some(rec) => format!(
                    "spliced_frames={} blind_in_splice={} added_ns={}",
                    rec.spliced_frames,
                    rec.blind_dispatches_in_splice,
                    rec.added_ns_per_execution()
                ),
                None => "evidence=unjudged".to_string(),
            };
            format!(
                "[cratonvm-jitc] chain-compile {method}: trees={} links={} costly={} \
                 min_entry_permille={} est_frame_added={} real_frame={} verdict={verdict} {gate}",
                self.trees,
                self.links,
                self.costly,
                self.min_entry_permille
                    .map_or("-".to_string(), |m| m.to_string()),
                self.est_frame_added,
                real_frame.map_or("-".to_string(), |f| f.to_string()),
            )
        }
    }

    /// JIT r25 wave 10 (W10-3): `CRATONVM_JIT_IR_NESTED_CHAIN_DEPTH`,
    /// **default ON under the chain switch** (`=0` kill; inert with
    /// [`ir_nested_chain_splice_enabled`] off). Read per call, no `static`.
    ///
    /// The c22 disassembly of `Matcher.search` on `split-ws` (`=1`) shows the
    /// cost the chain splices added. The links take nest levels from their
    /// own callees. The chain `search` -> `Start` (0) -> `Greedy` (1) ->
    /// `CharPredicate.is` forwarder (2) -> `lambda$ASCII_SPACE$0` (3) ->
    /// `ASCII.isSpace` (4) -> `ASCII.isType` (5) reaches the cap at
    /// `ASCII.getType` (6). It is refused there (`nest-static ...getType ...
    /// depth=6 -> refused`): a 17-byte body, over the leaf tier's 16. So every
    /// character the `\s+` scan reads makes a real compiled call into
    /// `getType`. That call costs 15 frame-block home clears, the
    /// frame-record and stack checks, the call itself, the callee's prologue
    /// and frame clear and the post-call thread stores: about 70 instructions.
    /// `Greedy`'s own artifact had spliced it (depth 4). Over the 96-character
    /// `split-ws` text that is ~115 such calls, about 8 000 instructions per
    /// op, the whole c12 loss (64 912 against 56 862).
    ///
    /// Two changes give the links' callees their levels back:
    ///
    /// * the unset `CRATONVM_JIT_IR_INLINE_MAX_NEST` becomes the deepest
    ///   nesting the builder opens ([`ir_inline_max_nest_frame_cap`]: 7
    ///   with the leaf tier, 8 frames), rather than 6. HotSpot's
    ///   `MaxInlineLevel` is 15, so depth is not a limit for it on these chains;
    /// * the leaf tier past the cap admits a call-free static body of up to
    ///   [`CHAIN_LEAF_MAX_BYTES`] (`getType`, 17 bytes, with its `ctype` read
    ///   and branch), as [`chain_leaf_splice_body`] judges.
    ///
    /// The splice-depth bound stays the builder's (`ir::MAX_IR_SPLICE_DEPTH`).
    /// The byte budget and every admission are unchanged.
    pub fn ir_nested_chain_depth_enabled() -> bool {
        // JIT r25 wave 10 (W10-4): or under the lambda-body interface rows,
        // whose `ASCII_WORD` predicate chain ends at the same `getType`.
        (ir_nested_chain_splice_enabled()
            || crate::r25_w10_4_lambda_iface::ir_nested_lambda_iface_enabled())
            && cratonvm_types::flags::runtime_flag_default_on("CRATONVM_JIT_IR_NESTED_CHAIN_DEPTH")
    }

    /// `CRATONVM_JIT_IR_NESTED_CHAIN_DEPTH_SCOPED` (r25 W11-7 review fix;
    /// default ON, `=0` restores the global raise). Read per call, no `static`.
    ///
    /// W10-3 raised the unset nest depth and the leaf tier for every optimizing
    /// compile, while its reason (the regex `\s+` chain reaching
    /// `ASCII.getType` at depth 6) is a dispatch chain's. Measured on 64.177
    /// against `CRATONVM_JIT_IR_NESTED_CHAIN_DEPTH=0` (compile-worker CPU, 3-5
    /// interleaved reps): javac compiling three probe sources 82.1 s against
    /// 72.7 s (+13 %), an H2 SQL workload 8.7 s against 8.3 s (+5 %),
    /// CratonBench and `split-ws` flat. So the raise now holds only in a
    /// splice tree below a chain body or a lambda body whose interface rows
    /// W10-4 opens (the VM resolver's `IR_CHAIN_TREE`).
    pub fn chain_depth_scoped_enabled() -> bool {
        cratonvm_types::flags::runtime_flag_default_on("CRATONVM_JIT_IR_NESTED_CHAIN_DEPTH_SCOPED")
    }

    /// Does the W10-3 raise apply to a resolution inside (`chain_tree`) or
    /// outside a chain splice tree?
    pub fn raise_applies(chain_tree: bool) -> bool {
        ir_nested_chain_depth_enabled() && (chain_tree || !chain_depth_scoped_enabled())
    }

    /// The optimizing tier's nest depth when `CRATONVM_JIT_IR_INLINE_MAX_NEST`
    /// is unset, inside a chain tree: [`default_nest_depth_in`]`(true)`.
    pub fn default_nest_depth() -> usize {
        default_nest_depth_in(true)
    }

    /// [`MAX_IR_INLINE_NEST_DEPTH`], or where [`raise_applies`] the builder's
    /// frame cap.
    pub fn default_nest_depth_in(chain_tree: bool) -> usize {
        if raise_applies(chain_tree) {
            ir_inline_max_nest_frame_cap(ir::ir_splice_leaf_past_depth_enabled())
                .max(MAX_IR_INLINE_NEST_DEPTH)
        } else {
            MAX_IR_INLINE_NEST_DEPTH
        }
    }

    /// W10-3: the largest call-free static body the leaf tier takes past the
    /// nest cap under [`ir_nested_chain_depth_enabled`] (16 otherwise).
    pub const CHAIN_LEAF_MAX_BYTES: usize = 24;

    /// W10-3: [`ir::ir_leaf_splice_body`]'s shape rule (no invoke,
    /// allocation, `athrow`, monitor or switch) up to `max` bytes.
    pub fn leaf_body_within(code: &[u8], code_len: usize, max: usize) -> bool {
        let len = code_len.min(code.len());
        if len == 0 || len > max {
            return false;
        }
        let mut pc = 0usize;
        while pc < len {
            if matches!(
                code[pc],
                0xaa | 0xab | 0xb6..=0xbf | 0xc2 | 0xc3 | 0xc4 | 0xc5
            ) {
                return false;
            }
            let step = crate::bytecode_analysis::step(code, pc);
            if step == 0 {
                return false;
            }
            pc += step;
        }
        true
    }

    /// The leaf tier's body rule: [`ir::ir_leaf_splice_body`], or under
    /// [`ir_nested_chain_depth_enabled`] the same shape up to
    /// [`CHAIN_LEAF_MAX_BYTES`].
    pub fn chain_leaf_splice_body(code: &[u8], code_len: usize) -> bool {
        chain_leaf_splice_body_in(code, code_len, true)
    }

    /// [`chain_leaf_splice_body`] inside (`chain_tree`) or outside a chain
    /// splice tree: the 24-byte rule only where [`raise_applies`].
    pub fn chain_leaf_splice_body_in(code: &[u8], code_len: usize, chain_tree: bool) -> bool {
        ir::ir_leaf_splice_body(code, code_len)
            || (raise_applies(chain_tree) && leaf_body_within(code, code_len, CHAIN_LEAF_MAX_BYTES))
    }

    #[cfg(test)]
    mod tests {
        use super::*;

        /// `ASCII.getType(I)I` as javac emits it: `iload_0; ldc; iand; ifne
        /// +11; getstatic ctype; iload_0; iaload; goto +4; iconst_0; ireturn`
        /// (17 bytes).
        const GET_TYPE: [u8; 17] = [
            0x1a, 0x12, 0x02, 0x7e, 0x9a, 0x00, 0x0b, 0xb2, 0x00, 0x03, 0x1a, 0x2e, 0xa7, 0x00,
            0x04, 0x03, 0xac,
        ];

        #[test]
        fn r25_w10_3_the_chain_gives_its_callees_their_levels_back() {
            const DEPTH: &str = "CRATONVM_JIT_IR_NESTED_CHAIN_DEPTH";
            const KNOB: &str = "CRATONVM_JIT_IR_INLINE_MAX_NEST";
            const LEAF: &str = "CRATONVM_JIT_IR_SPLICE_LEAF_PAST_DEPTH";
            const CLAMP: &str = "CRATONVM_JIT_IR_INLINE_MAX_NEST_FRAME_CLAMP";
            // The 17-byte getType is over the plain leaf rule, within the chain's.
            assert!(!ir::ir_leaf_splice_body(&GET_TYPE, GET_TYPE.len()));
            assert!(leaf_body_within(
                &GET_TYPE,
                GET_TYPE.len(),
                CHAIN_LEAF_MAX_BYTES
            ));
            // A call is never a leaf, at any size.
            let call = [0x1a, 0xb8, 0x00, 0x05, 0xac];
            assert!(!leaf_body_within(&call, call.len(), CHAIN_LEAF_MAX_BYTES));
            assert!(!leaf_body_within(&[0xac; 25], 25, CHAIN_LEAF_MAX_BYTES));
            let pins = |chain: Option<&'static str>, depth: Option<&'static str>| {
                [
                    (SWITCH, chain),
                    (DEPTH, depth),
                    (KNOB, None),
                    (LEAF, Some("1")),
                    (CLAMP, Some("1")),
                    // W10-4's switch also opens the depth rule: pinned off.
                    ("CRATONVM_JIT_IR_NESTED_LAMBDA_IFACE", Some("0")),
                    // rx27: the deep spine (default ON since 2026-10-29) raises
                    // the frame cap this test reads; pinned off.
                    ("CRATONVM_JIT_IR_CHAIN_DEEP_SPINE", Some("0")),
                ]
            };
            cratonvm_types::flags::with_thread_overrides(&pins(Some("1"), None), || {
                assert!(ir_nested_chain_depth_enabled());
                assert_eq!(default_nest_depth(), ir::MAX_IR_SPLICE_DEPTH - 1);
                assert_eq!(ir_inline_max_nest_depth(), ir::MAX_IR_SPLICE_DEPTH - 1);
                assert!(chain_leaf_splice_body(&GET_TYPE, GET_TYPE.len()));
            });
            // An explicit knob still wins.
            cratonvm_types::flags::with_thread_overrides(
                &[
                    (SWITCH, Some("1")),
                    (DEPTH, None),
                    (KNOB, Some("4")),
                    (LEAF, Some("1")),
                    (CLAMP, Some("1")),
                ],
                || assert_eq!(ir_inline_max_nest_depth(), 4),
            );
            // Off, and killed: exactly the old depth and leaf rule.
            for (chain, depth) in [(Some("0"), Some("0")), (Some("0"), None), (Some("1"), Some("0"))] {
                cratonvm_types::flags::with_thread_overrides(&pins(chain, depth), || {
                    assert!(!ir_nested_chain_depth_enabled());
                    assert_eq!(default_nest_depth(), MAX_IR_INLINE_NEST_DEPTH);
                    assert_eq!(ir_inline_max_nest_depth(), MAX_IR_INLINE_NEST_DEPTH);
                    assert!(!chain_leaf_splice_body(&GET_TYPE, GET_TYPE.len()));
                });
            }
        }

        /// The W11-7 review fix: the raise holds inside a chain tree only,
        /// unless `CRATONVM_JIT_IR_NESTED_CHAIN_DEPTH_SCOPED=0`.
        #[test]
        fn w11_7_the_depth_raise_is_scoped_to_chain_trees() {
            const SCOPED: &str = "CRATONVM_JIT_IR_NESTED_CHAIN_DEPTH_SCOPED";
            let pins = |scoped: Option<&'static str>| {
                [
                    (SWITCH, Some("1")),
                    ("CRATONVM_JIT_IR_NESTED_CHAIN_DEPTH", None),
                    ("CRATONVM_JIT_IR_INLINE_MAX_NEST", None),
                    ("CRATONVM_JIT_IR_SPLICE_LEAF_PAST_DEPTH", Some("1")),
                    ("CRATONVM_JIT_IR_INLINE_MAX_NEST_FRAME_CLAMP", Some("1")),
                    (SCOPED, scoped),
                    // rx27: the deep spine (default ON since 2026-10-29) raises
                    // the frame cap this test reads; pinned off.
                    ("CRATONVM_JIT_IR_CHAIN_DEEP_SPINE", Some("0")),
                ]
            };
            let raised = ir::MAX_IR_SPLICE_DEPTH - 1;
            cratonvm_types::flags::with_thread_overrides(&pins(None), || {
                assert_eq!(ir_inline_max_nest_depth_in(true), raised);
                assert!(chain_leaf_splice_body_in(&GET_TYPE, GET_TYPE.len(), true));
                assert_eq!(ir_inline_max_nest_depth_in(false), MAX_IR_INLINE_NEST_DEPTH);
                assert!(!chain_leaf_splice_body_in(&GET_TYPE, GET_TYPE.len(), false));
            });
            cratonvm_types::flags::with_thread_overrides(&pins(Some("0")), || {
                assert_eq!(ir_inline_max_nest_depth_in(false), raised, "=0: the global raise");
                assert!(chain_leaf_splice_body_in(&GET_TYPE, GET_TYPE.len(), false));
            });
            // An explicit knob is the operator's answer in or out of a tree.
            let mut knob = pins(None);
            knob[2].1 = Some("4");
            cratonvm_types::flags::with_thread_overrides(&knob, || {
                assert_eq!(ir_inline_max_nest_depth_in(false), 4);
                assert_eq!(ir_inline_max_nest_depth_in(true), 4);
            });
        }

        #[test]
        fn r25_w9_3_the_chain_compile_line_names_the_outcome() {
            let mut census = ChainCompileCensus::default();
            census.note(&ChainTreeReport {
                kept: 2,
                costly: 1,
                est_frame_before: 96,
                est_frame_after: 96 + 760,
                min_entry_permille: Some(500),
                ..ChainTreeReport::default()
            });
            census.note(&ChainTreeReport {
                unrooted: 1,
                est_frame_before: 40,
                est_frame_after: 40,
                ..ChainTreeReport::default()
            });
            assert_eq!(
                (
                    census.trees,
                    census.links,
                    census.costly,
                    census.est_frame_added
                ),
                (1, 2, 1, 760)
            );
            assert_eq!(census.min_entry_permille, Some(500));
            let rec = ir_evidence::CompileRecord {
                spliced_frames: 5,
                blind_dispatches_in_splice: 1,
                ..ir_evidence::CompileRecord::default()
            };
            let refused = census.line("M.m()V", true, false, Some(1184), Some(rec));
            assert!(refused.starts_with("[cratonvm-jitc] chain-compile M.m()V: trees=1 links=2"));
            assert!(refused.contains("real_frame=1184"));
            assert!(refused.contains("verdict=REFUSED by the acceptance gate"));
            assert!(refused.contains("blind_in_splice=1"));
            assert!(refused.contains(&format!("added_ns={}", rec.added_ns_per_execution())));
            assert!(census
                .line("M.m()V", false, false, None, None)
                .contains("real_frame=- verdict=NOT-LOWERED"));
            assert!(census
                .line("M.m()V", true, true, Some(64), None)
                .contains("verdict=accepted evidence=unjudged"));
        }

        const MATCH_DESC: &str = "(Ljava/util/regex/Matcher;ILjava/lang/CharSequence;)Z";

        fn target(kind: u8, name: &str, desc: &str) -> InlineInvokeTarget {
            InlineInvokeTarget {
                invoke_kind: kind,
                method_name: name.to_string(),
                descriptor: desc.to_string(),
                ..Default::default()
            }
        }

        /// `BmpCharPropertyGreedy.match`'s shape: a predicate call (spliced
        /// here: it has a nested row) and the chain's next link.
        fn greedy_like(len: usize) -> InlineSite {
            let mut site = InlineSite {
                callee_code: vec![0xac; len],
                callee_code_len: len,
                method_name: "match".to_string(),
                descriptor: MATCH_DESC.to_string(),
                ..InlineSite::default()
            };
            site.invoke_targets.push((10, target(2, "is", "(I)Z")));
            site.invoke_targets
                .push((20, target(0, "match", MATCH_DESC)));
            site.nested_sites.push(NestedInlineSite {
                callee_pc: 10,
                guard_class_id: 900,
                site: InlineSite::default(),
                bimorphic_second: None,
            });
            site
        }

        /// `Pattern$Start.match`'s shape: the chain call in a loop.
        fn start_like() -> InlineSite {
            InlineSite {
                callee_code: LOOPING.to_vec(),
                callee_code_len: LOOPING.len(),
                method_name: "match".to_string(),
                descriptor: MATCH_DESC.to_string(),
                invoke_targets: vec![(5, target(0, "match", MATCH_DESC))],
                ..InlineSite::default()
            }
        }

        /// `iload_1; ifeq 11; aload_0; invokevirtual #2; goto 4; return`: the
        /// call at pc 5 is in a loop, behind a branch.
        const LOOPING: [u8; 12] = [
            0x1b, 0x99, 0x00, 0x0a, 0x2a, 0xb6, 0x00, 0x02, 0xa7, 0xff, 0xfc, 0xb1,
        ];
        /// `iload_1; ifeq 8; aload_0; invokevirtual #2; iconst_1; ireturn`:
        /// the call at pc 5 is behind a branch, in no loop.
        const BEHIND: [u8; 10] = [0x1b, 0x99, 0x00, 0x07, 0x2a, 0xb6, 0x00, 0x02, 0x04, 0xac];

        fn samples(n: u32) -> profile::ReceiverCounts {
            let mut counts = profile::ReceiverCounts::default();
            counts.insert(608, n);
            counts
        }

        /// The chain switch as given, and every switch the rules here read
        /// pinned: the nested guarded row and its hot caps on, the two other
        /// over-cold-cap admissions (`_FORWARDER_EXACT_HOT`,
        /// `_PSPLICE_NESTED_EXACT_HOT`) off so only the rule under test admits.
        fn pinned<R>(on: Option<&str>, f: impl FnOnce() -> R) -> R {
            cratonvm_types::flags::with_thread_overrides(
                &[
                    (SWITCH, on),
                    ("CRATONVM_JIT_IR_NESTED_GUARDED_SPLICE", Some("1")),
                    ("CRATONVM_JIT_IR_GUARDED_SPLICE_HOT_CAP", Some("1")),
                    ("CRATONVM_JIT_IR_GUARDED_SPLICE_HOT_CAP_MULTI", Some("1")),
                    ("CRATONVM_JIT_IR_NESTED_GUARDED_HOT_CAP", Some("1")),
                    ("CRATONVM_JIT_IR_NESTED_GUARDED_HOT_CAP_LEAF", Some("1")),
                    ("CRATONVM_JIT_IR_SPLICE_NESTED_EXACT_RECEIVER", Some("1")),
                    ("CRATONVM_JIT_IR_PSPLICE_NESTED_EXACT_HOT", Some("0")),
                    ("CRATONVM_JIT_IR_SPLICE_FORWARDER_EXACT_HOT", Some("0")),
                    // rx27 bundle flip (2026-10-29): the rules these tests
                    // measure are the W7-B ones, so the default-ON chain
                    // entry, in-loop hot cap and chain pairs are pinned off.
                    ("CRATONVM_JIT_IR_CHAIN_ENTRY_SPLICE", Some("0")),
                    ("CRATONVM_JIT_IR_NESTED_IN_LOOP_HOT", Some("0")),
                    ("CRATONVM_JIT_IR_CHAIN_BIMORPHIC_PREDICATES", Some("0")),
                    ("CRATONVM_JIT_IR_CHAIN_BIMORPHIC_LINKS", Some("0")),
                ],
                f,
            )
        }

        #[test]
        fn r25_w7b_a_chain_call_is_a_virtual_call_of_the_bodys_own_selector() {
            assert!(is_chain_call(0, "match", MATCH_DESC, "match", MATCH_DESC));
            assert!(is_chain_call(2, "match", MATCH_DESC, "match", MATCH_DESC));
            assert!(!is_chain_call(3, "match", MATCH_DESC, "match", MATCH_DESC));
            assert!(!is_chain_call(1, "match", MATCH_DESC, "match", MATCH_DESC));
            assert!(!is_chain_call(0, "is", "(I)Z", "match", MATCH_DESC));
            assert!(!is_chain_call(0, "match", "(I)Z", "match", MATCH_DESC));
            assert!(body_is_chain_shaped(&greedy_like(89)));
            let mut leaf = greedy_like(45);
            leaf.invoke_targets.clear();
            assert!(!body_is_chain_shaped(&leaf));
            assert_eq!(first_kept_non_link_call(&greedy_like(89)), None);
        }

        #[test]
        fn r25_w7b_the_link_rule_admits_a_chain_body_over_the_cold_cap() {
            pinned(Some("1"), || {
                let greedy = greedy_like(89);
                // The leaf rule refuses it: it holds calls.
                assert!(!ir_nested_hot_body_admitted(
                    &greedy,
                    MAX_INLINE_BYTECODE_SIZE
                ));
                // In a loop of the enclosing body: hot without samples.
                assert_eq!(
                    chain_link_verdict(None, &LOOPING, LOOPING.len(), 5, &greedy, 1),
                    Ok(())
                );
                // Behind a branch in no loop: hot only from 100 samples.
                assert_eq!(
                    chain_link_verdict(Some(&samples(99)), &BEHIND, BEHIND.len(), 5, &greedy, 1),
                    Err(ChainRefusal::ColdSite)
                );
                assert_eq!(
                    chain_link_verdict(Some(&samples(100)), &BEHIND, BEHIND.len(), 5, &greedy, 1),
                    Ok(())
                );
                // A kept call that is not the next link refuses it.
                let mut lost = greedy.clone();
                lost.nested_sites.clear();
                assert_eq!(
                    chain_link_verdict(None, &LOOPING, LOOPING.len(), 5, &lost, 1),
                    Err(ChainRefusal::KeptCall(10))
                );
                // A static body, and a body over the share of two bodies.
                let mut stat = greedy.clone();
                stat.callee_is_static = true;
                assert_eq!(
                    chain_link_verdict(None, &LOOPING, LOOPING.len(), 5, &stat, 1),
                    Err(ChainRefusal::Static)
                );
                let big = greedy_like(MAX_INLINE_BYTECODE_SIZE);
                assert_eq!(
                    chain_link_verdict(None, &LOOPING, LOOPING.len(), 5, &big, 2),
                    Err(ChainRefusal::OverCap(ir_guarded_multi_body_cap(
                        ir::GUARDED_SPLICE_HOT_MAX_BODY_BYTES,
                        2
                    )))
                );
                assert_eq!(
                    chain_link_verdict(None, &LOOPING, LOOPING.len(), 5, &big, 1),
                    Ok(())
                );
            });
        }

        #[test]
        #[allow(clippy::single_element_loop)]
        fn r25_w7b_switched_off_nothing_changes() {
            // W11-7: `=0` only. Since the wave-10 flip an unset switch is ON,
            // which the `pinned(None, ..)` arm here still assumed was off
            // (`chain_link_verdict` then answers past `SwitchedOff`).
            for off in [Some("0")] {
                pinned(off, || {
                    let greedy = greedy_like(89);
                    assert_eq!(
                        chain_link_verdict(None, &LOOPING, LOOPING.len(), 5, &greedy, 1),
                        Err(ChainRefusal::SwitchedOff)
                    );
                    let parent = start_like();
                    let row = NestedInlineSite {
                        callee_pc: 5,
                        guard_class_id: 608,
                        site: greedy,
                        bimorphic_second: None,
                    };
                    assert!(!chain_row_admitted_in(&parent, &row, 1));
                    assert!(!ir_splice_nested_exact_admitted_in(
                        Some(&parent),
                        &row,
                        true
                    ));
                    assert!(!withdrawn_after_strip(&parent, &row, true));
                    let mut tree = parent.clone();
                    tree.nested_sites.push(row);
                    assert_eq!(ir_splice_strip_unadmitted_exact_nested(&mut tree, true), 1);
                });
            }
        }

        #[test]
        fn r25_w7b_the_planner_admits_the_row_the_resolver_admits() {
            pinned(Some("1"), || {
                let parent = start_like();
                let row = NestedInlineSite {
                    callee_pc: 5,
                    guard_class_id: 608,
                    site: greedy_like(89),
                    bimorphic_second: None,
                };
                assert!(chain_row_admitted_in(&parent, &row, 1));
                assert!(ir_splice_nested_exact_admitted_in(
                    Some(&parent),
                    &row,
                    true
                ));
                // Without chain fences the nested row is never admitted.
                assert!(!ir_splice_nested_exact_admitted_in(
                    Some(&parent),
                    &row,
                    false
                ));
                // The same body under a call of ANOTHER selector is no link.
                let mut other = parent.clone();
                other.invoke_targets = vec![(5, target(0, "hashCode", "()I"))];
                assert!(!chain_row_admitted_in(&other, &row, 1));
                assert!(!ir_splice_nested_exact_admitted_in(
                    Some(&other),
                    &row,
                    true
                ));
                // The strip keeps the admitted link, and drops it when its
                // predicate row is missing (its loop would keep that call).
                let mut tree = parent.clone();
                tree.nested_sites.push(row.clone());
                assert_eq!(ir_splice_strip_unadmitted_exact_nested(&mut tree, true), 0);
                assert_eq!(tree.nested_sites.len(), 1);
                let mut bare = parent.clone();
                let mut lost = row.clone();
                lost.site.nested_sites.clear();
                bare.nested_sites.push(lost);
                assert_eq!(ir_splice_strip_unadmitted_exact_nested(&mut bare, true), 1);
                assert!(bare.nested_sites.is_empty());
            });
        }

        #[test]
        fn r25_w7b_fix_an_object_call_of_the_bodys_selector_is_no_chain() {
            let mut element_hash = target(0, "hashCode", "()I");
            element_hash.class_name = "java/lang/Object".to_string();
            assert!(!is_chain_target(&element_hash, "hashCode", "()I"));
            let mut next = target(0, "match", MATCH_DESC);
            next.class_name = "java/util/regex/Pattern$Node".to_string();
            assert!(is_chain_target(&next, "match", MATCH_DESC));
            // An Object-typed same-selector call is a kept call to the link rule.
            let mut set_hash = InlineSite {
                callee_code_len: 60,
                method_name: "hashCode".to_string(),
                descriptor: "()I".to_string(),
                ..InlineSite::default()
            };
            set_hash.invoke_targets.push((7, element_hash));
            assert!(!body_is_chain_shaped(&set_hash));
            assert_eq!(first_kept_non_link_call(&set_hash), Some(7));
        }

        /// `greedy_like` whose next-link call at pc 20 carries a nested row
        /// of `len` bytes (a `LastNode`-like leaf).
        fn greedy_with_next(greedy_len: usize, len: usize) -> InlineSite {
            let mut greedy = greedy_like(greedy_len);
            greedy.nested_sites.push(NestedInlineSite {
                callee_pc: 20,
                guard_class_id: 610,
                site: InlineSite {
                    callee_code: vec![0xac; len],
                    callee_code_len: len,
                    callee_max_locals: 3,
                    method_name: "match".to_string(),
                    descriptor: MATCH_DESC.to_string(),
                    ..InlineSite::default()
                },
                bimorphic_second: None,
            });
            greedy
        }

        fn tree(parent_code: &[u8], link: InlineSite) -> InlineSite {
            let mut tree = start_like();
            tree.callee_code = parent_code.to_vec();
            tree.callee_code_len = parent_code.len();
            tree.nested_sites.push(NestedInlineSite {
                callee_pc: 5,
                guard_class_id: 608,
                site: link,
                bimorphic_second: None,
            });
            tree
        }

        #[test]
        fn r25_w7b_fix_a_loop_roots_the_chain_and_the_tree_cap_bounds_it() {
            pinned(Some("1"), || {
                // The loop at the first link's site roots the whole chain: the
                // next link (not in a loop of its own body) rides on it.
                let mut looped = tree(&LOOPING, greedy_with_next(89, 45));
                looped.nested_sites[0].site.class_name = "Greedy".to_string();
                let mut keys = Vec::new();
                let report = strip_chain_tree(&mut looped, false, &mut keys);
                assert_eq!(
                    keys,
                    vec![
                        format!("Greedy.match:{MATCH_DESC}"),
                        format!(".match:{MATCH_DESC}")
                    ]
                );
                assert_eq!(
                    (
                        report.kept,
                        report.unrooted,
                        report.capped,
                        report.bytes,
                        report.max_depth
                    ),
                    (2, 0, 0, 89 + 45, 2)
                );
                assert_eq!(report.added_locals, 3);
                assert_eq!(looped.nested_sites.len(), 1);
                assert_eq!(looped.nested_sites[0].site.nested_sites.len(), 2);
                // No loop above: the chain is entered once per root entry and
                // is dropped whole (the call stays at pc 5).
                let mut once = tree(&BEHIND, greedy_with_next(89, 45));
                let report = strip_chain_tree(&mut once, false, &mut Vec::new());
                assert_eq!((report.kept, report.unrooted), (0, 1));
                assert!(once.nested_sites.is_empty());
                // ... unless the top-level site itself is in a loop of the root.
                let mut top = tree(&BEHIND, greedy_with_next(89, 45));
                assert_eq!(strip_chain_tree(&mut top, true, &mut Vec::new()).kept, 2);
                // The tree cap: the nearer link is kept, the next one goes.
                let mut big = tree(&LOOPING, greedy_with_next(300, 45));
                let report = strip_chain_tree(&mut big, false, &mut Vec::new());
                assert_eq!((report.kept, report.capped, report.bytes), (1, 1, 300));
                assert_eq!(big.nested_sites[0].site.nested_sites.len(), 1);
                assert_eq!(CHAIN_TREE_MAX_BYTES, MAX_INLINE_BYTECODE_SIZE);
                // A non-chain row is kept unjudged, and roots nothing: the
                // chain row under it, in no loop, goes.
                let mut other = tree(&BEHIND, greedy_with_next(89, 45));
                other.invoke_targets = vec![(5, target(0, "hashCode", "()I"))];
                let report = strip_chain_tree(&mut other, false, &mut Vec::new());
                assert_eq!((report.kept, report.unrooted), (0, 1));
                assert_eq!(other.nested_sites.len(), 1);
                assert_eq!(other.nested_sites[0].site.nested_sites.len(), 1);
            });
            pinned(Some("0"), || {
                let mut once = tree(&BEHIND, greedy_with_next(89, 45));
                let report = strip_chain_tree(&mut once, false, &mut Vec::new());
                assert_eq!(report, ChainTreeReport::default());
                assert_eq!(once.nested_sites.len(), 1);
            });
        }

        #[test]
        fn r25_w7b_fix_only_kept_links_take_the_extra_hot_slots() {
            // Rows (combined pc, class): 10 and 20 plain bodies over the cold
            // cap, 30 and 40 kept links over it.
            let rows = [(10, 1), (20, 2), (30, 3), (40, 4)];
            let body = |key: usize| Some((90, key >= 30));
            pinned(Some("1"), || {
                // One base slot: the first plain row; both links ride on
                // their own slots.
                assert_eq!(nested_hot_cap_pcs(&rows, body, 1), vec![10, 30, 40]);
                assert_eq!(nested_hot_cap_pcs(&rows, body, 0), vec![30, 40]);
            });
            pinned(Some("0"), || {
                // Off: the plain rule, links or not.
                assert_eq!(nested_hot_cap_pcs(&rows, body, 1), vec![10]);
                assert_eq!(nested_hot_cap_pcs(&rows, body, 0), Vec::<usize>::new());
            });
        }

        #[test]
        fn r25_w7b_fix2_a_rare_link_site_is_refused() {
            assert_eq!(chain_frequency_permille(1, 4), 250);
            assert_eq!(chain_frequency_permille(5, 0), 0);
            assert_eq!(chain_frequency_permille(u32::MAX, 1), u32::MAX);
            // A quarter of the body's entries is frequent; less is not.
            assert_eq!(chain_frequency_verdict(250, 1000), Ok(()));
            assert_eq!(
                chain_frequency_verdict(249, 1000),
                Err(ChainRefusal::RareSite(249))
            );
            // `,\s*`: the `\s*` link runs after one position in twenty.
            assert_eq!(
                chain_frequency_verdict(50, 1000),
                Err(ChainRefusal::RareSite(50))
            );
            // A site in a scan loop runs more often than its body is entered.
            assert_eq!(chain_frequency_verdict(3000, 1000), Ok(()));
            // No invocation count: no evidence, the structural rule decides.
            assert_eq!(chain_frequency_verdict(0, 0), Ok(()));
            // A same-selector row the plain rules admit (within the cold cap)
            // is never judged by the chain cost rule, rooted or not.
            pinned(Some("1"), || {
                let mut small = tree(&BEHIND, greedy_like(MAX_INLINE_SIZE_COLD));
                let report = strip_chain_tree(&mut small, false, &mut Vec::new());
                assert_eq!(
                    (report.kept, report.unrooted, report.capped, report.costly),
                    (0, 0, 0, 0)
                );
                assert_eq!(report.est_frame_after, report.est_frame_before);
                assert_eq!(small.nested_sites.len(), 1);
            });
            assert!(ChainRefusal::RareSite(50)
                .to_string()
                .contains("rare site (50 per mille"));
        }

        #[test]
        fn r25_w8_5_a_link_must_pay_for_the_frame_it_adds() {
            // Greedy's estimate: 89 bytes + 6 locals = 760 frame bytes.
            assert_eq!(est_frame_bytes(89, 6), 760);
            // 760 bytes = 24 clear instructions; the call saves 40 + 24.
            assert!(link_pays_for_its_frame(1000, 760));
            assert!(link_pays_for_its_frame(375, 760));
            assert!(!link_pays_for_its_frame(374, 760));
            assert!(!link_pays_for_its_frame(0, 760));
            // A small frame pays at a small share; a frameless body always.
            assert!(link_pays_for_its_frame(100, 64));
            assert!(link_pays_for_its_frame(0, 0));
            // The entries come from the parent's samples over its invocations.
            let mut parent = start_like();
            assert_eq!(site_entry_permille(&parent, 5), None);
            parent.callee_invocations = 200;
            parent.callee_receiver_profile = vec![(5, samples(1000))];
            assert_eq!(site_entry_permille(&parent, 5), Some(5000));
            assert_eq!(site_entry_permille(&parent, 9), Some(0));
        }

        #[test]
        fn r25_w8_5_the_tree_rule_drops_a_cold_link_and_keeps_a_hot_one() {
            pinned(Some("1"), || {
                // Start's loop runs the first link five times per entry; the
                // next link runs after one in ten of those (half a run per
                // entry): 45 bytes (+3 locals) = 384 frame bytes, 12 clear
                // instructions, pays from 231 per mille.
                let mut link = greedy_with_next(89, 45);
                link.callee_invocations = 1000;
                link.callee_receiver_profile = vec![(20, samples(100))];
                let mut hot = tree(&LOOPING, link.clone());
                hot.callee_invocations = 200;
                hot.callee_receiver_profile = vec![(5, samples(1000))];
                let report = strip_chain_tree(&mut hot, false, &mut Vec::new());
                assert_eq!((report.kept, report.costly), (2, 0));
                assert_eq!(report.min_entry_permille, Some(500));
                assert_eq!(
                    report.est_frame_after - report.est_frame_before,
                    est_frame_bytes(134, 3)
                );
                // The same chain entered once per twenty top-level entries:
                // the first link (50 per mille) does not pay; nothing under it
                // is judged.
                let mut cold = tree(&LOOPING, link);
                cold.callee_invocations = 1000;
                cold.callee_receiver_profile = vec![(5, samples(50))];
                let report = strip_chain_tree(&mut cold, false, &mut Vec::new());
                assert_eq!((report.kept, report.costly), (0, 1));
                assert!(cold.nested_sites.is_empty());
                assert_eq!(report.est_frame_after, report.est_frame_before);
            });
        }

        #[test]
        fn r25_w7b_a_stripped_child_withdraws_its_link() {
            pinned(Some("1"), || {
                // The link's predicate row is a 90-byte non-leaf that no rule
                // admits, so the strip drops it -- and then the link would keep
                // that call, so the link goes too.
                let mut link = greedy_like(89);
                let mut child = InlineSite {
                    callee_code: vec![0xac; 90],
                    callee_code_len: 90,
                    method_name: "is".to_string(),
                    descriptor: "(I)Z".to_string(),
                    ..InlineSite::default()
                };
                child.invoke_targets.push((3, target(3, "helper", "()V")));
                link.nested_sites[0].site = child;
                let mut tree = start_like();
                tree.nested_sites.push(NestedInlineSite {
                    callee_pc: 5,
                    guard_class_id: 608,
                    site: link,
                    bimorphic_second: None,
                });
                assert_eq!(ir_splice_strip_unadmitted_exact_nested(&mut tree, true), 2);
                assert!(tree.nested_sites.is_empty());
            });
        }

        /// Round rx27 (lane chain, W7B-2): the tree cap is a knob. A
        /// 300-byte link with a 45-byte next link is capped at the default
        /// 325 bytes and kept whole at 400; an unset or unparsable knob is
        /// the default, and a knob over the compile's whole budget is clamped.
        #[test]
        fn rx27_chain_the_tree_cap_is_a_knob_for_the_ab() {
            const KNOB: &str = "CRATONVM_JIT_IR_CHAIN_TREE_MAX_BYTES";
            let with = |knob: Option<&'static str>, f: &dyn Fn()| {
                cratonvm_types::flags::with_thread_overrides(
                    &[
                        (SWITCH, Some("1")),
                        ("CRATONVM_JIT_IR_NESTED_GUARDED_SPLICE", Some("1")),
                        ("CRATONVM_JIT_IR_GUARDED_SPLICE_HOT_CAP", Some("1")),
                        ("CRATONVM_JIT_IR_GUARDED_SPLICE_HOT_CAP_MULTI", Some("1")),
                        ("CRATONVM_JIT_IR_NESTED_GUARDED_HOT_CAP", Some("1")),
                        ("CRATONVM_JIT_IR_NESTED_GUARDED_HOT_CAP_LEAF", Some("1")),
                        ("CRATONVM_JIT_IR_SPLICE_NESTED_EXACT_RECEIVER", Some("1")),
                        ("CRATONVM_JIT_IR_PSPLICE_NESTED_EXACT_HOT", Some("0")),
                        ("CRATONVM_JIT_IR_SPLICE_FORWARDER_EXACT_HOT", Some("0")),
                        (KNOB, knob),
                    ],
                    f,
                )
            };
            with(None, &|| {
                assert_eq!(chain_tree_max_bytes(), CHAIN_TREE_MAX_BYTES);
                let mut big = tree(&LOOPING, greedy_with_next(300, 45));
                let report = strip_chain_tree(&mut big, false, &mut Vec::new());
                assert_eq!((report.kept, report.capped), (1, 1));
            });
            with(Some("x"), &|| {
                assert_eq!(chain_tree_max_bytes(), CHAIN_TREE_MAX_BYTES)
            });
            with(Some("400"), &|| {
                assert_eq!(chain_tree_max_bytes(), 400);
                let mut big = tree(&LOOPING, greedy_with_next(300, 45));
                let report = strip_chain_tree(&mut big, false, &mut Vec::new());
                assert_eq!((report.kept, report.capped, report.bytes), (2, 0, 345));
                assert_eq!(big.nested_sites[0].site.nested_sites.len(), 2);
            });
            with(Some("99999"), &|| {
                assert_eq!(chain_tree_max_bytes(), IR_INLINE_MAX_TOTAL_BYTES)
            });
        }

        /// Round rx27 wave 3 (lane chain, W7B-3): `GroupTail.match` pc 70's
        /// two-class row. A leaf pair at `Start`-shaped pc 5 (a chain site in
        /// a loop) keeps its second body under the chain-scoped switch with
        /// the global nested bimorphic switch off; the same pair at a
        /// non-chain site (`hashCode`) loses it; with both switches off the
        /// pair goes, as before rx27.
        #[test]
        fn rx27_chain_a_chain_sites_pair_is_kept_without_the_global_switch() {
            const PAIR: &str = "CRATONVM_JIT_IR_CHAIN_BIMORPHIC_LINKS";
            const GLOBAL: &str = "CRATONVM_JIT_IR_NESTED_BIMORPHIC_SPLICE";
            let with = |pair: Option<&'static str>, global: Option<&'static str>, f: &dyn Fn()| {
                cratonvm_types::flags::with_thread_overrides(
                    &[
                        (SWITCH, Some("1")),
                        ("CRATONVM_JIT_IR_NESTED_GUARDED_SPLICE", Some("1")),
                        ("CRATONVM_JIT_IR_BIMORPHIC_GUARDED_SPLICE", Some("1")),
                        ("CRATONVM_JIT_IR_GUARDED_SPLICE_HOT_CAP", Some("1")),
                        ("CRATONVM_JIT_IR_GUARDED_SPLICE_HOT_CAP_MULTI", Some("1")),
                        ("CRATONVM_JIT_IR_NESTED_GUARDED_HOT_CAP", Some("1")),
                        ("CRATONVM_JIT_IR_NESTED_GUARDED_HOT_CAP_LEAF", Some("1")),
                        ("CRATONVM_JIT_IR_SPLICE_NESTED_EXACT_RECEIVER", Some("1")),
                        ("CRATONVM_JIT_IR_PSPLICE_NESTED_EXACT_HOT", Some("0")),
                        ("CRATONVM_JIT_IR_SPLICE_FORWARDER_EXACT_HOT", Some("0")),
                        (PAIR, pair),
                        (GLOBAL, global),
                        // rx27 bundle flip (2026-10-29): the other default-ON
                        // chain switches pinned off, so only `PAIR` decides.
                        ("CRATONVM_JIT_IR_CHAIN_BIMORPHIC_PREDICATES", Some("0")),
                        ("CRATONVM_JIT_IR_CHAIN_ENTRY_SPLICE", Some("0")),
                        ("CRATONVM_JIT_IR_NESTED_IN_LOOP_HOT", Some("0")),
                    ],
                    f,
                )
            };
            let leaf = |len: usize| InlineSite {
                callee_code: vec![0xac; len],
                callee_code_len: len,
                callee_max_locals: 3,
                method_name: "match".to_string(),
                descriptor: MATCH_DESC.to_string(),
                ..InlineSite::default()
            };
            let pair_tree = |chain: bool| {
                let mut tree = start_like();
                if !chain {
                    tree.invoke_targets = vec![(5, target(0, "hashCode", "()I"))];
                }
                tree.nested_sites.push(NestedInlineSite {
                    callee_pc: 5,
                    guard_class_id: 610,
                    site: leaf(20),
                    bimorphic_second: Some(Box::new(NestedInlineSite {
                        callee_pc: 5,
                        guard_class_id: 611,
                        site: leaf(30),
                        bimorphic_second: None,
                    })),
                });
                tree
            };
            let second_kept = |chain: bool| {
                let mut tree = pair_tree(chain);
                ir_splice_strip_unadmitted_exact_nested(&mut tree, true);
                tree.nested_sites
                    .first()
                    .is_some_and(|n| n.bimorphic_second.is_some())
            };
            with(Some("1"), Some("0"), &|| {
                assert!(chain_bimorphic_links_enabled());
                assert!(nested_pair_admitted(true));
                assert!(!nested_pair_admitted(false));
                assert!(nested_pair_switch_on());
                assert!(second_kept(true), "a chain site's pair stays");
                assert!(!second_kept(false), "a non-chain site's pair goes");
            });
            // Default ON since the rx27 bundle flip; `=0` kills it.
            with(None, Some("0"), &|| assert!(chain_bimorphic_links_enabled(), "default ON"));
            with(Some("0"), Some("0"), &|| {
                assert!(!chain_bimorphic_links_enabled(), "killed");
                assert!(!nested_pair_admitted(true));
                assert!(!nested_pair_switch_on());
                assert!(!second_kept(true));
            });
            with(None, Some("1"), &|| {
                assert!(nested_pair_admitted(false), "the global switch opens every site");
                assert!(second_kept(false));
            });
            // Inert without the chain switch.
            cratonvm_types::flags::with_thread_overrides(&[(SWITCH, Some("0")), (PAIR, Some("1"))], || {
                assert!(!chain_bimorphic_links_enabled())
            });
        }

        /// Round rx27 wave 4 (lane chain): a greedy node's `predicate.is`
        /// (an interface site of a chain body) may hold a two-class row under
        /// `CRATONVM_JIT_IR_CHAIN_BIMORPHIC_PREDICATES`; the same interface
        /// call in a non-chain body may not, nor a chain body's site with
        /// the switch off.
        #[test]
        fn rx27_chain_a_chain_bodys_predicate_site_takes_a_pair() {
            const PRED: &str = "CRATONVM_JIT_IR_CHAIN_BIMORPHIC_PREDICATES";
            let with = |pred: Option<&'static str>, f: &dyn Fn()| {
                cratonvm_types::flags::with_thread_overrides(
                    &[
                        (SWITCH, Some("1")),
                        ("CRATONVM_JIT_IR_NESTED_GUARDED_SPLICE", Some("1")),
                        ("CRATONVM_JIT_IR_BIMORPHIC_GUARDED_SPLICE", Some("1")),
                        ("CRATONVM_JIT_IR_NESTED_BIMORPHIC_SPLICE", Some("0")),
                        ("CRATONVM_JIT_IR_CHAIN_BIMORPHIC_LINKS", Some("0")),
                        (PRED, pred),
                    ],
                    f,
                )
            };
            let greedy = greedy_like(89);
            let row = greedy.nested_sites[0].clone();
            let mut plain = greedy_like(89);
            plain.invoke_targets.truncate(1);
            with(Some("1"), &|| {
                assert!(chain_bimorphic_predicates_enabled());
                assert!(chain_predicate_pair_site(true, 2));
                assert!(!chain_predicate_pair_site(true, 0));
                assert!(!chain_predicate_pair_site(false, 2));
                assert!(nested_pair_admitted_row(&greedy, &row), "predicate.is of a chain body");
                assert!(!nested_pair_admitted_row(&plain, &row), "not a chain body");
                assert!(nested_pair_switch_on());
            });
            // Default ON since the rx27 bundle flip; `=0` kills it.
            with(None, &|| assert!(chain_bimorphic_predicates_enabled(), "default ON"));
            with(Some("0"), &|| {
                assert!(!chain_bimorphic_predicates_enabled(), "killed");
                assert!(!nested_pair_admitted_row(&greedy, &row));
                assert!(!nested_pair_switch_on());
            });
        }
    }
}

/// Round rx27 wave 1 (lane chain, `CRATONVM_JIT_IR_LOOP_ROOT_OWN_COMPILE`,
/// opt-in; `docs/known-issues/jit/r23-w2-regex-rows-gap-is-per-call-cost-20261021.md`,
/// "Round rx27 wave 1 (lane chain)"): a loop-rooted body whose in-loop rows
/// the caller's compile cannot hold stays a call, and keeps its own compile.
///
/// Three measured cases share one premise. A body with a loop, spliced into
/// a caller, takes its in-loop call sites with it; they are planned there
/// under what is left of the CALLER's budget and as nested rows, where its
/// own compile plans them as top-level in-loop sites with the whole budget.
/// When the caller cannot hold them they become calls, paid once per loop
/// iteration, to remove one call per entry:
///
/// * W13-6 `cached`: `Pattern.split(CharSequence,int,boolean)` moved up
///   through three callers (`left=181`), and `Matcher.find` / `subSequence`
///   became calls in its split loop (+12.6 %);
/// * W13-6 `matchonly`: with `Matcher.<init>` spliced, `Start.match` (the
///   position loop) resolved into `Matcher.search` pc 121 with three of its
///   nested bodies pruned (+8.3 %);
/// * round 16 wave c: `boxHelper(I)J`'s loop spliced into `run(II)J` lost
///   its `intValue()` intrinsic (16 -> 195 ns/op).
///
/// W13-6 fixed the first by its trigger (an `anewarray` callee with a back
/// edge, `ir::splice_anewarray_refuses_loop_callee`). This rule asks the
/// premise instead, after the append, from what the append actually did:
///
/// * `resolved`: the tree's rows under a loop of the tree (a row whose call is
///   in a loop of its enclosing body, and every row below it) as the resolver
///   built them, less the rows the caller's compile could not splice in the
///   callee's own compile either (the String-prefix carve-out, the append's
///   static refusals);
/// * `planned`: the same count after every nested strip of this compile;
/// * `spliced`: the same count read back from the site table the append
///   wrote (the bodies really appended, under the caller's budget).
///
/// `spliced < planned` means the append ran out of budget (or the nested
/// cold reserve) inside a loop: the site is rolled back and stays a call.
/// With `CRATONVM_JIT_IR_LOOP_ROOT_OWN_COMPILE_STRIPS=1` also
/// `spliced < resolved` (a nested strip of this compile dropped an in-loop
/// row), which is the `matchonly` reading if its pruned bodies were in-loop.
///
/// Sound: it only ever keeps a call the planner could keep (the same
/// rollback as a refused bimorphic second body). Bimorphic and polymorphic
/// top-level sites, synchronized bodies and self-recursion plans are not
/// judged.
pub mod rx27_loop_root {
    use super::*;

    /// The switch (opt-in).
    pub const SWITCH: &str = "CRATONVM_JIT_IR_LOOP_ROOT_OWN_COMPILE";
    /// Also count the nested strips as losses (opt-in, inert alone).
    pub const STRIPS_SWITCH: &str = "CRATONVM_JIT_IR_LOOP_ROOT_OWN_COMPILE_STRIPS";

    /// `CRATONVM_JIT_IR_LOOP_ROOT_OWN_COMPILE`. Read per call, no `static`.
    pub fn enabled() -> bool {
        cratonvm_types::flags::runtime_flag_on(SWITCH)
    }

    /// `CRATONVM_JIT_IR_LOOP_ROOT_OWN_COMPILE_STRIPS`, under [`enabled`].
    pub fn strips_counted() -> bool {
        enabled() && cratonvm_types::flags::runtime_flag_on(STRIPS_SWITCH)
    }

    /// The rows of `site`'s tree under a loop of the tree: a row whose call
    /// pc is in a loop of its enclosing body, and every row below one. First
    /// bodies only (a bimorphic second is not counted, here or in
    /// [`spliced_in_loop_rows`]).
    pub fn in_loop_rows(site: &InlineSite) -> usize {
        rows_under(site, false)
    }

    fn rows_under(site: &InlineSite, under: bool) -> usize {
        site.nested_sites
            .iter()
            .map(|n| {
                let in_loop = under
                    || bytecode_pc_in_loop(&site.callee_code, site.callee_code_len, n.callee_pc);
                usize::from(in_loop) + rows_under(&n.site, in_loop)
            })
            .sum()
    }

    /// The `resolved` count: [`in_loop_rows`] of a copy of `site` with only
    /// the strips that bind the callee's own compile too (the nested String
    /// prefix carve-out, and the append's static refusals,
    /// [`ir_splice_prune_refused_nested`], when the planner runs it).
    /// `None` when the tree has no row under a loop: nothing to judge.
    pub(crate) fn resolved_in_loop_rows(
        site: &InlineSite,
        flags: ir::SpliceFenceRelax,
        chain_fences: bool,
    ) -> Option<usize> {
        if in_loop_rows(site) == 0 {
            return None;
        }
        let mut copy = site.clone();
        let _ = ir_splice_strip_string_prefix_nested(&mut copy);
        if ir_splice_prune_nested_enabled() {
            let _ = ir_splice_prune_refused_nested(&mut copy, flags, chain_fences);
        }
        let rows = in_loop_rows(&copy);
        (rows > 0).then_some(rows)
    }

    /// The `spliced` count, read back from the append's site table `sites`
    /// (keyed by caller pc in the combined buffer `combined`): the rows under
    /// a loop of the tree whose top-level body is keyed `top`. A row's
    /// children are the keys inside its body's range; a bimorphic or
    /// polymorphic second body's tagged key is in no range.
    pub fn spliced_in_loop_rows(
        sites: &HashMap<usize, ir::IrInlineSite>,
        combined: &[u8],
        top: usize,
    ) -> usize {
        spliced_under(sites, combined, top, false)
    }

    fn spliced_under(
        sites: &HashMap<usize, ir::IrInlineSite>,
        combined: &[u8],
        key: usize,
        under: bool,
    ) -> usize {
        let Some(row) = sites.get(&key) else {
            return 0;
        };
        let end = row.base.saturating_add(row.code_len);
        let code = combined.get(row.base..end.min(combined.len())).unwrap_or(&[]);
        sites
            .keys()
            .filter(|&&k| k >= row.base && k < end && k != key)
            .map(|&k| {
                let in_loop = under || bytecode_pc_in_loop(code, code.len(), k - row.base);
                usize::from(in_loop) + spliced_under(sites, combined, k, in_loop)
            })
            .sum()
    }

    /// The verdict: does the site stay a call? See the module comment.
    pub fn keeps_call(resolved: usize, planned: usize, spliced: usize, strips: bool) -> bool {
        spliced < planned || (strips && spliced < resolved)
    }

    /// The census line (`CRATONVM_DBG_JITC=1`), one per judged site.
    #[allow(clippy::too_many_arguments)]
    pub fn census_line(
        callee: &str,
        pc: usize,
        root: &str,
        resolved: usize,
        planned: usize,
        spliced: usize,
        budget_left: usize,
        kept_call: bool,
    ) -> String {
        format!(
            "[cratonvm-jitc] ir-loop-root-own-compile {callee} at pc={pc} in {root}: in-loop rows \
             resolved={resolved} planned={planned} spliced={spliced} budget_left={budget_left} -> {}",
            if kept_call {
                "kept as a call (compiled as its own root)"
            } else {
                "spliced (this compile holds its in-loop rows)"
            }
        )
    }

    #[cfg(test)]
    mod tests {
        use super::*;

        /// `iload_1; ifeq 11; aload_0; invokevirtual #2; goto 4; return`: the
        /// call at pc 5 is in a loop.
        const LOOPING: [u8; 12] = [
            0x1b, 0x99, 0x00, 0x0a, 0x2a, 0xb6, 0x00, 0x02, 0xa7, 0xff, 0xfc, 0xb1,
        ];
        /// `iload_1; ifeq 8; aload_0; invokevirtual #2; iconst_1; ireturn`:
        /// the call at pc 5 is in no loop.
        const BEHIND: [u8; 10] = [0x1b, 0x99, 0x00, 0x07, 0x2a, 0xb6, 0x00, 0x02, 0x04, 0xac];
        /// `aload_0; invokevirtual #2; ireturn`: a straight body, call at 1.
        const STRAIGHT: [u8; 5] = [0x2a, 0xb6, 0x00, 0x02, 0xac];

        fn body(code: &[u8]) -> InlineSite {
            InlineSite {
                callee_code: code.to_vec(),
                callee_code_len: code.len(),
                ..InlineSite::default()
            }
        }

        fn row(callee_pc: usize, site: InlineSite) -> NestedInlineSite {
            NestedInlineSite {
                callee_pc,
                guard_class_id: 0,
                site,
                bimorphic_second: None,
            }
        }

        /// A loop-rooted top body (`LOOPING`) whose in-loop call (pc 5) is a
        /// straight body that itself splices a leaf (pc 1): `Start.match`
        /// -> `Greedy` -> `LastNode` in shape.
        fn loop_rooted() -> InlineSite {
            let mut mid = body(&STRAIGHT);
            mid.nested_sites.push(row(1, body(&[0xac])));
            let mut top = body(&LOOPING);
            top.nested_sites.push(row(5, mid));
            top
        }

        #[test]
        fn rx27_rows_under_a_loop_are_the_in_loop_row_and_everything_below_it() {
            assert_eq!(in_loop_rows(&loop_rooted()), 2);
            // The same tree behind a branch in no loop: nothing is in a loop.
            let mut straight = loop_rooted();
            straight.callee_code = BEHIND.to_vec();
            straight.callee_code_len = BEHIND.len();
            assert_eq!(in_loop_rows(&straight), 0);
            // A loop deeper down counts from there: a straight top body whose
            // row (pc 1) is a looping body with an in-loop row (pc 5).
            let mut inner = body(&LOOPING);
            inner.nested_sites.push(row(5, body(&[0xac])));
            let mut top = body(&STRAIGHT);
            top.nested_sites.push(row(1, inner));
            assert_eq!(in_loop_rows(&top), 1);
        }

        /// The site table `append_ir_inline_site` writes for `loop_rooted`
        /// spliced at caller pc 2: the top body at 8, its pc-5 row at 20,
        /// that row's pc-1 leaf at 28.
        fn table(with_leaf: bool) -> (HashMap<usize, ir::IrInlineSite>, Vec<u8>) {
            let at = |base: usize, code_len: usize| ir::IrInlineSite {
                base,
                code_len,
                num_args: 1,
                max_locals: 2,
                arg_local_slots: vec![0],
                returns_value: true,
                receiver_is_arg0: true,
                method_key: String::new(),
                class_id: 0,
            };
            let mut combined = vec![0u8; 8];
            combined.extend_from_slice(&LOOPING);
            combined.resize(20, 0);
            combined.extend_from_slice(&STRAIGHT);
            combined.resize(28, 0);
            combined.push(0xac);
            let mut sites = HashMap::new();
            sites.insert(2, at(8, LOOPING.len()));
            sites.insert(8 + 5, at(20, STRAIGHT.len()));
            if with_leaf {
                sites.insert(20 + 1, at(28, 1));
            }
            // A bimorphic second body's tagged key sits in no body's range.
            sites.insert(ir::bimorphic_second_site_key(8 + 5), at(28, 1));
            (sites, combined)
        }

        #[test]
        fn rx27_the_spliced_count_reads_back_what_the_append_wrote() {
            let (sites, combined) = table(true);
            assert_eq!(spliced_in_loop_rows(&sites, &combined, 2), 2);
            // The leaf fell back to its call (the budget ran out): one less.
            let (sites, combined) = table(false);
            assert_eq!(spliced_in_loop_rows(&sites, &combined, 2), 1);
            // No top-level row: nothing spliced.
            assert_eq!(spliced_in_loop_rows(&sites, &combined, 3), 0);
        }

        #[test]
        fn rx27_a_loop_root_that_lost_an_in_loop_row_keeps_its_call() {
            // The append held every planned in-loop row: spliced.
            assert!(!keeps_call(2, 2, 2, false));
            // The budget ran out inside the loop: kept as a call.
            assert!(keeps_call(2, 2, 1, false));
            // A nested strip dropped one: a loss only under the strips switch.
            assert!(!keeps_call(3, 2, 2, false));
            assert!(keeps_call(3, 2, 2, true));
            // The rule reads the tree end to end on the fixture: the planned
            // tree holds 2 in-loop rows; the append wrote 1.
            let planned = in_loop_rows(&loop_rooted());
            let (sites, combined) = table(false);
            let spliced = spliced_in_loop_rows(&sites, &combined, 2);
            assert!(keeps_call(planned, planned, spliced, false));
            let line = census_line("P.s()V", 2, "R.r()V", planned, planned, spliced, 181, true);
            assert!(line.starts_with("[cratonvm-jitc] ir-loop-root-own-compile P.s()V at pc=2"));
            assert!(
                line.contains("resolved=2 planned=2 spliced=1 budget_left=181 -> kept as a call")
            );
        }

        #[test]
        fn rx27_the_loop_root_switches_are_opt_in() {
            let pins = |on: Option<&'static str>, strips: Option<&'static str>| {
                [(SWITCH, on), (STRIPS_SWITCH, strips)]
            };
            cratonvm_types::flags::with_thread_overrides(&pins(None, Some("1")), || {
                assert!(!enabled());
                assert!(!strips_counted(), "inert alone");
            });
            cratonvm_types::flags::with_thread_overrides(&pins(Some("1"), None), || {
                assert!(enabled());
                assert!(!strips_counted());
            });
            cratonvm_types::flags::with_thread_overrides(&pins(Some("1"), Some("1")), || {
                assert!(strips_counted())
            });
        }

        #[test]
        fn rx27_a_tree_with_no_row_under_a_loop_is_not_judged() {
            let mut straight = loop_rooted();
            straight.callee_code = BEHIND.to_vec();
            straight.callee_code_len = BEHIND.len();
            cratonvm_types::flags::with_thread_overrides(
                &[("CRATONVM_JIT_IR_SPLICE_PRUNE_NESTED", Some("0"))],
                || {
                    assert_eq!(
                        resolved_in_loop_rows(&straight, ir::SpliceFenceRelax::NONE, true),
                        None
                    );
                    assert_eq!(
                        resolved_in_loop_rows(&loop_rooted(), ir::SpliceFenceRelax::NONE, true),
                        Some(2)
                    );
                },
            );
        }
    }
}

/// Round rx27 wave 4 (lane chain, `CRATONVM_JIT_IR_CHAIN_ENTRY_SPLICE`, opt-in;
/// page `docs/known-issues/jit/rx27-chain-matcher-entry-group-and-predicate-pairs-20261028.md`):
/// the call that ENTERS a dispatch chain from a non-chain body is judged by the
/// chain link rule.
///
/// `regex-matches` runs `WORDNUM.matcher(s).matches()` per subject. With the
/// lambda spliced into the driver, `matches()` -> `match()` splice as
/// forwarder / exact rows, and `match()`'s `parentPattern.matchRoot.match(..)`
/// is a profiled nested row of `BmpCharPropertyGreedy.match` (89 bytes, with
/// calls). The plain nested rule admits a body over 35 bytes only as a leaf,
/// and the chain rule only at a call of the body's own selector, which
/// `Matcher.match(II)Z` -> `Node.match(Matcher;I;CharSequence)Z` is not. So the
/// greedy node's own artifact is called once per subject: a 928-byte frame
/// clear, a stack guard and argument moves (`rx27-w4-per-row-instruction-breakdown-20261028.md`,
/// 7.2k instr/op). HotSpot inlines it.
///
/// Under the switch a profiled nested row whose BODY is chain-shaped
/// ([`r25_w7b_chain_splice::body_is_chain_shaped`]) is admitted by
/// [`r25_w7b_chain_splice::chain_link_verdict`] (hot site, the multi-body hot
/// cap, and every call of the body spliced or its next link), in the VM's
/// resolver and the planner alike (`chain_row_admitted_in`). The planner's
/// cost rule (`strip_chain_tree`) judges it as a link, rooted when its site or
/// any site above it is in a loop. Rows, guards and miss edges are the nested
/// guarded row's, unchanged.
///
/// Census: `[cratonvm-jitc] chain-entry <cp>.match.. at callee_pc=P depth=D in
/// <body>` followed by that site's `nest-chain ... SPLICED | refused: <why>`.
pub mod rx27_chain_entry {
    use super::*;

    /// The switch (opt-in; inert without the chain switch).
    pub const SWITCH: &str = "CRATONVM_JIT_IR_CHAIN_ENTRY_SPLICE";

    /// `CRATONVM_JIT_IR_CHAIN_ENTRY_SPLICE`, under the chain switch. **Opt-in**
    /// (`=1`). It was default ON in the rx27 bundle flip of 2026-10-29
    /// ([`bundle_flip_evidence`]) and went back to opt-in the same day: on
    /// bimodal-10 (14 rows, 5 reps) it was the one bundle member that regressed
    /// `cached` (+19 %) and `split-ws` (+14 %). With it off and the deep spine
    /// on ("dse0"), `cached` read 45.1k -> 35.8k, `split-ws` 49.3k -> 42.9k,
    /// `regex-split` -5 %, every other row within 1.5 %. Read per call, no
    /// `static`.
    pub fn enabled() -> bool {
        r25_w7b_chain_splice::ir_nested_chain_splice_enabled()
            && cratonvm_types::flags::runtime_flag_on(SWITCH)
    }

    /// The rx27 bundle flip (2026-10-29, coordinator): this switch,
    /// `CRATONVM_JIT_IR_NESTED_IN_LOOP_HOT`,
    /// `CRATONVM_JIT_IR_CHAIN_BIMORPHIC_PREDICATES`,
    /// `CRATONVM_JIT_IR_CHAIN_BIMORPHIC_LINKS` and
    /// `CRATONVM_JIT_IR_SPLICE_COLD_HANDLER_ARM` turned default ON together.
    /// Evidence (lane prof, icount2 main/op, 5 reps each, against the
    /// default):
    /// * regex-matches -8.6 % (b7), -8 % (b8), -11.8 % (b9), ranges disjoint
    ///   each time;
    /// * regex-groups -11.5 % (b7), overlapping on b9;
    /// * find-email / find-ci -0.3 / -0.4 %, disjoint;
    /// * facts and the GC battery (34/34) identical under the bundle on b9.
    ///
    /// They flip together because the entry alone regressed regex-groups by
    /// 11 % (b8): it must not run without the predicate pairs.
    ///
    /// Revised the same day ("dse0", lane bimodal's A/B on bimodal-10): this
    /// switch is opt-in again (inside the bundle it cost `cached` +19 % and
    /// `split-ws` +14 %). The other four stay ON, and
    /// `CRATONVM_JIT_IR_CHAIN_DEEP_SPINE` is default ON
    /// (`rx27_deep_spine::enabled`). A doc anchor only.
    pub const fn bundle_flip_evidence() {}

    /// The VM resolver's form: may the resolved body `site` be judged as a
    /// chain entry?
    pub fn entry_body(site: &InlineSite) -> bool {
        enabled() && !site.callee_is_static && r25_w7b_chain_splice::body_is_chain_shaped(site)
    }

    /// Round rx27 wave 7 (lane chain): the receiver row a chain entry is
    /// judged by when the enclosing body's interpreted profile has none at
    /// the site (`has_row` false) and the class came from that body's own
    /// optimizing artifact (`from_guard_class`), which guard-spliced `site`
    /// there. A body over the cold cap is guard-spliced only at a site that
    /// compile judged hot (`ir_guarded_site_is_hot`), so the row carries
    /// [`r25_w7b_chain_splice::CHAIN_HOT_MIN_CALLS`] samples of `class_id`,
    /// or the enclosing body's interpreted `invocations` when that is more
    /// (the planner's frame rule divides the row by that count: one sample
    /// per invocation reads as a site run on every entry, which a site the
    /// artifact spliced unguarded-by-branch is).
    /// `Matcher.match` pc 121 is the case: `Matcher.match` compiles before
    /// the row lambda that splices it, its interpreted profile stops there,
    /// and its artifact splices the greedy node at that pc.
    pub fn artifact_hot_row(
        entry_site: bool,
        from_guard_class: bool,
        has_row: bool,
        site: &InlineSite,
        class_id: u32,
        invocations: u32,
    ) -> Option<profile::ReceiverCounts> {
        if !entry_site
            || !from_guard_class
            || has_row
            || class_id == 0
            || site.callee_code_len <= MAX_INLINE_SIZE_COLD
            || !enabled()
        {
            return None;
        }
        let mut row = profile::ReceiverCounts::default();
        row.insert(class_id, r25_w7b_chain_splice::CHAIN_HOT_MIN_CALLS.max(invocations));
        Some(row)
    }

    /// The planner's form: is nested row `n` of `parent` a chain entry -- a
    /// guarded row at a virtual or interface call of `parent` that is not a
    /// chain site of `parent`, whose body is chain-shaped?
    pub fn entry_row(parent: &InlineSite, n: &NestedInlineSite) -> bool {
        n.guard_class_id != 0
            && entry_body(&n.site)
            && !r25_w7b_chain_splice::row_is_chain(parent, n)
            && parent.invoke_targets.iter().any(|(pc, t)| {
                *pc == n.callee_pc
                    && matches!(t.invoke_kind, 0 | 2)
                    && t.class_name != "java/lang/Object"
            })
    }

    #[cfg(test)]
    mod tests {
        use super::*;
        use crate::r25_w7b_chain_splice::{chain_link_verdict, chain_row_admitted_in, strip_chain_tree};

        const MATCH_DESC: &str = "(Ljava/util/regex/Matcher;ILjava/lang/CharSequence;)Z";
        /// `iload_1; ifeq 11; aload_0; invokevirtual #2; goto 4; return`: the
        /// call at pc 5 is in a loop.
        const LOOPING: [u8; 12] = [
            0x1b, 0x99, 0x00, 0x0a, 0x2a, 0xb6, 0x00, 0x02, 0xa7, 0xff, 0xfc, 0xb1,
        ];
        /// `iload_1; ifeq 8; aload_0; invokevirtual #2; iconst_1; ireturn`:
        /// the call at pc 5 is behind a branch, in no loop.
        const BEHIND: [u8; 10] = [0x1b, 0x99, 0x00, 0x07, 0x2a, 0xb6, 0x00, 0x02, 0x04, 0xac];

        fn target(kind: u8, class: &str, name: &str, desc: &str) -> InlineInvokeTarget {
            InlineInvokeTarget {
                invoke_kind: kind,
                class_name: class.to_string(),
                method_name: name.to_string(),
                descriptor: desc.to_string(),
                ..Default::default()
            }
        }

        /// `BmpCharPropertyGreedy.match` in shape: 89 bytes, its predicate
        /// call spliced (pc 10) and its next link (pc 20).
        fn greedy() -> InlineSite {
            let mut g = InlineSite {
                callee_code: vec![0xac; 89],
                callee_code_len: 89,
                class_name: "java/util/regex/Pattern$BmpCharPropertyGreedy".to_string(),
                method_name: "match".to_string(),
                descriptor: MATCH_DESC.to_string(),
                ..InlineSite::default()
            };
            g.invoke_targets
                .push((10, target(2, "java/util/regex/Pattern$CharPredicate", "is", "(I)Z")));
            g.invoke_targets
                .push((20, target(0, "java/util/regex/Pattern$Node", "match", MATCH_DESC)));
            g.nested_sites.push(NestedInlineSite {
                callee_pc: 10,
                guard_class_id: 900,
                site: InlineSite::default(),
                bimorphic_second: None,
            });
            g
        }

        /// `Matcher.match(II)Z` in shape: its `matchRoot.match` at pc 5 holds
        /// the greedy row.
        fn matcher_match(code: &[u8]) -> InlineSite {
            let mut m = InlineSite {
                callee_code: code.to_vec(),
                callee_code_len: code.len(),
                class_name: "java/util/regex/Matcher".to_string(),
                method_name: "match".to_string(),
                descriptor: "(II)Z".to_string(),
                ..InlineSite::default()
            };
            m.invoke_targets
                .push((5, target(0, "java/util/regex/Pattern$Node", "match", MATCH_DESC)));
            m.nested_sites.push(NestedInlineSite {
                callee_pc: 5,
                guard_class_id: 608,
                site: greedy(),
                bimorphic_second: None,
            });
            m
        }

        fn pinned<R>(on: Option<&str>, f: impl FnOnce() -> R) -> R {
            cratonvm_types::flags::with_thread_overrides(
                &[
                    (SWITCH, on),
                    (r25_w7b_chain_splice::SWITCH, Some("1")),
                    ("CRATONVM_JIT_IR_NESTED_GUARDED_SPLICE", Some("1")),
                    ("CRATONVM_JIT_IR_GUARDED_SPLICE_HOT_CAP", Some("1")),
                    ("CRATONVM_JIT_IR_GUARDED_SPLICE_HOT_CAP_MULTI", Some("1")),
                    ("CRATONVM_JIT_IR_NESTED_GUARDED_HOT_CAP", Some("1")),
                    ("CRATONVM_JIT_IR_NESTED_GUARDED_HOT_CAP_LEAF", Some("1")),
                    ("CRATONVM_JIT_IR_SPLICE_NESTED_EXACT_RECEIVER", Some("1")),
                    ("CRATONVM_JIT_IR_PSPLICE_NESTED_EXACT_HOT", Some("0")),
                    ("CRATONVM_JIT_IR_SPLICE_FORWARDER_EXACT_HOT", Some("0")),
                    ("CRATONVM_JIT_IR_CHAIN_DEEP_SPINE", Some("0")),
                ],
                f,
            )
        }

        #[test]
        fn rx27_chain_entry_a_chain_body_entered_from_a_non_chain_site_is_a_link() {
            pinned(Some("1"), || {
                let parent = matcher_match(&LOOPING);
                let row = &parent.nested_sites[0];
                assert!(entry_body(&row.site));
                assert!(entry_row(&parent, row));
                assert!(!r25_w7b_chain_splice::row_is_chain(&parent, row));
                assert!(chain_row_admitted_in(&parent, row, 1), "the link rule admits it");
                // The greedy body that keeps a non-link call is refused.
                let mut lost = matcher_match(&LOOPING);
                lost.nested_sites[0].site.nested_sites.clear();
                assert!(!chain_row_admitted_in(&lost, &lost.nested_sites[0], 1));
                // A body that is no chain node is no entry.
                let mut plain = matcher_match(&LOOPING);
                plain.nested_sites[0].site.invoke_targets.truncate(1);
                assert!(!entry_row(&plain, &plain.nested_sites[0]));
            });
            pinned(Some("0"), || {
                let parent = matcher_match(&LOOPING);
                assert!(!entry_row(&parent, &parent.nested_sites[0]));
                assert!(!chain_row_admitted_in(&parent, &parent.nested_sites[0], 1));
            });
        }

        /// Round rx27 wave 7: a site the enclosing body's artifact
        /// guard-spliced the body at, with no interpreted row, is hot for
        /// the link rule (it was `ColdSite` with no row, the site not in a
        /// loop of `Matcher.match` and not on its entry prefix).
        #[test]
        fn rx27_chain_entry_an_artifact_guarded_site_is_hot() {
            pinned(Some("1"), || {
                let parent = matcher_match(&BEHIND);
                let g = &parent.nested_sites[0].site;
                assert_eq!(
                    chain_link_verdict(None, &BEHIND, BEHIND.len(), 5, g, 1),
                    Err(r25_w7b_chain_splice::ChainRefusal::ColdSite)
                );
                let row = artifact_hot_row(true, true, false, g, 586, 0).expect("artifact row");
                assert_eq!(
                    chain_link_verdict(Some(&row), &BEHIND, BEHIND.len(), 5, g, 1),
                    Ok(())
                );
                // No row from a profiled class, an existing row, a non-entry,
                // or a body within the cold cap (the artifact needed no hot
                // verdict for it).
                assert!(artifact_hot_row(true, false, false, g, 586, 0).is_none());
                assert!(artifact_hot_row(true, true, true, g, 586, 0).is_none());
                assert!(artifact_hot_row(false, true, false, g, 586, 0).is_none());
                let mut small = g.clone();
                small.callee_code_len = MAX_INLINE_SIZE_COLD;
                assert!(artifact_hot_row(true, true, false, &small, 586, 0).is_none());
            });
            pinned(Some("0"), || {
                let parent = matcher_match(&BEHIND);
                assert!(artifact_hot_row(true, true, false, &parent.nested_sites[0].site, 586, 0)
                    .is_none());
            });
        }

        /// Opt-in again since 2026-10-29 (it regressed `cached` / `split-ws`
        /// inside the bundle): unset reads off.
        #[test]
        fn rx27_chain_entry_is_opt_in() {
            let at = |entry: Option<&'static str>| {
                cratonvm_types::flags::with_thread_overrides(
                    &[(SWITCH, entry), (r25_w7b_chain_splice::SWITCH, Some("1"))],
                    enabled,
                )
            };
            assert!(!at(None));
            assert!(!at(Some("0")));
            assert!(at(Some("1")));
        }

        #[test]
        fn rx27_chain_entry_a_loop_above_roots_the_entry() {
            pinned(Some("1"), || {
                // Entry site in a loop of `Matcher.match`: kept as a link.
                let mut looped = matcher_match(&LOOPING);
                let mut keys = Vec::new();
                let report = strip_chain_tree(&mut looped, false, &mut keys);
                assert_eq!(report.kept, 1);
                assert!(keys
                    .iter()
                    .any(|k| k.starts_with("java/util/regex/Pattern$BmpCharPropertyGreedy.match")));
                // In no loop and nothing above in a loop: dropped as unrooted.
                let mut once = matcher_match(&BEHIND);
                let report = strip_chain_tree(&mut once, false, &mut Vec::new());
                assert_eq!((report.kept, report.unrooted), (0, 1));
                assert!(once.nested_sites.is_empty());
                // The top-level site in a loop of the compiling method roots it.
                let mut top = matcher_match(&BEHIND);
                assert_eq!(strip_chain_tree(&mut top, true, &mut Vec::new()).kept, 1);
            });
        }
    }
}

/// Round rx27 wave 4 (lane chain, `CRATONVM_JIT_IR_NESTED_IN_LOOP_HOT`, opt-in;
/// same page): a nested call in a loop of its enclosing body is hot.
///
/// The nested hot cap ([`ir_nested_guarded_body_cap_in`]) counted a nested row
/// hot from 256 interpreted receiver samples or on its body's entry prefix,
/// and the planner's cold prune ([`ir_splice_prune_cold_nested`]) kept a
/// statically bound nested body over 35 bytes only on the entry prefix or the
/// profiled dominant path. A call in a loop of a spliced body (the
/// `regex-groups` lambda's `m.group(1)` in its `while (m.find())` loop, once
/// the lambda is spliced into the driver) is neither, so `Matcher.group`
/// stays a call: 3.6k instr/op. HotSpot's C2 inlines a site by its frequency,
/// which a loop makes high. Under the switch:
///
/// * a site in a loop of its enclosing body takes the nested hot cap (the
///   profiled rows keep their leaf rule);
/// * a nest-exact row's tree may hold a loop there
///   ([`ir_psplice_nested_exact_row_admitted`]: `Matcher.<init>`'s `groups`
///   fill under `Pattern.matcher` in `regex-matches`);
/// * the cold prune keeps a row in a loop of its enclosing body, and every
///   row under one.
///
/// The VM's resolver and the planner read the same functions, so they agree.
/// Bounded by the hot cap, the per-compile budget and every other rule.
pub mod rx27_nested_in_loop_hot {
    use super::*;

    /// The switch (opt-in).
    pub const SWITCH: &str = "CRATONVM_JIT_IR_NESTED_IN_LOOP_HOT";

    /// `CRATONVM_JIT_IR_NESTED_IN_LOOP_HOT`. **Default ON** since the rx27
    /// bundle flip (2026-10-29, `rx27_chain_entry::bundle_flip_evidence`),
    /// `=0` kills it. Read per call, no `static`.
    pub fn enabled() -> bool {
        cratonvm_types::flags::runtime_flag_default_on(SWITCH)
    }

    /// Under the switch, is the call at `callee_pc` of `code[..code_len]` in a
    /// loop of that body?
    pub fn site_in_loop(code: &[u8], code_len: usize, callee_pc: usize) -> bool {
        enabled() && bytecode_pc_in_loop(code, code_len, callee_pc)
    }

    #[cfg(test)]
    mod tests {
        use super::*;

        /// `iload_1; ifeq 11; aload_0; invokevirtual #2; goto 4; return`: the
        /// call at pc 5 is in a loop.
        const LOOPING: [u8; 12] = [
            0x1b, 0x99, 0x00, 0x0a, 0x2a, 0xb6, 0x00, 0x02, 0xa7, 0xff, 0xfc, 0xb1,
        ];

        fn pinned<R>(on: Option<&str>, f: impl FnOnce() -> R) -> R {
            cratonvm_types::flags::with_thread_overrides(
                &[
                    (SWITCH, on),
                    ("CRATONVM_JIT_IR_NESTED_GUARDED_SPLICE", Some("1")),
                    ("CRATONVM_JIT_IR_GUARDED_SPLICE_HOT_CAP", Some("1")),
                    ("CRATONVM_JIT_IR_GUARDED_SPLICE_HOT_CAP_MULTI", Some("1")),
                    ("CRATONVM_JIT_IR_NESTED_GUARDED_HOT_CAP", Some("1")),
                    ("CRATONVM_JIT_IR_PSPLICE_NESTED_EXACT_HOT", Some("1")),
                    ("CRATONVM_JIT_IR_NESTED_HOT_CAP_BY_FREQUENCY", Some("0")),
                    ("CRATONVM_JIT_IR_SPLICE_FORWARDER_EXACT_HOT", Some("0")),
                ],
                f,
            )
        }

        /// A `Matcher.group`-sized body (60 bytes) whose code holds a loop
        /// (`LOOPING`, padded).
        fn looping_body() -> InlineSite {
            let mut code = LOOPING.to_vec();
            code.resize(60, 0x00);
            InlineSite {
                callee_code_len: code.len(),
                callee_code: code,
                class_name: "java/util/regex/Matcher".to_string(),
                method_name: "group".to_string(),
                descriptor: "(I)Ljava/lang/String;".to_string(),
                ..InlineSite::default()
            }
        }

        #[test]
        fn rx27_in_loop_a_nested_site_in_a_loop_takes_the_hot_cap() {
            pinned(Some("1"), || {
                assert_eq!(
                    ir_nested_guarded_body_cap(None, &LOOPING, LOOPING.len(), 5, 1),
                    ir_guarded_multi_body_cap(ir::GUARDED_SPLICE_HOT_MAX_BODY_BYTES, 1)
                );
                // A nest-exact body with a loop in its tree, at that site.
                assert!(ir_psplice_nested_exact_row_admitted(
                    &looping_body(),
                    None,
                    &LOOPING,
                    LOOPING.len(),
                    5,
                    1
                ));
            });
            pinned(Some("0"), || {
                assert_eq!(
                    ir_nested_guarded_body_cap(None, &LOOPING, LOOPING.len(), 5, 1),
                    MAX_INLINE_SIZE_COLD
                );
                assert!(!ir_psplice_nested_exact_row_admitted(
                    &looping_body(),
                    None,
                    &LOOPING,
                    LOOPING.len(),
                    5,
                    1
                ));
            });
        }

        #[test]
        fn rx27_in_loop_the_cold_prune_keeps_a_row_in_a_loop() {
            let tree = || {
                let mut parent = InlineSite {
                    callee_code: LOOPING.to_vec(),
                    callee_code_len: LOOPING.len(),
                    ..InlineSite::default()
                };
                parent.invoke_targets.push((
                    5,
                    InlineInvokeTarget {
                        invoke_kind: 0,
                        class_name: "java/util/regex/Matcher".to_string(),
                        method_name: "group".to_string(),
                        descriptor: "(I)Ljava/lang/String;".to_string(),
                        ..Default::default()
                    },
                ));
                // `group` (60 bytes, guard 0) with a 40-byte child of its own,
                // which runs per iteration too.
                let mut group = looping_body();
                // `iconst_0; ifeq +7; nop..`: the child's pc 9 is past a branch.
                group.callee_code = vec![0x03, 0x99, 0x00, 0x07];
                group.callee_code.resize(60, 0x00);
                group.invoke_targets.push((
                    9,
                    InlineInvokeTarget {
                        invoke_kind: 0,
                        class_name: "java/lang/CharSequence".to_string(),
                        method_name: "toString".to_string(),
                        descriptor: "()Ljava/lang/String;".to_string(),
                        ..Default::default()
                    },
                ));
                group.nested_sites.push(NestedInlineSite {
                    callee_pc: 9,
                    guard_class_id: 0,
                    site: InlineSite {
                        callee_code: vec![0x00; 40],
                        callee_code_len: 40,
                        ..InlineSite::default()
                    },
                    bimorphic_second: None,
                });
                parent.nested_sites.push(NestedInlineSite {
                    callee_pc: 5,
                    guard_class_id: 0,
                    site: group,
                    bimorphic_second: None,
                });
                parent
            };
            pinned(Some("0"), || {
                let mut t = tree();
                assert_eq!(ir_splice_prune_cold_nested(&mut t), 1, "behind the loop's branch");
                assert!(t.nested_sites.is_empty());
            });
            pinned(Some("1"), || {
                let mut t = tree();
                assert_eq!(ir_splice_prune_cold_nested(&mut t), 0);
                assert_eq!(t.nested_sites[0].site.nested_sites.len(), 1, "the row below it too");
            });
        }
    }
}

/// Round rx27 wave 4 (lane chain, `CRATONVM_JIT_IR_CHAIN_DEEP_SPINE`, default ON since 2026-10-29;
/// page `docs/internal/fixed-bugs/rx27-chain-regex-groups-spine-is-deeper-than-the-builder-frame-cap-20261028.md`):
/// a dispatch-chain spine deeper than the builder's 8 frames, with the cost
/// rule made transitive so a deeper link never trades a call per position for
/// a call per character.
///
/// `regex-groups`' `(\w+)=(\w+)` from `Matcher.search` pc 121 is `Start` 0,
/// `GroupHead` 1, `Greedy` 2, `GroupTail` 3, `BmpCharProperty` 4, `GroupHead`
/// 5, `Greedy` 6, and each `Greedy`'s `\w` predicate adds forwarder, lambda,
/// `isWord`, `isType`, `getType` (5 levels) under it. The second `Greedy`
/// therefore needs 12 splice frames. Three parts, one switch:
///
/// 1. **Frames.** [`ir::ir_max_splice_depth`] is [`SPLICE_DEPTH`] (12), and
///    so the chain tree's unset nest depth (`ir_inline_max_nest_frame_cap`)
///    is 11 plus the leaf tier. Outside chain trees the unset depth stays 6
///    (W11-7's scope rule).
/// 2. **Resume budget.** [`crate::deopt::max_osr_inline_resume_depth`] is
///    [`RESUME_DEPTH`] (13, one more than the frames, as 9 is to 8), read by
///    every admission and transfer check on both sides (the jit's OSR-exit
///    policy and chain publication, the VM's `deopt_resume` sinks). The sinks
///    build the chain in a `Vec` and refuse before the first push, so the
///    budget bounds work, not storage.
/// 3. **Transitive link rule.** The chain link rule asked only that each call
///    of the link has a row; a row that itself keeps a call counted as
///    spliced. With more frames that admits the second `Greedy` with its
///    forwarder spliced and the `\w` lambda left as a call once per
///    character (W10-3's loss). Under the switch, a link is refused
///    ([`r25_w7b_chain_splice::ChainRefusal::HalfSpliced`]) when a row at a pc
///    in a loop of the link keeps a call anywhere in its own tree
///    ([`first_half_spliced_row`]).
///
/// Census: `nest-chain ... refused: half-spliced row at body pc P` (the VM
/// resolver's chain line), `[cratonvm-jitc] chain-deep-spine splice at pc=..
/// depth=D` (the builder, per frame past 8), and the `ir-chain-tree` line's
/// `max_depth`.
pub mod rx27_deep_spine {
    use super::*;

    /// The switch (default ON since 2026-10-29, `=0` kills it; inert without
    /// the chain switch).
    pub const SWITCH: &str = "CRATONVM_JIT_IR_CHAIN_DEEP_SPINE";
    /// The builder's splice-frame cap under the switch.
    pub const SPLICE_DEPTH: usize = 12;
    /// The inline resume budget under the switch.
    pub const RESUME_DEPTH: usize = SPLICE_DEPTH + 1;

    /// `CRATONVM_JIT_IR_CHAIN_DEEP_SPINE`, under the chain switch. **Default
    /// ON** since 2026-10-29 (`=0` kills it), with
    /// `CRATONVM_JIT_IR_CHAIN_ENTRY_SPLICE` back to opt-in ("dse0", coordinator
    /// decision from lane bimodal's A/B on bimodal-10, 14 rows, 5 reps, against
    /// the bundle default):
    /// * `cached` 45.1k -> 35.8k (-21 %), `split-ws` 49.3k -> 42.9k (-13 %),
    ///   `regex-split` -5 %, ranges separate;
    /// * every other row within 1.5 %;
    /// * facts, the GC probes and `J27DeoptRows` identical in both modes.
    ///
    /// The deep spine alone lost on find-ci and matchonly only together with
    /// the entry. Read per call, no `static`.
    pub fn enabled() -> bool {
        r25_w7b_chain_splice::ir_nested_chain_splice_enabled()
            && cratonvm_types::flags::runtime_flag_default_on(SWITCH)
    }

    /// Does `site`'s tree keep a real call: a call with no nested row, other
    /// than one the inline String prefix answers (W10-3b) or a constructor
    /// (`<init>`, the exception a guard path builds)? Bimorphic second bodies
    /// are asked too.
    pub fn tree_keeps_call(site: &InlineSite) -> bool {
        let kept_here = site.invoke_targets.iter().any(|(pc, t)| {
            !site.nested_sites.iter().any(|n| n.callee_pc == *pc)
                && t.method_name != "<init>"
                && !crate::r25_w10_3b::site_answered_by_string_prefix(
                    &t.class_name,
                    &t.method_name,
                    &t.descriptor,
                    t.invoke_kind,
                )
        });
        kept_here
            || site.nested_sites.iter().any(|n| {
                tree_keeps_call(&n.site)
                    || n.bimorphic_second
                        .as_ref()
                        .is_some_and(|s| tree_keeps_call(&s.site))
            })
    }

    /// The transitive half of the chain link rule: the first row of the link
    /// body `site`, at a pc in a loop of the body and not the chain's next
    /// link, whose tree keeps a call ([`tree_keeps_call`]). Such a row runs
    /// once per loop iteration (per character in a scan), and so does the
    /// call it keeps.
    pub fn first_half_spliced_row(site: &InlineSite) -> Option<usize> {
        site.nested_sites
            .iter()
            .find(|n| {
                !r25_w7b_chain_splice::row_is_chain(site, n)
                    && bytecode_pc_in_loop(&site.callee_code, site.callee_code_len, n.callee_pc)
                    && (tree_keeps_call(&n.site)
                        || n.bimorphic_second
                            .as_ref()
                            .is_some_and(|s| tree_keeps_call(&s.site)))
            })
            .map(|n| n.callee_pc)
    }

    #[cfg(test)]
    mod tests {
        use super::*;
        use crate::r25_w7b_chain_splice::{chain_link_verdict, ChainRefusal};

        const MATCH_DESC: &str = "(Ljava/util/regex/Matcher;ILjava/lang/CharSequence;)Z";
        /// `iload_1; ifeq 11; aload_0; invokevirtual #2; goto 4; return`: the
        /// call at pc 5 is in a loop (a greedy node's scan loop, in shape).
        const LOOPING: [u8; 12] = [
            0x1b, 0x99, 0x00, 0x0a, 0x2a, 0xb6, 0x00, 0x02, 0xa7, 0xff, 0xfc, 0xb1,
        ];

        fn target(kind: u8, class: &str, name: &str, desc: &str) -> InlineInvokeTarget {
            InlineInvokeTarget {
                invoke_kind: kind,
                class_name: class.to_string(),
                method_name: name.to_string(),
                descriptor: desc.to_string(),
                ..Default::default()
            }
        }

        fn row(callee_pc: usize, guard: u32, site: InlineSite) -> NestedInlineSite {
            NestedInlineSite {
                callee_pc,
                guard_class_id: guard,
                site,
                bimorphic_second: None,
            }
        }

        /// A `\w` predicate forwarder: its one call (pc 1) is the lambda
        /// implementation, spliced (`impl_spliced`) or kept.
        fn forwarder(impl_spliced: bool) -> InlineSite {
            let mut fwd = InlineSite {
                callee_code: vec![0x2a, 0xb8, 0x00, 0x03, 0xac],
                callee_code_len: 5,
                method_name: "is".to_string(),
                descriptor: "(I)Z".to_string(),
                ..InlineSite::default()
            };
            fwd.invoke_targets
                .push((1, target(3, "P", "lambda$ASCII_WORD$0", "(I)Z")));
            if impl_spliced {
                fwd.nested_sites.push(row(
                    1,
                    0,
                    InlineSite {
                        callee_code: vec![0x04, 0xac],
                        callee_code_len: 2,
                        callee_is_static: true,
                        ..InlineSite::default()
                    },
                ));
            }
            fwd
        }

        /// A greedy link whose scan-loop call (pc 5, `predicate.is`) has the
        /// forwarder row.
        fn greedy(impl_spliced: bool) -> InlineSite {
            let mut link = InlineSite {
                callee_code: LOOPING.to_vec(),
                callee_code_len: LOOPING.len(),
                method_name: "match".to_string(),
                descriptor: MATCH_DESC.to_string(),
                ..InlineSite::default()
            };
            link.invoke_targets
                .push((5, target(2, "java/util/regex/Pattern$CharPredicate", "is", "(I)Z")));
            link.nested_sites
                .push(row(5, 900, forwarder(impl_spliced)));
            link
        }

        fn pinned<R>(deep: Option<&str>, f: impl FnOnce() -> R) -> R {
            cratonvm_types::flags::with_thread_overrides(
                &[
                    (SWITCH, deep),
                    (r25_w7b_chain_splice::SWITCH, Some("1")),
                    ("CRATONVM_JIT_IR_NESTED_GUARDED_SPLICE", Some("1")),
                    ("CRATONVM_JIT_IR_GUARDED_SPLICE_HOT_CAP", Some("1")),
                    ("CRATONVM_JIT_IR_GUARDED_SPLICE_HOT_CAP_MULTI", Some("1")),
                    ("CRATONVM_JIT_IR_NESTED_GUARDED_HOT_CAP", Some("1")),
                    ("CRATONVM_JIT_IR_NESTED_GUARDED_HOT_CAP_LEAF", Some("1")),
                    ("CRATONVM_JIT_IR_SPLICE_NESTED_EXACT_RECEIVER", Some("1")),
                    ("CRATONVM_JIT_IR_PSPLICE_NESTED_EXACT_HOT", Some("0")),
                    ("CRATONVM_JIT_IR_SPLICE_FORWARDER_EXACT_HOT", Some("0")),
                ],
                f,
            )
        }

        #[test]
        fn rx27_deep_spine_the_transitive_rule_refuses_a_half_spliced_link() {
            pinned(Some("1"), || {
                assert!(enabled());
                // The lambda left as a call under the spliced forwarder: refused.
                let half = greedy(false);
                assert_eq!(first_half_spliced_row(&half), Some(5));
                assert_eq!(
                    chain_link_verdict(None, &LOOPING, LOOPING.len(), 5, &half, 1),
                    Err(ChainRefusal::HalfSpliced(5))
                );
                assert!(ChainRefusal::HalfSpliced(5)
                    .to_string()
                    .starts_with("half-spliced row at body pc 5"));
                // The whole predicate spliced: admitted.
                let whole = greedy(true);
                assert_eq!(first_half_spliced_row(&whole), None);
                assert_eq!(
                    chain_link_verdict(None, &LOOPING, LOOPING.len(), 5, &whole, 1),
                    Ok(())
                );
                // A constructor (a guard path's exception) is no kept call.
                let mut throws = greedy(true);
                throws.nested_sites[0]
                    .site
                    .invoke_targets
                    .push((3, target(1, "java/lang/IllegalStateException", "<init>", "()V")));
                assert_eq!(first_half_spliced_row(&throws), None);
            });
            // Off: the link rule as before (the row counts as spliced).
            pinned(Some("0"), || {
                assert!(!enabled(), "killed");
                assert_eq!(
                    chain_link_verdict(None, &LOOPING, LOOPING.len(), 5, &greedy(false), 1),
                    Ok(())
                );
            });
        }

        /// Default ON since 2026-10-29 ("dse0"), `=0` kills it, and inert
        /// without the chain switch.
        #[test]
        fn rx27_deep_spine_is_default_on_with_a_kill() {
            let at = |deep: Option<&'static str>, chain: Option<&'static str>| {
                cratonvm_types::flags::with_thread_overrides(
                    &[(SWITCH, deep), (r25_w7b_chain_splice::SWITCH, chain)],
                    enabled,
                )
            };
            assert!(at(None, Some("1")));
            assert!(!at(Some("0"), Some("1")));
            assert!(!at(None, Some("0")));
        }

        #[test]
        fn rx27_deep_spine_raises_the_frame_cap_and_the_resume_budget_together() {
            pinned(Some("1"), || {
                assert_eq!(ir::ir_max_splice_depth(), SPLICE_DEPTH);
                assert_eq!(crate::deopt::max_osr_inline_resume_depth(), RESUME_DEPTH);
                assert!(crate::deopt::max_osr_inline_resume_depth() > ir::ir_max_splice_depth());
                // The unset nest depth in a chain tree is the new frame cap
                // (less the leaf tier); outside a chain tree it stays 6.
                cratonvm_types::flags::with_thread_overrides(
                    &[
                        (SWITCH, Some("1")),
                        (r25_w7b_chain_splice::SWITCH, Some("1")),
                        ("CRATONVM_JIT_IR_NESTED_CHAIN_DEPTH", None),
                        ("CRATONVM_JIT_IR_NESTED_CHAIN_DEPTH_SCOPED", None),
                        ("CRATONVM_JIT_IR_INLINE_MAX_NEST", None),
                        ("CRATONVM_JIT_IR_SPLICE_LEAF_PAST_DEPTH", Some("1")),
                        ("CRATONVM_JIT_IR_INLINE_MAX_NEST_FRAME_CLAMP", Some("1")),
                    ],
                    || {
                        assert_eq!(ir_inline_max_nest_depth_in(true), SPLICE_DEPTH - 1);
                        assert_eq!(ir_inline_max_nest_depth_in(false), MAX_IR_INLINE_NEST_DEPTH);
                    },
                );
            });
            pinned(Some("0"), || {
                assert_eq!(ir::ir_max_splice_depth(), ir::MAX_IR_SPLICE_DEPTH);
                assert_eq!(
                    crate::deopt::max_osr_inline_resume_depth(),
                    crate::deopt::MAX_OSR_INLINE_RESUME_DEPTH
                );
            });
            // Inert without the chain switch.
            cratonvm_types::flags::with_thread_overrides(
                &[(SWITCH, Some("1")), (r25_w7b_chain_splice::SWITCH, Some("0"))],
                || assert_eq!(ir::ir_max_splice_depth(), ir::MAX_IR_SPLICE_DEPTH),
            );
        }
    }
}

/// JIT r25 wave 10, lane W10-4 (`CRATONVM_JIT_IR_NESTED_LAMBDA_IFACE`,
/// default ON since the wave-10 flip, `=0` kills it; `docs/known-issues/jit/r23-w2-regex-rows-gap-is-per-call-cost-20261021.md`,
/// "Wave 10 W10-4"): profile-guarded nested rows for the interface calls inside
/// a spliced LAMBDA IMPLEMENTATION body.
///
/// The `regex-find-email` profile (host c22, default arm, `perf record -e
/// instructions:u`, `CRATONVM_JIT_PERF_MAP=1`) puts 20.5 % of user
/// instructions in the compiled body of `CharPredicates.lambda$ASCII_WORD$0`
/// and 4.1 % in `Pattern$BitClass.is`. Each is called once per character.
/// `[\w.+-]+` compiles to `BmpCharPropertyGreedy` over a UNION predicate,
/// `CharPredicate.union`'s lambda `ch -> is(ch) || p.is(ch)`. The greedy
/// node's own compile splices its `predicate.is` site as the union lambda
/// (forwarder plus `lambda$union$N`, the lambda route). That body's two
/// calls are `invokeinterface CharPredicate.is` on the captured predicates
/// (the `\w` lambda proxy and a `BitClass`), and they stay calls: one level
/// down, an interface site has a profiled nested route only under the
/// global, opt-in `CRATONVM_JIT_IR_NESTED_GUARDED_INTERFACE`.
///
/// Under this switch those sites, and only sites inside a body whose method is
/// a javac lambda implementation (`lambda$...`), take the existing
/// `nest-profiled-iface` row. That row is the callee profile's dominant class
/// (80 %, or the compiled cache's), spliced behind an exact class test, with
/// the site's unchanged interface call (and its inline cache) on the miss
/// edge. A lambda-proxy receiver resolves through the nested lambda route
/// (forwarder plus implementation). HotSpot inlines the same sites from the
/// same per-bci profile.
///
/// `CRATONVM_JIT_IR_NESTED_CHAIN_DEPTH` (W10-3) applies under this switch too:
/// the `\w` predicate's chain (`lambda$ASCII_WORD$0` -> `ASCII.isWord` ->
/// `isType` -> `getType`) ends past the default nest cap from a greedy
/// node's own compile (forwarder 0, union implementation 1, `\w` forwarder 2,
/// its implementation 3, `isWord` 4, `isType` 5, `getType` 6).
pub mod r25_w10_4_lambda_iface {
    /// The switch's token.
    pub const SWITCH: &str = "CRATONVM_JIT_IR_NESTED_LAMBDA_IFACE";

    /// `CRATONVM_JIT_IR_NESTED_LAMBDA_IFACE` (default ON since the r25 wave-10
    /// flip; `=0` kills it). Read per call, no
    /// `static`.
    pub fn ir_nested_lambda_iface_enabled() -> bool {
        cratonvm_types::flags::runtime_flag_default_on("CRATONVM_JIT_IR_NESTED_LAMBDA_IFACE")
    }

    /// Is `method` a javac lambda implementation (`lambda$<enclosing>$<n>`,
    /// JLS-unnamed, synthetic)? javac names every desugared lambda body this
    /// way. A user method can never start with `lambda$` and also be an
    /// enclosing body of a CharPredicate splice by accident, and if it does,
    /// its interface sites only take the profiled guarded row every other
    /// nested site may take.
    pub fn is_lambda_impl_name(method: &str) -> bool {
        method.starts_with("lambda$")
    }

    /// May an interface site inside the body `method` take the profiled
    /// nested row under this switch?
    pub fn admits_body(method: &str) -> bool {
        ir_nested_lambda_iface_enabled()
            && crate::ir::ir_nested_guarded_splice_enabled()
            && is_lambda_impl_name(method)
    }

    #[cfg(test)]
    mod tests {
        use super::*;

        #[test]
        fn r25_w10_4_only_lambda_bodies_open_the_interface_route() {
            assert!(is_lambda_impl_name("lambda$union$2"));
            assert!(is_lambda_impl_name("lambda$ASCII_WORD$0"));
            assert!(!is_lambda_impl_name("match"));
            assert!(!is_lambda_impl_name("is"));
            assert!(!is_lambda_impl_name("xlambda$1"));
            const NESTED: &str = "CRATONVM_JIT_IR_NESTED_GUARDED_SPLICE";
            const DEPTH: &str = "CRATONVM_JIT_IR_NESTED_CHAIN_DEPTH";
            const CHAIN: &str = "CRATONVM_JIT_IR_NESTED_CHAIN_SPLICE";
            cratonvm_types::flags::with_thread_overrides(
                &[
                    (SWITCH, Some("1")),
                    (NESTED, Some("1")),
                    (DEPTH, None),
                    (CHAIN, Some("0")),
                ],
                || {
                    assert!(admits_body("lambda$union$2"));
                    assert!(!admits_body("match"));
                    // The W10-3 depth rule rides on this switch too.
                    assert!(crate::r25_w7b_chain_splice::ir_nested_chain_depth_enabled());
                },
            );
            for (on, nested) in [
                (Some("0"), Some("0")),
                (Some("0"), Some("1")),
                (Some("1"), Some("0")),
            ] {
                cratonvm_types::flags::with_thread_overrides(
                    &[(SWITCH, on), (NESTED, nested), (DEPTH, None), (CHAIN, Some("0"))],
                    || assert!(!admits_body("lambda$union$2")),
                );
            }
            cratonvm_types::flags::with_thread_overrides(
                &[
                    (SWITCH, Some("0")),
                    (NESTED, Some("1")),
                    (DEPTH, None),
                    (CHAIN, Some("0")),
                ],
                || assert!(!crate::r25_w7b_chain_splice::ir_nested_chain_depth_enabled()),
            );
        }
    }
}

/// JIT r25 wave 10, lane W10-5 (`CRATONVM_JIT_LAMBDA_ADAPTER_SUPERSEDE`,
/// **default ON**, `=0` kill; fix): a lambda-adapter thunk stops entering a
/// superseded implementation body.
///
/// [`crate::lambda_adapter`] builds one thunk per `(proxy class,
/// implementation entry, shape)` and installs it in inline caches as if it
/// were the receiver's compiled method. The thunk tail-jumps to the fixed
/// entry it was built for. When the implementation's body is superseded (C1
/// -> C2), the supersede path retargets the caches that publish the displaced
/// BODY (`retarget_superseded_inline_caches`). The caches that publish a
/// THUNK into it hold the thunk as their owner, so they were never reached:
/// every call kept entering the C1 body, and its not-entrant stub once the
/// body was redirected. `regex-split` spent 2.9 % in `Pattern.lambda$Single$0
/// [c1]`, and `regex-find-email` 0.8 % plus 0.27 % in
/// `not-entrant-stub lambda$Single$0`.
///
/// On supersede, every thunk built for the displaced body (matched by its
/// recorded `(entry, artifact id)`, so an address the allocator reused never
/// matches) is taken out of the thunk map and treated like a superseded body:
/// it is marked `superseded`, every MIC / PIC slot holding it is cleared
/// (`retarget_superseded_inline_caches` on the THUNK), it leaves the shared
/// megamorphic table, and it is marked `retired` (refused by every installer)
/// and handed to the retirement queue. The next call through each cache
/// misses into the VM's lambda helper. The helper re-reads the site's
/// implementation body after the generation bump and builds a thunk for the
/// current body. `lambda_adapter::adapter_entry` refuses to build one for a
/// superseded body, with the same two-check pairing it uses for a retired one,
/// so a thunk raced in after this sweep is never findable.
///
/// Lifetime: a thunk roots its implementation (`_direct_callee_roots`), so the
/// displaced body stays mapped until the thunk itself leaves the retirement
/// queue. That happens once no thread can still be executing it, which is the
/// rule baked callers already follow. No new statics.
mod r25_w10_5_adapter_supersede {
    use super::*;

    impl JitCache {
        /// The supersede half for thunks into `old`. Called with `mutation`
        /// held, after `old.superseded` was set. Returns the thunks withdrawn.
        pub(crate) fn retarget_superseded_lambda_adapters(&self, old: &CompiledMethod) -> usize {
            if !crate::lambda_adapter::w10_5_supersede::lambda_adapter_supersede_enabled() {
                return 0;
            }
            let thunks = crate::lambda_adapter::w10_5_supersede::take_adapters_into(
                &self.lambda_adapters,
                old,
            );
            if thunks.is_empty() {
                return 0;
            }
            let mut cleared = 0usize;
            let count = thunks.len();
            for thunk in thunks {
                thunk_withdraw(&thunk, &mut cleared);
                if let Some(table) = self.mega_dispatch_table_if_any() {
                    table.retire_entry(thunk.entry_ptr() as usize);
                }
                defer_jit_owner(Some(thunk));
            }
            if crate::x64::dbg_jitc_enabled() {
                eprintln!(
                    "[cratonvm-jitc] lambda-adapter-supersede {} thunks={count} cache_slots_cleared={cleared}",
                    old.method_label,
                );
            }
            count
        }
    }

    /// Mark `thunk` superseded, then retired, and clear every cache slot that
    /// publishes it, adding their count to `cleared`. The superseded mark comes
    /// first, as for a body: a racing publication either lands in the holder
    /// list the walk takes, or sees the flag and withdraws itself
    /// (`note_published_owner`).
    pub(crate) fn thunk_withdraw(thunk: &Arc<CompiledMethod>, cleared: &mut usize) {
        thunk
            .superseded
            .store(true, std::sync::atomic::Ordering::Release);
        thunk
            .retired
            .store(true, std::sync::atomic::Ordering::SeqCst);
        *cleared += thunk.retarget_superseded_inline_caches();
    }

    #[cfg(test)]
    mod tests {
        use super::*;
        use crate::lambda_adapter::w10_5_supersede::take_adapters_into;
        use crate::lambda_adapter::{adapters_reaching, lambda_adapter_entry};
        use std::sync::atomic::Ordering;

        fn ret_body() -> CompiledMethod {
            let mut buf = ExecutableBuffer::new(64).expect("an executable buffer");
            buf.emit(&[0xC3]); // ret
            CompiledMethod::new(buf)
        }

        const SWITCH: &str = "CRATONVM_JIT_LAMBDA_ADAPTER_SUPERSEDE";

        #[test]
        fn r25_w10_5_a_superseded_impl_takes_its_thunks_with_it() {
            let cache = JitCache::new();
            let adapters = cache.lambda_adapters();
            cratonvm_types::flags::with_thread_overrides(&[(SWITCH, None)], || {
                let old = Arc::new(ret_body());
                let thunk = lambda_adapter_entry(adapters, 0x8000_0B01, &old, b"", 1)
                    .expect("a no-capture thunk is emitted");
                // The supersede: the flag, then the sweep.
                old.superseded.store(true, Ordering::Release);
                let taken = take_adapters_into(adapters, &old);
                assert_eq!(taken.len(), 1);
                assert_eq!(taken[0].entry_ptr() as usize, thunk);
                let mut cleared = 0;
                thunk_withdraw(&taken[0], &mut cleared);
                assert!(taken[0].retired.load(Ordering::SeqCst));
                assert!(taken[0].superseded.load(Ordering::SeqCst));
                // Gone from the map, and no new thunk is built for the
                // superseded body.
                assert!(
                    take_adapters_into(adapters, &old).is_empty()
                );
                assert!(
                    lambda_adapter_entry(adapters, 0x8000_0B01, &old, b"", 1)
                        .is_none()
                );
                // The successor gets a thunk of its own.
                let new = Arc::new(ret_body());
                let fresh = lambda_adapter_entry(adapters, 0x8000_0B01, &new, b"", 1)
                    .expect("the current body gets a thunk");
                assert_ne!(fresh, thunk);
                defer_jit_owner(Some(Arc::clone(&taken[0])));
            });
        }

        #[test]
        fn r25_w10_5_only_thunks_into_that_body_are_taken() {
            let cache = JitCache::new();
            let adapters = cache.lambda_adapters();
            cratonvm_types::flags::with_thread_overrides(&[(SWITCH, None)], || {
                let a = Arc::new(ret_body());
                let b = Arc::new(ret_body());
                lambda_adapter_entry(adapters, 0x8000_0B02, &a, b"", 1)
                    .expect("thunk a");
                let tb = lambda_adapter_entry(adapters, 0x8000_0B03, &b, b"", 1)
                    .expect("thunk b");
                a.superseded.store(true, Ordering::Release);
                let taken = take_adapters_into(adapters, &a);
                assert_eq!(taken.len(), 1);
                assert_ne!(taken[0].entry_ptr() as usize, tb);
                let reach: std::collections::HashSet<usize> =
                    [b.entry_ptr() as usize].into_iter().collect();
                assert_eq!(adapters_reaching(adapters, &reach), vec![tb]);
                for t in taken {
                    defer_jit_owner(Some(t));
                }
            });
        }

        #[test]
        fn r25_w10_5_switched_off_the_old_behaviour_stays() {
            let adapters = &crate::lambda_adapter::LambdaAdapterMap::new();
            cratonvm_types::flags::with_thread_overrides(&[(SWITCH, Some("0"))], || {
                let old = Arc::new(ret_body());
                lambda_adapter_entry(adapters, 0x8000_0B04, &old, b"", 1)
                    .expect("thunk");
                old.superseded.store(true, Ordering::Release);
                // A superseded body still gets (and keeps) its thunk.
                assert!(
                    lambda_adapter_entry(adapters, 0x8000_0B04, &old, b"", 1)
                        .is_some()
                );
                let cache = JitCache::new();
                assert_eq!(cache.retarget_superseded_lambda_adapters(&old), 0);
            });
        }
    }
}

/// JIT round 25 wave 10, lane W10-2: hot JDK leaf methods that run their
/// single-pass (`[c1]` in the perf map) body in steady state. Page:
/// `docs/internal/fixed-bugs/r25-w10-steady-state-single-pass-bodies-FIXED-20261027.md`.
///
/// The perf map's `[c1]` / `[c2]` names the BACKEND of the published body
/// (`CompiledMethod::used_ir_backend`), not the manager's tier, so a method
/// whose C2 task's optimizing attempt was refused -- an admission pin, the
/// acceptance gate -- publishes its single-pass fall-through, is settled at
/// C2, and reads `[c1]` for the rest of the run. That is what this lane
/// found for `Arrays.copyOfRange([BII)`: the String-intrinsic pin keeps it on
/// the single-pass backend because its cold throw arm builds the
/// `IllegalArgumentException` message with `StringBuilder`
/// ([`string_pin_skips_cold_throw_arms_enabled`]). That skip lost its A/B in
/// round 23 only because the IR body then copied through the bound helper
/// instead of inline; with `CRATONVM_JIT_IR_INLINE_BYTE_ARRAYCOPY` on it
/// copies inline, so the skip now follows that switch unless its own key is
/// set.
pub(crate) mod r25_w10_2_steady_c1 {
    /// With `CRATONVM_JIT_STRING_PIN_SKIPS_COLD_THROW_ARMS` unset: skip the
    /// cold throw arms' String sites exactly when the IR tier copies byte
    /// arrays inline (`CRATONVM_JIT_IR_INLINE_BYTE_ARRAYCOPY`, opt-in), so
    /// the default stays the round-23 pin and the two switches can no longer
    /// be A/B'd apart into the losing combination. Read per compile.
    pub(crate) fn cold_arm_skip_follows_inline_copy() -> bool {
        crate::ir_lower::ir_inline_byte_arraycopy_enabled()
    }

    /// `CRATONVM_JIT_IR_CONTEXT_ABI_OF_BASELINE` (JIT r25 wave 10, W10-2b;
    /// **default ON** since wave 13 (W13-2), `=0` kills). c30 named the
    /// refusal it removes on real methods: `c2-supersede <init>` and
    /// `indexOf`, `superseded body KEPT entrant (context ABI: the C1 body
    /// takes the VM context, the C2 body does not)`. It changes only a body
    /// whose graph lost every context node while its single-pass body takes
    /// one -- exactly the pairs that refusal names -- so it is a no-op
    /// everywhere else (the c27 opt-in A/B: neutral on all 8 rows). Read per
    /// compile.
    pub(crate) fn context_abi_of_baseline_enabled() -> bool {
        cratonvm_types::flags::runtime_flag_default_on("CRATONVM_JIT_IR_CONTEXT_ABI_OF_BASELINE")
    }

    /// W10-2b: `Graph::context_abi_floor` for an optimizing build of a method
    /// whose bytecode scan says `scan_needs_heap` -- the single-pass body's
    /// hidden VM-context argument (`x64::driver`: `try_new_with_context` on
    /// `needs_heap`).
    ///
    /// Why: a C2 supersede forwards the C1 body's baked callers only to a body
    /// of the same ABI (`not_entrant::supersede_forward_admissible`). A small
    /// leaf whose optimized graph lost every context-taking node -- a cold
    /// throw arm pruned to a guard, a static read only that arm used, an
    /// inlined callee -- publishes a context-free C2 body over a context-taking
    /// C1 body. The forward is then refused, the C1 body stays entrant, and
    /// every caller that baked it runs C1 for the rest of the process:
    /// `String.checkBoundsBeginEnd` (a `getstatic` + an `invokestatic`) and
    /// `Preconditions.checkFromToIndex` (an `invokestatic` in its throw arm),
    /// both accepted at C2 and still `[c1]` in the steady-state profile. With
    /// the floor the C2 body reserves the context slot (one store in its
    /// prologue, the caller's one extra argument move) and the forward
    /// applies.
    pub(crate) fn context_abi_floor(scan_needs_heap: bool) -> bool {
        scan_needs_heap && context_abi_of_baseline_enabled()
    }

    /// `CRATONVM_JIT_IR_CONTEXT_ABI_FLOOR_COUNTS_LDC` (t1 wave 9, lane LCAP;
    /// **default OFF**, `=1` enables; page
    /// `docs/known-issues/jit/t1-lcap-context-abi-floor-misses-the-driver-context-reasons-20261026.md`).
    /// Read per compile.
    pub(crate) fn context_abi_floor_counts_ldc_enabled() -> bool {
        cratonvm_types::flags::runtime_flag_on("CRATONVM_JIT_IR_CONTEXT_ABI_FLOOR_COUNTS_LDC")
    }

    /// The part of the single-pass body's context ABI that [`context_abi_floor`]
    /// cannot see: the bytecode scan leaves `needs_heap` false for a string or
    /// class `ldc`, and `x64::driver` turns the context form on afterwards
    /// (`needs_heap || !ldc_string_info.is_empty() || !ldc_class_info.is_empty()`).
    /// When the optimizing graph then loses every `ConstString`/`ConstClass`
    /// (a pruned cold arm, `ir_fold_string_literal_queries`), its body is
    /// context-free over a context-taking C1 body and
    /// `not_entrant::supersede_forward_refusal` keeps the baked callers on C1
    /// -- the refusal W10-2b removed for the scan's own reasons. Needs the
    /// W10-2b switch too: this widens that floor, it is not a second one.
    pub(crate) fn ldc_context_abi_floor(ir_ldc_takes_context: bool) -> bool {
        ir_ldc_takes_context
            && context_abi_of_baseline_enabled()
            && context_abi_floor_counts_ldc_enabled()
    }

    /// `CRATONVM_JIT_IR_CONTEXT_ABI_OF_INSTALLED` (t1 wave 10, lane LCAP2;
    /// **default OFF**, `=1` enables; pages
    /// `docs/known-issues/jit/t1-lcap-context-abi-floor-misses-the-driver-context-reasons-20261026.md`
    /// and `t1-lcap-implicit-exception-edges-give-c2-a-context-c1-lacks-20261026.md`).
    /// Read per compile.
    pub(crate) fn context_abi_of_installed_enabled() -> bool {
        cratonvm_types::flags::runtime_flag_on("CRATONVM_JIT_IR_CONTEXT_ABI_OF_INSTALLED")
    }

    /// The floor from the single-pass body's REAL entry ABI instead of the
    /// bytecode scan's: `installed` is the published body's
    /// `needs_context` (`CompileRequest::installed_body_needs_context`), the
    /// body the C2 body will supersede. Every reason the driver and the table
    /// builder widen `needs_heap` for -- a string/class `ldc`, a deferred field
    /// site, a self-locking body, and the table builder's own arms -- is in
    /// that one bit, so none is copied here. Widens the W10-2b floor (needs
    /// that switch too); `None` (no published body) adds nothing.
    pub(crate) fn installed_context_abi_floor(installed: Option<bool>) -> bool {
        installed == Some(true)
            && context_abi_of_baseline_enabled()
            && context_abi_of_installed_enabled()
    }

    /// The opposite direction: the published body is context-FREE, so a C2
    /// body that reserves the context can never take over its baked callers.
    /// The optimizing tier then withholds its implicit exception edges
    /// (`CRATONVM_JIT_IR_IMPLICIT_EXCEPTION_EDGES`), whose `CallThrew` pads
    /// are the context reason a single-pass body never has for an `idiv` /
    /// array access inside a `try` (the single-pass handler is armed only
    /// with `needs_heap`). Such a build is exactly the build with that switch
    /// off: the site deopts to the interpreter's handler, as on C1.
    pub(crate) fn installed_body_withholds_implicit_edges(installed: Option<bool>) -> bool {
        installed == Some(false) && context_abi_of_installed_enabled()
    }
}

/// `CRATONVM_JIT_IR_CONTEXT_ABI_OF_INSTALLED` for the VM's optimizing door,
/// which fills `CompileRequest::installed_body_needs_context` only under it
/// (one JIT-cache probe per optimizing compile). t1 wave 10, lane LCAP2.
pub fn ir_context_abi_of_installed_enabled() -> bool {
    r25_w10_2_steady_c1::context_abi_of_installed_enabled()
}

#[cfg(test)]
mod r25_w10_2_steady_c1_tests {
    use super::*;

    const SKIP: &str = "CRATONVM_JIT_STRING_PIN_SKIPS_COLD_THROW_ARMS";
    const COPY: &str = "CRATONVM_JIT_IR_INLINE_BYTE_ARRAYCOPY";

    /// The skip's truth table: its own key wins either way; unset, it follows
    /// the inline byte copy; both unset is the round-23 default (pinned).
    #[test]
    fn w10_2_the_cold_arm_skip_follows_the_inline_copy_unless_set() {
        // The row-bound splice, which the unset inline copy follows, pinned
        // off (it is default ON since the W10 page's retirement).
        let skip = |s: Option<&str>, c: Option<&str>| {
            cratonvm_types::flags::with_thread_overrides(
                &[(SKIP, s), (COPY, c), ("CRATONVM_JIT_IR_SPLICE_ARRAYCOPY_ROW_BOUND", Some("0"))],
                string_pin_skips_cold_throw_arms_enabled,
            )
        };
        assert!(!skip(None, None), "all unset under a switched-off splice: the round-23 pin");
        assert!(skip(None, Some("1")), "unset, it follows the inline copy");
        assert!(!skip(Some("0"), Some("1")), "=0 is the skip's own answer");
        assert!(skip(Some("1"), None), "=1 is the skip's own answer");
        assert!(!skip(None, Some("0")));
    }

    /// The pin's input on `Arrays.copyOfRange([BII)`'s shape: with the skip
    /// on, the throw arm's `StringBuilder` sites (pcs 38..51, inside the arm
    /// 26..57 the `ifge 58` at pc 23 jumps around) are not asked about, the
    /// `clone` site at pc 11 still is.
    #[test]
    fn w10_2_the_copy_of_range_arm_sites_leave_the_pin() {
        let arms = [ir::ColdThrowArm {
            branch_pc: 23,
            start: 26,
            athrow_pc: 57,
        }];
        let ops: Vec<(usize, u16, u8)> =
            vec![(11, 1, 0xb6), (34, 5, 0xb7), (38, 6, 0xb6), (51, 9, 0xb6)];
        let kept = invoke_ops_outside_arms(&ops, &arms);
        assert_eq!(kept, vec![(11, 1, 0xb6)]);
    }
}

/// JIT r25 wave 10, lane W10-3b: the two remaining costs of
/// `CRATONVM_JIT_IR_NESTED_CHAIN_SPLICE` on the `\s+` rows (`split-ws`,
/// `cached`, `matchonly`), read off the host c24 captures
/// (`docs/known-issues/jit/r23-w2-regex-rows-gap-is-per-call-cost-20261021.md`,
/// "Wave 10 W10-3b").
///
/// 1. **`CRATONVM_JIT_IR_CHAIN_STRING_PREFIX_KEPT`** (default ON under the
///    chain or lambda-body interface switch, `=0` kill). The chain rule opened
///    the profiled interface route for every interface site of a chain body,
///    `seq.charAt(i)` included. In the default build that site stays a call,
///    and the inline String prefix answers it (`IrStringSearchKind::SeqCharAt`:
///    the String class test, the coder byte, one bounds compare and a load;
///    about 22 instructions on `Start.match`'s c24 listing). Spliced, it became
///    `String.charAt` -> `isLatin1` -> `StringLatin1.charAt` -> `checkIndex`,
///    with the `COMPACT_STRINGS` static, two field reads behind the layout
///    flag, two index checks and stores and reloads: about 45 instructions per
///    character. Over ~115 characters per op that is about 2 600
///    instructions, most of the measured `split-ws` / `matchonly` loss. Under
///    the switch a site the prefix answers keeps its call (the VM resolver), and
///    the chain link rule counts it as answered rather than as a kept call
///    ([`super::r25_w7b_chain_splice::first_kept_non_link_call`]).
/// 2. **`CRATONVM_JIT_IR_CHAIN_LOOP_ROOTED_HOT`** (default ON under the chain
///    switch, `=0` kill). `matchonly` is bimodal (101 G vs 108-110 G
///    instructions). In fast runs, `Matcher.search`'s optimizing body carries
///    the `Start` -> `Greedy` chain (22 864 bytes). In slow runs it is a 7 821-byte
///    body with no `ir-chain-tree` line at all. The planner drops every nested
///    row over the cold cap under a top-level site it does not call hot
///    (`ir_splice_strip_cold_nested_hot_rows`: in a loop, or 256 recorded
///    calls), and `search`'s `root.match` site is neither when `search`
///    reaches the optimizing tier early. But a chain link that runs per
///    iteration of the top-level body's OWN loop (`Start`'s position loop)
///    is hot whatever the top-level count. Under the switch, such a tree keeps
///    its nested rows.
pub mod r25_w10_3b {
    use super::*;

    /// `CRATONVM_JIT_IR_CHAIN_STRING_PREFIX_KEPT`: see the module note. Read
    /// per site; no `static`.
    pub fn prefix_kept_enabled() -> bool {
        (r25_w7b_chain_splice::ir_nested_chain_splice_enabled()
            || r25_w10_4_lambda_iface::ir_nested_lambda_iface_enabled())
            && cratonvm_types::flags::runtime_flag_default_on(
                "CRATONVM_JIT_IR_CHAIN_STRING_PREFIX_KEPT",
            )
    }

    /// `CRATONVM_JIT_IR_CHAIN_LOOP_ROOTED_HOT`: see the module note. Read per
    /// planned site; no `static`.
    pub fn loop_rooted_hot_enabled() -> bool {
        r25_w7b_chain_splice::ir_nested_chain_splice_enabled()
            && cratonvm_types::flags::runtime_flag_default_on(
                "CRATONVM_JIT_IR_CHAIN_LOOP_ROOTED_HOT",
            )
    }

    /// Does the inline String prefix answer a call of kind `invoke_kind` to
    /// `class.name descriptor` that stays a call (the IR builder's prefix over
    /// the kept `Op::Call`)? The prefix's own gates decide: the
    /// prefix switches and the inline-field layout (`ir_string_search_prefix_handled_kind`).
    pub fn site_answered_by_string_prefix(
        class: &str,
        name: &str,
        descriptor: &str,
        invoke_kind: u8,
    ) -> bool {
        ir_string_search_prefix_handled_kind(class, name, descriptor)
            .is_some_and(|k| k.admits_invoke_kind(invoke_kind))
    }

    /// Is there, anywhere in `site`'s tree, a chain row whose site is in a
    /// loop of its enclosing body? `false` with the switch off.
    pub(crate) fn tree_has_loop_rooted_chain(site: &InlineSite) -> bool {
        loop_rooted_hot_enabled() && has_loop_rooted_chain(site)
    }

    fn has_loop_rooted_chain(site: &InlineSite) -> bool {
        site.nested_sites.iter().any(|n| {
            (n.guard_class_id != 0
                && r25_w7b_chain_splice::row_is_chain(site, n)
                && bytecode_pc_in_loop(&site.callee_code, site.callee_code_len, n.callee_pc))
                || has_loop_rooted_chain(&n.site)
        })
    }

    #[cfg(test)]
    mod tests {
        use super::*;

        const CHAIN: &str = "CRATONVM_JIT_IR_NESTED_CHAIN_SPLICE";
        const LAMBDA: &str = "CRATONVM_JIT_IR_NESTED_LAMBDA_IFACE";
        const KEPT: &str = "CRATONVM_JIT_IR_CHAIN_STRING_PREFIX_KEPT";
        const HOT: &str = "CRATONVM_JIT_IR_CHAIN_LOOP_ROOTED_HOT";
        const MATCH_DESC: &str = "(Ljava/util/regex/Matcher;ILjava/lang/CharSequence;)Z";
        /// `iload_1; ifeq 11; aload_0; invokevirtual #2; goto 4; return`.
        const LOOPING: [u8; 12] = [
            0x1b, 0x99, 0x00, 0x0a, 0x2a, 0xb6, 0x00, 0x02, 0xa7, 0xff, 0xfc, 0xb1,
        ];

        fn target(kind: u8, class: &str, name: &str, desc: &str) -> InlineInvokeTarget {
            InlineInvokeTarget {
                invoke_kind: kind,
                class_name: class.to_string(),
                method_name: name.to_string(),
                descriptor: desc.to_string(),
                ..Default::default()
            }
        }

        #[test]
        fn r25_w10_3b_the_switches_ride_on_the_chain_switches() {
            for (chain, lambda, kept, on) in [
                (Some("1"), None, None, true),
                (None, Some("1"), None, true),
                (Some("1"), None, Some("0"), false),
                (Some("0"), Some("0"), None, false),
                (None, None, None, true),
            ] {
                cratonvm_types::flags::with_thread_overrides(
                    &[(CHAIN, chain), (LAMBDA, lambda), (KEPT, kept)],
                    || assert_eq!(prefix_kept_enabled(), on),
                );
            }
            cratonvm_types::flags::with_thread_overrides(
                &[(CHAIN, Some("1")), (HOT, Some("0"))],
                || assert!(!loop_rooted_hot_enabled()),
            );
            cratonvm_types::flags::with_thread_overrides(&[(CHAIN, Some("0")), (HOT, None)], || {
                assert!(!loop_rooted_hot_enabled())
            });
        }

        #[test]
        fn r25_w10_3b_a_prefix_answered_site_is_no_kept_call() {
            // Greedy's shape: `seq.charAt` (no nested row) and the next link.
            let mut greedy = InlineSite {
                callee_code_len: 89,
                method_name: "match".to_string(),
                descriptor: MATCH_DESC.to_string(),
                ..InlineSite::default()
            };
            greedy
                .invoke_targets
                .push((21, target(2, "java/lang/CharSequence", "charAt", "(I)C")));
            greedy.invoke_targets.push((
                40,
                target(0, "java/util/regex/Pattern$Node", "match", MATCH_DESC),
            ));
            let answered =
                site_answered_by_string_prefix("java/lang/CharSequence", "charAt", "(I)C", 2);
            cratonvm_types::flags::with_thread_overrides(
                &[(CHAIN, Some("1")), (KEPT, None)],
                || {
                    // Whatever the prefix's own gates say on this build, the
                    // link rule follows them exactly.
                    assert_eq!(
                        r25_w7b_chain_splice::first_kept_non_link_call(&greedy),
                        if answered { None } else { Some(21) }
                    );
                },
            );
            cratonvm_types::flags::with_thread_overrides(
                &[(CHAIN, Some("1")), (KEPT, Some("0"))],
                || {
                    assert_eq!(
                        r25_w7b_chain_splice::first_kept_non_link_call(&greedy),
                        Some(21)
                    );
                },
            );
            // A static call or another selector is never answered as charAt.
            assert!(!site_answered_by_string_prefix(
                "java/lang/CharSequence",
                "charAt",
                "(I)C",
                3
            ));
            assert!(!site_answered_by_string_prefix(
                "java/util/regex/Pattern$Node",
                "match",
                MATCH_DESC,
                0
            ));
        }

        #[test]
        fn r25_w10_3b_a_loop_rooted_chain_keeps_the_tree_hot() {
            let row = NestedInlineSite {
                callee_pc: 5,
                guard_class_id: 608,
                site: InlineSite::default(),
                bimorphic_second: None,
            };
            let mut start = InlineSite {
                callee_code: LOOPING.to_vec(),
                callee_code_len: LOOPING.len(),
                method_name: "match".to_string(),
                descriptor: MATCH_DESC.to_string(),
                invoke_targets: vec![(
                    5,
                    target(0, "java/util/regex/Pattern$Node", "match", MATCH_DESC),
                )],
                ..InlineSite::default()
            };
            start.nested_sites.push(row.clone());
            // `search`'s top-level body, holding Start as a non-chain row.
            let mut search = InlineSite {
                method_name: "search".to_string(),
                descriptor: "(I)Z".to_string(),
                invoke_targets: vec![(
                    3,
                    target(0, "java/util/regex/Pattern$Node", "match", MATCH_DESC),
                )],
                ..InlineSite::default()
            };
            search.nested_sites.push(NestedInlineSite {
                callee_pc: 3,
                guard_class_id: 592,
                site: start.clone(),
                bimorphic_second: None,
            });
            cratonvm_types::flags::with_thread_overrides(
                &[(CHAIN, Some("1")), (HOT, None)],
                || {
                    assert!(tree_has_loop_rooted_chain(&search));
                    assert!(tree_has_loop_rooted_chain(&start));
                    // The same chain call outside a loop roots nothing.
                    let mut flat = start.clone();
                    flat.callee_code = vec![0x2a, 0x2a, 0x2a, 0x2a, 0x2a, 0xb6, 0x00, 0x02, 0xac];
                    flat.callee_code_len = flat.callee_code.len();
                    assert!(!tree_has_loop_rooted_chain(&flat));
                },
            );
            cratonvm_types::flags::with_thread_overrides(&[(CHAIN, Some("0")), (HOT, None)], || {
                assert!(!tree_has_loop_rooted_chain(&search));
            });
        }
    }
}

#[cfg(test)]
mod r25w10_splice_anewarray_tests {
    //! JIT round 25 wave 10 (W10-6, `CRATONVM_JIT_IR_SPLICE_ANEWARRAY`): a
    //! spliced body's `anewarray` rows are rebased into the builder's table,
    //! or the body keeps its call.

    use super::*;

    const SWITCH: &str = "CRATONVM_JIT_IR_SPLICE_ANEWARRAY";
    const COMPONENT: u32 = 0x0000_4242;

    /// Append `site` at caller pc 3 of a 10-byte caller (base 10).
    fn append(site: InlineSite) -> (Result<(), &'static str>, ir::IrInlineTables) {
        let mut combined = vec![0u8; 10];
        let mut tables = ir::IrInlineTables::default();
        let mut owned_strings: Vec<Box<str>> = Vec::new();
        let mut owned_invoke_infos: Vec<Box<JitInvokeInfo>> = Vec::new();
        let mut direct_callee_entries: Vec<(usize, u64)> = Vec::new();
        let mut budget = IR_INLINE_MAX_TOTAL_BYTES;
        let mut vcalls: Vec<(usize, usize)> = Vec::new();
        let mut compact: HashMap<(usize, bool), (u32, bool, u8)> = HashMap::new();
        let mut static_init: Vec<u32> = Vec::new();
        let mut direct_calls: Vec<(usize, (usize, bool))> = Vec::new();
        let mut checkcast_seen = false;
        let mut volatile: Vec<usize> = Vec::new();
        let mut exact_nested: Vec<(usize, u32)> = Vec::new();
        let result = append_ir_inline_site(
            site,
            3,
            &mut combined,
            &mut tables,
            &mut owned_strings,
            &mut owned_invoke_infos,
            &mut direct_callee_entries,
            &mut budget,
            &mut vcalls,
            &mut compact,
            false,
            false,
            &mut static_init,
            &mut direct_calls,
            &mut checkcast_seen,
            &mut volatile,
            &mut exact_nested,
            None,
            &|_, _, _| None,
            ir::SpliceFenceRelax::NONE,
            false,
        );
        (result, tables)
    }

    /// `static Object[] m(int n) { return new Object[n]; }`:
    /// `0: iload_0  1: anewarray #2  4: areturn`.
    fn body(rows: Vec<(usize, u32)>) -> InlineSite {
        InlineSite {
            callee_code: vec![0x1a, 0xbd, 0x00, 0x02, 0xb0, 0, 0],
            callee_code_len: 5,
            callee_max_locals: 1,
            callee_num_args: 1,
            callee_is_static: true,
            return_type: b'L',
            class_name: "p/Host".to_string(),
            class_id: 7,
            method_name: "m".to_string(),
            descriptor: "(I)[Ljava/lang/Object;".to_string(),
            ir_anewarray_info: rows,
            ..Default::default()
        }
    }

    #[test]
    fn r25w10_the_switch_is_default_on_with_a_zero_kill() {
        let read = ir::ir_splice_anewarray_enabled;
        // Default ON since j27 2026-10-28 (WARNING j27-user-flip-20261028).
        assert!(cratonvm_types::flags::with_thread_overrides(&[(SWITCH, None)], read));
        assert!(!cratonvm_types::flags::with_thread_overrides(&[(SWITCH, Some("0"))], read));
        assert!(cratonvm_types::flags::with_thread_overrides(&[(SWITCH, Some("1"))], read));
    }

    #[test]
    fn r25w10_a_resolved_anewarray_row_is_rebased() {
        cratonvm_types::flags::with_thread_overrides(&[(SWITCH, Some("1"))], || {
            let (result, tables) = append(body(vec![(1, COMPONENT)]));
            assert_eq!(result, Ok(()));
            assert_eq!(tables.anewarray_info, HashMap::from([(11usize, COMPONENT)]));
        });
    }

    /// A row on another opcode, a missing row, a duplicate, a class id of 0,
    /// or any row with the switch off: the body keeps its call, and no table
    /// gains a row.
    #[test]
    fn r25w10_a_row_set_it_cannot_vouch_for_refuses_the_body() {
        cratonvm_types::flags::with_thread_overrides(&[(SWITCH, Some("1"))], || {
            for rows in [
                vec![(0, COMPONENT)],
                Vec::new(),
                vec![(1, COMPONENT), (1, COMPONENT)],
                vec![(1, 0)],
            ] {
                let (result, tables) = append(body(rows.clone()));
                assert_eq!(result, Err("ir-splice-anewarray-row-mismatch"), "{rows:?}");
                assert!(tables.anewarray_info.is_empty(), "{rows:?}");
            }
        });
        // `=0` is the only OFF since the j27 default-ON flip.
        cratonvm_types::flags::with_thread_overrides(&[(SWITCH, Some("0"))], || {
            let (result, tables) = append(body(vec![(1, COMPONENT)]));
            assert_eq!(result, Err("ir-splice-anewarray-off"), "=0");
            assert!(tables.anewarray_info.is_empty());
        });
    }

    /// A body with no `anewarray` and no row is untouched by the switch.
    #[test]
    fn r25w10_a_body_without_anewarray_needs_no_switch() {
        let mut site = body(Vec::new());
        // `0: iload_0  1: newarray int  3: areturn`.
        site.callee_code = vec![0x1a, 0xbc, 0x0a, 0xb0, 0, 0];
        site.callee_code_len = 4;
        site.descriptor = "(I)[I".to_string();
        assert_eq!(ir_splice_anewarray_rows_ok(&site), Ok(()));
        for v in [None, Some("1")] {
            cratonvm_types::flags::with_thread_overrides(&[(SWITCH, v)], || {
                let (result, tables) = append(site.clone());
                assert_eq!(result, Ok(()), "{v:?}");
                assert!(tables.anewarray_info.is_empty());
            });
        }
    }

    /// The builder end to end: a caller `static Object[] c(int n) { return
    /// m(n); }` with `m` spliced and its `anewarray` row in the inline tables
    /// builds one reference `Op::NewArray` of the row's component class;
    /// without the row the build bails (which is why the rebase refuses a
    /// body that cannot vouch for every site).
    #[test]
    fn r25w10_the_builder_allocates_a_spliced_reference_array_from_the_row() {
        // Caller: `0: iload_0  1: invokestatic #1  4: areturn`, base 5.
        let build = |with_row: bool| {
            let mut combined = vec![0x1a, 0xb8, 0x00, 0x01, 0xb0];
            let base = combined.len();
            combined.extend_from_slice(&[0x1a, 0xbd, 0x00, 0x02, 0xb0]);
            let mut b = ir::IrBuilder::new(1, 1);
            b.set_param_types(&[ir::IrType::Int]);
            let mut tables = ir::IrInlineTables::default();
            tables.sites.insert(
                1,
                ir::IrInlineSite {
                    base,
                    code_len: 5,
                    num_args: 1,
                    max_locals: 1,
                    arg_local_slots: vec![0],
                    returns_value: true,
                    receiver_is_arg0: false,
                    method_key: "p/Host.m:(I)[Ljava/lang/Object;".to_string(),
                    class_id: 7,
                },
            );
            if with_row {
                tables.anewarray_info.insert(base + 1, COMPONENT);
            }
            b.apply_inline_tables(tables);
            b.build(&combined, base)
        };
        let graph = build(true).expect("the spliced anewarray builds from its row");
        let arrays: Vec<_> = graph
            .nodes
            .iter()
            .filter(|n| matches!(n.op, ir::Op::NewArray { element_type: 0, .. }))
            .collect();
        assert_eq!(arrays.len(), 1);
        assert!(matches!(
            arrays[0].op,
            ir::Op::NewArray { element_type: 0, component_class_id } if component_class_id == COMPONENT
        ));
        assert!(build(false).is_none(), "no row: the builder bails the method");
    }
}

/// JIT r25 wave 11 (W11-2): `Arrays.copyOfRange([BII)` spliced into its
/// optimizing callers (`StringLatin1.newString`, and through it `substring`,
/// `subSequence`, `Matcher.group`, `Pattern.split`), as HotSpot inlines it.
///
/// What refused it: neither the String-intrinsic pin (the resolver masks the
/// cold `IllegalArgumentException` arm, so its `StringBuilder` rows never
/// reach `splice_loses_string_intrinsic`), nor `arraylength` (single-pass
/// only), nor the allocation (`newarray` lowers in a splice), nor the byte
/// budget (82 bytes). It is the planner's unbindable-call rule: the body's
/// surviving `System.arraycopy` is a statically bound row with no
/// `direct_entry` (a native: the resolver's binder declines it), so
/// `append_ir_inline_site` refused the site
/// (`ir-splice-refused ir-splice-unbindable-surviving-call
/// java/util/Arrays.copyOfRange([BII)[B at pc=16 in
/// java/lang/StringLatin1.newString`), and as a nested body the VM's resolver
/// turned it back into its call (`ir_splice_body_has_unbindable_call`). The
/// premise is false for that one row: after the build every
/// `System.arraycopy` call node, relocated ones included, is bound to
/// `ir_arraycopy_entry`'s direct helper with its inline prefixes -- the rule
/// `CRATONVM_JIT_IR_SPLICE_PAST_ARRAYCOPY` already relies on in the resolver.
/// JIT round 22 (lane memory; MEM20-8's residual): a spliced body's
/// `Reference.reachabilityFence(Object)` row and the unbindable-call rule.
///
/// JDK 25's `DirectByteBuffer.getInt(J)I` (and every other scoped buffer
/// accessor) ends in `finally { Reference.reachabilityFence(this); }`. The
/// resolver keeps the fence as a call row ("kept as a keep-alive call") and
/// never binds it (the empty body is never compiled), so the unbindable-call
/// rule refused every splice that carried one: `ByteBuffer.getInt(I)I` stayed
/// a real call in each caller loop, once per access. The builder never emits
/// that call: it builds the row as an [`ir::Op::KeepAlive`] (a use of the
/// referent at that point, no code; `CRATONVM_JIT_IR_REACHABILITY_FENCE_KEEPALIVE`),
/// for spliced rows as for the method's own. So such a row is no unbindable
/// call.
pub(crate) mod r22_fence_row {
    use crate::InlineInvokeTarget;

    /// `CRATONVM_JIT_IR_SPLICE_FENCE_ROW_KEEPALIVE` (perf, **default ON**,
    /// `=0` restores the refusal). Read per row, no static.
    pub(crate) fn enabled() -> bool {
        cratonvm_types::flags::runtime_flag_default_on("CRATONVM_JIT_IR_SPLICE_FENCE_ROW_KEEPALIVE")
    }

    /// Does the unbound row `t` of a spliced body count as bound for the
    /// unbindable-call rule? Only the static `reachabilityFence(Object)`, and
    /// only while the builder takes it as a keep-alive.
    pub(crate) fn counts_keepalive(t: &InlineInvokeTarget) -> bool {
        t.invoke_kind == 3
            && t.direct_entry.is_none()
            && crate::is_reachability_fence_site(&t.class_name, &t.method_name, &t.descriptor)
            && crate::ir::ir_reachability_fence_keepalive_enabled()
            && enabled()
    }
}

#[cfg(test)]
mod r22_fence_row_tests {
    use super::*;

    fn row(kind: u8, class: &str, method: &str, desc: &str) -> InlineInvokeTarget {
        InlineInvokeTarget {
            class_name: class.to_string(),
            method_name: method.to_string(),
            descriptor: desc.to_string(),
            invoke_kind: kind,
            direct_entry: None,
            ..InlineInvokeTarget::default()
        }
    }

    /// Only the static fence row counts, only while both switches hold; a
    /// bound row is not this rule's question.
    #[test]
    fn r22_only_the_static_fence_row_counts_as_a_keepalive() {
        let fence = row(
            3,
            "java/lang/ref/Reference",
            "reachabilityFence",
            "(Ljava/lang/Object;)V",
        );
        let keepalive = |key: &str, value: Option<&str>| {
            cratonvm_types::flags::with_thread_overrides(&[(key, value)], || {
                r22_fence_row::counts_keepalive(&fence)
            })
        };
        const ROW: &str = "CRATONVM_JIT_IR_SPLICE_FENCE_ROW_KEEPALIVE";
        const BUILDER: &str = "CRATONVM_JIT_IR_REACHABILITY_FENCE_KEEPALIVE";
        assert!(keepalive(ROW, None));
        assert!(!keepalive(ROW, Some("0")));
        assert!(!keepalive(BUILDER, Some("0")));
        assert!(!r22_fence_row::counts_keepalive(&row(
            3,
            "java/lang/ref/Reference",
            "reachabilityFence",
            "()V"
        )));
        assert!(!r22_fence_row::counts_keepalive(&row(
            2,
            "java/lang/ref/Reference",
            "reachabilityFence",
            "(Ljava/lang/Object;)V"
        )));
        let mut bound = fence.clone();
        bound.direct_entry = Some((0x1000, false));
        assert!(!r22_fence_row::counts_keepalive(&bound));
        // The rule itself: a body whose only unbound row is the fence has no
        // unbindable call.
        let site = InlineSite {
            class_name: "java/nio/DirectByteBuffer".to_string(),
            method_name: "getInt".to_string(),
            descriptor: "(I)I".to_string(),
            callee_code: vec![0xac; 24],
            callee_code_len: 24,
            invoke_targets: vec![(16, fence.clone())],
            ..InlineSite::default()
        };
        let unbindable = |value: Option<&str>| {
            cratonvm_types::flags::with_thread_overrides(
                &[("CRATONVM_JIT_IR_SPLICE_FENCE_ROW_KEEPALIVE", value)],
                || ir_splice_body_has_unbindable_call(&site),
            )
        };
        assert!(!unbindable(None));
        assert!(unbindable(Some("0")));
    }
}

pub(crate) mod r25_w11_2_arraycopy_row {
    use crate::InlineInvokeTarget;

    /// `CRATONVM_JIT_IR_SPLICE_ARRAYCOPY_ROW_BOUND` (perf, **default ON**
    /// since 2026-10-27, `=0` kill). With its own key unset it also turns on
    /// the inline byte copy (`CRATONVM_JIT_IR_INLINE_BYTE_ARRAYCOPY`) and,
    /// through that, the String pin's cold-throw-arm skip. The 64.177 A/B of
    /// the three together (r25 W10 page's retirement): instructions per op
    /// -27 % `regex-groups` (40280 -> 29396), -27 % `split-ws`, -29 %
    /// `regex-split` (quiesced `icount2`, 3 reps); thread-CPU ns/op lower on
    /// all five rows (7 interleaved reps); `facts` = HotSpot.
    /// Read per row, no static.
    pub(crate) fn enabled() -> bool {
        cratonvm_types::flags::runtime_flag_default_on("CRATONVM_JIT_IR_SPLICE_ARRAYCOPY_ROW_BOUND")
    }

    /// Does the unbound statically bound row `t` of a spliced body count as
    /// bound for the unbindable-call rule? Only a static `System.arraycopy`,
    /// under the switch, when the post-build bind applies
    /// (`crate::ir_splice_keeps_arraycopy_bind`: its descriptor and gates).
    pub(crate) fn counts_bound(t: &InlineInvokeTarget) -> bool {
        t.invoke_kind == 3
            && t.direct_entry.is_none()
            && enabled()
            // JIT r25 wave 13 (W13-2): only with the inline byte copy (which
            // this switch implies when its own key is unset): c30 measured the
            // splice alone 22-27 % slower, so that arm is unreachable.
            && crate::ir_lower::ir_inline_byte_arraycopy_enabled()
            && crate::ir_splice_keeps_arraycopy_bind(&t.class_name, &t.method_name, &t.descriptor)
    }
}

#[cfg(test)]
mod r25_w11_2_arraycopy_row_tests {
    use super::*;

    const KEY: &str = "CRATONVM_JIT_IR_SPLICE_ARRAYCOPY_ROW_BOUND";
    const ARRAYCOPY: &str = "(Ljava/lang/Object;ILjava/lang/Object;II)V";

    fn row(kind: u8, class: &str, method: &str, desc: &str) -> InlineInvokeTarget {
        InlineInvokeTarget {
            class_name: class.to_string(),
            method_name: method.to_string(),
            descriptor: desc.to_string(),
            invoke_kind: kind,
            direct_entry: None,
            ..InlineInvokeTarget::default()
        }
    }

    /// The JDK 25 `Arrays.copyOfRange([BII)` rows that survive a splice, as
    /// the resolver hands them over: `byte[].clone()` (virtual), `Math.min`
    /// (a scalar row) and `System.arraycopy` (static, unbound).
    fn copy_of_range() -> InlineSite {
        InlineSite {
            class_name: "java/util/Arrays".to_string(),
            method_name: "copyOfRange".to_string(),
            descriptor: "([BII)[B".to_string(),
            callee_is_static: true,
            callee_code: vec![0xb0; 82],
            callee_code_len: 82,
            invoke_targets: vec![
                (11, row(0, "[B", "clone", "()Ljava/lang/Object;")),
                (73, row(3, "java/lang/Math", "min", "(II)I")),
                (76, row(3, "java/lang/System", "arraycopy", ARRAYCOPY)),
            ],
            ..InlineSite::default()
        }
    }

    fn with<R>(on: Option<&str>, f: impl FnOnce() -> R) -> R {
        cratonvm_types::flags::with_thread_overrides(
            &[
                (KEY, on),
                ("CRATONVM_JIT_IR_SPLICE_PAST_ARRAYCOPY", Some("1")),
                ("CRATONVM_JIT_IR_ARRAYCOPY", Some("1")),
            ],
            f,
        )
    }

    /// Only the static arraycopy row, only under the switch, only when the
    /// post-build bind applies.
    #[test]
    fn w11_2_only_an_arraycopy_row_counts_bound() {
        let copy = row(3, "java/lang/System", "arraycopy", ARRAYCOPY);
        assert_eq!(
            with(None, || r25_w11_2_arraycopy_row::counts_bound(&copy)),
            with(Some("1"), || r25_w11_2_arraycopy_row::counts_bound(&copy)),
            "default ON"
        );
        assert!(!with(Some("0"), || r25_w11_2_arraycopy_row::counts_bound(
            &copy
        )));
        with(Some("1"), || {
            assert_eq!(
                r25_w11_2_arraycopy_row::counts_bound(&copy),
                ir_splice_keeps_arraycopy_bind("java/lang/System", "arraycopy", ARRAYCOPY),
                "exactly the bind's own gates"
            );
            assert!(!r25_w11_2_arraycopy_row::counts_bound(&row(
                3,
                "java/lang/System",
                "arraycopy",
                "()V"
            )));
            assert!(!r25_w11_2_arraycopy_row::counts_bound(&row(
                3,
                "r22/NeverCompiled",
                "fold",
                "(C)C"
            )));
            let mut bound = copy.clone();
            bound.direct_entry = Some((0x1000, false));
            assert!(
                !r25_w11_2_arraycopy_row::counts_bound(&bound),
                "already bound"
            );
            let mut virt = copy.clone();
            virt.invoke_kind = 0;
            assert!(!r25_w11_2_arraycopy_row::counts_bound(&virt));
        });
        cratonvm_types::flags::with_thread_overrides(
            &[(KEY, Some("1")), ("CRATONVM_JIT_IR_ARRAYCOPY", Some("0"))],
            || {
                assert!(
                    !r25_w11_2_arraycopy_row::counts_bound(&copy),
                    "no bind, no exemption"
                )
            },
        );
    }

    /// `copyOfRange`'s body: the unbindable-call rule refused it for its
    /// arraycopy row alone; with the switch (and the bind) it does not, and
    /// any other unbound static still does.
    #[test]
    fn w11_2_copy_of_range_is_no_unbindable_body_under_the_switch() {
        if !ir_splice_refuse_unbindable_call_enabled() {
            return; // the rule is off in this process: nothing to exempt.
        }
        let site = copy_of_range();
        let min_lowered = ir_spliced_scalar_row("java/lang/Math", "min", "(II)I", 3).is_some();
        if min_lowered {
            assert!(
                with(Some("0"), || ir_splice_body_has_unbindable_call(&site)),
                "switched off: the arraycopy row refuses the body"
            );
        }
        with(Some("1"), || {
            if !ir_splice_keeps_arraycopy_bind("java/lang/System", "arraycopy", ARRAYCOPY) {
                return;
            }
            if min_lowered {
                assert!(!ir_splice_body_has_unbindable_call(&site));
                let nested = NestedInlineSite {
                    callee_pc: 16,
                    site: site.clone(),
                    ..NestedInlineSite::default()
                };
                assert!(!ir_splice_nested_entry_refused(&nested, None, true));
            }
            let mut other = site.clone();
            other
                .invoke_targets
                .push((79, row(3, "r22/NeverCompiled", "fold", "(C)C")));
            assert!(ir_splice_body_has_unbindable_call(&other));
        });
    }

    /// Source pins: the exemption sits in all three copies of the rule.
    #[test]
    fn w11_2_every_copy_of_the_rule_asks_the_exemption() {
        let lib = include_str!("lib.rs").replace("\r\n", "\n");
        let asks = lib
            .matches(concat!("&& !r25_w11_2_", "arraycopy_row::counts_bound(t)"))
            .count();
        assert_eq!(asks, 3, "append, nested-entry and the VM's body question");
        let append = lib
            .split("fn append_ir_inline_site(")
            .nth(1)
            .expect("append_ir_inline_site");
        let refusal = append
            .find("return Err(\"ir-splice-unbindable-surviving-call\");")
            .expect("the refusal");
        assert!(append[..refusal].contains("r25_w11_2_arraycopy_row::counts_bound(t)"));
    }
}

#[cfg(test)]
#[cfg(target_arch = "x86_64")]
mod r25_w10_2b_context_abi_tests {
    use super::*;

    const FLOOR: &str = "CRATONVM_JIT_IR_CONTEXT_ABI_OF_BASELINE";

    /// The floor: on unless killed, only for a method whose single-pass body
    /// takes the context.
    #[test]
    fn w10_2b_the_floor_needs_the_switch_and_a_context_taking_baseline() {
        let floor = |v: Option<&str>, heap: bool| {
            cratonvm_types::flags::with_thread_overrides(&[(FLOOR, v)], || {
                r25_w10_2_steady_c1::context_abi_floor(heap)
            })
        };
        assert!(floor(None, true), "W13-2: default ON");
        assert!(floor(Some("1"), true));
        assert!(
            !floor(Some("1"), false),
            "no context in the baseline, none forced"
        );
        assert!(!floor(Some("0"), true));
    }

    /// t1 wave 9 (lane LCAP): the ldc widening is opt-in, needs an ldc row,
    /// and never outlives the W10-2b kill.
    #[test]
    fn t1_lcap_the_ldc_floor_needs_its_switch_the_floor_and_an_ldc_row() {
        const LDC: &str = "CRATONVM_JIT_IR_CONTEXT_ABI_FLOOR_COUNTS_LDC";
        let floor = |base: Option<&str>, ldc: Option<&str>, row: bool| {
            cratonvm_types::flags::with_thread_overrides(&[(FLOOR, base), (LDC, ldc)], || {
                r25_w10_2_steady_c1::ldc_context_abi_floor(row)
            })
        };
        assert!(!floor(None, None, true), "default OFF");
        assert!(floor(None, Some("1"), true));
        assert!(!floor(None, Some("1"), false), "no ldc row, no floor");
        assert!(!floor(Some("0"), Some("1"), true), "the W10-2b kill wins");
        let lib = include_str!("lib.rs").replace("\r\n", "\n");
        assert!(lib.contains("ir_ldc_takes_context = !strs.is_empty() || !classes.is_empty();"));
        assert!(lib.contains(
            "graph.context_abi_floor |=\n                    r25_w10_2_steady_c1::ldc_context_abi_floor(ir_ldc_takes_context);"
        ));
    }

    /// t1 wave 10 (lane LCAP2): the installed body's real ABI as the floor
    /// (and, context-free, as the implicit-edge withhold) is opt-in, needs a
    /// published body, and the floor never outlives the W10-2b kill.
    #[test]
    fn t1_lcap2_the_installed_abi_floor_and_withhold_need_their_switch() {
        const INST: &str = "CRATONVM_JIT_IR_CONTEXT_ABI_OF_INSTALLED";
        let floor = |base: Option<&str>, inst: Option<&str>, body: Option<bool>| {
            cratonvm_types::flags::with_thread_overrides(&[(FLOOR, base), (INST, inst)], || {
                r25_w10_2_steady_c1::installed_context_abi_floor(body)
            })
        };
        assert!(!floor(None, None, Some(true)), "default OFF");
        assert!(floor(None, Some("1"), Some(true)));
        assert!(!floor(None, Some("1"), Some(false)), "a context-free body forces none");
        assert!(!floor(None, Some("1"), None), "no published body, no floor");
        assert!(!floor(Some("0"), Some("1"), Some(true)), "the W10-2b kill wins");
        let withhold = |inst: Option<&str>, body: Option<bool>| {
            cratonvm_types::flags::with_thread_overrides(&[(INST, inst)], || {
                r25_w10_2_steady_c1::installed_body_withholds_implicit_edges(body)
            })
        };
        assert!(!withhold(None, Some(false)), "default OFF");
        assert!(withhold(Some("1"), Some(false)));
        assert!(!withhold(Some("1"), Some(true)));
        assert!(!withhold(Some("1"), None));
        let lib = include_str!("lib.rs").replace("\r\n", "\n");
        assert!(lib.contains(
            "graph.context_abi_floor |= r25_w10_2_steady_c1::installed_context_abi_floor(\n                    req.installed_body_needs_context,\n                );"
        ));
        assert!(lib.contains(
            "builder.set_implicit_throw_edges_withheld(\n        r25_w10_2_steady_c1::installed_body_withholds_implicit_edges(\n            req.installed_body_needs_context,\n        ),\n    );"
        ));
    }

    /// EXECUTED. `int f(int a) { return a + 1; }` needs no context; with the
    /// floor its optimizing body takes one anyway (the baseline's ABI), and
    /// both bodies answer the same for every argument.
    #[test]
    fn w10_2b_a_floored_body_takes_the_context_and_answers_the_same() {
        // iload_0; iconst_1; iadd; ireturn
        let code = [0x1a, 0x04, 0x60, 0xac, 0, 0];
        let lower_with = |floor: bool| -> CompiledMethod {
            let mut builder = ir::IrBuilder::new(1, 1);
            builder.set_param_types(&[ir::IrType::Int]);
            let mut graph = builder.build(&code, 4).expect("IR build");
            ir_optimize::optimize(&mut graph);
            graph.context_abi_floor = floor;
            let schedule = ir_schedule::schedule(&graph);
            // SAFETY: `JitRuntimeHelpers` is `#[repr(C)]` and every field is a `usize`, so all-zero is a valid value; this body calls no helper.
            let helpers: JitRuntimeHelpers = unsafe { std::mem::zeroed() };
            ir_lower::lower(&graph, &schedule, 1, 1, &helpers).expect("the body lowers")
        };
        let plain = lower_with(false);
        let floored = lower_with(true);
        assert!(
            !plain.needs_context(),
            "the graph alone asks for no context"
        );
        assert!(floored.needs_context(), "the floor reserves it");
        for a in [0i64, 1, -1, 41, i64::from(i32::MAX)] {
            // SAFETY: both bodies were compiled by this test for one `int` argument; the context word is never read by an arithmetic body.
            let p = unsafe { plain.try_call_with_context(0, &[a]) }.expect("runs");
            // SAFETY: as above.
            let f = unsafe { floored.try_call_with_context(0, &[a]) }.expect("runs");
            assert_eq!(p as u32 as i32, f as u32 as i32, "a={a}");
            // Cast: Java's `int` arithmetic on the low half.
            assert_eq!(f as u32 as i32, (a as i32).wrapping_add(1), "a={a}");
        }
    }

    /// Source pins: the production pipeline sets the floor from the bytecode
    /// scan, and the frame-needs scan starts from it.
    #[test]
    fn w10_2b_the_floor_is_wired_where_the_frame_is_sized() {
        let lib = include_str!("lib.rs").replace("\r\n", "\n");
        assert!(lib.contains(
            "graph.context_abi_floor = r25_w10_2_steady_c1::context_abi_floor(scan.needs_heap);"
        ));
        let lower = include_str!("ir_lower.rs").replace("\r\n", "\n");
        let scan = lower
            .split(
                "fn scan_frame_needs(graph: &Graph, helpers: &JitRuntimeHelpers) -> FrameNeeds {",
            )
            .nth(1)
            .expect("scan_frame_needs is in ir_lower.rs");
        let floor = scan
            .find("let mut needs_context = graph.context_abi_floor;")
            .expect("the floor");
        let first = scan.find("for n in &graph.nodes {").expect("the scan loop");
        assert!(floor < first);
    }
}

#[cfg(test)]
mod r25_w13_2_row_bound_pairs_inline_copy_tests {
    use super::*;

    const ROW: &str = "CRATONVM_JIT_IR_SPLICE_ARRAYCOPY_ROW_BOUND";
    const COPY: &str = "CRATONVM_JIT_IR_INLINE_BYTE_ARRAYCOPY";
    const DESC: &str = "(Ljava/lang/Object;ILjava/lang/Object;II)V";

    fn copy_row() -> InlineInvokeTarget {
        InlineInvokeTarget {
            class_name: "java/lang/System".to_string(),
            method_name: "arraycopy".to_string(),
            descriptor: DESC.to_string(),
            invoke_kind: 3,
            direct_entry: None,
            ..InlineInvokeTarget::default()
        }
    }

    /// c30: the row-bound splice without the inline copy lost 22-27 %. Unset,
    /// the copy follows the splice switch; killed, the splice is not admitted.
    #[test]
    fn w13_2_the_losing_arm_is_unreachable() {
        let both = |row: Option<&str>, copy: Option<&str>| {
            cratonvm_types::flags::with_thread_overrides(
                &[
                    (ROW, row),
                    (COPY, copy),
                    ("CRATONVM_JIT_IR_SPLICE_PAST_ARRAYCOPY", Some("1")),
                    ("CRATONVM_JIT_IR_ARRAYCOPY", Some("1")),
                ],
                || {
                    (
                        crate::ir_lower::ir_inline_byte_arraycopy_enabled(),
                        r25_w11_2_arraycopy_row::counts_bound(&copy_row()),
                        ir_splice_keeps_arraycopy_bind("java/lang/System", "arraycopy", DESC),
                    )
                },
            )
        };
        // Default ON since the r25 W10 page's retirement: both, together.
        let (copy, bound, bind) = both(None, None);
        assert!(copy, "both on by default");
        assert_eq!(bound, bind);
        let (copy, bound, _) = both(Some("0"), None);
        assert!(!copy && !bound, "the kill turns both off");
        let (copy, bound, bind) = both(Some("1"), None);
        assert!(copy, "the splice switch implies the inline copy");
        assert_eq!(bound, bind);
        let (copy, bound, _) = both(Some("1"), Some("0"));
        assert!(!copy);
        assert!(!bound, "no inline copy: the splice is not admitted");
        let (copy, bound, _) = both(Some("0"), Some("1"));
        assert!(copy && !bound, "the copy alone admits no splice");
    }
}

/// JIT round 21 (lane lambda2, TLOCAL21-1 / LAMBDATRAP21-3): the door's plan
/// of SAM calls built as their lambda's impl call (`ir_lambda_impl_plan`):
/// which receivers straight-line code proves, which rows it rewrites, and the
/// switch.
#[cfg(test)]
mod jr21_lambda2_plan_tests {
    use super::*;

    const OWN: (&str, &str, &str) = ("p/Host", "k", "(I)I");

    fn answer(
        captures: usize,
        sam: (&str, &str),
        desc: &str,
    ) -> compile_request::IndyLambdaImplAnswer {
        compile_request::IndyLambdaImplAnswer {
            proxy_class_id: 0x8000_0021,
            num_captures: captures,
            sam_name: sam.0.to_string(),
            sam_descriptor: sam.1.to_string(),
            class: "p/Host".to_string(),
            name: "lambda$k$0".to_string(),
            descriptor: desc.to_string(),
            class_id: 0x7121,
        }
    }

    fn names(cp_idx: u16) -> Option<(String, String, String)> {
        match cp_idx {
            2 => Some((
                "java/util/function/IntSupplier".to_string(),
                "getAsInt".to_string(),
                "()I".to_string(),
            )),
            3 => Some((
                "java/util/function/IntSupplier".to_string(),
                "toString".to_string(),
                "()Ljava/lang/String;".to_string(),
            )),
            _ => None,
        }
    }

    fn plan(code: &[u8], invoke_ops: &[(usize, u16, u8)], indy_pc: usize) -> IrLambdaImplPlan {
        let lambdas = HashMap::from([(
            indy_pc,
            (1u16, 1usize, answer(1, ("getAsInt", "()I"), "(I)I")),
        )]);
        let shapes = HashMap::from([(indy_pc, (1usize, b'L'))]);
        let names: &dyn Fn(u16) -> Option<(String, String, String)> = &names;
        ir_lambda_impl_plan(
            Some(names),
            &lambdas,
            &shapes,
            code,
            code.len(),
            &[],
            invoke_ops,
            true,
            OWN,
            &|_| false,
            None,
        )
    }

    //  0: iload_0  1: invokedynamic #1 (I)L  6: astore_1  7: aload_1
    //  8: invokeinterface #2 getAsInt()I, 1  13: ireturn
    const CAPTURE: [u8; 14] = [
        0x1a, 0xba, 0x00, 0x01, 0x00, 0x00, 0x4c, 0x2b, 0xb9, 0x00, 0x02, 0x01, 0x00, 0xac,
    ];

    #[test]
    fn a_sam_call_on_a_stored_lambda_is_planned_as_its_impl() {
        let p = plan(&CAPTURE, &[(8, 2, 0xb9)], 1);
        assert_eq!(p.site_count(), 1);
        assert_eq!(
            p.names(1),
            Some((
                "p/Host".to_string(),
                "lambda$k$0".to_string(),
                "(I)I".to_string()
            ))
        );
        assert_eq!(p.class_id(1), Some(0x7121));
        assert_eq!(p.rewritten_invoke_ops(&[(8, 2, 0xb9)]), vec![(8, 1, 0xb8)]);
        assert_eq!(
            p.builder_sites(),
            HashMap::from([(8usize, (1usize, 1usize, 1usize))])
        );
    }

    #[test]
    fn a_sam_call_directly_on_the_invokedynamic_is_planned_too() {
        //  0: iload_0  1: invokedynamic #1 (I)L  6: invokeinterface #2, 1  11: ireturn
        let code = [
            0x1a, 0xba, 0x00, 0x01, 0x00, 0x00, 0xb9, 0x00, 0x02, 0x01, 0x00, 0xac,
        ];
        let p = plan(&code, &[(6, 2, 0xb9)], 1);
        assert_eq!(
            p.builder_sites(),
            HashMap::from([(6usize, (1usize, 1usize, 1usize))])
        );
    }

    #[test]
    fn unproven_or_foreign_calls_keep_the_interface_call() {
        // Another method of the interface (not the SAM).
        assert!(plan(&CAPTURE, &[(8, 3, 0xb9)], 1).is_empty());
        // The planned lambda is not the one the slot holds.
        assert!(plan(&CAPTURE, &[(8, 2, 0xb9)], 99).is_empty());
        // A branch target between the store and the load.
        //  0: iload_0  1: invokedynamic  6: astore_1  7: goto +3  10: aload_1
        // 11: invokeinterface #2, 1  16: ireturn
        let joined = [
            0x1a, 0xba, 0x00, 0x01, 0x00, 0x00, 0x4c, 0xa7, 0x00, 0x03, 0x2b, 0xb9, 0x00, 0x02,
            0x01, 0x00, 0xac,
        ];
        assert!(plan(&joined, &[(11, 2, 0xb9)], 1).is_empty());
        // The slot is written again between the store and the load.
        //  0: iload_0  1: invokedynamic  6: astore_1  7: aconst_null  8: astore_1
        //  9: aload_1  10: invokeinterface #2, 1  15: ireturn
        let rewritten = [
            0x1a, 0xba, 0x00, 0x01, 0x00, 0x00, 0x4c, 0x01, 0x4c, 0x2b, 0xb9, 0x00, 0x02, 0x01,
            0x00, 0xac,
        ];
        assert!(plan(&rewritten, &[(10, 2, 0xb9)], 1).is_empty());
        // The impl is the compiling method itself.
        let lambdas = HashMap::from([(
            1usize,
            (1u16, 1usize, answer(1, ("getAsInt", "()I"), "(I)I")),
        )]);
        let shapes = HashMap::from([(1usize, (1usize, b'L'))]);
        let names: &dyn Fn(u16) -> Option<(String, String, String)> = &names;
        let own = ("p/Host", "lambda$k$0", "(I)I");
        assert!(ir_lambda_impl_plan(
            Some(names),
            &lambdas,
            &shapes,
            &CAPTURE,
            CAPTURE.len(),
            &[],
            &[(8, 2, 0xb9)],
            true,
            own,
            &|_| false,
            None,
        )
        .is_empty());
        // An unresolved (first-call) site, and the static-call gate off.
        for (static_calls, unresolved) in [(true, true), (false, false)] {
            assert!(ir_lambda_impl_plan(
                Some(names),
                &lambdas,
                &shapes,
                &CAPTURE,
                CAPTURE.len(),
                &[],
                &[(8, 2, 0xb9)],
                static_calls,
                OWN,
                &|_| unresolved,
                None,
            )
            .is_empty());
        }
    }

    #[test]
    fn the_switch_is_default_on_and_zero_kills_it() {
        let key = "CRATONVM_JIT_IR_LAMBDA_IMPL_CALL";
        cratonvm_types::flags::with_thread_overrides(&[(key, None)], || {
            assert!(ir_lambda_impl_call_enabled())
        });
        cratonvm_types::flags::with_thread_overrides(&[(key, Some("0"))], || {
            assert!(!ir_lambda_impl_call_enabled())
        });
    }
}

/// JIT round 21, lane revjit2: the optimizing OSR door's blind megamorphic
/// splice decline counts the published body's inline capacity -- the MIC plus
/// four ways under `CRATONVM_JIT_IC_MIC_PLUS_FOUR` -- so a five-class callee
/// site no longer declines the splice its own slot serves inline.
#[cfg(test)]
mod jr21_revjit2_blind_mega_capacity_tests {
    use super::*;

    /// `0: nop  1: invokestatic #5  4: pop  5: goto 0  8: return`.
    const CODE: [u8; 11] = [0x00, 0xb8, 0, 5, 0x57, 0xa7, 0xff, 0xfb, 0xb1, 0, 0];

    /// `aload_0; iload_1; invokeinterface #7, 2, 0; ireturn`: callee pc 2.
    fn site_body() -> InlineSite {
        let code = vec![0x2a, 0x1b, 0xb9, 0, 7, 2, 0, 0xac, 0, 0];
        InlineSite {
            callee_code_len: code.len() - 2,
            callee_code: code,
            callee_max_locals: 2,
            callee_num_args: 2,
            callee_is_static: true,
            return_type: b'I',
            class_name: "p/Main".to_string(),
            class_id: 42,
            method_name: "site".to_string(),
            descriptor: "(Lp/V;I)I".to_string(),
            ..InlineSite::default()
        }
    }

    /// `classes` receiver classes, 20 observations each, at callee pc 2.
    fn ask(classes: u32) -> Option<(usize, usize)> {
        let resolve = |_: &str, _: &str, _: &str| Some(site_body());
        let lookup = |_: u32, _: &str, _: &str| {
            let mut p = profile::MethodProfile::default();
            p.receivers
                .insert(2, (0..classes).map(|c| (100 + c, 20)).collect());
            Some(p)
        };
        let at = OsrSpliceCandidate {
            pc: 1,
            invoke_kind: 3,
            class_name: "p/Main",
            method_name: "site",
            descriptor: "(Lp/V;I)I",
        };
        osr_door_blind_megamorphic_splice_site(&CODE, 9, 0, &[at], &resolve, &lookup)
    }

    #[test]
    fn a_five_class_site_declines_only_without_the_fifth_inline_class() {
        const DECLINE: &str = "CRATONVM_JIT_OSR_DECLINE_BLIND_MEGA_SPLICE";
        const PLUS_FOUR: &str = "CRATONVM_JIT_IC_MIC_PLUS_FOUR";
        cratonvm_types::flags::with_thread_overrides(
            &[(DECLINE, Some("1")), (PLUS_FOUR, None)],
            || {
                assert_eq!(ask(5), None, "MIC + four ways hold five classes");
                assert_eq!(ask(6), Some((1, 2)), "a sixth class overflows");
            },
        );
        cratonvm_types::flags::with_thread_overrides(
            &[(DECLINE, Some("1")), (PLUS_FOUR, Some("0"))],
            || assert_eq!(ask(5), Some((1, 2)), "=0: four inline classes, as before"),
        );
    }
}

/// JIT round 21 (lane tl2, `CRATONVM_JIT_IR_SPLICE_TL_THIN`): a spliced body's
/// surviving `ThreadLocal.get()` / `set(Object)` call finds the thin helper's
/// cell; nothing else does, and `=0` finds none.
#[cfg(test)]
mod jr21_tl2_splice_tl_thin_tests {
    use super::*;

    #[test]
    fn jr21_tl2_only_the_two_thread_local_rows_find_a_cell() {
        let table = DirectHelperTable {
            thread_local_get: 0x7100,
            thread_local_set: 0x7200,
            ..DirectHelperTable::EMPTY
        };
        let get = "()Ljava/lang/Object;";
        let set = "(Ljava/lang/Object;)V";
        cratonvm_types::flags::with_thread_overrides(
            &[("CRATONVM_JIT_IR_SPLICE_TL_THIN", None)],
            || {
                for cn in ["java/lang/ThreadLocal", "java/lang/InheritableThreadLocal"] {
                    assert_eq!(
                        spliced_thread_local_thin_cell(&table, cn, "get", get),
                        Some(0x7100)
                    );
                    assert_eq!(
                        spliced_thread_local_thin_cell(&table, cn, "set", set),
                        Some(0x7200)
                    );
                    assert_eq!(
                        spliced_thread_local_thin_cell(&table, cn, "remove", "()V"),
                        None
                    );
                    let private_get = "(Ljava/lang/Thread;)Ljava/lang/Object;";
                    assert_eq!(
                        spliced_thread_local_thin_cell(&table, cn, "get", private_get),
                        None,
                        "the private get(Thread) body is real bytecode"
                    );
                }
                assert_eq!(
                    spliced_thread_local_thin_cell(
                        &table,
                        "jdk/internal/misc/TerminatingThreadLocal",
                        "get",
                        get
                    ),
                    None
                );
            },
        );
        cratonvm_types::flags::with_thread_overrides(
            &[("CRATONVM_JIT_IR_SPLICE_TL_THIN", Some("0"))],
            || {
                assert_eq!(
                    spliced_thread_local_thin_cell(&table, "java/lang/ThreadLocal", "get", get),
                    None
                );
            },
        );
    }

    /// Text pin: the closure asks the policy questions the own-site ladder
    /// asks, and `append_ir_inline_site` keeps `invokespecial` rows off the
    /// helper (its decline edge re-dispatches virtually).
    #[test]
    fn jr21_tl2_the_spliced_bind_keeps_the_own_site_gates() {
        let src = include_str!("lib.rs").replace("\r\n", "\n");
        let closure = &src[src
            .find("let spliced_thin_helper = |cn: &str, mn: &str, desc: &str|")
            .expect("the closure")..];
        let arm = &closure[closure
            .find("spliced_thread_local_thin_cell(direct_helpers, cn, mn, desc)")
            .expect("the arm")..];
        let arm = &arm[..arm
            .find("is_unsafe_accessor_op(cn, mn, desc)")
            .expect("next arm")];
        for needle in [
            "jdk_only && thread_local_get_direct_enabled()",
            "direct_native_helper(",
            "direct_bind_admission",
            "note_thread_local_get_direct_site()",
        ] {
            assert!(arm.contains(needle), "{needle}");
        }
        assert!(src.contains("t.invoke_kind == 0\n                    || !thread_local_thin_row("));
    }
}

/// JIT round 21 (lane lambda3; `CRATONVM_JIT_IR_LAMBDA_IMPL_SPLICED_CAPTURES`):
/// a capturing lambda's SAM call stays its impl call only where the impl
/// splices -- the plan drops a capturing call whose splice a rebuild dropped,
/// and the per-site census names the route and the proxy.
#[cfg(test)]
mod jr21_lambda3_tests {
    use super::*;

    const PROXY: u32 = 0x8000_0031;

    fn site(captures: usize, pcs: Vec<(usize, usize)>) -> IrLambdaImplSite {
        IrLambdaImplSite {
            pcs,
            class: "p/Host".to_string(),
            name: "lambda$k$0".to_string(),
            desc: "(II)I".to_string(),
            class_id: 0x7131,
            captures,
        }
    }

    fn plan(rows: Vec<(u16, IrLambdaImplSite)>) -> IrLambdaImplPlan {
        IrLambdaImplPlan {
            by_cp: rows.into_iter().collect(),
        }
    }

    #[test]
    fn a_dropped_splice_unplans_only_the_capturing_call_there() {
        let p = plan(vec![
            (1, site(2, vec![(10, 5), (30, 5)])),
            (2, site(0, vec![(20, 15)])),
            (3, site(1, vec![(40, 35)])),
        ])
        .without_capture_pcs(&[10, 20, 40]);
        // The capturing entry keeps its other call; the non-capturing call at
        // a dropped pc is kept; an entry left with no call is gone.
        assert_eq!(p.site_count(), 2);
        assert_eq!(
            p.builder_sites(),
            HashMap::from([(30usize, (5usize, 2usize, 2usize)), (20, (15, 0, 2))])
        );
        assert!(p.names(3).is_none());
        assert_eq!(
            p.rewritten_invoke_ops(&[(10, 9, 0xb9), (30, 9, 0xb9), (40, 9, 0xb9)]),
            vec![(10, 9, 0xb9), (30, 1, 0xb8), (40, 9, 0xb9)]
        );
        // Nothing to drop: the plan is unchanged.
        let q = plan(vec![(1, site(2, vec![(10, 5)]))]).without_capture_pcs(&[]);
        assert_eq!(q.site_count(), 1);
    }

    #[test]
    fn the_census_names_the_call_route_and_the_proxy() {
        let mut g = ir::Graph::empty(8);
        g.add(
            ir::Op::New {
                class_id: PROXY,
                num_fields: 2,
            },
            ir::IrType::Ref,
            vec![],
            Some(5),
        );
        g.lambda_proxy_alloc_classes.insert(PROXY);
        g.add(
            ir::Op::Call { info_ptr: 0 },
            ir::IrType::Int,
            vec![],
            Some(10),
        );
        let p = plan(vec![
            (1, site(2, vec![(10, 5)])),
            (2, site(0, vec![(20, 15)])),
        ]);
        let none: HashMap<usize, (usize, bool)> = HashMap::new();
        let no_cells: HashMap<usize, usize> = HashMap::new();
        let lines = p.census_lines(&g, &none, &no_cells);
        assert_eq!(lines.len(), 2);
        assert!(
            lines[0].starts_with("pc=10 indy_pc=5 impl=p/Host.lambda$k$0(II)I captures=2"),
            "{}",
            lines[0]
        );
        assert!(
            lines[0].contains("call=generic calls=1 proxy=kept"),
            "{}",
            lines[0]
        );
        assert!(
            lines[1].contains("call=spliced calls=0 proxy=singleton"),
            "{}",
            lines[1]
        );
        let bound: HashMap<usize, (usize, bool)> = HashMap::from([(10usize, (0x1000usize, false))]);
        let lines = p.census_lines(&g, &bound, &no_cells);
        assert!(lines[0].contains("call=bound"), "{}", lines[0]);
        let cells: HashMap<usize, usize> = HashMap::from([(10usize, 0x2000usize)]);
        let lines = p.census_lines(&g, &none, &cells);
        assert!(lines[0].contains("call=late-cell"), "{}", lines[0]);
        // The proxy's `New` gone (scalar-replaced) and the call spliced.
        for n in g.nodes.iter_mut() {
            n.op = ir::Op::Dead;
        }
        let lines = p.census_lines(&g, &none, &no_cells);
        assert!(
            lines[0].contains("call=spliced calls=0 proxy=elided"),
            "{}",
            lines[0]
        );
    }

    #[test]
    fn capturing_sites_are_default_on_and_a_trapped_indy_is_named() {
        let key = "CRATONVM_JIT_IR_LAMBDA_IMPL_CAPTURING";
        cratonvm_types::flags::with_thread_overrides(&[(key, None)], || {
            assert!(ir_lambda_impl_capturing_enabled())
        });
        cratonvm_types::flags::with_thread_overrides(&[(key, Some("0"))], || {
            assert!(!ir_lambda_impl_capturing_enabled())
        });
        let mut g = ir::Graph::empty(4);
        g.site_trap_pcs.push(5);
        let p = plan(vec![(1, site(2, vec![(10, 5)]))]);
        let none: HashMap<usize, (usize, bool)> = HashMap::new();
        let no_cells: HashMap<usize, usize> = HashMap::new();
        let lines = p.census_lines(&g, &none, &no_cells);
        assert!(lines[0].contains("proxy=trapped"), "{}", lines[0]);
    }

    #[test]
    fn the_switch_is_default_on_and_zero_kills_it() {
        let key = "CRATONVM_JIT_IR_LAMBDA_IMPL_SPLICED_CAPTURES";
        cratonvm_types::flags::with_thread_overrides(&[(key, None)], || {
            assert!(ir_lambda_impl_spliced_captures_enabled())
        });
        cratonvm_types::flags::with_thread_overrides(&[(key, Some("0"))], || {
            assert!(!ir_lambda_impl_spliced_captures_enabled())
        });
    }

    /// The retry without the plan runs only after every other retry declined
    /// (`ir_tier`'s last arm), and only for an attempt that planned a call.
    #[test]
    fn the_tier_retries_once_without_the_plan_last() {
        let src = include_str!("lib.rs");
        let tier: String = src
            .split("\nfn ir_tier(")
            .nth(1)
            .expect("ir_tier is in this file")
            .split("\nfn ")
            .next()
            .unwrap_or("")
            .chars()
            .filter(|c| !c.is_whitespace())
            .collect();
        let rebuild = tier
            .find("letSome(site)=rebuild_without")
            .expect("the splice rebuild arm");
        let retry = tier
            .find("lambda_plan_withheld=true;continue;")
            .expect("the lambda retry");
        assert!(rebuild < retry);
        assert!(tier.contains("iflambda_plan_built&&!lambda_plan_withheld"));
    }
}

#[cfg(test)]
mod jr21_ci_nested_case_prefix_tests {
    use super::*;

    /// JIT round 21, lane ci: the three Latin-1 case statics (as statics
    /// only) are what the VM's resolver drops from a nested body to a bound
    /// call; any other site, and `=0`, keeps the nested body.
    #[test]
    fn only_the_latin1_case_statics_leave_a_nested_body_for_a_bound_call() {
        const L1: &str = "java/lang/StringLatin1";
        const CASE: &str = "(Ljava/lang/String;[BLjava/util/Locale;)Ljava/lang/String;";
        let ask = || {
            [
                ir_splice_nested_case_prefix_stays_call(L1, "compareToCI", "([B[B)I", 3),
                ir_splice_nested_case_prefix_stays_call(L1, "toLowerCase", CASE, 3),
                ir_splice_nested_case_prefix_stays_call(L1, "toUpperCase", CASE, 3),
                ir_splice_nested_case_prefix_stays_call(L1, "compareToCI", "([B[B)I", 0),
                ir_splice_nested_case_prefix_stays_call(L1, "equals", "([B[B)Z", 3),
                ir_splice_nested_case_prefix_stays_call(
                    "java/lang/String",
                    "equals",
                    "(Ljava/lang/Object;)Z",
                    0,
                ),
            ]
        };
        let on = cratonvm_types::flags::with_thread_overrides(
            &[
                ("CRATONVM_JIT_IR_STRING_SEARCH_PREFIX", None),
                ("CRATONVM_JIT_IR_LATIN1_CASE_NESTED_TO_CALL", None),
            ],
            ask,
        );
        assert_eq!(on, [true, true, true, false, false, false]);
        let off = cratonvm_types::flags::with_thread_overrides(
            &[
                ("CRATONVM_JIT_IR_STRING_SEARCH_PREFIX", None),
                ("CRATONVM_JIT_IR_LATIN1_CASE_NESTED_TO_CALL", Some("0")),
            ],
            ask,
        );
        assert_eq!(off, [false; 6]);
    }
}

#[cfg(test)]
mod jr21_lambda3_w15_in_splice_tests {
    //! JIT round 21 wave 15, lane lambda3 (LAMBDACAP21-2,
    //! `CRATONVM_JIT_IR_LAMBDA_IMPL_IN_SPLICE`): a SAM call inside a spliced
    //! body on a lambda that body built gets its impl grafted as a nested
    //! splice, and the append registers the builder's row only for an impl it
    //! appended.

    use super::*;

    const PROXY: u32 = 0x7000_0051;
    const BRIDGE: usize = 0x5150;
    const INNER_PROXY: u32 = 0x7000_0052;
    const INNER_BRIDGE: usize = 0x5151;

    /// `static int <name>(int j) { IntSupplier s = () -> j; return
    /// s.getAsInt(); }`: `0: iload_0  1: invokedynamic #2 (I)L..IntSupplier;
    /// 6: astore_1  7: aload_1  8: invokeinterface #3 IntSupplier.getAsInt()I
    /// 13: ireturn`.
    fn lambda_body(name: &str, proxy: u32, bridge: usize) -> InlineSite {
        InlineSite {
            callee_code: vec![
                0x1a, 0xba, 0x00, 0x02, 0x00, 0x00, 0x4c, 0x2b, 0xb9, 0x00, 0x03, 0x01, 0x00, 0xac,
                0, 0,
            ],
            callee_code_len: 14,
            callee_max_locals: 2,
            callee_num_args: 1,
            callee_is_static: true,
            return_type: b'I',
            class_name: "p/Host".to_string(),
            class_id: 7,
            method_name: name.to_string(),
            descriptor: "(I)I".to_string(),
            invoke_targets: vec![(
                8,
                InlineInvokeTarget {
                    class_name: "java/util/function/IntSupplier".to_string(),
                    method_name: "getAsInt".to_string(),
                    descriptor: "()I".to_string(),
                    num_jit_args: 1,
                    return_type: b'I',
                    invoke_kind: 2,
                    declaring_class_id: 7,
                    ..Default::default()
                },
            )],
            ir_indy_capture_rows: vec![(1, proxy, vec![b'I'])],
            ir_indy_capture_sites: vec![(1, bridge)],
            ..Default::default()
        }
    }

    fn kernel() -> InlineSite {
        lambda_body("f", PROXY, BRIDGE)
    }

    fn answer(proxy: u32, name: &str) -> compile_request::IndyLambdaImplAnswer {
        compile_request::IndyLambdaImplAnswer {
            proxy_class_id: proxy,
            num_captures: 1,
            sam_name: "getAsInt".to_string(),
            sam_descriptor: "()I".to_string(),
            class: "p/Host".to_string(),
            name: name.to_string(),
            descriptor: "(I)I".to_string(),
            class_id: 7,
        }
    }

    /// `private static int lambda$f$0(int j) { return j; }`.
    fn impl_body(code_len: usize) -> InlineSite {
        InlineSite {
            callee_code: vec![0x1a, 0xac, 0, 0],
            callee_code_len: code_len,
            callee_max_locals: 1,
            callee_num_args: 1,
            callee_is_static: true,
            return_type: b'I',
            class_name: "p/Host".to_string(),
            class_id: 7,
            method_name: "lambda$f$0".to_string(),
            descriptor: "(I)I".to_string(),
            ..Default::default()
        }
    }

    const OWN: (&str, &str, &str) = ("p/Caller", "run", "(II)I");

    fn graft(site: &mut InlineSite, capturing: bool, impl_len: usize) -> usize {
        let impls = |bridge: usize| (bridge == BRIDGE).then(|| answer(PROXY, "lambda$f$0"));
        let resolver = move |c: &str, n: &str, d: &str| {
            (c == "p/Host" && n == "lambda$f$0" && d == "(I)I").then(|| impl_body(impl_len))
        };
        ir_graft_spliced_lambda_impls(site, &impls, &resolver, capturing, OWN, false, 0)
    }

    #[test]
    fn jr21w15_a_capturing_sam_call_in_a_body_gets_its_impl_grafted() {
        let mut site = kernel();
        assert_eq!(graft(&mut site, true, 2), 1);
        assert_eq!(site.ir_lambda_impl_rows, vec![(8, 1, 1, 1)]);
        assert_eq!(site.nested_sites.len(), 1);
        assert_eq!(site.nested_sites[0].callee_pc, 8);
        assert_eq!(site.nested_sites[0].guard_class_id, 0);
        assert_eq!(site.nested_sites[0].site.method_name, "lambda$f$0");
        // The SAM call's own row stays: a refused impl leaves the call.
        assert_eq!(site.invoke_targets.len(), 1);
    }

    #[test]
    fn jr21w15_nothing_is_grafted_without_the_proof_or_the_answer() {
        // Capturing sites switched off.
        let mut site = kernel();
        assert_eq!(graft(&mut site, false, 2), 0);
        assert!(site.nested_sites.is_empty() && site.ir_lambda_impl_rows.is_empty());
        // Another SAM (a default method, say) is another call.
        let mut site = kernel();
        site.invoke_targets[0].1.method_name = "other".to_string();
        assert_eq!(graft(&mut site, true, 2), 0);
        // The loaded slot is not the one the lambda was stored to.
        let mut site = kernel();
        // astore_2: the lambda goes to slot 2, and nothing in the window
        // writes the slot the aload_1 reads.
        site.callee_code[6] = 0x4d;
        assert_eq!(graft(&mut site, true, 2), 0);
        // No bridge site for the capture row: the VM cannot be asked.
        let mut site = kernel();
        site.ir_indy_capture_sites.clear();
        assert_eq!(graft(&mut site, true, 2), 0);
        // A proxy the answer does not name.
        let mut site = kernel();
        site.ir_indy_capture_rows[0].1 = PROXY + 1;
        assert_eq!(graft(&mut site, true, 2), 0);
        // A synchronized body is never grafted into.
        let mut site = kernel();
        site.callee_is_synchronized = true;
        assert_eq!(graft(&mut site, true, 2), 0);
        // The impl is the compiling method itself.
        let mut site = kernel();
        let impls = |bridge: usize| (bridge == BRIDGE).then(|| answer(PROXY, "lambda$f$0"));
        let resolver = |_: &str, _: &str, _: &str| Some(impl_body(2));
        let own = ("p/Host", "lambda$f$0", "(I)I");
        assert_eq!(ir_graft_spliced_lambda_impls(&mut site, &impls, &resolver, true, own, false, 0), 0);
    }

    /// LAMBDA321-6 (t1 wave 8): the outer lambda's impl builds and applies its
    /// own lambda; that inner SAM call gets the inner impl grafted inside the
    /// grafted outer impl.
    #[test]
    fn t1w8_a_graft_inside_a_grafted_impl() {
        let impls = |bridge: usize| match bridge {
            BRIDGE => Some(answer(PROXY, "lambda$f$0")),
            INNER_BRIDGE => Some(answer(INNER_PROXY, "lambda$f$1")),
            _ => None,
        };
        let resolver = |c: &str, n: &str, d: &str| {
            if c != "p/Host" || d != "(I)I" {
                return None;
            }
            match n {
                "lambda$f$0" => Some(lambda_body("lambda$f$0", INNER_PROXY, INNER_BRIDGE)),
                "lambda$f$1" => Some(InlineSite {
                    method_name: "lambda$f$1".to_string(),
                    ..impl_body(2)
                }),
                _ => None,
            }
        };
        let mut site = kernel();
        assert_eq!(ir_graft_spliced_lambda_impls(&mut site, &impls, &resolver, true, OWN, false, 0), 2);
        assert_eq!(site.ir_lambda_impl_rows, vec![(8, 1, 1, 1)]);
        let outer = &site.nested_sites[0].site;
        assert_eq!(outer.method_name, "lambda$f$0");
        assert_eq!(outer.ir_lambda_impl_rows, vec![(8, 1, 1, 1)]);
        assert_eq!(outer.nested_sites.len(), 1);
        assert_eq!(outer.nested_sites[0].site.method_name, "lambda$f$1");
        // The depth bound stops the walk.
        let mut site = kernel();
        let past = IR_LAMBDA_GRAFT_MAX_DEPTH + 1;
        assert_eq!(ir_graft_spliced_lambda_impls(&mut site, &impls, &resolver, true, OWN, false, past), 0);
    }

    /// Append `site` at caller pc 3 of a 10-byte caller (base 10).
    fn append(site: InlineSite) -> (Result<(), &'static str>, ir::IrInlineTables) {
        let mut combined = vec![0u8; 10];
        let mut tables = ir::IrInlineTables::default();
        let mut owned_strings: Vec<Box<str>> = Vec::new();
        let mut owned_invoke_infos: Vec<Box<JitInvokeInfo>> = Vec::new();
        let mut direct_callee_entries: Vec<(usize, u64)> = Vec::new();
        let mut budget = IR_INLINE_MAX_TOTAL_BYTES;
        let mut vcalls: Vec<(usize, usize)> = Vec::new();
        let mut compact: HashMap<(usize, bool), (u32, bool, u8)> = HashMap::new();
        let mut static_init: Vec<u32> = Vec::new();
        let mut direct_calls: Vec<(usize, (usize, bool))> = Vec::new();
        let mut checkcast_seen = false;
        let mut volatile: Vec<usize> = Vec::new();
        let mut exact_nested: Vec<(usize, u32)> = Vec::new();
        let result = append_ir_inline_site(
            site,
            3,
            &mut combined,
            &mut tables,
            &mut owned_strings,
            &mut owned_invoke_infos,
            &mut direct_callee_entries,
            &mut budget,
            &mut vcalls,
            &mut compact,
            false,
            false,
            &mut static_init,
            &mut direct_calls,
            &mut checkcast_seen,
            &mut volatile,
            &mut exact_nested,
            None,
            &|_, _, _| None,
            ir::SpliceFenceRelax::NONE,
            true,
        );
        (result, tables)
    }

    #[test]
    fn jr21w15_the_append_registers_the_row_only_for_an_appended_impl() {
        cratonvm_types::flags::with_thread_overrides(
            &[("CRATONVM_JIT_IR_SPLICE_INDY_CAPTURE", None)],
            || {
                // Appended: the impl's body at the SAM call's combined pc, the
                // builder's row there, no call row left at that pc.
                let mut site = kernel();
                assert_eq!(graft(&mut site, true, 2), 1);
                let (result, tables) = append(site);
                assert_eq!(result, Ok(()));
                assert!(tables.sites.contains_key(&18));
                assert_eq!(
                    tables.lambda_impl_sites,
                    HashMap::from([(18usize, (11usize, 1usize, 1usize))])
                );
                assert!(!tables.invoke_info.contains_key(&18));
                // Refused (a body of length 0): the enclosing body is still
                // appended, and the SAM call keeps its call row.
                let mut site = kernel();
                assert_eq!(graft(&mut site, true, 0), 1);
                let (result, tables) = append(site);
                assert_eq!(result, Ok(()));
                assert!(!tables.sites.contains_key(&18));
                assert!(tables.lambda_impl_sites.is_empty());
                assert!(tables.invoke_info.contains_key(&18));
            },
        );
    }

    #[test]
    fn jr21w15_the_switch_reads_default_on() {
        let key = "CRATONVM_JIT_IR_LAMBDA_IMPL_IN_SPLICE";
        let on = cratonvm_types::flags::with_thread_overrides(&[(key, None)], || {
            ir_lambda_impl_in_splice_enabled()
        });
        let off = cratonvm_types::flags::with_thread_overrides(&[(key, Some("0"))], || {
            ir_lambda_impl_in_splice_enabled()
        });
        assert!(on);
        assert!(!off);
    }
}

/// JIT round 21 lane indylate (`972af884ca`, re-landed t1 wave 8 lane
/// RL-REFL): `JitVerdictRegistry::forget_ir_input_refusal` drops the
/// acceptance gate's input-stamped refusal and keeps a sticky site-trap ban.
#[cfg(test)]
mod rlrefl_indylate_refusal_forget_tests {
    #[test]
    fn rlrefl_the_registry_forgets_a_gate_refusal_and_keeps_a_sticky_ban() {
        const C: &str = "cratonvm/test/RlreflIndyLateForget";
        let verdicts = crate::JitVerdictRegistry::default();
        let id = cratonvm_types::ClassId::new(2181);
        let other = cratonvm_types::ClassId::new(2182);
        let hash = crate::ir_method_memo_hash(C, "k", "(II)I");
        let key = verdicts.ir_refusal_key(hash, id);
        assert!(!verdicts.forget_ir_input_refusal(C, "k", "(II)I", id), "nothing recorded");
        verdicts.ir_refusals().note_refused_for_inputs(key);
        assert!(!verdicts.forget_ir_input_refusal(C, "k", "(II)I", other), "another class");
        assert!(verdicts.ir_refusals().is_recorded(key));
        assert!(verdicts.forget_ir_input_refusal(C, "k", "(II)I", id));
        assert!(!verdicts.ir_refusals().is_recorded(key));
        verdicts.note_ir_method_refused(C, "k", "(II)I", id);
        assert!(!verdicts.forget_ir_input_refusal(C, "k", "(II)I", id), "a sticky ban stays");
        assert!(verdicts.ir_method_ban_holds(C, "k", "(II)I", id));
    }
}

#[cfg(test)]
mod jr21_lambda3fix_loop_slot_tests {
    //! JIT round 21 wave 19, lane lambda3fix (LAMBDA321-4,
    //! `CRATONVM_JIT_IR_LAMBDA_IMPL_LOOP_SLOT`): a SAM call on a lambda made
    //! before the loop that applies it is planned (method-own sites) and
    //! grafted (spliced bodies) when the method writes the receiver local once,
    //! outside every loop.

    use super::*;

    const PROXY: u32 = 0x8000_0041;
    const BRIDGE: usize = 0x4141;

    // static int k(int j, int n) {
    //     IntSupplier f = () -> j; int s = 0;
    //     for (int i = 0; i < n; i++) s += f.getAsInt();
    //     return s;
    // }
    //  0: iload_0  1: invokedynamic #1 (I)L  6: astore_2  7: iconst_0  8: istore_3
    //  9: iconst_0  10: istore 4  12: iload 4  14: iload_1  15: if_icmpge 33
    // 18: iload_3  19: aload_2  20: invokeinterface #2 getAsInt()I, 1  25: iadd
    // 26: istore_3  27: iinc 4 1  30: goto 12  33: iload_3  34: ireturn
    const LOOP: [u8; 35] = [
        0x1a, 0xba, 0x00, 0x01, 0x00, 0x00, 0x4d, 0x03, 0x3e, 0x03, 0x36, 0x04, 0x15, 0x04, 0x1b,
        0xa2, 0x00, 0x12, 0x1d, 0x2c, 0xb9, 0x00, 0x02, 0x01, 0x00, 0x60, 0x3e, 0x84, 0x04, 0x01,
        0xa7, 0xff, 0xee, 0x1d, 0xac,
    ];

    const OWN: (&str, &str, &str) = ("p/Caller", "k", "(II)I");

    fn answer() -> compile_request::IndyLambdaImplAnswer {
        compile_request::IndyLambdaImplAnswer {
            proxy_class_id: PROXY,
            num_captures: 1,
            sam_name: "getAsInt".to_string(),
            sam_descriptor: "()I".to_string(),
            class: "p/Host".to_string(),
            name: "lambda$k$0".to_string(),
            descriptor: "(I)I".to_string(),
            class_id: 0x7141,
        }
    }

    fn names(cp: u16) -> Option<(String, String, String)> {
        (cp == 2).then(|| {
            (
                "java/util/function/IntSupplier".to_string(),
                "getAsInt".to_string(),
                "()I".to_string(),
            )
        })
    }

    fn plan(code: &[u8], loop_slot: Option<(usize, bool)>) -> IrLambdaImplPlan {
        let lambdas = HashMap::from([(1usize, (1u16, 1usize, answer()))]);
        let shapes = HashMap::from([(1usize, (1usize, b'L'))]);
        let names: &dyn Fn(u16) -> Option<(String, String, String)> = &names;
        ir_lambda_impl_plan(
            Some(names),
            &lambdas,
            &shapes,
            code,
            code.len(),
            &[],
            &[(20, 2, 0xb9)],
            true,
            OWN,
            &|_| false,
            loop_slot,
        )
    }

    #[test]
    fn jr21lambda3fix_the_one_store_outside_every_loop_is_found() {
        assert_eq!(
            lambda_single_store_outside_loops(&LOOP, LOOP.len(), 2, 2),
            Some(6)
        );
        // A parameter slot, a slot written twice / by a non-`astore`.
        assert_eq!(
            lambda_single_store_outside_loops(&LOOP, LOOP.len(), 2, 3),
            None
        );
        assert_eq!(
            lambda_single_store_outside_loops(&LOOP, LOOP.len(), 3, 2),
            None
        );
        // The store inside the loop: `astore_2` in place of `istore_3` at 26.
        let mut inside = LOOP;
        inside[6] = 0x57; // pop: the only store is now the loop's
        inside[26] = 0x4d;
        assert_eq!(
            lambda_single_store_outside_loops(&inside, inside.len(), 2, 2),
            None
        );
    }

    #[test]
    fn jr21lambda3fix_a_sam_call_in_the_loop_is_planned_with_the_route() {
        let p = plan(&LOOP, Some((2, true)));
        assert_eq!(
            p.builder_sites(),
            HashMap::from([(20usize, (1usize, 1usize, 1usize))])
        );
        assert_eq!(
            p.rewritten_invoke_ops(&[(20, 2, 0xb9)]),
            vec![(20, 1, 0xb8)]
        );
        // Without the route (or the switch), capturing sites refused there
        // (an OSR compile), or the local a parameter: the interface call.
        assert!(plan(&LOOP, None).is_empty());
        assert!(plan(&LOOP, Some((2, false))).is_empty());
        assert!(plan(&LOOP, Some((3, true))).is_empty());
    }

    fn body() -> InlineSite {
        let mut code = LOOP.to_vec();
        code.extend_from_slice(&[0, 0]);
        InlineSite {
            callee_code: code,
            callee_code_len: LOOP.len(),
            callee_max_locals: 5,
            callee_num_args: 2,
            callee_is_static: true,
            return_type: b'I',
            class_name: "p/Host".to_string(),
            class_id: 7,
            method_name: "k".to_string(),
            descriptor: "(II)I".to_string(),
            invoke_targets: vec![(
                20,
                InlineInvokeTarget {
                    class_name: "java/util/function/IntSupplier".to_string(),
                    method_name: "getAsInt".to_string(),
                    descriptor: "()I".to_string(),
                    num_jit_args: 1,
                    return_type: b'I',
                    invoke_kind: 2,
                    declaring_class_id: 7,
                    ..Default::default()
                },
            )],
            ir_indy_capture_rows: vec![(1, PROXY, vec![b'I'])],
            ir_indy_capture_sites: vec![(1, BRIDGE)],
            ..Default::default()
        }
    }

    fn graft(site: &mut InlineSite, loop_slot: bool) -> usize {
        let impls = |bridge: usize| (bridge == BRIDGE).then(answer);
        let resolver = |c: &str, n: &str, d: &str| {
            (c == "p/Host" && n == "lambda$k$0" && d == "(I)I").then(|| InlineSite {
                callee_code: vec![0x1a, 0xac, 0, 0],
                callee_code_len: 2,
                callee_max_locals: 1,
                callee_num_args: 1,
                callee_is_static: true,
                return_type: b'I',
                class_name: "p/Host".to_string(),
                class_id: 0x7141,
                method_name: "lambda$k$0".to_string(),
                descriptor: "(I)I".to_string(),
                ..Default::default()
            })
        };
        ir_graft_spliced_lambda_impls(site, &impls, &resolver, true, OWN, loop_slot, 0)
    }

    #[test]
    fn jr21lambda3fix_a_spliced_loop_body_gets_its_impl_grafted_with_the_route() {
        let mut site = body();
        assert_eq!(graft(&mut site, true), 1);
        assert_eq!(site.ir_lambda_impl_rows, vec![(20, 1, 1, 1)]);
        assert_eq!(site.nested_sites.len(), 1);
        assert_eq!(site.nested_sites[0].callee_pc, 20);
        let mut site = body();
        assert_eq!(graft(&mut site, false), 0);
        assert!(site.nested_sites.is_empty());
    }

    #[test]
    fn jr21lambda3fix_the_switch_reads_default_on() {
        let key = "CRATONVM_JIT_IR_LAMBDA_IMPL_LOOP_SLOT";
        let on = cratonvm_types::flags::with_thread_overrides(&[(key, None)], || {
            ir_lambda_impl_loop_slot_enabled()
        });
        let off = cratonvm_types::flags::with_thread_overrides(&[(key, Some("0"))], || {
            ir_lambda_impl_loop_slot_enabled()
        });
        assert!(on);
        assert!(!off);
    }
}

/// JIT round 21, lane strintr2 (STRINTR21-1): the withdrawn-site set and the
/// three String accessor call-prefix kinds.
#[cfg(test)]
mod strintr2_string_accessor_call_tests {
    use super::*;

    const WITHDRAW: &str = "CRATONVM_JIT_IR_STRING_ACCESS_TRAP_WITHDRAW";
    const PREFIX: &str = "CRATONVM_JIT_IR_STRING_ACCESSOR_CALL_PREFIX";
    const KEY: &str = "p/Scan.oob:(I)J";

    #[test]
    fn only_a_withdrawn_invokevirtual_pc_is_listed() {
        let registry = deopt::DespecRegistry::new();
        // invokevirtual @4 (never trapped), invokevirtual @9 (the guard trapped
        // past the limit), invokestatic @12 (a wildcard there, not a site).
        let ops: [(usize, u16, u8); 3] = [(4, 1, 0xb6), (9, 2, 0xb6), (12, 3, 0xb8)];
        registry.insert(
            KEY,
            9,
            deopt::speculation_id(9, deopt::DeoptReason::UncommonTrap),
        );
        registry.insert(KEY, 12, deopt::SPECULATION_ID_ANY);
        let on = cratonvm_types::flags::with_thread_overrides(&[(WITHDRAW, None)], || {
            string_access_withdrawn_pcs(Some(&registry), KEY, &ops)
        });
        let want: std::collections::HashSet<usize> = [9usize].into_iter().collect();
        assert_eq!(on, want);
        // The wildcard withdraws the site too.
        registry.insert(KEY, 4, deopt::SPECULATION_ID_ANY);
        let both = cratonvm_types::flags::with_thread_overrides(&[(WITHDRAW, None)], || {
            string_access_withdrawn_pcs(Some(&registry), KEY, &ops)
        });
        assert_eq!(both.len(), 2);
        // Another method's key, no registry, and the kill switch list nothing.
        let other = cratonvm_types::flags::with_thread_overrides(&[(WITHDRAW, None)], || {
            string_access_withdrawn_pcs(Some(&registry), "p/Scan.other:(I)J", &ops)
        });
        assert!(other.is_empty());
        assert!(string_access_withdrawn_pcs(None, KEY, &ops).is_empty());
        let off = cratonvm_types::flags::with_thread_overrides(&[(WITHDRAW, Some("0"))], || {
            string_access_withdrawn_pcs(Some(&registry), KEY, &ops)
        });
        assert!(off.is_empty());
    }

    #[test]
    fn the_string_accessor_kinds_front_a_call_and_move_no_decision() {
        use IrStringSearchKind as K;
        let kinds = |prefix: Option<&'static str>| {
            cratonvm_types::flags::with_thread_overrides(
                &[
                    ("CRATONVM_JIT_IR_STRING_SEARCH_PREFIX", None),
                    ("CRATONVM_JIT_IR_CHARSEQ_PREFIX", None),
                    (PREFIX, prefix),
                ],
                || {
                    (
                        ir_string_search_prefix_kind("java/lang/String", "length", "()I"),
                        ir_string_search_prefix_kind("java/lang/String", "isEmpty", "()Z"),
                        ir_string_search_prefix_kind("java/lang/String", "charAt", "(I)C"),
                        ir_string_search_prefix_handled_kind("java/lang/String", "charAt", "(I)C"),
                        ir_string_search_prefix_kind("java/lang/CharSequence", "charAt", "(I)C"),
                    )
                },
            )
        };
        let (len, empty, at, handled, seq) = kinds(None);
        assert_eq!(len, Some(K::StrLength));
        assert_eq!(empty, Some(K::StrIsEmpty));
        assert_eq!(at, Some(K::StrCharAt));
        assert_eq!(
            handled, None,
            "the pin / planning / splice view never sees them"
        );
        assert_eq!(seq, Some(K::SeqCharAt));
        let (len, empty, at, handled, seq) = kinds(Some("0"));
        assert_eq!((len, empty, at, handled), (None, None, None, None));
        assert_eq!(
            seq,
            Some(K::SeqCharAt),
            "the kill switch is the String kinds' only"
        );
        // Shapes: an `invokevirtual` (or devirtualised special) of a final
        // class, the receiver plus `charAt`'s index, never a builder kind,
        // never kept a call by the splice planners.
        for k in [K::StrLength, K::StrIsEmpty, K::StrCharAt] {
            assert!(k.is_string_accessor_call());
            assert!(k.admits_opcode(0xb6) && !k.admits_opcode(0xb9));
            assert!(k.admits_invoke_kind(0) && k.admits_invoke_kind(1));
            assert!(!k.admits_invoke_kind(2) && !k.is_builder());
            assert!(!ir_string_prefix_site_stays_a_call(k));
        }
        assert_eq!(K::StrLength.num_params(), 0);
        assert_eq!(K::StrIsEmpty.num_params(), 0);
        assert_eq!(K::StrCharAt.num_params(), 1);
        assert!(!K::SeqCharAt.is_string_accessor_call());
    }
}

#[cfg(test)]
mod jr21_mhbind2_bound_plan_tests {
    use super::*;

    type Answer = Option<(String, String, String, u8, u32)>;
    type Row = Option<(u32, u32)>;

    /// `invokevirtual` cp 9 is `MethodHandle.invokeExact(I)I`.
    fn names(cp: u16) -> Option<(String, String, String)> {
        (cp == 9).then(|| {
            (
                "java/lang/invoke/MethodHandle".into(),
                "invokeExact".into(),
                "(I)I".into(),
            )
        })
    }

    fn plus(_invoke_cp: u16, _pc: usize, field_cp: u16) -> Answer {
        (field_cp == 3).then(|| ("p/Acc".into(), "plus".into(), "(I)I".into(), 4, 0x7474))
    }

    fn never(_: usize) -> bool {
        false
    }

    fn row(invoke_cp: u16, pc: usize, field_cp: u16) -> Row {
        (invoke_cp == 9 && pc == 4 && field_cp == 3).then_some((5, 0x7575))
    }

    fn no_row(_: u16, _: usize, _: u16) -> Row {
        None
    }

    #[test]
    fn jr21_a_bound_constant_handle_site_needs_its_row() {
        // 0: getstatic #3  3: iload_1  4: invokevirtual #9  7: ireturn
        let code = [0xb2, 0, 3, 0x1b, 0xb6, 0, 9, 0xac];
        let ops = [(4usize, 9u16, 0xb6u8)];
        let plan = |answer: &dyn Fn(u16, usize, u16) -> Answer,
                    gates: (bool, bool),
                    trapped: &dyn Fn(usize) -> bool| {
            ir_mh_constant_plan(
                Some(answer),
                Some(&names),
                &code,
                code.len(),
                &[],
                &ops,
                gates,
                ("p/Caller", "loop", "(I)J"),
                trapped,
            )
        };
        // Planned, then kept only with a row.
        assert_eq!(plan(&plus, (true, true), &never).site_count(), 1);
        assert!(plan(&plus, (true, true), &never)
            .with_bound_rows(None)
            .is_empty());
        assert!(plan(&plus, (true, true), &never)
            .with_bound_rows(Some(&no_row))
            .is_empty());
        let planned = plan(&plus, (true, true), &never).with_bound_rows(Some(&row));
        assert_eq!(planned.site_count(), 1);
        assert_eq!(
            planned.names(3),
            Some(("p/Acc".into(), "plus".into(), "(I)I".into()))
        );
        assert_eq!(planned.rewritten_invoke_ops(&ops), vec![(4, 3, 0xb6)]);
        assert_eq!(planned.receiver_pcs().get(&4), Some(&0));
        assert_eq!(planned.bound_slots().get(&4), Some(&5));
        assert_eq!(planned.bound_receiver_class_at(4), Some(0x7575));
        assert!(planned.interface_pcs().is_empty());
        // The virtual gate off, or a trapped receiver guard: nothing.
        assert!(plan(&plus, (true, false), &never).is_empty());
        assert!(plan(&plus, (true, true), &|pc| pc == 4).is_empty());
        // A member that is not the site's own descriptor: nothing.
        let wide = |_: u16, _: usize, _: u16| -> Answer {
            Some(("p/Acc".into(), "plus".into(), "(J)I".into(), 4, 0x7474))
        };
        assert!(plan(&wide, (true, true), &never).is_empty());
        // A non-bound site never asks the row and keeps its plan.
        let stat = |_: u16, _: usize, _: u16| -> Answer {
            Some(("p/Host".into(), "twice".into(), "(I)I".into(), 3, 0x7171))
        };
        let kept = plan(&stat, (true, true), &never).with_bound_rows(Some(&no_row));
        assert_eq!(kept.site_count(), 1);
        assert!(kept.bound_slots().is_empty());
        assert_eq!(kept.bound_receiver_class_at(4), None);
    }
}

/// JIT round 21 wave 20 (lane mhfilter; MHBIND2-1): a filter species' site
/// (`invoke_kind 5`) keeps its plan only with a PRE row that fits; the PRE
/// call joins the invoke plan at the site's `getstatic` pc, named under
/// `MH_FILTER_PRE_KEY`.
#[cfg(test)]
mod jr21_mhfilter_plan_tests {
    use super::*;
    use crate::compile_request::MhConstantFilterRow;

    type Answer = Option<(String, String, String, u8, u32)>;

    /// `invokevirtual` cp 9 is `MethodHandle.invokeExact(I)I`.
    fn names(cp: u16) -> Option<(String, String, String)> {
        (cp == 9).then(|| {
            (
                "java/lang/invoke/MethodHandle".into(),
                "invokeExact".into(),
                "(I)I".into(),
            )
        })
    }

    fn twice(_invoke_cp: u16, _pc: usize, field_cp: u16) -> Answer {
        (field_cp == 3).then(|| ("p/Host".into(), "twice".into(), "(I)I".into(), 5, 0x7171))
    }

    fn never(_: usize) -> bool {
        false
    }

    fn neg_row() -> MhConstantFilterRow {
        MhConstantFilterRow {
            position: Some(0),
            main_kind: 3,
            pre_class: "p/F".into(),
            pre_name: "neg".into(),
            pre_desc: "(I)I".into(),
            pre_kind: 3,
            pre_class_id: 0x7272,
            target_slot: 0,
        }
    }

    fn row(
        invoke_cp: u16,
        pc: usize,
        field_cp: u16,
        getstatic_pc: usize,
    ) -> Option<MhConstantFilterRow> {
        (invoke_cp == 9 && pc == 4 && field_cp == 3 && getstatic_pc == 0).then(neg_row)
    }

    // 0: getstatic #3  3: iload_1  4: invokevirtual #9  7: ireturn
    const CODE: [u8; 8] = [0xb2, 0, 3, 0x1b, 0xb6, 0, 9, 0xac];
    const OPS: [(usize, u16, u8); 1] = [(4, 9, 0xb6)];
    const OWN: (&str, &str, &str) = ("p/Caller", "loop", "(I)J");

    fn plan(code: &[u8], ops: &[(usize, u16, u8)], gates: (bool, bool)) -> IrMhConstantPlan {
        ir_mh_constant_plan(
            Some(&twice),
            Some(&names),
            code,
            code.len(),
            &[],
            ops,
            gates,
            OWN,
            &never,
        )
    }

    #[test]
    fn jr21_a_filter_species_site_plans_its_pre_call_at_the_getstatic() {
        let planned = plan(&CODE, &OPS, (true, true)).with_filter_rows(
            Some(&row),
            &CODE,
            &never,
            (true, true),
            OWN,
        );
        assert_eq!(planned.site_count(), 1);
        assert_eq!(
            planned.rewritten_invoke_ops(&OPS),
            vec![(0, MH_FILTER_PRE_KEY, 0xb8), (4, 3, 0xb8)]
        );
        assert_eq!(
            planned.names(MH_FILTER_PRE_KEY),
            Some(("p/F".into(), "neg".into(), "(I)I".into()))
        );
        assert_eq!(planned.class_id(MH_FILTER_PRE_KEY), Some(0x7272));
        assert_eq!(
            planned.names(3),
            Some(("p/Host".into(), "twice".into(), "(I)I".into()))
        );
        assert_eq!(planned.class_context_at(4), Some(0x7171));
        assert_eq!(planned.class_context_at(0), Some(0x7272));
        assert!(planned.is_filter_pc(0) && planned.is_filter_pc(4) && !planned.is_filter_pc(3));
        assert_eq!(
            planned.filter_sites().get(&4),
            Some(&ir::IrMhFilterSite {
                pre_pc: 0,
                position: Some(0),
                main_virtual: false,
                pre_virtual: false,
                target_slot: 0,
            })
        );
        assert_eq!(planned.receiver_pcs().get(&4), Some(&0));
        assert!(planned.bound_slots().is_empty());
    }

    #[test]
    fn jr21_a_filter_site_without_a_fitting_row_is_dropped() {
        let filter = |resolver: Option<&dyn Fn(u16, usize, u16, usize) -> Option<MhConstantFilterRow>>,
                      protected: &dyn Fn(usize) -> bool,
                      gates: (bool, bool)| {
            plan(&CODE, &OPS, gates).with_filter_rows(resolver, &CODE, protected, gates, OWN)
        };
        // No resolver, or no row.
        assert!(filter(None, &never, (true, true)).is_empty());
        let no_row = |_: u16, _: usize, _: u16, _: usize| -> Option<MhConstantFilterRow> { None };
        assert!(filter(Some(&no_row), &never, (true, true)).is_empty());
        // A handler over the window.
        assert!(filter(Some(&row), &|bci: usize| bci == 3, (true, true)).is_empty());
        // The static gate off (both calls are static).
        assert!(filter(Some(&row), &never, (false, true)).is_empty());
        // A row whose shape is not the site's: a filter of a long.
        let wide = |_: u16, _: usize, _: u16, _: usize| -> Option<MhConstantFilterRow> {
            Some(MhConstantFilterRow {
                pre_desc: "(J)I".into(),
                ..neg_row()
            })
        };
        assert!(filter(Some(&wide), &never, (true, true)).is_empty());
        // A PRE member of no known class.
        let no_class = |_: u16, _: usize, _: u16, _: usize| -> Option<MhConstantFilterRow> {
            Some(MhConstantFilterRow {
                pre_class_id: 0,
                ..neg_row()
            })
        };
        assert!(filter(Some(&no_class), &never, (true, true)).is_empty());
        // A local written between the getstatic and the invoke:
        // 0: getstatic #3  3: iinc 1 1  6: iload_1  7: invokevirtual #9  10: ireturn
        let code = [0xb2, 0, 3, 0x84, 1, 1, 0x1b, 0xb6, 0, 9, 0xac];
        let ops = [(7usize, 9u16, 0xb6u8)];
        let at7 = |_: u16, pc: usize, _: u16, _: usize| -> Option<MhConstantFilterRow> {
            (pc == 7).then(neg_row)
        };
        let planned = plan(&code, &ops, (true, true));
        assert_eq!(planned.site_count(), 1, "the walk plans it");
        assert!(planned
            .with_filter_rows(Some(&at7), &code, &never, (true, true), OWN)
            .is_empty());
    }

    /// JIT round j27 (lane MHINDY): the resolver is asked for EVERY site of
    /// the field with that site's own `(invoke pc, getstatic pc)`, and one
    /// refusal (the VM's split-line check) drops the field's every site.
    #[test]
    fn j27_every_filter_site_is_asked_with_its_own_getstatic_pc() {
        // 0: getstatic #3  3: iload_1  4: invokevirtual #9  7: pop
        // 8: getstatic #3  11: iload_1  12: invokevirtual #9  15: ireturn
        let code = [
            0xb2, 0, 3, 0x1b, 0xb6, 0, 9, 0x57, 0xb2, 0, 3, 0x1b, 0xb6, 0, 9, 0xac,
        ];
        let ops = [(4usize, 9u16, 0xb6u8), (12, 9, 0xb6)];
        let planned = plan(&code, &ops, (true, true));
        assert_eq!(planned.site_count(), 2, "the walk plans both");
        let asked = std::cell::RefCell::new(Vec::new());
        let both = |_: u16, pc: usize, _: u16, getstatic_pc: usize| {
            asked.borrow_mut().push((pc, getstatic_pc));
            Some(neg_row())
        };
        let kept = plan(&code, &ops, (true, true)).with_filter_rows(
            Some(&both),
            &code,
            &never,
            (true, true),
            OWN,
        );
        assert_eq!(kept.site_count(), 2);
        assert_eq!(*asked.borrow(), vec![(4, 0), (12, 8)]);
        // The second site's two pcs on different lines: the VM answers None.
        let split = |_: u16, pc: usize, _: u16, _: usize| (pc != 12).then(neg_row);
        assert!(planned
            .with_filter_rows(Some(&split), &code, &never, (true, true), OWN)
            .is_empty());
    }
}

/// j27 wave 6 (lane T1LAM2; item 1 of
/// `j27-mh-real-astype-converting-bind-proposal-20261028.md`): a bound STATIC
/// constant handle's site (`invoke_kind 6`) is planned as an `invokestatic` of
/// its member only with its `argL1` row, under the static gate, and never
/// takes the virtual bound site's receiver class.
#[cfg(test)]
mod j27_t1lam2_bound_static_plan_tests {
    use super::*;

    type Answer = Option<(String, String, String, u8, u32)>;
    type Row = Option<(u32, u32)>;

    /// `invokevirtual` cp 9 is `MethodHandle.invokeExact(I)J`.
    fn names(cp: u16) -> Option<(String, String, String)> {
        (cp == 9).then(|| {
            (
                "java/lang/invoke/MethodHandle".into(),
                "invokeExact".into(),
                "(I)J".into(),
            )
        })
    }

    /// `static long addL(Long, int)` bound on its `Long`.
    fn add_l(_invoke_cp: u16, _pc: usize, field_cp: u16) -> Answer {
        (field_cp == 3).then(|| {
            (
                "p/S".into(),
                "addL".into(),
                "(Ljava/lang/Long;I)J".into(),
                6,
                0x7171,
            )
        })
    }

    fn never(_: usize) -> bool {
        false
    }

    fn row(invoke_cp: u16, pc: usize, field_cp: u16) -> Row {
        (invoke_cp == 9 && pc == 4 && field_cp == 3).then_some((7, 0))
    }

    fn no_row(_: u16, _: usize, _: u16) -> Row {
        None
    }

    // 0: getstatic #3  3: iload_1  4: invokevirtual #9  7: lreturn
    const CODE: [u8; 8] = [0xb2, 0, 3, 0x1b, 0xb6, 0, 9, 0xad];
    const OPS: [(usize, u16, u8); 1] = [(4, 9, 0xb6)];

    fn plan(answer: &dyn Fn(u16, usize, u16) -> Answer, gates: (bool, bool)) -> IrMhConstantPlan {
        ir_mh_constant_plan(
            Some(answer),
            Some(&names),
            &CODE,
            CODE.len(),
            &[],
            &OPS,
            gates,
            ("p/Caller", "loop", "(I)J"),
            &never,
        )
    }

    #[test]
    fn a_bound_static_site_is_an_invokestatic_with_its_row() {
        let planned = plan(&add_l, (true, false)).with_bound_rows(Some(&row));
        assert_eq!(planned.site_count(), 1);
        assert_eq!(planned.rewritten_invoke_ops(&OPS), vec![(4, 3, 0xb8)]);
        assert_eq!(
            planned.names(3),
            Some(("p/S".into(), "addL".into(), "(Ljava/lang/Long;I)J".into()))
        );
        assert_eq!(planned.bound_slots().get(&4), Some(&7));
        assert!(planned.bound_static_pcs().contains(&4));
        // No receiver: the guarded splice never takes a class from it.
        assert_eq!(planned.bound_receiver_class_at(4), None);
        assert_eq!(planned.receiver_pcs().get(&4), Some(&0));
    }

    #[test]
    fn a_bound_static_site_without_its_row_or_gate_is_dropped() {
        // Planned as a plain kind 3 it would call addL without its Long.
        assert!(plan(&add_l, (true, true)).with_bound_rows(None).is_empty());
        assert!(plan(&add_l, (true, true)).with_bound_rows(Some(&no_row)).is_empty());
        // The static gate off.
        assert!(plan(&add_l, (false, true)).is_empty());
        // A member whose descriptor is not the site's plus one leading
        // reference (the bound handle is at another type: the door's WMTE).
        let same = |_: u16, _: usize, _: u16| -> Answer {
            Some(("p/S".into(), "addL".into(), "(I)J".into(), 6, 0x7171))
        };
        assert!(plan(&same, (true, true)).is_empty());
        let prim = |_: u16, _: usize, _: u16| -> Answer {
            Some(("p/S".into(), "addL".into(), "(JI)J".into(), 6, 0x7171))
        };
        assert!(plan(&prim, (true, true)).is_empty());
    }

    #[test]
    fn a_bound_virtual_site_is_not_a_static_one() {
        let plus = |_: u16, _: usize, field_cp: u16| -> Answer {
            (field_cp == 3).then(|| ("p/Acc".into(), "plus".into(), "(I)J".into(), 4, 0x7474))
        };
        let planned = plan(&plus, (true, true)).with_bound_rows(Some(&row));
        assert_eq!(planned.site_count(), 1);
        assert!(planned.bound_static_pcs().is_empty());
        assert_eq!(planned.rewritten_invoke_ops(&OPS), vec![(4, 3, 0xb6)]);
    }
}
